65: /**
66:  * This operator is an abstract class that give the {@link AbstractStreamOperatorV2} the ability to
67:  * perform {@link AsyncStateProcessing}. The aim is to make any subclass of {@link
68:  * AbstractStreamOperatorV2} could manipulate async state with only a change of base class.
69:  */
70: @Internal
71: @SuppressWarnings("rawtypes")
72: public abstract class AbstractAsyncStateStreamOperatorV2<OUT> extends AbstractStreamOperatorV2<OUT>
73:         implements AsyncStateProcessingOperator {
74: 
75:     private static final Logger LOG =
76:             LoggerFactory.getLogger(AbstractAsyncStateStreamOperatorV2.class);
77: 
78:     private final Environment environment;
79:     private final StreamTask<?, ?> streamTask;
80:     private AsyncExecutionController asyncExecutionController;
81: 
82:     /** Act as a cache for {@link #setAsyncKeyedContextElement} and {@link #postProcessElement}. */
83:     private RecordContext currentProcessingContext;
84: 
85:     protected DeclarationManager declarationManager;
86: 
87:     public AbstractAsyncStateStreamOperatorV2(
88:             StreamOperatorParameters<OUT> parameters, int numberOfInputs) {
89:         super(parameters, numberOfInputs);
90:         this.environment = parameters.getContainingTask().getEnvironment();
91:         this.streamTask = parameters.getContainingTask();
92:     }
93: 
94:     /** Initialize necessary state components for {@link AbstractStreamOperatorV2}. */
95:     @Override
96:     public final void beforeInitializeStateHandler() {
97:         KeyedStateStore stateStore = stateHandler.getKeyedStateStore().orElse(null);
98:         if (stateStore instanceof DefaultKeyedStateStore) {
99:             ((DefaultKeyedStateStore) stateStore).setSupportKeyedStateApiSetV2();
100:         }
101: 
102:         final int inFlightRecordsLimit = getExecutionConfig().getAsyncStateTotalBufferSize();
103:         final int asyncBufferSize = getExecutionConfig().getAsyncStateBufferSize();
104:         final long asyncBufferTimeout = getExecutionConfig().getAsyncStateBufferTimeout();
105:         int maxParallelism = getExecutionConfig().getMaxParallelism();
106: 
107:         this.declarationManager = new DeclarationManager();
108:         if (isAsyncStateProcessingEnabled()) {
109:             AsyncKeyedStateBackend asyncKeyedStateBackend =
110:                     stateHandler.getAsyncKeyedStateBackend();
111:             if (asyncKeyedStateBackend != null) {
112:                 this.asyncExecutionController =
113:                         new AsyncExecutionController(
114:                                 environment.getMainMailboxExecutor(),
115:                                 this::handleAsyncStateException,
116:                                 asyncKeyedStateBackend.createStateExecutor(),
117:                                 declarationManager,
118:                                 maxParallelism,
119:                                 asyncBufferSize,
120:                                 asyncBufferTimeout,
121:                                 inFlightRecordsLimit,
122:                                 asyncKeyedStateBackend,
123:                                 getMetricGroup().addGroup("asyncStateProcessing"));
124:                 asyncKeyedStateBackend.setup(asyncExecutionController);
125:                 if (asyncKeyedStateBackend instanceof AsyncKeyedStateBackendAdaptor) {
126:                     LOG.warn(
127:                             "A normal KeyedStateBackend({}) is used when enabling the async state "
128:                                     + "processing. Parallel asynchronous processing does not work. "
129:                                     + "All state access will be processed synchronously.",
130:                             stateHandler.getKeyedStateBackend());
131:                 }
132:             } else if (stateHandler.getKeyedStateBackend() != null) {
133:                 throw new UnsupportedOperationException(
134:                         "Current State Backend doesn't support async access, AsyncExecutionController could not work");
135:             }
136:         }
137:     }
138: 
139:     private void handleAsyncStateException(String message, Throwable exception) {
140:         environment.failExternally(new AsyncStateException(message, exception));
141:     }
142: 
143:     @Override
144:     public boolean isAsyncStateProcessingEnabled() {
145:         return true;
146:     }
147: 
148:     @Override
149:     public ElementOrder getElementOrder() {
150:         return ElementOrder.RECORD_ORDER;
151:     }
152: 
153:     @Override
154:     @SuppressWarnings("unchecked")
155:     public final <T> void setAsyncKeyedContextElement(
156:             StreamRecord<T> record, KeySelector<T, ?> keySelector) throws Exception {
157:         currentProcessingContext =
158:                 asyncExecutionController.buildContext(
159:                         record.getValue(), keySelector.getKey(record.getValue()));
160:         // The processElement will be treated as a callback for dummy request. So reference
161:         // counting should be maintained.
162:         // When state request submitted, ref count +1, as described in FLIP-425:
163:         // To cover the statements without a callback, in addition to the reference count marked
164:         // in Fig.5, each state request itself is also protected by a paired reference count.
165:         currentProcessingContext.retain();
166:         asyncExecutionController.setCurrentContext(currentProcessingContext);
167:         newKeySelected(currentProcessingContext.getKey());
168:     }
169: 
170:     /**
171:      * A hook that will be invoked after a new key is selected. It is not recommended to perform
172:      * async state here. Only some synchronous logic is suggested.
173:      *
174:      * @param newKey the new key selected.
175:      */
176:     public void newKeySelected(Object newKey) {
177:         // By default, do nothing.
178:         // Subclass could override this method to do some operations when a new key is selected.
179:     }
180: 
181:     @Override
182:     protected <T> void internalSetKeyContextElement(
183:             StreamRecord<T> record, KeySelector<T, ?> selector) throws Exception {
184:         // This method is invoked only when isAsyncStateProcessingEnabled() is false.
185:         super.internalSetKeyContextElement(record, selector);
186:         if (selector != null) {
187:             newKeySelected(getCurrentKey());
188:         }
189:     }
190: 
191:     @Override
192:     public Object getCurrentKey() {
193:         if (isAsyncStateProcessingEnabled()) {
194:             RecordContext currentContext = asyncExecutionController.getCurrentContext();
195:             if (currentContext == null) {
196:                 throw new UnsupportedOperationException(
197:                         "Have not set the current key yet, this may because the operator has not "
198:                                 + "started to run, or you are invoking this under a non-keyed context.");
199:             }
200:             return currentContext.getKey();
201:         } else {
202:             return super.getCurrentKey();
203:         }
204:     }
205: 
206:     @Override
207:     public final void postProcessElement() {
208:         // The processElement will be treated as a callback for dummy request. So reference
209:         // counting should be maintained.
210:         // When a state request completes, ref count -1, as described in FLIP-425:
211:         // To cover the statements without a callback, in addition to the reference count marked
212:         // in Fig.5, each state request itself is also protected by a paired reference count.
213:         currentProcessingContext.release();
214:     }
215: 
216:     @Override
217:     @SuppressWarnings("unchecked")
218:     public final void preserveRecordOrderAndProcess(ThrowingRunnable<Exception> processing) {
219:         asyncExecutionController.syncPointRequestWithCallback(processing, false);
220:     }
221: 
222:     @Override
223:     @SuppressWarnings("unchecked")
224:     public <K> void asyncProcessWithKey(K key, ThrowingRunnable<Exception> processing) {
225:         RecordContext<K> oldContext = asyncExecutionController.getCurrentContext();
226:         // build a context and switch to the new context
227:         RecordContext<K> newContext = asyncExecutionController.buildContext(null, key, true);
