79:                 type.isBlockingOrBlockingPersistentResultPartition()
80:                         && numSubpartitions >= sortShuffleMinParallelism;
81:         int expected;
82:         if (isSortShuffle) {
83:             expected = sortShuffleMinBuffers;
84:         } else {
85:             expected =
86:                     enableTieredStorage
87:                             ? Math.min(tieredStoreExclusiveBuffers, numSubpartitions + 1)
88:                             : (numSubpartitions + 1);
89:         }
90: 
91:         int min = expected;
