177:     private static int getNumBuffersToAnnounceForResultPartition(
178:             ResultPartitionType type,
179:             int configuredNetworkBuffersPerChannel,
180:             int floatingBuffersPerGate,
181:             int sortShuffleMinParallelism,
182:             int sortShuffleMinBuffers,
183:             int numSubpartitions) {
184: 
185:         Tuple3<Integer, Integer, Integer> tuple =
186:                 getMinMaxNetworkBuffersPerResultPartition(
187:                         configuredNetworkBuffersPerChannel,
188:                         floatingBuffersPerGate,
189:                         sortShuffleMinParallelism,
190:                         sortShuffleMinBuffers,
191:                         numSubpartitions,
192:                         false,
193:                         0,
194:                         type);
195: 
196:         // In order to avoid network buffer request timeout (see FLINK-12852), we announce
197:         // network buffer requirement by below:
198:         // 1. For canBePipelined shuffle, the floating buffers may not be returned in time due to
199:         // back pressure so we need to include all the floating buffers in the announcement, i.e. we
200:         // should take the max value;
201:         // 2. For blocking shuffle, it is back pressure free and floating buffers can be recycled
202:         // in time, so that the minimum required buffers would be enough.
203:         int ret = type.canBePipelinedConsumed() ? tuple.f2 : tuple.f0;
204: 
205:         if (ret == Integer.MAX_VALUE) {
