56: /**
57:  * The NetworkBufferPool is a fixed size pool of {@link MemorySegment} instances for the network
58:  * stack.
59:  *
60:  * <p>The NetworkBufferPool creates {@link LocalBufferPool}s from which the individual tasks draw
61:  * the buffers for the network data transfer. When new local buffer pools are created, the
62:  * NetworkBufferPool dynamically redistributes the buffers between the pools. The redistribution
63:  * logic is to make the number of buffers of each buffer pool fall within the minimum and maximum
64:  * numbers while endeavoring to closely align with its individual expected number.
65:  */
66: public class NetworkBufferPool
67:         implements BufferPoolFactory, MemorySegmentProvider, AvailabilityProvider {
68: 
69:     public static final int UNBOUNDED_POOL_SIZE = Integer.MAX_VALUE;
70: 
71:     private static final int USAGE_WARNING_THRESHOLD = 100;
72: 
73:     private static final Logger LOG = LoggerFactory.getLogger(NetworkBufferPool.class);
74: 
75:     private final int totalNumberOfMemorySegments;
76: 
77:     private final int memorySegmentSize;
78: 
79:     private final ArrayDeque<MemorySegment> availableMemorySegments;
80: 
81:     private volatile boolean isDestroyed;
82: 
83:     // ---- Managed buffer pools ----------------------------------------------
84: 
85:     private final Object factoryLock = new Object();
86: 
87:     private final Set<LocalBufferPool> allBufferPools = new HashSet<>();
88: 
89:     private final Set<LocalBufferPool> resizableBufferPools = new HashSet<>();
90: 
91:     private int numTotalRequiredBuffers;
92: 
