486:     @Test
487:     void testEmitRecordExpandsLastBuffer() throws IOException {
488:         int recordSize = 10;
489:         int maxBufferSize = 2 * recordSize;
490:         // create a pool with just 1 buffer - so that the test times out in case of back-pressure
491:         NetworkBufferPool globalPool = new NetworkBufferPool(1, maxBufferSize);
492:         BufferPool localPool = globalPool.createBufferPool(1, 1, 1, 1, Integer.MAX_VALUE, 0);
493:         ResultPartition resultPartition =
494:                 new ResultPartitionBuilder().setBufferPoolFactory(() -> localPool).build();
495:         resultPartition.setup();
496:         // emulate BufferDebloater - and suggest small buffer size
497:         resultPartition
498:                 .createSubpartitionView(
499:                         new ResultSubpartitionIndexSet(0), (ResultSubpartitionView view) -> {})
500:                 .notifyNewBufferSize(1);
501:         // need to insert two records: the 1st one expands the buffer regardless of back-pressure
502:         resultPartition.emitRecord(ByteBuffer.allocate(recordSize), 0);
503:         // insert the 2nd record:
504:         // - the buffer should still be available for writing after the previous record
505:         // - it should be resized again to fit the new record fully
506:         // - so no new buffer is necessary and there is no back-pressure
507:         resultPartition.emitRecord(ByteBuffer.allocate(recordSize), 0);
508:     }
