579:         subpartition1.bufferSize(6);
580: 
581:         // and: Add the buffer.
582:         bufferWritingResultPartition.emitRecord(ByteBuffer.allocate(2), 0);
583:         bufferWritingResultPartition.emitRecord(ByteBuffer.allocate(10), 0);
584:         bufferWritingResultPartition.emitRecord(ByteBuffer.allocate(2), 1);
585:         bufferWritingResultPartition.emitRecord(ByteBuffer.allocate(10), 1);
586: 
587:         // then: The buffer is less or equal to configured.
588:         assertThat(subpartition0.pollBuffer().buffer().getSize()).isEqualTo(10);
589:         assertThat(subpartition0.pollBuffer().buffer().getSize()).isEqualTo(2);
590:         assertThat(subpartition1.pollBuffer().buffer().getSize()).isEqualTo(6);
591:         assertThat(subpartition1.pollBuffer().buffer().getSize()).isEqualTo(6);
592: 
593:         // when: Reset the buffer size.
594:         subpartition0.bufferSize(13);
595:         subpartition1.bufferSize(5);
596: 
597:         // and: Add the buffer.
598:         bufferWritingResultPartition.emitRecord(ByteBuffer.allocate(12), 0);
599:         bufferWritingResultPartition.emitRecord(ByteBuffer.allocate(8), 0);
600:         bufferWritingResultPartition.emitRecord(ByteBuffer.allocate(2), 1);
601:         bufferWritingResultPartition.emitRecord(ByteBuffer.allocate(7), 1);
602: 
603:         // then: The buffer less or equal to configured.
604:         // 8 bytes which fitted to the previous unfinished buffer(10 - 2).
605:         assertThat(subpartition0.pollBuffer().buffer().getSize()).isEqualTo(8);
606:         // 12 rest bytes which fitted to a new buffer which has 13 bytes.
607:         assertThat(subpartition0.pollBuffer().buffer().getSize()).isEqualTo(12);
608:         assertThat(subpartition1.pollBuffer().buffer().getSize()).isEqualTo(5);
609:         assertThat(subpartition1.pollBuffer().buffer().getSize()).isEqualTo(4);
