522:     private boolean readAndEmitData(ResultSubpartitionView view, SortMergeResultPartition partition)
523:             throws Exception {
524:         MemorySegment segment = MemorySegmentFactory.allocateUnpooledSegment(bufferSize);
525:         ResultSubpartition.BufferAndBacklog buffer;
526:         do {
527:             buffer = view.getNextBuffer();
528:             if (buffer != null) {
529:                 Buffer data = ((CompositeBuffer) buffer.buffer()).getFullBufferData(segment);
530:                 partition.emitRecord(data.getNioBufferReadable(), 0);
531:                 if (!data.isRecycled()) {
532:                     data.recycleBuffer();
533:                 }
534:                 return buffer.buffer().isBuffer();
535:             }
536:         } while (true);
537:     }
