56:     /** Create latency tracking state if enabled. */
57:     public static <K, N, V, S extends State>
58:             InternalKvState<K, N, ?> createStateAndWrapWithLatencyTrackingIfEnabled(
59:                     InternalKvState<K, N, ?> kvState,
60:                     StateDescriptor<S, V> stateDescriptor,
61:                     LatencyTrackingStateConfig latencyTrackingStateConfig)
