630:         ForStOperationUtils.ForStKvStateInfo oldStateInfo =
631:                 kvStateInformation.get(stateDesc.getName());
632: 
633:         TypeSerializer<SV> stateSerializer = stateDesc.getSerializer();
634: 
635:         ForStOperationUtils.ForStKvStateInfo newRocksStateInfo;
636:         RegisteredKeyValueStateBackendMetaInfo<N, SV> newMetaInfo;
637:         if (oldStateInfo != null) {
638:             @SuppressWarnings("unchecked")
