742:     /**
743:      * Migrate only the state value, that is the "value" that is stored in ForSt. We don't migrate
744:      * the key here, which is made up of key group, key, namespace and map key (in case of
745:      * MapState).
746:      */
747:     @SuppressWarnings("unchecked")
748:     private <N, S extends State, SV> void migrateStateValues(
749:             StateDescriptor<S, SV> stateDesc,
750:             Tuple2<ColumnFamilyHandle, RegisteredKeyValueStateBackendMetaInfo<N, SV>> stateMetaInfo)
751:             throws Exception {
752: 
753:         if (stateDesc.getType() == StateDescriptor.Type.MAP) {
754:             TypeSerializerSnapshot<SV> previousSerializerSnapshot =
755:                     stateMetaInfo.f1.getPreviousStateSerializerSnapshot();
756:             checkState(
757:                     previousSerializerSnapshot != null,
758:                     "the previous serializer snapshot should exist.");
759:             checkState(
760:                     previousSerializerSnapshot instanceof MapSerializerSnapshot,
761:                     "previous serializer snapshot should be a MapSerializerSnapshot.");
762: 
763:             TypeSerializer<SV> newSerializer = stateMetaInfo.f1.getStateSerializer();
764:             checkState(
765:                     newSerializer instanceof MapSerializer,
766:                     "new serializer should be a MapSerializer.");
767: 
768:             MapSerializer<?, ?> mapSerializer = (MapSerializer<?, ?>) newSerializer;
769:             MapSerializerSnapshot<?, ?> mapSerializerSnapshot =
770:                     (MapSerializerSnapshot<?, ?>) previousSerializerSnapshot;
771:             if (!checkMapStateKeySchemaCompatibility(mapSerializerSnapshot, mapSerializer)) {
772:                 throw new StateMigrationException(
773:                         "The new serializer for a MapState requires state migration in order for the job to proceed, since the key schema has changed. However, migration for MapState currently only allows value schema evolutions.");
774:             }
775:         }
776: 
777:         LOG.info(
778:                 "Performing state migration for state {} because the state serializer's schema, i.e. serialization format, has changed.",
779:                 stateDesc);
780: 
781:         // we need to get an actual state instance because migration is different
782:         // for different state types. For example, ListState needs to deal with
783:         // individual elements
784:         State state = createState(stateDesc, stateMetaInfo);
785:         if (!(state instanceof AbstractForStSyncState)) {
786:             throw new FlinkRuntimeException(
787:                     "State should be an AbstractForStSyncState but is " + state);
788:         }
789: 
790:         @SuppressWarnings("unchecked")
791:         AbstractForStSyncState<?, ?, SV> forStState = (AbstractForStSyncState<?, ?, SV>) state;
792: 
793:         Snapshot forstSnapshot = db.getSnapshot();
794:         try (ForStIteratorWrapper iterator =
795:                         ForStOperationUtils.getForStIterator(db, stateMetaInfo.f0, readOptions);
796:                 ForStDBWriteBatchWrapper batchWriter =
797:                         new ForStDBWriteBatchWrapper(db, getWriteOptions(), getWriteBatchSize());
798:                 Closeable ignored =
799:                         cancelStreamRegistry.registerCloseableTemporarily(
800:                                 writeBatchWrapper.getCancelCloseable())) {
801:             iterator.seekToFirst();
802: 
803:             DataInputDeserializer serializedValueInput = new DataInputDeserializer();
804:             DataOutputSerializer migratedSerializedValueOutput = new DataOutputSerializer(512);
805:             while (iterator.isValid()) {
806:                 serializedValueInput.setBuffer(iterator.value());
807: 
808:                 forStState.migrateSerializedValue(
809:                         serializedValueInput,
810:                         migratedSerializedValueOutput,
811:                         stateMetaInfo.f1.getPreviousStateSerializer(),
812:                         stateMetaInfo.f1.getStateSerializer());
813: 
814:                 batchWriter.put(
815:                         stateMetaInfo.f0,
816:                         iterator.key(),
817:                         migratedSerializedValueOutput.getCopyOfBuffer());
818: 
819:                 migratedSerializedValueOutput.clear();
820:                 iterator.next();
821:             }
822:         } finally {
823:             db.releaseSnapshot(forstSnapshot);
824:             forstSnapshot.close();
825:         }
826:     }
