828:     @SuppressWarnings("unchecked")
829:     private static <UK> boolean checkMapStateKeySchemaCompatibility(
830:             MapSerializerSnapshot<?, ?> mapStateSerializerSnapshot,
831:             MapSerializer<?, ?> newMapStateSerializer) {
832:         TypeSerializerSnapshot<UK> previousKeySerializerSnapshot =
833:                 (TypeSerializerSnapshot<UK>) mapStateSerializerSnapshot.getKeySerializerSnapshot();
834:         TypeSerializer<UK> newUserKeySerializer =
835:                 (TypeSerializer<UK>) newMapStateSerializer.getKeySerializer();
836: 
837:         TypeSerializerSchemaCompatibility<UK> keyCompatibility =
838:                 newUserKeySerializer
839:                         .snapshotConfiguration()
840:                         .resolveSchemaCompatibility(previousKeySerializerSnapshot);
841:         return keyCompatibility.isCompatibleAsIs();
