878:     private <N, SV, S extends State, IS extends S> IS createState(
879:             StateDescriptor<S, SV> stateDesc,
880:             Tuple2<ColumnFamilyHandle, RegisteredKeyValueStateBackendMetaInfo<N, SV>>
881:                     registerResult)
882:             throws Exception {
883:         @SuppressWarnings("unchecked")
884:         IS createdState = (IS) createdKVStates.get(stateDesc.getName());
885:         if (createdState == null) {
886:             StateCreateFactory stateCreateFactory = STATE_CREATE_FACTORIES.get(stateDesc.getType());
887:             if (stateCreateFactory == null) {
888:                 throw new FlinkRuntimeException(stateNotSupportedMessage(stateDesc));
889:             }
890:             createdState =
891:                     stateCreateFactory.createState(
892:                             stateDesc, registerResult, ForStSyncKeyedStateBackend.this);
893:         } else {
894:             StateUpdateFactory stateUpdateFactory = STATE_UPDATE_FACTORIES.get(stateDesc.getType());
895:             if (stateUpdateFactory == null) {
896:                 throw new FlinkRuntimeException(stateNotSupportedMessage(stateDesc));
897:             }
898:             createdState = stateUpdateFactory.updateState(stateDesc, registerResult, createdState);
899:         }
900: 
901:         createdKVStates.put(stateDesc.getName(), createdState);
902:         return createdState;
903:     }
