341:     private void lazyInitializeForJob(
342:             Environment env, @SuppressWarnings("unused") String operatorIdentifier)
343:             throws IOException {
344: 
345:         if (isInitialized) {
346:             return;
347:         }
348: 
349:         this.jobId = env.getJobID();
350: 
351:         // initialize the paths where the local ForSt files should be stored
352:         if (localForStDirectories == null) {
353:             initializedDbBasePaths = new File[] {env.getTaskManagerInfo().getTmpWorkingDirectory()};
354:         } else {
355:             List<File> dirs = new ArrayList<>(localForStDirectories.length);
356:             StringBuilder errorMessage = new StringBuilder();
357: 
358:             for (File f : localForStDirectories) {
359:                 File testDir = new File(f, UUID.randomUUID().toString());
360:                 if (!testDir.mkdirs()) {
361:                     String msg =
362:                             "Local DB files directory '"
363:                                     + f
364:                                     + "' does not exist and cannot be created. ";
365:                     LOG.error(msg);
366:                     errorMessage.append(msg);
367:                 } else {
368:                     dirs.add(f);
369:                 }
370:                 //noinspection ResultOfMethodCallIgnored
371:                 testDir.delete();
372:             }
373: 
374:             if (dirs.isEmpty()) {
375:                 throw new IOException("No local storage directories available. " + errorMessage);
376:             } else {
377:                 initializedDbBasePaths = dirs.toArray(new File[0]);
378:             }
379:         }
380: 
381:         nextDirectory = new Random().nextInt(initializedDbBasePaths.length);
382: 
383:         isInitialized = true;
384:     }
385: 
386:     private File getNextStoragePath() {
387:         int ni = nextDirectory + 1;
388:         ni = ni >= initializedDbBasePaths.length ? 0 : ni;
389:         nextDirectory = ni;
390: 
391:         return initializedDbBasePaths[ni];
392:     }
