403:     @Override
404:     public <K> ForStKeyedStateBackend<K> createAsyncKeyedStateBackend(
405:             KeyedStateBackendParameters<K> parameters) throws IOException {
406:         Environment env = parameters.getEnv();
407: 
408:         // first, make sure that the ForSt JNI library is loaded
409:         // we do this explicitly here to have better error handling
410:         String tempDir = env.getTaskManagerInfo().getTmpWorkingDirectory().getAbsolutePath();
411:         ensureForStIsLoaded(tempDir, env.getAsyncOperationsThreadPool());
412: 
413:         // replace all characters that are not legal for filenames with underscore
414:         String fileCompatibleIdentifier =
415:                 parameters.getOperatorIdentifier().replaceAll("[^a-zA-Z0-9\\-]", "_");
416: 
417:         lazyInitializeForJob(env, fileCompatibleIdentifier);
418: 
419:         Tuple2<Path, Path> localAndRemoteBasePath = getForStBasePath(fileCompatibleIdentifier, env);
420: 
421:         final OpaqueMemoryResource<ForStSharedResources> sharedResources =
422:                 ForStOperationUtils.allocateSharedCachesIfConfigured(
423:                         memoryConfiguration,
424:                         env,
425:                         parameters.getManagedMemoryFraction(),
426:                         LOG,
427:                         forStMemoryFactory);
428:         if (sharedResources != null) {
429:             LOG.info("Obtained shared ForSt cache of size {} bytes", sharedResources.getSize());
430:         }
431:         final ForStResourceContainer resourceContainer =
432:                 createOptionsAndResourceContainer(
433:                         sharedResources,
434:                         localAndRemoteBasePath.f0,
435:                         localAndRemoteBasePath.f1,
436:                         env.getCheckpointStorageAccess(),
437:                         parameters.getMetricGroup(),
438:                         nativeMetricOptions.isStatisticsEnabled());
439: 
440:         ForStKeyedStateBackendBuilder<K> builder =
441:                 new ForStKeyedStateBackendBuilder<>(
442:                                 parameters.getOperatorIdentifier(),
443:                                 env.getUserCodeClassLoader().asClassLoader(),
444:                                 resourceContainer,
445:                                 stateName -> resourceContainer.getColumnOptions(),
446:                                 parameters.getKeySerializer(),
447:                                 parameters.getNumberOfKeyGroups(),
448:                                 parameters.getKeyGroupRange(),
449:                                 env.getExecutionConfig(),
450:                                 priorityQueueConfig,
451:                                 parameters.getTtlTimeProvider(),
452:                                 parameters.getMetricGroup(),
453:                                 parameters.getCustomInitializationMetrics(),
454:                                 parameters.getStateHandles(),
455:                                 parameters.getCancelStreamRegistry())
456:                         // TODO: remove after support more snapshot strategy
457:                         .setEnableIncrementalCheckpointing(true)
458:                         .setNativeMetricOptions(
459:                                 resourceContainer.getMemoryWatcherOptions(nativeMetricOptions))
460:                         .setOverlapFractionThreshold(
461:                                 overlapFractionThreshold == UNDEFINED_OVERLAP_FRACTION_THRESHOLD
462:                                         ? RESTORE_OVERLAP_FRACTION_THRESHOLD.defaultValue()
463:                                         : overlapFractionThreshold)
464:                         .setUseIngestDbRestoreMode(
465:                                 useIngestDbRestoreMode.getOrDefault(
466:                                         USE_INGEST_DB_RESTORE_MODE.defaultValue()))
467:                         .setRescalingUseDeleteFilesInRange(
468:                                 rescalingUseDeleteFilesInRange.getOrDefault(
469:                                         USE_DELETE_FILES_IN_RANGE_DURING_RESCALING.defaultValue()))
470:                         .setRecoveryClaimMode(recoveryClaimMode);
471: 
472:         return builder.build();
473:     }
