475:     @Override
476:     public <K> AbstractKeyedStateBackend<K> createKeyedStateBackend(
477:             KeyedStateBackendParameters<K> parameters) throws IOException {
478:         Environment env = parameters.getEnv();
479: 
480:         // first, make sure that the RocksDB JNI library is loaded
481:         // we do this explicitly here to have better error handling
482:         String tempDir = env.getTaskManagerInfo().getTmpWorkingDirectory().getAbsolutePath();
483:         ensureForStIsLoaded(tempDir, env.getAsyncOperationsThreadPool());
484: 
485:         // replace all characters that are not legal for filenames with underscore
486:         String fileCompatibleIdentifier =
487:                 parameters.getOperatorIdentifier().replaceAll("[^a-zA-Z0-9\\-]", "_");
488: 
489:         lazyInitializeForJob(env, fileCompatibleIdentifier);
490: 
491:         Tuple2<Path, Path> localAndRemoteBasePath = getForStBasePath(fileCompatibleIdentifier, env);
492: 
493:         LocalRecoveryConfig localRecoveryConfig =
494:                 env.getTaskStateManager().createLocalRecoveryConfig();
495: 
496:         final OpaqueMemoryResource<ForStSharedResources> sharedResources =
497:                 ForStOperationUtils.allocateSharedCachesIfConfigured(
498:                         memoryConfiguration,
499:                         env,
500:                         parameters.getManagedMemoryFraction(),
501:                         LOG,
502:                         forStMemoryFactory);
503:         if (sharedResources != null) {
504:             LOG.info("Obtained shared RocksDB cache of size {} bytes", sharedResources.getSize());
505:         }
506:         final ForStResourceContainer resourceContainer =
507:                 createOptionsAndResourceContainer(
508:                         sharedResources,
509:                         localAndRemoteBasePath.f0,
510:                         forceSyncLocal ? null : localAndRemoteBasePath.f1,
511:                         env.getCheckpointStorageAccess(),
512:                         parameters.getMetricGroup(),
513:                         nativeMetricOptions.isStatisticsEnabled());
514: 
515:         ExecutionConfig executionConfig = env.getExecutionConfig();
516:         StreamCompressionDecorator keyGroupCompressionDecorator =
517:                 getCompressionDecorator(executionConfig);
518: 
519:         MetricsTrackingStateConfig latencyTrackingStateConfig =
520:                 latencyTrackingConfigBuilder.setMetricGroup(parameters.getMetricGroup()).build();
521:         ForStSyncKeyedStateBackendBuilder<K> builder =
522:                 new ForStSyncKeyedStateBackendBuilder<>(
523:                                 parameters.getOperatorIdentifier(),
524:                                 env.getUserCodeClassLoader().asClassLoader(),
525:                                 resourceContainer,
526:                                 stateName -> resourceContainer.getColumnOptions(),
527:                                 parameters.getKvStateRegistry(),
528:                                 parameters.getKeySerializer(),
529:                                 parameters.getNumberOfKeyGroups(),
530:                                 parameters.getKeyGroupRange(),
531:                                 executionConfig,
532:                                 localRecoveryConfig,
533:                                 priorityQueueConfig,
534:                                 parameters.getTtlTimeProvider(),
535:                                 latencyTrackingStateConfig,
536:                                 parameters.getMetricGroup(),
537:                                 parameters.getCustomInitializationMetrics(),
538:                                 parameters.getStateHandles(),
539:                                 keyGroupCompressionDecorator,
540:                                 parameters.getCancelStreamRegistry())
541:                         .setEnableIncrementalCheckpointing(isIncrementalCheckpointsEnabled())
542:                         .setNativeMetricOptions(
543:                                 resourceContainer.getMemoryWatcherOptions(nativeMetricOptions))
544:                         .setOverlapFractionThreshold(
545:                                 overlapFractionThreshold == UNDEFINED_OVERLAP_FRACTION_THRESHOLD
546:                                         ? RESTORE_OVERLAP_FRACTION_THRESHOLD.defaultValue()
547:                                         : overlapFractionThreshold)
548:                         .setUseIngestDbRestoreMode(
549:                                 useIngestDbRestoreMode.getOrDefault(
550:                                         USE_INGEST_DB_RESTORE_MODE.defaultValue()))
551:                         .setRescalingUseDeleteFilesInRange(
552:                                 rescalingUseDeleteFilesInRange.getOrDefault(
553:                                         USE_DELETE_FILES_IN_RANGE_DURING_RESCALING.defaultValue()))
554:                         .setRecoveryClaimMode(recoveryClaimMode);
555:         return builder.build();
556:     }
