657:     /**
658:      * Sets the local directories in which the ForSt database puts some files (like metadata files).
659:      * These directories do not need to be persistent, they can be ephemeral, meaning that they are
660:      * lost on a machine failure, because state in ForSt is persisted in checkpoints.
661:      *
662:      * <p>If nothing is configured, these directories default to the TaskManager's local temporary
663:      * file directories.
664:      *
665:      * <p>Each distinct state will be stored in one path, but when the state backend creates
666:      * multiple states, they will store their files on different paths.
667:      *
668:      * <p>Passing {@code null} to this function restores the default behavior, where the configured
669:      * temp directories will be used.
670:      *
671:      * @param paths The paths across which the local ForSt database files will be spread.
672:      */
673:     public void setLocalDbStoragePaths(String... paths) {
674:         if (paths == null) {
675:             localForStDirectories = null;
676:         } else if (paths.length == 0) {
677:             throw new IllegalArgumentException("empty paths");
678:         } else {
679:             File[] pp = new File[paths.length];
680: 
681:             for (int i = 0; i < paths.length; i++) {
682:                 final String rawPath = paths[i];
683:                 final String path;
684: 
685:                 if (rawPath == null) {
686:                     throw new IllegalArgumentException("null path");
687:                 } else {
688:                     // we need this for backwards compatibility, to allow URIs like 'file:///'...
689:                     URI uri = null;
690:                     try {
691:                         uri = new Path(rawPath).toUri();
692:                     } catch (Exception e) {
693:                         // cannot parse as a path
694:                     }
695: 
696:                     if (uri != null && uri.getScheme() != null) {
697:                         if ("file".equalsIgnoreCase(uri.getScheme())) {
698:                             path = uri.getPath();
699:                         } else {
700:                             throw new IllegalArgumentException(
701:                                     "Path " + rawPath + " has a non-local scheme");
702:                         }
703:                     } else {
704:                         path = rawPath;
705:                     }
706:                 }
707: 
708:                 pp[i] = new File(path);
709:                 if (!pp[i].isAbsolute()) {
710:                     throw new IllegalArgumentException("Relative paths are not supported");
711:                 }
712:             }
713: 
714:             localForStDirectories = pp;
715:         }
716:     }
