872:     @VisibleForTesting
873:     static void ensureForStIsLoaded(
874:             String tempDirectory,
875:             Supplier<NativeLibraryLoader> nativeLibraryLoaderSupplier,
876:             Executor executor)
877:             throws IOException {
878:         synchronized (ForStStateBackend.class) {
879:             if (!forStInitialized) {
880: 
881:                 final File tempDirParent = new File(tempDirectory).getAbsoluteFile();
882:                 LOG.info(
883:                         "Attempting to load ForSt native library and store it under '{}'",
884:                         tempDirParent);
885: 
886:                 Throwable lastException = null;
887:                 for (int attempt = 1; attempt <= FORST_LIB_LOADING_ATTEMPTS; attempt++) {
888:                     AtomicReference<File> rocksLibFolder = new AtomicReference<>(null);
889:                     try {
890:                         // when multiple instances of this class and ForSt exist in different
891:                         // class loaders, then we can see the following exception:
892:                         // "java.lang.UnsatisfiedLinkError: Native Library
893:                         // /path/to/temp/dir/librocksdbjni-linux64.so
894:                         // already loaded in another class loader"
895: 
896:                         // to avoid that, we need to add a random element to the library file path
897:                         // (I know, seems like an unnecessary hack, since the JVM obviously can
898:                         // handle multiple
899:                         //  instances of the same JNI library being loaded in different class
900:                         // loaders, but
901:                         //  apparently not when coming from the same file path, so there we go)
902: 
903:                         // We use an async procedure to load the library, to make current thread be
904:                         // able to interrupt for a fast quit.
905:                         CompletableFuture<Void> future =
906:                                 FutureUtils.runAsync(
907:                                         () -> {
908:                                             File libFolder =
909:                                                     new File(
910:                                                             tempDirParent,
911:                                                             "rocksdb-lib-" + new AbstractID());
912:                                             rocksLibFolder.set(libFolder);
913: 
914:                                             // make sure the temp path exists
915:                                             LOG.debug(
916:                                                     "Attempting to create ForSt native library folder {}",
917:                                                     libFolder);
918:                                             // noinspection ResultOfMethodCallIgnored
919:                                             libFolder.mkdirs();
920: 
921:                                             // explicitly load the JNI dependency if it has not been
922:                                             // loaded before
923:                                             nativeLibraryLoaderSupplier
924:                                                     .get()
925:                                                     .loadLibrary(libFolder.getAbsolutePath());
926: 
927:                                             // this initialization here should validate that the
928:                                             // loading succeeded
929:                                             RocksDB.loadLibrary();
930:                                         },
931:                                         executor);
932: 
933:                         // wait for finish or be interrupted.
934:                         future.get();
935: 
936:                         // seems to have worked
937:                         LOG.info("Successfully loaded ForSt native library");
938:                         forStInitialized = true;
939:                         return;
940:                     } catch (Throwable t) {
941:                         lastException = t;
942:                         LOG.debug("ForSt JNI library loading attempt {} failed", attempt, t);
943: 
944:                         // try to force ForSt to attempt reloading the library
945:                         try {
946:                             resetForStLoadedFlag();
947:                         } catch (Throwable tt) {
948:                             LOG.debug(
949:                                     "Failed to reset 'initialized' flag in ForSt native code loader",
950:                                     tt);
951:                         }
952: 
953:                         FileUtils.deleteDirectoryQuietly(rocksLibFolder.get());
954:                     }
955:                 }
956: 
957:                 throw new IOException("Could not load the native ForSt library", lastException);
958:             }
959:         }
960:     }
961: 
962:     @VisibleForTesting
963:     static void resetForStLoadedFlag() throws Exception {
964:         final Field initField = NativeLibraryLoader.class.getDeclaredField("initialized");
965:         initField.setAccessible(true);
966:         initField.setBoolean(null, false);
967:     }
