229:         this.overlapFractionThreshold = UNDEFINED_OVERLAP_FRACTION_THRESHOLD;
230:         this.rocksDBMemoryFactory = RocksDBMemoryFactory.DEFAULT;
231:         this.priorityQueueConfig = new RocksDBPriorityQueueConfig();
232:         this.useIngestDbRestoreMode = TernaryBoolean.UNDEFINED;
233:         this.incrementalRestoreAsyncCompactAfterRescale = TernaryBoolean.UNDEFINED;
