554:     private RocksDBOptionsFactory configureOptionsFactory(
555:             @Nullable RocksDBOptionsFactory originalOptionsFactory,
556:             @Nullable String factoryClassName,
557:             ReadableConfig config,
558:             ClassLoader classLoader)
559:             throws DynamicCodeLoadingException {
560: 
561:         RocksDBOptionsFactory optionsFactory = null;
562: 
563:         if (originalOptionsFactory != null) {
564:             if (originalOptionsFactory instanceof ConfigurableRocksDBOptionsFactory) {
565:                 originalOptionsFactory =
566:                         ((ConfigurableRocksDBOptionsFactory) originalOptionsFactory)
567:                                 .configure(config);
568:             }
569:             LOG.info("Using application-defined options factory: {}.", originalOptionsFactory);
570: 
571:             optionsFactory = originalOptionsFactory;
572:         } else if (factoryClassName != null) {
573:             // Do nothing if user does not define any factory class.
574:             try {
575:                 Class<? extends RocksDBOptionsFactory> clazz =
576:                         Class.forName(factoryClassName, false, classLoader)
577:                                 .asSubclass(RocksDBOptionsFactory.class);
578: 
579:                 optionsFactory = clazz.newInstance();
580:                 if (optionsFactory instanceof ConfigurableRocksDBOptionsFactory) {
581:                     optionsFactory =
582:                             ((ConfigurableRocksDBOptionsFactory) optionsFactory).configure(config);
583:                 }
584:                 LOG.info("Using configured options factory: {}.", optionsFactory);
585: 
586:             } catch (ClassNotFoundException e) {
587:                 throw new DynamicCodeLoadingException(
588:                         "Cannot find configured options factory class: " + factoryClassName, e);
589:             } catch (ClassCastException | InstantiationException | IllegalAccessException e) {
590:                 throw new DynamicCodeLoadingException(
591:                         "The class configured under '"
592:                                 + RocksDBOptions.OPTIONS_FACTORY.key()
593:                                 + "' is not a valid options factory ("
594:                                 + factoryClassName
595:                                 + ')',
596:                         e);
597:             }
598:         }
599:         return optionsFactory;
600:     }
