614:     /**
615:      * Sets the path where the RocksDB local database files should be stored on the local file
616:      * system. Setting this path overrides the default behavior, where the files are stored across
617:      * the configured temp directories.
618:      *
619:      * <p>Passing {@code null} to this function restores the default behavior, where the configured
620:      * temp directories will be used.
621:      *
622:      * @param path The path where the local RocksDB database files are stored.
623:      */
624:     public void setDbStoragePath(String path) {
625:         setDbStoragePaths(path == null ? null : new String[] {path});
626:     }
