1587:     /**
1588:      * Tests {@link ValueState#value()} and {@link InternalKvState#getSerializedValue(byte[],
1589:      * TypeSerializer, TypeSerializer, TypeSerializer)} accessing the state concurrently. They
1590:      * should not get in the way of each other.
1591:      */
1592:     @TestTemplate
1593:     @SuppressWarnings("unchecked")
1594:     void testValueStateRace() throws Exception {
1595:         final Integer namespace = 1;
1596: 
1597:         final ValueStateDescriptor<String> kvId = new ValueStateDescriptor<>("id", String.class);
1598: 
1599:         final TypeSerializer<Integer> keySerializer = IntSerializer.INSTANCE;
1600:         final TypeSerializer<Integer> namespaceSerializer = IntSerializer.INSTANCE;
1601: 
1602:         final CheckpointableKeyedStateBackend<Integer> backend =
1603:                 createKeyedBackend(IntSerializer.INSTANCE);
1604:         try {
1605:             final ValueState<String> state =
1606:                     backend.getPartitionedState(namespace, IntSerializer.INSTANCE, kvId);
1607: 
1608:             // this is only available after the backend initialized the serializer
1609:             final TypeSerializer<String> valueSerializer = kvId.getSerializer();
1610: 
1611:             @SuppressWarnings("unchecked")
1612:             final InternalKvState<Integer, Integer, String> kvState =
1613:                     (InternalKvState<Integer, Integer, String>) state;
1614: 
1615:             /**
1616:              * 1) Test that ValueState#value() before and after KvState#getSerializedValue(byte[])
1617:              * return the same value.
1618:              */
1619: 
1620:             // set some key and namespace
1621:             final int key1 = 1;
1622:             backend.setCurrentKey(key1);
1623:             kvState.setCurrentNamespace(2);
1624:             state.update("2");
1625:             assertThat(state.value()).isEqualTo("2");
1626: 
1627:             // query another key and namespace
1628:             assertThat(
1629:                             getSerializedValue(
1630:                                     kvState,
1631:                                     3,
1632:                                     keySerializer,
1633:                                     namespace,
1634:                                     IntSerializer.INSTANCE,
1635:                                     valueSerializer))
1636:                     .isNull();
1637: 
1638:             // the state should not have changed!
1639:             assertThat(state.value()).isEqualTo("2");
1640: 
1641:             // re-set values
1642:             kvState.setCurrentNamespace(namespace);
1643: 
1644:             /**
1645:              * 2) Test two threads concurrently using ValueState#value() and
1646:              * KvState#getSerializedValue(byte[]).
1647:              */
1648: 
1649:             // some modifications to the state
1650:             final int key2 = 10;
1651:             backend.setCurrentKey(key2);
1652:             assertThat(state.value()).isNull();
1653:             assertThat(
1654:                             getSerializedValue(
1655:                                     kvState,
1656:                                     key2,
1657:                                     keySerializer,
1658:                                     namespace,
1659:                                     namespaceSerializer,
1660:                                     valueSerializer))
1661:                     .isNull();
1662:             state.update("1");
1663: 
1664:             final CheckedThread getter =
1665:                     new CheckedThread("State getter") {
1666:                         @Override
1667:                         public void go() throws Exception {
1668:                             while (!isInterrupted()) {
1669:                                 assertThat(state.value()).isEqualTo("1");
1670:                             }
1671:                         }
1672:                     };
1673: 
1674:             final CheckedThread serializedGetter =
1675:                     new CheckedThread("Serialized state getter") {
1676:                         @Override
1677:                         public void go() throws Exception {
1678:                             while (!isInterrupted() && getter.isAlive()) {
1679:                                 final String serializedValue =
1680:                                         getSerializedValue(
1681:                                                 kvState,
1682:                                                 key2,
1683:                                                 keySerializer,
1684:                                                 namespace,
1685:                                                 namespaceSerializer,
1686:                                                 valueSerializer);
1687:                                 assertThat(serializedValue).isEqualTo("1");
1688:                             }
1689:                         }
1690:                     };
1691: 
1692:             getter.start();
1693:             serializedGetter.start();
1694: 
1695:             // run both threads for max 100ms
1696:             Timer t = new Timer("stopper");
1697:             t.schedule(
1698:                     new TimerTask() {
1699:                         @Override
1700:                         public void run() {
1701:                             getter.interrupt();
1702:                             serializedGetter.interrupt();
1703:                             this.cancel();
1704:                         }
1705:                     },
1706:                     100);
1707: 
1708:             // wait for both threads to finish
1709:             // serializedGetter will finish if its assertion fails or if
1710:             // getter is not alive any more
1711:             serializedGetter.sync();
1712:             // if serializedGetter crashed, getter will not know -> interrupt just in case
1713:             getter.interrupt();
1714:             getter.sync();
1715:             t.cancel(); // if not executed yet
1716:         } finally {
1717:             // clean up
1718:             IOUtils.closeQuietly(backend);
1719:             backend.dispose();
1720:         }
1721:     }
