5256:     protected Future<SnapshotResult<KeyedStateHandle>> runSnapshotAsync(
5257:             ExecutorService executorService,
5258:             RunnableFuture<SnapshotResult<KeyedStateHandle>> snapshotRunnableFuture)
5259:             throws Exception {
5260: 
5261:         if (!snapshotRunnableFuture.isDone()) {
5262:             CompletableFuture<SnapshotResult<KeyedStateHandle>> completableFuture =
5263:                     new CompletableFuture<>();
5264:             executorService.submit(
5265:                     () -> {
5266:                         try {
5267:                             snapshotRunnableFuture.run();
5268:                             completableFuture.complete(snapshotRunnableFuture.get());
5269:                         } catch (Exception e) {
5270:                             completableFuture.completeExceptionally(e);
5271:                         }
5272:                     });
5273:             return completableFuture;
5274:         }
5275:         return CompletableFuture.completedFuture(snapshotRunnableFuture.get());
5276:     }
