340:     void testKeyGroupedInternalPriorityQueue(boolean addAll) throws Exception {
341:         String fieldName = "key-grouped-priority-queue";
342:         CheckpointableKeyedStateBackend<Integer> backend =
343:                 createKeyedBackend(IntSerializer.INSTANCE);
344:         try {
345:             KeyGroupedInternalPriorityQueue<TestType> priorityQueue =
346:                     backend.create(fieldName, new TestType.V1TestTypeSerializer());
347: 
348:             TestType elementA42 = new TestType("a", 42);
349:             TestType elementA44 = new TestType("a", 44);
350:             TestType elementB1 = new TestType("b", 1);
351:             TestType elementB3 = new TestType("b", 3);
352: 
353:             TestType[] elements = {
354:                 elementA44, elementB1, elementB1, elementB3, elementA42,
355:             };
356: 
357:             if (addAll) {
358:                 priorityQueue.addAll(asList(elements));
359:             } else {
360:                 assertThat(priorityQueue.add(elements[0])).isTrue();
361:                 assertThat(priorityQueue.add(elements[1])).isTrue();
362:                 assertThat(priorityQueue.add(elements[2])).isFalse();
363:                 assertThat(priorityQueue.add(elements[3])).isFalse();
364:                 assertThat(priorityQueue.add(elements[4])).isFalse();
365:             }
366:             assertThat(priorityQueue.isEmpty()).isFalse();
367:             assertThat(priorityQueue.getSubsetForKeyGroup(1))
368:                     .containsExactlyInAnyOrder(elementA42, elementA44);
369:             assertThat(priorityQueue.getSubsetForKeyGroup(8))
370:                     .containsExactlyInAnyOrder(elementB1, elementB3);
371: 
372:             assertThat(priorityQueue.peek()).isEqualTo(elementB1);
373:             assertThat(priorityQueue.poll()).isEqualTo(elementB1);
374:             assertThat(priorityQueue.peek()).isEqualTo(elementB3);
375: 
376:             List<TestType> actualList = new ArrayList<>();
377:             try (CloseableIterator<TestType> iterator = priorityQueue.iterator()) {
378:                 iterator.forEachRemaining(actualList::add);
379:             }
380: 
381:             assertThat(actualList).containsExactlyInAnyOrder(elementB3, elementA42, elementA44);
382: 
383:             assertThat(priorityQueue.size()).isEqualTo(3);
384: 
385:             assertThat(priorityQueue.remove(elementB1)).isFalse();
386:             assertThat(priorityQueue.remove(elementB3)).isTrue();
387:             assertThat(priorityQueue.peek()).isEqualTo(elementA42);
388:         } finally {
389:             IOUtils.closeQuietly(backend);
390:             backend.dispose();
391:         }
392:     }
