3949:     private void testKeyGroupSnapshotRestore(
3950:             int sourceParallelism, int targetParallelism, int maxParallelism) throws Exception {
3951:         checkArgument(
3952:                 sourceParallelism > 0,
3953:                 "parallelism must be positive, current is %s.",
3954:                 sourceParallelism);
3955:         checkArgument(
3956:                 targetParallelism > 0,
3957:                 "parallelism must be positive, current is %s.",
3958:                 targetParallelism);
3959:         checkArgument(
3960:                 sourceParallelism <= maxParallelism,
3961:                 "Maximum parallelism must not be smaller than parallelism.");
3962:         checkArgument(
3963:                 targetParallelism <= maxParallelism,
3964:                 "Maximum parallelism must not be smaller than parallelism.");
3965: 
3966:         Random random = new Random();
3967: 
3968:         List<ValueStateDescriptor<String>> stateDescriptors = new ArrayList<>(maxParallelism);
3969:         List<Integer> keyInKeyGroups = new ArrayList<>(maxParallelism);
3970:         List<String> expectedValue = new ArrayList<>(maxParallelism);
3971:         for (int i = 0; i < maxParallelism; ++i) {
3972:             // all states have different name to mock that all the parallelisms of one operator have
3973:             // different states.
3974:             stateDescriptors.add(new ValueStateDescriptor<>("state" + i, String.class));
3975:         }
3976: 
3977:         CheckpointStreamFactory streamFactory = createStreamFactory();
3978:         SharedStateRegistry sharedStateRegistry = new SharedStateRegistryImpl();
3979: 
3980:         List<KeyedStateHandle> snapshots = new ArrayList<>(sourceParallelism);
3981:         for (int i = 0; i < sourceParallelism; ++i) {
3982:             KeyGroupRange range =
3983:                     KeyGroupRange.of(
3984:                             maxParallelism * i / sourceParallelism,
3985:                             maxParallelism * (i + 1) / sourceParallelism - 1);
3986:             CheckpointableKeyedStateBackend<Integer> backend =
3987:                     createKeyedBackend(IntSerializer.INSTANCE, maxParallelism, range, env);
3988:             try {
3989:                 for (int j = range.getStartKeyGroup(); j <= range.getEndKeyGroup(); ++j) {
3990:                     ValueState<String> state =
3991:                             backend.getPartitionedState(
3992:                                     VoidNamespace.INSTANCE,
3993:                                     VoidNamespaceSerializer.INSTANCE,
3994:                                     stateDescriptors.get(j));
3995:                     int keyInKeyGroup =
3996:                             getKeyInKeyGroup(random, maxParallelism, KeyGroupRange.of(j, j));
3997:                     backend.setCurrentKey(keyInKeyGroup);
3998:                     keyInKeyGroups.add(keyInKeyGroup);
3999:                     String updateValue = i + ":" + j;
4000:                     state.update(updateValue);
4001:                     expectedValue.add(updateValue);
4002:                 }
4003: 
4004:                 // snapshot
4005:                 snapshots.add(
4006:                         runSnapshot(
4007:                                 backend.snapshot(
4008:                                         0,
4009:                                         0,
4010:                                         streamFactory,
4011:                                         CheckpointOptions.forCheckpointWithDefaultLocation()),
4012:                                 sharedStateRegistry));
4013:             } finally {
4014:                 IOUtils.closeQuietly(backend);
4015:                 backend.dispose();
4016:             }
4017:         }
4018: 
4019:         // redistribute the stateHandle
4020:         List<KeyGroupRange> keyGroupRangesRestore = new ArrayList<>();
4021:         for (int i = 0; i < targetParallelism; ++i) {
4022:             keyGroupRangesRestore.add(
4023:                     KeyGroupRangeAssignment.computeKeyGroupRangeForOperatorIndex(
4024:                             maxParallelism, targetParallelism, i));
4025:         }
4026:         List<List<KeyedStateHandle>> keyGroupStatesAfterDistribute =
4027:                 new ArrayList<>(targetParallelism);
4028:         for (int i = 0; i < targetParallelism; ++i) {
4029:             List<KeyedStateHandle> keyedStateHandles = new ArrayList<>();
4030:             StateAssignmentOperation.extractIntersectingState(
4031:                     snapshots, keyGroupRangesRestore.get(i), keyedStateHandles);
4032:             keyGroupStatesAfterDistribute.add(keyedStateHandles);
4033:         }
4034: 
4035:         // restore and verify
4036:         for (int i = 0; i < targetParallelism; ++i) {
4037:             CheckpointableKeyedStateBackend<Integer> backend =
4038:                     restoreKeyedBackend(
4039:                             IntSerializer.INSTANCE,
4040:                             maxParallelism,
4041:                             keyGroupRangesRestore.get(i),
4042:                             keyGroupStatesAfterDistribute.get(i),
4043:                             env);
4044:             try {
4045:                 KeyGroupRange range = keyGroupRangesRestore.get(i);
4046:                 for (int j = range.getStartKeyGroup(); j <= range.getEndKeyGroup(); ++j) {
4047:                     ValueState<String> state =
4048:                             backend.getPartitionedState(
4049:                                     VoidNamespace.INSTANCE,
4050:                                     VoidNamespaceSerializer.INSTANCE,
4051:                                     stateDescriptors.get(j));
4052:                     backend.setCurrentKey(keyInKeyGroups.get(j));
4053:                     assertThat(state.value()).isEqualTo(expectedValue.get(j));
4054:                 }
4055:             } finally {
4056:                 IOUtils.closeQuietly(backend);
4057:                 backend.dispose();
4058:             }
4059:         }
4060:     }
