4682:     /**
4683:      * The purpose of this test is to check that parallel snapshots are possible, and work even if a
4684:      * previous snapshot is still running and blocking.
4685:      */
4686:     @TestTemplate
4687:     void testParallelAsyncSnapshots() throws Exception {
4688:         assumeThat(snapshotUsesStreamFactory()).isTrue();
4689:         OneShotLatch blocker = new OneShotLatch();
4690:         OneShotLatch waiter = new OneShotLatch();
4691:         BlockerCheckpointStreamFactory streamFactory =
4692:                 new BlockerCheckpointStreamFactory(1024 * 1024);
4693:         streamFactory.setWaiterLatch(waiter);
4694:         streamFactory.setBlockerLatch(blocker);
4695:         streamFactory.setAfterNumberInvocations(10);
4696: 
4697:         final CheckpointableKeyedStateBackend<Integer> backend =
4698:                 createKeyedBackend(IntSerializer.INSTANCE);
4699: 
4700:         try {
4701: 
4702:             if (!supportsAsynchronousSnapshots()) {
4703:                 return;
4704:             }
4705: 
4706:             // insert some data to the backend.
4707:             InternalValueState<Integer, VoidNamespace, Integer> valueState =
4708:                     backend.createOrUpdateInternalState(
4709:                             VoidNamespaceSerializer.INSTANCE,
4710:                             new ValueStateDescriptor<>("test", IntSerializer.INSTANCE));
4711: 
4712:             valueState.setCurrentNamespace(VoidNamespace.INSTANCE);
4713: 
4714:             for (int i = 0; i < 10; ++i) {
4715:                 backend.setCurrentKey(i);
4716:                 valueState.update(i);
4717:             }
4718: 
4719:             RunnableFuture<SnapshotResult<KeyedStateHandle>> snapshot1 =
4720:                     backend.snapshot(
4721:                             0L,
4722:                             0L,
4723:                             streamFactory,
4724:                             CheckpointOptions.forCheckpointWithDefaultLocation());
4725: 
4726:             Thread runner1 = new Thread(snapshot1, "snapshot-1-runner");
4727:             runner1.start();
4728:             // after this call returns, we have a running snapshot-1 that is blocked in IO.
4729:             waiter.await();
4730: 
4731:             // do some updates in between the snapshots.
4732:             for (int i = 5; i < 15; ++i) {
4733:                 backend.setCurrentKey(i);
4734:                 valueState.update(i + 1);
4735:             }
4736: 
4737:             // we don't want to block the second snapshot.
4738:             streamFactory.setWaiterLatch(null);
4739:             streamFactory.setBlockerLatch(null);
4740: 
4741:             RunnableFuture<SnapshotResult<KeyedStateHandle>> snapshot2 =
4742:                     backend.snapshot(
4743:                             1L,
4744:                             1L,
4745:                             streamFactory,
4746:                             CheckpointOptions.forCheckpointWithDefaultLocation());
4747: 
4748:             Thread runner2 = new Thread(snapshot2, "snapshot-2-runner");
4749:             runner2.start();
4750:             // snapshot-2 should run and succeed, while snapshot-1 is still running and blocked in
4751:             // IO.
4752:             snapshot2.get();
4753: 
4754:             // we release the blocking IO so that snapshot-1 can also finish and succeed.
4755:             blocker.trigger();
4756:             snapshot1.get();
4757: 
4758:         } finally {
4759:             IOUtils.closeQuietly(backend);
4760:             backend.dispose();
4761:         }
4762:     }
