369:         final TypeSerializer<N> namespaceSerializer =
370:                 registeredKeyValueStateBackendMetaInfo.getNamespaceSerializer();
371:         final DataOutputSerializer namespaceOutputView = new DataOutputSerializer(8);
372:         boolean ambiguousKeyPossible =
373:                 CompositeKeySerializationUtils.isAmbiguousKeyPossible(
374:                         getKeySerializer(), namespaceSerializer);
375:         final byte[] nameSpaceBytes;
376:         try {
377:             CompositeKeySerializationUtils.writeNameSpace(
378:                     namespace, namespaceSerializer, namespaceOutputView, ambiguousKeyPossible);
379:             nameSpaceBytes = namespaceOutputView.getCopyOfBuffer();
380:         } catch (IOException ex) {
381:             throw new FlinkRuntimeException("Failed to get keys from RocksDB state backend.", ex);
382:         }
