389:         final RocksStateKeysIterator<K> iteratorWrapper =
390:                 new RocksStateKeysIterator<>(
391:                         iterator,
392:                         state,
393:                         getKeySerializer(),
394:                         keyGroupPrefixBytes,
395:                         ambiguousKeyPossible,
396:                         nameSpaceBytes);
397: 
398:         Stream<K> targetStream =
399:                 StreamSupport.stream(
400:                         Spliterators.spliteratorUnknownSize(iteratorWrapper, Spliterator.ORDERED),
401:                         false);
