659:     /**
660:      * Triggers an asynchronous snapshot of the keyed state backend from RocksDB. This snapshot can
661:      * be canceled and is also stopped when the backend is closed through {@link #dispose()}. For
662:      * each backend, this method must always be called by the same thread.
663:      *
664:      * @param checkpointId The Id of the checkpoint.
665:      * @param timestamp The timestamp of the checkpoint.
666:      * @param streamFactory The factory that we can use for writing our state to streams.
667:      * @param checkpointOptions Options for how to perform this checkpoint.
668:      * @return Future to the state handle of the snapshot data.
669:      * @throws Exception indicating a problem in the synchronous part of the checkpoint.
670:      */
671:     @Nonnull
672:     @Override
673:     public RunnableFuture<SnapshotResult<KeyedStateHandle>> snapshot(
674:             final long checkpointId,
675:             final long timestamp,
676:             @Nonnull final CheckpointStreamFactory streamFactory,
677:             @Nonnull CheckpointOptions checkpointOptions)
678:             throws Exception {
679: 
680:         // flush everything into db before taking a snapshot
681:         writeBatchWrapper.flush();
682: 
683:         return new SnapshotStrategyRunner<>(
684:                         checkpointSnapshotStrategy.getDescription(),
685:                         checkpointSnapshotStrategy,
686:                         cancelStreamRegistry,
687:                         ASYNCHRONOUS)
688:                 .snapshot(checkpointId, timestamp, streamFactory, checkpointOptions);
689:     }
