732:     /**
733:      * Registers a k/v state information, which includes its state id, type, RocksDB column family
734:      * handle, and serializers.
735:      *
736:      * <p>When restoring from a snapshot, we don’t restore the individual k/v states, just the
737:      * global RocksDB database and the list of k/v state information. When a k/v state is first
738:      * requested we check here whether we already have a registered entry for that and return it
739:      * (after some necessary state compatibility checks) or create a new one if it does not exist.
740:      */
741:     private <N, S extends State, SV, SEV>
742:             Tuple2<ColumnFamilyHandle, RegisteredKeyValueStateBackendMetaInfo<N, SV>>
743:                     tryRegisterKvStateInformation(
744:                             StateDescriptor<S, SV> stateDesc,
745:                             TypeSerializer<N> namespaceSerializer,
746:                             @Nonnull StateSnapshotTransformFactory<SEV> snapshotTransformFactory,
747:                             boolean allowFutureMetadataUpdates)
748:                             throws Exception {
749: 
750:         RocksDbKvStateInfo oldStateInfo = kvStateInformation.get(stateDesc.getName());
751: 
752:         TypeSerializer<SV> stateSerializer = stateDesc.getSerializer();
753: 
754:         RocksDbKvStateInfo newRocksStateInfo;
755:         RegisteredKeyValueStateBackendMetaInfo<N, SV> newMetaInfo;
756:         if (oldStateInfo != null) {
757:             @SuppressWarnings("unchecked")
758:             RegisteredKeyValueStateBackendMetaInfo<N, SV> castedMetaInfo =
759:                     (RegisteredKeyValueStateBackendMetaInfo<N, SV>) oldStateInfo.metaInfo;
760: 
761:             Tuple2<ColumnFamilyHandle, RegisteredKeyValueStateBackendMetaInfo<N, SV>>
762:                     newRocksDBState =
763:                             updateRestoredStateMetaInfo(
764:                                     Tuple2.of(oldStateInfo.columnFamilyHandle, castedMetaInfo),
765:                                     stateDesc,
766:                                     namespaceSerializer,
767:                                     stateSerializer);
768:             newMetaInfo = newRocksDBState.f1;
769:             newMetaInfo =
770:                     allowFutureMetadataUpdates
771:                             ? newMetaInfo.withSerializerUpgradesAllowed()
772:                             : newMetaInfo;
773: 
774:             newRocksStateInfo = new RocksDbKvStateInfo(newRocksDBState.f0, newMetaInfo);
775:             kvStateInformation.put(stateDesc.getName(), newRocksStateInfo);
776:             sstMergeManager.register(newRocksStateInfo);
777:         } else {
778:             newMetaInfo =
779:                     new RegisteredKeyValueStateBackendMetaInfo<>(
780:                             stateDesc.getType(),
781:                             stateDesc.getName(),
782:                             namespaceSerializer,
783:                             stateSerializer,
784:                             StateSnapshotTransformFactory.noTransform());
785: 
786:             newMetaInfo =
787:                     allowFutureMetadataUpdates
788:                             ? newMetaInfo.withSerializerUpgradesAllowed()
789:                             : newMetaInfo;
790: 
791:             newRocksStateInfo =
792:                     RocksDBOperationUtils.createStateInfo(
793:                             newMetaInfo,
794:                             db,
795:                             columnFamilyOptionsFactory,
796:                             ttlCompactFiltersManager,
797:                             optionsContainer.getWriteBufferManagerCapacity(),
798:                             // Using ICloseableRegistry.NO_OP here because there is no restore in
799:                             // progress; created column families will be closed in dispose()
800:                             ICloseableRegistry.NO_OP);
801:             RocksDBOperationUtils.registerKvStateInformation(
802:                     this.kvStateInformation,
803:                     this.nativeMetricMonitor,
804:                     stateDesc.getName(),
805:                     newRocksStateInfo);
806:             sstMergeManager.register(newRocksStateInfo);
807:         }
808: 
809:         StateSnapshotTransformFactory<SV> wrappedSnapshotTransformFactory =
810:                 wrapStateSnapshotTransformFactory(
811:                         stateDesc, snapshotTransformFactory, newMetaInfo.getStateSerializer());
812:         newMetaInfo.updateSnapshotTransformFactory(wrappedSnapshotTransformFactory);
813: 
814:         return Tuple2.of(newRocksStateInfo.columnFamilyHandle, newMetaInfo);
815:     }
