336:     public <N, S extends State, T> void applyToAllKeys(
337:             final N namespace,
338:             final TypeSerializer<N> namespaceSerializer,
339:             final StateDescriptor<S, T> stateDescriptor,
340:             final KeyedStateFunction<K, S> function,
341:             final PartitionStateFactory partitionStateFactory)
342:             throws Exception {
343: 
344:         try (Stream<K> keyStream = getKeys(stateDescriptor.getName(), namespace)) {
345: 
346:             final S state =
347:                     partitionStateFactory.get(namespace, namespaceSerializer, stateDescriptor);
348: 
349:             keyStream.forEach(
350:                     (K key) -> {
351:                         setCurrentKey(key);
