403:             @Nonnull CheckpointOptions checkpointOptions)
404:             throws Exception {
405: 
406:         if (checkpointOptions.getCheckpointType().isSavepoint()) {
407:             return nativeSavepoint(checkpointId, timestamp, streamFactory, checkpointOptions);
408:         }
409: 
410:         // The range to upload may overlap with the previous one(s). To reuse them, we could store
411:         // the previous results either here in the backend or in the writer. However,
412:         // materialization may truncate only a part of the previous result and the backend would
413:         // have to split it somehow for the former option, so the latter is used.
414:         lastCheckpointId = checkpointId;
415:         lastUploadedFrom = changelogSnapshotState.lastMaterializedTo();
416:         lastUploadedTo = stateChangelogWriter.nextSequenceNumber();
417:         changelogTruncateHelper.checkpoint(checkpointId, lastUploadedTo);
418: 
419:         LOG.info(
420:                 "snapshot of {} for checkpoint {}, change range: {}..{}, materialization ID {}",
421:                 subtaskName,
422:                 checkpointId,
423:                 lastUploadedFrom,
424:                 lastUploadedTo,
425:                 changelogSnapshotState.getMaterializationID());
426: 
427:         ChangelogSnapshotState changelogStateBackendStateCopy = changelogSnapshotState;
428: 
429:         materializationIdByCheckpointId.put(
430:                 checkpointId, changelogStateBackendStateCopy.materializationID);
