432:         return toRunnableFuture(
433:                 stateChangelogWriter
434:                         .persist(lastUploadedFrom, checkpointId)
435:                         .thenApply(
436:                                 delta ->
437:                                         buildSnapshotResult(
438:                                                 checkpointId,
439:                                                 delta,
440:                                                 changelogStateBackendStateCopy))
441:                         .whenComplete(
442:                                 (snapshotResult, throwable) ->
443:                                         metrics.reportSnapshotResult(snapshotResult))
444:                         .thenApply(this::castSnapshotResult));
