1076:     /**
1077:      * Snapshot State for ChangelogKeyedStateBackend, a wrapper over {@link SnapshotResult}.
1078:      *
1079:      * <p>It includes three parts: - materialized snapshot from the underlying delegated state
1080:      * backend - non-materialized part in the current changelog - non-materialized changelog, from
1081:      * previous logs (before failover or rescaling)
1082:      */
1083:     private class ChangelogSnapshotState {
1084: 
1085:         /** Set initially on restore and later upon materialization. */
1086:         private final SnapshotResult<ChangelogStateBackendHandle> changelogSnapshot;
1087: 
1088:         /**
1089:          * The {@link SequenceNumber} up to which the state is materialized, exclusive. This
1090:          * indicates the non-materialized part of the current changelog.
1091:          */
1092:         private final SequenceNumber materializedTo;
1093: 
1094:         /** ID of this materialization corresponding to the nested backend checkpoint ID. */
1095:         private final long materializationID;
1096: 
1097:         /**
1098:          * Construct a ChangelogSnapshotState with empty non-materialized part, which could be used
1099:          * when triggering manual materialization.
1100:          */
1101:         public ChangelogSnapshotState(
1102:                 List<KeyedStateHandle> materializedSnapshot, long materializationID) {
1103:             this(
1104:                     materializedSnapshot,
1105:                     Collections.emptyList(),
1106:                     SequenceNumber.of(Long.MAX_VALUE),
1107:                     materializationID);
1108:         }
1109: 
1110:         public ChangelogSnapshotState(
1111:                 List<KeyedStateHandle> materializedSnapshot,
1112:                 List<ChangelogStateHandle> restoredNonMaterialized,
1113:                 SequenceNumber materializedTo,
1114:                 long materializationID) {
1115:             this.changelogSnapshot =
1116:                     SnapshotResult.of(
1117:                             new ChangelogStateBackendHandleImpl(
1118:                                     materializedSnapshot,
1119:                                     restoredNonMaterialized,
1120:                                     getKeyGroupRange(),
1121:                                     lastCheckpointId,
1122:                                     materializationID,
1123:                                     0L));
1124:             this.materializedTo = materializedTo;
1125:             this.materializationID = materializationID;
1126:         }
1127: 
1128:         public ChangelogSnapshotState(
1129:                 List<KeyedStateHandle> materializedSnapshot,
1130:                 List<KeyedStateHandle> localMaterializedSnapshot,
1131:                 List<ChangelogStateHandle> restoredNonMaterialized,
1132:                 List<ChangelogStateHandle> localRestoredNonMaterialized,
1133:                 SequenceNumber materializedTo,
1134:                 long materializationID) {
1135:             ChangelogStateBackendHandleImpl jmHandle =
1136:                     new ChangelogStateBackendHandleImpl(
1137:                             materializedSnapshot,
1138:                             restoredNonMaterialized,
1139:                             getKeyGroupRange(),
1140:                             lastCheckpointId,
1141:                             materializationID,
1142:                             0L);
1143:             this.changelogSnapshot =
1144:                     SnapshotResult.withLocalState(
1145:                             jmHandle,
1146:                             new ChangelogStateBackendLocalHandle(
1147:                                     localMaterializedSnapshot,
1148:                                     localRestoredNonMaterialized,
1149:                                     jmHandle));
1150:             this.materializedTo = materializedTo;
1151:             this.materializationID = materializationID;
1152:         }
1153: 
