718:     /**
719:      * Gets the configured local DB storage paths, or null, if none were configured.
720:      *
721:      * <p>Under these directories on the TaskManager, ForSt stores some metadata files. These
722:      * directories do not need to be persistent, they can be ephermeral, meaning that they are lost
723:      * on a machine failure, because state in ForSt is persisted in checkpoints.
724:      *
725:      * <p>If nothing is configured, these directories default to the TaskManager's local temporary
726:      * file directories.
727:      */
728:     public String[] getLocalDbStoragePaths() {
729:         if (localForStDirectories == null) {
730:             return null;
731:         } else {
732:             String[] paths = new String[localForStDirectories.length];
733:             for (int i = 0; i < paths.length; i++) {
734:                 paths[i] = localForStDirectories[i].toString();
735:             }
736:             return paths;
737:         }
738:     }
