29: /** Base class of state latency metric which counts and histogram the state metric. */
30: class StateLatencyMetricBase implements AutoCloseable {
31:     protected static final String STATE_NAME_KEY = "state_name";
32:     protected static final String STATE_CLEAR_LATENCY = "stateClearLatency";
33:     private final MetricGroup metricGroup;
34:     private final int sampleInterval;
35:     private final Map<String, Histogram> histogramMetrics;
36:     private final Supplier<Histogram> histogramSupplier;
37:     private int clearCount = 0;
38: 
39:     StateLatencyMetricBase(
40:             String stateName,
41:             MetricGroup metricGroup,
42:             int sampleInterval,
43:             int historySize,
44:             boolean stateNameAsVariable) {
45:         this.metricGroup =
46:                 stateNameAsVariable
47:                         ? metricGroup.addGroup(STATE_NAME_KEY, stateName)
48:                         : metricGroup.addGroup(stateName);
49:         this.sampleInterval = sampleInterval;
50:         this.histogramMetrics = new HashMap<>();
51:         this.histogramSupplier = () -> new DescriptiveStatisticsHistogram(historySize);
52:     }
53: 
54:     int getClearCount() {
55:         return clearCount;
56:     }
57: 
58:     protected boolean trackLatencyOnClear() {
59:         clearCount = loopUpdateCounter(clearCount);
60:         return clearCount == 1;
61:     }
62: 
63:     protected int loopUpdateCounter(int counter) {
64:         return (counter + 1 < sampleInterval) ? counter + 1 : 0;
65:     }
66: 
67:     protected void updateLatency(String latencyLabel, long duration) {
68:         updateHistogram(latencyLabel, duration);
69:     }
70: 
71:     private void updateHistogram(final String metricName, final long durationNanoTime) {
72:         this.histogramMetrics
73:                 .computeIfAbsent(
74:                         metricName,
75:                         (k) -> {
76:                             Histogram histogram = histogramSupplier.get();
77:                             metricGroup.histogram(metricName, histogram);
78:                             return histogram;
79:                         })
80:                 .update(durationNanoTime);
81:     }
82: 
83:     @Override
84:     public void close() throws Exception {
85:         histogramMetrics.clear();
86:     }
