1157:         final int parallelism = 240;
1158:         final int expectedMaxParallelism =
1159:                 KeyGroupRangeAssignment.computeDefaultMaxParallelism(parallelism);
1160:         final JobVertex vertex = createNoOpVertex(parallelism);
1161:         final JobGraph jobGraph = streamingJobGraph(vertex);
1162: 
