1169:                                 singleThreadMainThreadExecutor,
1170:                                 EXECUTOR_RESOURCE.getExecutor())
1171:                         .setDeclarativeSlotPool(declarativeSlotPool)
1172:                         .setJobMasterConfiguration(createConfigurationWithNoTimeouts())
1173:                         .build();
1174: 
1175:         final SubmissionBufferingTaskManagerGateway taskManagerGateway =
1176:                 new SubmissionBufferingTaskManagerGateway(1 + parallelism);
1177:         taskManagerGateway.setCancelConsumer(createCancelConsumer(scheduler));
1178: 
1179:         // offer just enough resources to run at the lowest possible parallelism
1180:         singleThreadMainThreadExecutor.execute(
1181:                 () -> {
1182:                     scheduler.startScheduling();
1183:                     offerSlots(
1184:                             declarativeSlotPool,
1185:                             createSlotOffersForResourceRequirements(
1186:                                     ResourceCounter.withResource(ResourceProfile.UNKNOWN, 1)),
1187:                             taskManagerGateway);
1188:                 });
1189: 
1190:         // Wait for task to be submitted
1191:         taskManagerGateway.waitForSubmissions(1);
1192: 
1193:         ArchivedExecutionGraph executionGraph =
1194:                 getArchivedExecutionGraphForRunningJob(scheduler).get();
1195:         ArchivedExecutionJobVertex archivedVertex = executionGraph.getJobVertex(vertex.getID());
1196: 
1197:         // ensure that the parallelism was submitted based on what is available
1198:         assertThat(archivedVertex.getParallelism()).isOne();
1199:         // and that the max parallelism was submitted based on what was configured
1200:         assertThat(archivedVertex.getMaxParallelism()).isEqualTo(expectedMaxParallelism);
1201: 
1202:         // offer the resources to run at full parallelism
1203:         singleThreadMainThreadExecutor.execute(
1204:                 () -> {
1205:                     offerSlots(
1206:                             declarativeSlotPool,
1207:                             createSlotOffersForResourceRequirements(
1208:                                     ResourceCounter.withResource(
1209:                                             ResourceProfile.UNKNOWN, parallelism)),
1210:                             taskManagerGateway);
1211:                 });
1212: 
1213:         // wait for the job to be re-submitted
1214:         taskManagerGateway.waitForSubmissions(parallelism);
1215: 
1216:         ArchivedExecutionGraph resubmittedExecutionGraph =
1217:                 getArchivedExecutionGraphForRunningJob(scheduler).get();
1218:         ArchivedExecutionJobVertex resubmittedArchivedVertex =
1219:                 resubmittedExecutionGraph.getJobVertex(vertex.getID());
