1222:         assertThat(resubmittedArchivedVertex.getParallelism()).isEqualTo(parallelism);
1223:         // and that the max parallelism was submitted based on what was configured
1224:         assertThat(resubmittedArchivedVertex.getMaxParallelism()).isEqualTo(expectedMaxParallelism);
