1489:     private SubmissionBufferingTaskManagerGateway createSubmissionBufferingTaskManagerGateway(
1490:             int parallelism, SchedulerNG scheduler) {
1491:         SubmissionBufferingTaskManagerGateway taskManagerGateway =
1492:                 new SubmissionBufferingTaskManagerGateway(parallelism);
1493:         taskManagerGateway.setCancelConsumer(
1494:                 executionAttemptID ->
1495:                         singleThreadMainThreadExecutor.execute(
1496:                                 () ->
1497:                                         scheduler.updateTaskExecutionState(
1498:                                                 new TaskExecutionState(
1499:                                                         executionAttemptID,
1500:                                                         ExecutionState.CANCELED))));
1501:         return taskManagerGateway;
1502:     }
