1504:     private void startJobWithSlotsMatchingParallelism(
1505:             SchedulerNG scheduler,
1506:             DeclarativeSlotPool declarativeSlotPool,
1507:             TaskManagerGateway taskManagerGateway,
1508:             int parallelism) {
1509:         singleThreadMainThreadExecutor.execute(
1510:                 () -> {
1511:                     scheduler.startScheduling();
1512:                     offerSlots(
1513:                             declarativeSlotPool,
1514:                             createSlotOffersForResourceRequirements(
1515:                                     ResourceCounter.withResource(
1516:                                             ResourceProfile.UNKNOWN, parallelism)),
1517:                             taskManagerGateway);
1518:                 });
1519:     }
