1521:     private void awaitJobReachingParallelism(
1522:             SubmissionBufferingTaskManagerGateway taskManagerGateway,
1523:             SchedulerNG scheduler,
1524:             int parallelism)
1525:             throws Exception {
1526:         // Wait for all tasks to be submitted
1527:         taskManagerGateway.waitForSubmissions(parallelism);
1528: 
1529:         final ArchivedExecutionGraph executionGraph =
1530:                 CompletableFuture.supplyAsync(
1531:                                 () -> scheduler.requestJob().getArchivedExecutionGraph(),
1532:                                 singleThreadMainThreadExecutor)
1533:                         .get();
1534: 
1535:         assertThat(executionGraph.getJobVertex(JOB_VERTEX.getID()).getParallelism())
1536:                 .isEqualTo(parallelism);
1537:     }
