2148:     @Test
2149:     void testIdleSlotsAreReleasedAfterDownScalingTriggeredByLoweredResourceRequirements()
2150:             throws Exception {
2151:         final JobGraph jobGraph = createJobGraph();
2152:         final Duration slotIdleTimeout = Duration.ofMillis(10);
2153: 
2154:         final Configuration configuration = createConfigurationWithNoTimeouts();
2155:         configuration.set(JobManagerOptions.SLOT_IDLE_TIMEOUT, slotIdleTimeout);
2156: 
2157:         final DeclarativeSlotPool declarativeSlotPool =
2158:                 createDeclarativeSlotPool(
2159:                         jobGraph.getJobID(), singleThreadMainThreadExecutor, slotIdleTimeout);
2160:         scheduler =
2161:                 new AdaptiveSchedulerBuilder(
2162:                                 jobGraph,
2163:                                 singleThreadMainThreadExecutor,
2164:                                 EXECUTOR_RESOURCE.getExecutor())
2165:                         .setDeclarativeSlotPool(declarativeSlotPool)
2166:                         .setJobMasterConfiguration(configuration)
2167:                         .build();
2168: 
2169:         final int numInitialSlots = 4;
2170:         final int numSlotsAfterDownscaling = 2;
2171: 
2172:         final SubmissionBufferingTaskManagerGateway taskManagerGateway =
2173:                 new SubmissionBufferingTaskManagerGateway(numInitialSlots);
2174: 
2175:         taskManagerGateway.setCancelConsumer(createCancelConsumer(scheduler));
2176: 
2177:         singleThreadMainThreadExecutor.execute(
2178:                 () -> {
2179:                     scheduler.startScheduling();
2180:                     offerSlots(
2181:                             declarativeSlotPool,
2182:                             createSlotOffersForResourceRequirements(
2183:                                     ResourceCounter.withResource(
2184:                                             ResourceProfile.UNKNOWN, numInitialSlots)),
2185:                             taskManagerGateway);
2186:                 });
2187: 
2188:         // wait for all tasks to be submitted
2189:         taskManagerGateway.waitForSubmissions(numInitialSlots);
2190: 
2191:         // lower the resource requirements
2192:         singleThreadMainThreadExecutor.execute(
2193:                 () ->
2194:                         scheduler.updateJobResourceRequirements(
2195:                                 JobResourceRequirements.newBuilder()
2196:                                         .setParallelismForJobVertex(
2197:                                                 JOB_VERTEX.getID(), 1, numSlotsAfterDownscaling)
2198:                                         .build()));
2199: 
2200:         // job should be resubmitted with lower parallelism
2201:         taskManagerGateway.waitForSubmissions(numSlotsAfterDownscaling);
2202: 
2203:         // and excessive slots should be freed
2204:         taskManagerGateway.waitForFreedSlots(numInitialSlots - numSlotsAfterDownscaling);
2205: 
2206:         final CompletableFuture<JobStatus> jobStatusFuture = new CompletableFuture<>();
2207:         singleThreadMainThreadExecutor.execute(
2208:                 () -> jobStatusFuture.complete(scheduler.getState().getJobStatus()));
2209:         assertThatFuture(jobStatusFuture).eventuallySucceeds().isEqualTo(JobStatus.RUNNING);
2210: 
2211:         // make sure we haven't freed up any more slots
2212:         assertThat(taskManagerGateway.freedSlots).isEmpty();
2213:     }
