2661:     /**
2662:      * A {@link SimpleAckingTaskManagerGateway} that buffers all the task submissions into a
2663:      * blocking queue, allowing one to wait for an arbitrary number of submissions.
2664:      */
2665:     public static class SubmissionBufferingTaskManagerGateway
2666:             extends SimpleAckingTaskManagerGateway {
2667:         final BlockingQueue<TaskDeploymentDescriptor> submittedTasks;
2668:         final BlockingQueue<AllocationID> freedSlots;
2669: 
2670:         public SubmissionBufferingTaskManagerGateway(int capacity) {
2671:             submittedTasks = new ArrayBlockingQueue<>(capacity);
2672:             freedSlots = new ArrayBlockingQueue<>(capacity);
2673:             initializeFunctions();
2674:         }
2675: 
2676:         @Override
2677:         public void setSubmitConsumer(Consumer<TaskDeploymentDescriptor> submitConsumer) {
2678:             super.setSubmitConsumer(
2679:                     taskDeploymentDescriptor -> {
2680:                         Preconditions.checkState(submittedTasks.offer(taskDeploymentDescriptor));
2681:                         submitConsumer.accept(taskDeploymentDescriptor);
2682:                     });
2683:         }
2684: 
2685:         @Override
2686:         public void setFreeSlotFunction(
2687:                 BiFunction<AllocationID, Throwable, CompletableFuture<Acknowledge>>
2688:                         freeSlotFunction) {
2689:             super.setFreeSlotFunction(
2690:                     (allocationID, throwable) -> {
2691:                         Preconditions.checkState(freedSlots.offer(allocationID));
2692:                         return freeSlotFunction.apply(allocationID, throwable);
2693:                     });
2694:         }
2695: 
2696:         /**
2697:          * Block until an arbitrary number of submissions have been received.
2698:          *
2699:          * @param numSubmissions The number of submissions to wait for
2700:          * @return the list of the waited-for submissions
2701:          * @throws InterruptedException if a timeout is exceeded waiting for a submission
2702:          */
2703:         public List<TaskDeploymentDescriptor> waitForSubmissions(int numSubmissions)
2704:                 throws InterruptedException {
2705:             List<TaskDeploymentDescriptor> descriptors = new ArrayList<>();
2706:             for (int i = 0; i < numSubmissions; i++) {
2707:                 descriptors.add(submittedTasks.take());
2708:             }
2709:             return descriptors;
2710:         }
2711: 
2712:         public List<AllocationID> waitForFreedSlots(int numFreedSlots) throws InterruptedException {
2713:             final List<AllocationID> allocationIds = new ArrayList<>();
2714:             for (int i = 0; i < numFreedSlots; i++) {
2715:                 allocationIds.add(freedSlots.take());
2716:             }
2717:             return allocationIds;
2718:         }
2719: 
2720:         private void initializeFunctions() {
2721:             setSubmitConsumer(ignored -> {});
2722:             setFreeSlotFunction(
2723:                     (allocationId, throwable) ->
2724:                             CompletableFuture.completedFuture(Acknowledge.get()));
2725:         }
2726:     }
