40: 
41:     private final FSDataInputStream originalInputStream;
42: 
43:     /**
44:      * InputStream Pool which provides multiple input streams to random read concurrently. An input
45:      * stream should only be used by a thread at a point in time.
46:      */
47:     private final Queue<FSDataInputStream> readInputStreamPool;
48: 
49:     private final Callable<FSDataInputStream> inputStreamBuilder;
50: 
51:     private final long totalFileSize;
52: 
53:     public ByteBufferReadableFSDataInputStream(
54:             Callable<FSDataInputStream> inputStreamBuilder,
55:             int inputStreamCapacity,
56:             long totalFileSize)
57:             throws IOException {
58:         try {
59:             this.originalInputStream = inputStreamBuilder.call();
60:         } catch (Exception e) {
61:             throw new IOException("Exception when build original input stream", e);
62:         }
63:         this.inputStreamBuilder = inputStreamBuilder;
64:         this.readInputStreamPool = new LinkedBlockingQueue<>(inputStreamCapacity);
65:         this.totalFileSize = totalFileSize;
66:     }
67: 
68:     /**
69:      * Reads up to <code>ByteBuffer#remaining</code> bytes of data from the input stream into a
70:      * ByteBuffer. Not Thread-safe yet since the interface of sequential read of ForSt only be
71:      * accessed by one thread at a time. TODO: Rename all methods about 'readFully' to 'read' when
72:      * next version of ForSt is ready.
73:      *
74:      * @param bb the buffer into which the data is read.
75:      * @return the total number of bytes read into the buffer.
76:      * @throws IOException If the first byte cannot be read for any reason other than end of file,
77:      *     or if the input stream has been closed, or if some other I/O error occurs.
78:      * @throws NullPointerException If <code>bb</code> is <code>null</code>.
79:      */
80:     public int readFully(ByteBuffer bb) throws IOException {
81:         if (bb == null) {
82:             throw new NullPointerException();
83:         } else if (bb.remaining() == 0) {
84:             return 0;
85:         }
86:         return originalInputStream instanceof ByteBufferReadable
87:                 ? ((ByteBufferReadable) originalInputStream).read(bb)
88:                 : readFullyFromFSDataInputStream(originalInputStream, bb);
89:     }
90: 
91:     /**
92:      * Reads up to <code>ByteBuffer#remaining</code> bytes of data from the specific position of the
93:      * input stream into a ByteBuffer. Thread-safe since the interface of random read of ForSt may
94:      * be concurrently accessed by multiple threads. TODO: Support to split this method to other
95:      * class.
96:      *
97:      * @param position the start offset in input stream at which the data is read.
98:      * @param bb the buffer into which the data is read.
99:      * @return the total number of bytes read into the buffer.
100:      * @throws IOException If the first byte cannot be read for any reason other than end of file,
101:      *     or if the input stream has been closed, or if some other I/O error occurs.
102:      * @throws NullPointerException If <code>bb</code> is <code>null</code>.
103:      */
104:     public int readFully(long position, ByteBuffer bb) throws Exception {
105:         if (bb == null) {
106:             throw new NullPointerException();
107:         } else if (position >= totalFileSize) {
108:             throw new IllegalArgumentException(
109:                     String.format(
110:                             "position [%s] is larger than or equals to totalFileSize [%s]",
111:                             position, totalFileSize));
112:         }
113: 
114:         // Avoid bb.remaining() exceeding the file size limit.
115:         bb.limit(
116:                 Math.min(
117:                         bb.limit(),
118:                         (int)
119:                                 Math.min(
120:                                         totalFileSize - position + bb.position(),
121:                                         Integer.MAX_VALUE)));
122: 
123:         if (bb.remaining() == 0) {
124:             return 0;
125:         }
126: 
127:         FSDataInputStream fsDataInputStream = readInputStreamPool.poll();
128:         if (fsDataInputStream == null) {
129:             fsDataInputStream = inputStreamBuilder.call();
130:         }
131: 
132:         int result;
133:         if (fsDataInputStream instanceof ByteBufferReadable) {
134:             result = ((ByteBufferReadable) fsDataInputStream).read(position, bb);
135:         } else {
136:             fsDataInputStream.seek(position);
137:             result = readFullyFromFSDataInputStream(fsDataInputStream, bb);
138:         }
139: 
140:         boolean offered;
141:         try {
142:             offered = readInputStreamPool.offer(fsDataInputStream);
143:         } catch (Exception ex) {
144:             // Close input stream and rethrow when any exception
145:             fsDataInputStream.close();
146:             throw ex;
147:         }
148: 
149:         if (!offered) {
150:             fsDataInputStream.close();
151:         }
152: 
153:         return result;
154:     }
155: 
156:     private int readFullyFromFSDataInputStream(FSDataInputStream originalInputStream, ByteBuffer bb)
157:             throws IOException {
158:         int c = originalInputStream.read();
159:         if (c == -1) {
160:             return -1;
161:         }
162:         bb.put((byte) c);
163: 
164:         int n = 1, len = bb.remaining() + 1;
165:         for (; n < len; n++) {
166:             c = originalInputStream.read();
167:             if (c == -1) {
168:                 break;
169:             }
170:             bb.put((byte) c);
171:         }
172:         return n;
173:     }
174: 
175:     @Override
176:     public void seek(long desired) throws IOException {
177:         originalInputStream.seek(desired);
178:     }
179: 
180:     @Override
181:     public long getPos() throws IOException {
182:         return originalInputStream.getPos();
183:     }
184: 
185:     @Override
186:     public int read() throws IOException {
187:         return originalInputStream.read();
188:     }
189: 
190:     @Override
191:     public int read(byte[] b) throws IOException {
192:         return originalInputStream.read(b);
193:     }
194: 
195:     @Override
196:     public int read(byte[] b, int off, int len) throws IOException {
197:         return originalInputStream.read(b, off, len);
198:     }
199: 
200:     @Override
201:     public long skip(long n) throws IOException {
202:         long position = getPos();
203:         seek(position + n);
204:         return getPos() - position;
205:     }
206: 
207:     @Override
208:     public int available() throws IOException {
209:         return originalInputStream.available();
210:     }
211: 
212:     @Override
213:     public void close() throws IOException {
214:         originalInputStream.close();
215:         for (FSDataInputStream fsDataInputStream : readInputStreamPool) {
216:             fsDataInputStream.close();
217:         }
218:     }
219: 
