101:     public static FileBasedCache getFileBasedCache(
102:             Path cacheBase, long cacheCapacity, long cacheReservedSize, MetricGroup metricGroup)
103:             throws IOException {
104:         if (cacheBase == null || cacheCapacity <= 0 && cacheReservedSize <= 0) {
105:             return null;
106:         }
107:         CacheLimitPolicy cacheLimitPolicy = null;
108:         if (cacheCapacity > 0 && cacheReservedSize > 0) {
109:             cacheLimitPolicy =
110:                     new BundledCacheLimitPolicy(
111:                             new SizeBasedCacheLimitPolicy(cacheCapacity),
112:                             new SpaceBasedCacheLimitPolicy(
113:                                     new File(cacheBase.toString()),
114:                                     cacheReservedSize,
115:                                     SST_FILE_SIZE));
116:         } else if (cacheCapacity > 0) {
117:             cacheLimitPolicy = new SizeBasedCacheLimitPolicy(cacheCapacity);
118:         } else if (cacheReservedSize > 0) {
119:             cacheLimitPolicy =
120:                     new SpaceBasedCacheLimitPolicy(
121:                             new File(cacheBase.toString()), cacheReservedSize, SST_FILE_SIZE);
122:         }
123:         return new FileBasedCache(
124:                 Integer.MAX_VALUE,
125:                 cacheLimitPolicy,
126:                 cacheBase.getFileSystem(),
127:                 cacheBase,
128:                 metricGroup);
129:     }
