229:     @Override
230:     public synchronized boolean exists(final Path f) throws IOException {
231:         FileMappingManager.RealPath realPath = fileMappingManager.realPath(f);
232:         if (realPath == null) {
233:             return delegateFS.exists(f) && delegateFS.getFileStatus(f).isDir();
234:         }
235: 
236:         boolean status = false;
237:         if (realPath.isLocal) {
238:             status |= localFS.exists(realPath.path);
239:             if (!status) {
240:                 status = delegateFS.exists(f);
241:             }
242:         } else {
243:             status = delegateFS.exists(realPath.path);
244:         }
245:         return status;
246:     }
