271:     @Override
272:     public synchronized FileStatus[] listStatus(Path path) throws IOException {
273:         // mapping files
274:         List<FileStatus> fileStatuses = new ArrayList<>();
275:         String pathStr = path.toString();
276:         if (!pathStr.endsWith("/")) {
277:             pathStr += "/";
278:         }
279:         List<String> mappingFiles = fileMappingManager.listByPrefix(pathStr);
280:         for (String mappingFile : mappingFiles) {
281:             String relativePath = mappingFile.substring(pathStr.length());
282:             int slashIndex = relativePath.indexOf('/');
283:             if (slashIndex == -1) { // direct child
284:                 fileStatuses.add(getFileStatus(new Path(mappingFile)));
285:             }
286:         }
287:         return fileStatuses.toArray(new FileStatus[0]);
288:     }
