290:     @Override
291:     public synchronized boolean delete(Path path, boolean recursive) throws IOException {
292:         boolean success = fileMappingManager.deleteFile(path, recursive);
293:         if (fileBasedCache != null) {
294:             // only new generated file will put into cache, no need to consider file mapping
295:             fileBasedCache.delete(path);
296:         }
297:         return success;
298:     }
