575:     /**
576:      * Relocates the default log directory of ForSt with the Flink log directory. Finds the Flink
577:      * log directory using log.file Java property that is set during startup.
578:      *
579:      * @param dbOptions The ForSt {@link DBOptions}.
580:      */
581:     private void relocateDefaultDbLogDir(DBOptions dbOptions) {
582:         String logFilePath = System.getProperty("log.file");
583:         if (logFilePath != null) {
584:             File logFile = resolveFileLocation(logFilePath);
585:             if (logFile != null && resolveFileLocation(logFile.getParent()) != null) {
586:                 String relocatedDbLogDir = logFile.getParent();
587:                 this.relocatedDbLogBaseDir = new File(relocatedDbLogDir).toPath();
588:                 dbOptions.setDbLogDir(relocatedDbLogDir);
589:             } else {
590:                 setLocalForStPathAsLogDir(dbOptions);
591:             }
592:         } else {
593:             setLocalForStPathAsLogDir(dbOptions);
594:         }
595:     }
596: 
597:     private void setLocalForStPathAsLogDir(DBOptions dbOptions) {
598:         // Currently, ForStDB does not support mixing local-dir and remote-dir, and ForStDB will
599:         // concatenates the dfs directory with the local directory as working dir when using flink
600:         // env. We expect to directly use the dfs directory in flink env or local directory as
601:         // working dir. We will implement this in ForStDB later, but before that, we achieved this
602:         // by setting the dbPath to "/" when the dfs directory existed. Another problem is that when
603:         // the system property "log.file" is not set, ForSt directly uses the instance path as the
604:         // log dir, which results in "/" being used as the log directory. This often has permission
605:         // issues, so the db log dir is temporarily set explicitly here.
606:         // TODO: remove this method after ForSt deal log dir well
607:         if (localForStPath != null) {
608:             this.relocatedDbLogBaseDir = java.nio.file.Path.of(localForStPath.toUri().toString());
609:             dbOptions.setDbLogDir(localForStPath.getPath());
610:         }
611:     }
