624:     /** Clean all relocated ForSt logs. */
625:     private void cleanRelocatedDbLogs() {
626:         if (localForStPath != null && relocatedDbLogBaseDir != null) {
627:             LOG.info("Cleaning up relocated ForSt logs: {}.", relocatedDbLogBaseDir);
628: 
629:             String relocatedDbLogPrefix = resolveRelocatedDbLogPrefix(localForStPath.getPath());
630:             try {
631:                 Arrays.stream(FileUtils.listDirectory(relocatedDbLogBaseDir))
632:                         .filter(
633:                                 path ->
634:                                         !Files.isDirectory(path)
635:                                                 && path.toFile()
636:                                                         .getName()
637:                                                         .startsWith(relocatedDbLogPrefix))
638:                         .forEach(IOUtils::deleteFileQuietly);
639:             } catch (IOException e) {
640:                 LOG.warn("Could not list relocated ForSt log directory: {}", relocatedDbLogBaseDir);
641:             }
642:         }
643:     }
