645:     /**
646:      * Resolve the prefix of ForSt's log file name according to ForSt's log file name rules.
647:      *
648:      * @param instanceForStAbsolutePath The path where the ForSt directory is located.
649:      * @return Resolved ForSt log name prefix.
650:      */
651:     private String resolveRelocatedDbLogPrefix(String instanceForStAbsolutePath) {
652:         if (!instanceForStAbsolutePath.isEmpty()
653:                 && !instanceForStAbsolutePath.matches("^[a-zA-Z0-9\\-._].*")) {
654:             instanceForStAbsolutePath = instanceForStAbsolutePath.substring(1);
655:         }
656:         return instanceForStAbsolutePath.replaceAll("[^a-zA-Z0-9\\-._]", "_")
657:                 + FORST_RELOCATE_LOG_SUFFIX;
658:     }
