448:     // --------------------------------------------------------------------------------------------
449:     //  Topological Graph Access
450:     // --------------------------------------------------------------------------------------------
451: 
452:     public List<JobVertex> getVerticesSortedTopologicallyFromSources()
453:             throws InvalidProgramException {
454:         // early out on empty lists
455:         if (this.taskVertices.isEmpty()) {
456:             return Collections.emptyList();
457:         }
458: 
459:         List<JobVertex> sorted = new ArrayList<JobVertex>(this.taskVertices.size());
460:         Set<JobVertex> remaining = new LinkedHashSet<JobVertex>(this.taskVertices.values());
461: 
462:         // start by finding the vertices with no input edges
463:         // and the ones with disconnected inputs (that refer to some standalone data set)
464:         {
465:             Iterator<JobVertex> iter = remaining.iterator();
466:             while (iter.hasNext()) {
467:                 JobVertex vertex = iter.next();
468: 
469:                 if (vertex.hasNoConnectedInputs()) {
470:                     sorted.add(vertex);
471:                     iter.remove();
472:                 }
473:             }
474:         }
475: 
476:         int startNodePos = 0;
477: 
478:         // traverse from the nodes that were added until we found all elements
479:         while (!remaining.isEmpty()) {
480: 
481:             // first check if we have more candidates to start traversing from. if not, then the
482:             // graph is cyclic, which is not permitted
483:             if (startNodePos >= sorted.size()) {
484:                 throw new InvalidProgramException("The job graph is cyclic.");
485:             }
486: 
487:             JobVertex current = sorted.get(startNodePos++);
488:             addNodesThatHaveNoNewPredecessors(current, sorted, remaining);
489:         }
490: 
491:         return sorted;
492:     }
493: 
494:     private void addNodesThatHaveNoNewPredecessors(
495:             JobVertex start, List<JobVertex> target, Set<JobVertex> remaining) {
496: 
497:         // forward traverse over all produced data sets and all their consumers
498:         for (IntermediateDataSet dataSet : start.getProducedDataSets()) {
499:             for (JobEdge edge : dataSet.getConsumers()) {
500: 
501:                 // a vertex can be added, if it has no predecessors that are still in the
502:                 // 'remaining' set
503:                 JobVertex v = edge.getTarget();
504:                 if (!remaining.contains(v)) {
505:                     continue;
506:                 }
507: 
508:                 boolean hasNewPredecessors = false;
509: 
510:                 for (JobEdge e : v.getInputs()) {
511:                     // skip the edge through which we came
512:                     if (e == edge) {
513:                         continue;
514:                     }
515: 
516:                     IntermediateDataSet source = e.getSource();
517:                     if (remaining.contains(source.getProducer())) {
518:                         hasNewPredecessors = true;
519:                         break;
520:                     }
521:                 }
522: 
523:                 if (!hasNewPredecessors) {
524:                     target.add(v);
525:                     remaining.remove(v);
526:                     addNodesThatHaveNoNewPredecessors(v, target, remaining);
527:                 }
528:             }
529:         }
530:     }
