258:     public MiniCluster(
259:             MiniClusterConfiguration miniClusterConfiguration,
260:             Supplier<Reference<RpcSystem>> rpcSystemSupplier) {
261: 
262:         this.miniClusterConfiguration =
263:                 checkNotNull(miniClusterConfiguration, "config may not be null");
264:         this.rpcServices =
265:                 new ArrayList<>(
266:                         1
267:                                 + 2
268:                                 + miniClusterConfiguration
269:                                         .getNumTaskManagers()); // common + JM + RM + TMs
270:         this.dispatcherResourceManagerComponents = new ArrayList<>(1);
271: 
272:         // There shouldn't be any lost messages between the MiniCluster and the Flink components
273:         // since they all run in the same process.
274:         this.rpcTimeout = RpcUtils.INF_TIMEOUT;
275:         this.terminationFuture = CompletableFuture.completedFuture(null);
276:         running = false;
277: 
278:         this.taskManagers = new ArrayList<>(miniClusterConfiguration.getNumTaskManagers());
279: 
280:         this.rpcSystemSupplier = rpcSystemSupplier;
