544:                     HeartbeatServices heartbeatServices,
545:                     DelegationTokenManager delegationTokenManager,
546:                     MetricRegistry metricRegistry,
547:                     MetricQueryServiceRetriever metricQueryServiceRetriever,
548:                     FatalErrorHandler fatalErrorHandler)
549:                     throws Exception {
550:         DispatcherResourceManagerComponentFactory dispatcherResourceManagerComponentFactory =
551:                 createDispatcherResourceManagerComponentFactory();
552: 
553:         final DispatcherResourceManagerComponent dispatcherResourceManagerComponent =
554:                 dispatcherResourceManagerComponentFactory.create(
555:                         configuration,
556:                         ResourceID.generate(),
557:                         ioExecutor,
558:                         rpcServiceFactory.createRpcService(),
559:                         haServices,
560:                         blobServer,
561:                         heartbeatServices,
562:                         delegationTokenManager,
563:                         metricRegistry,
564:                         new MemoryExecutionGraphInfoStore(),
565:                         metricQueryServiceRetriever,
566:                         Collections.emptySet(),
567:                         fatalErrorHandler);
568:         FutureUtils.assertNoException(
569:                 dispatcherResourceManagerComponent
570:                         .getShutDownFuture()
571:                         .thenCompose(
572:                                 applicationStatus ->
573:                                         dispatcherResourceManagerComponent.stopApplication(
574:                                                 applicationStatus, null)));
575:         return Collections.singleton(dispatcherResourceManagerComponent);
