1008:     /**
1009:      * This method executes a job in detached mode. The method returns immediately after the job has
1010:      * been added to the
1011:      *
1012:      * @param job The Flink job to execute
1013:      * @throws JobExecutionException Thrown if anything went amiss during initial job launch, or if
1014:      *     the job terminally failed.
1015:      */
1016:     public void runDetached(JobGraph job) throws JobExecutionException, InterruptedException {
1017:         checkNotNull(job, "job is null");
1018: 
1019:         final CompletableFuture<JobSubmissionResult> submissionFuture = submitJob(job);
1020: 
1021:         try {
1022:             submissionFuture.get();
1023:         } catch (ExecutionException e) {
1024:             throw new JobExecutionException(
1025:                     job.getJobID(), ExceptionUtils.stripExecutionException(e));
1026:         }
1027:     }
1028: 
1029:     /**
1030:      * This method runs a job in blocking mode. The method returns only after the job completed
1031:      * successfully, or after it failed terminally.
1032:      *
1033:      * @param job The Flink job to execute
1034:      * @return The result of the job execution
1035:      * @throws JobExecutionException Thrown if anything went amiss during initial job launch, or if
1036:      *     the job terminally failed.
1037:      */
1038:     public JobExecutionResult executeJobBlocking(JobGraph job)
1039:             throws JobExecutionException, InterruptedException {
1040:         checkNotNull(job, "job is null");
1041: 
1042:         final CompletableFuture<JobSubmissionResult> submissionFuture = submitJob(job);
1043: 
1044:         final CompletableFuture<JobResult> jobResultFuture =
1045:                 submissionFuture.thenCompose(
1046:                         (JobSubmissionResult ignored) -> requestJobResult(job.getJobID()));
1047: 
1048:         final JobResult jobResult;
1049: 
1050:         try {
1051:             jobResult = jobResultFuture.get();
1052:         } catch (ExecutionException e) {
1053:             throw new JobExecutionException(
1054:                     job.getJobID(),
1055:                     "Could not retrieve JobResult.",
1056:                     ExceptionUtils.stripExecutionException(e));
1057:         }
1058: 
1059:         try {
1060:             return jobResult.toJobExecutionResult(Thread.currentThread().getContextClassLoader());
1061:         } catch (IOException | ClassNotFoundException e) {
1062:             throw new JobExecutionException(job.getJobID(), e);
1063:         }
1064:     }
