1066:     public CompletableFuture<JobSubmissionResult> submitJob(ExecutionPlan executionPlan) {
1067:         if (executionPlan instanceof StreamGraph) {
1068:             try {
1069:                 ((StreamGraph) executionPlan).serializeUserDefinedInstances();
1070:             } catch (IOException e) {
1071:                 throw new RuntimeException(e);
1072:             }
1073:         }
1074: 
1075:         // When MiniCluster uses the local RPC, the provided ExecutionPlan is passed directly to the
1076:         // Dispatcher. This means that any mutations to the JG can affect the Dispatcher behaviour,
1077:         // so we rather clone it to guard against this.
1078:         final ExecutionPlan clonedExecutionPlan = InstantiationUtil.cloneUnchecked(executionPlan);
1079:         checkRestoreModeForChangelogStateBackend(clonedExecutionPlan);
1080:         final CompletableFuture<DispatcherGateway> dispatcherGatewayFuture =
1081:                 getDispatcherGatewayFuture();
1082:         final CompletableFuture<InetSocketAddress> blobServerAddressFuture =
1083:                 createBlobServerAddress(dispatcherGatewayFuture);
1084:         final CompletableFuture<Void> jarUploadFuture =
1085:                 uploadAndSetJobFiles(blobServerAddressFuture, clonedExecutionPlan);
1086:         final CompletableFuture<Acknowledge> acknowledgeCompletableFuture =
1087:                 jarUploadFuture
1088:                         .thenCombine(
1089:                                 dispatcherGatewayFuture,
1090:                                 (Void ack, DispatcherGateway dispatcherGateway) ->
1091:                                         dispatcherGateway.submitJob(
1092:                                                 clonedExecutionPlan, rpcTimeout))
1093:                         .thenCompose(Function.identity());
1094:         return acknowledgeCompletableFuture.thenApply(
1095:                 (Acknowledge ignored) -> new JobSubmissionResult(clonedExecutionPlan.getJobID()));
1096:     }
