1098:     // HACK: temporary hack to make the randomized changelog state backend tests work with forced
1099:     // full snapshots. This option should be removed once changelog state backend supports forced
1100:     // full snapshots
1101:     private void checkRestoreModeForChangelogStateBackend(ExecutionPlan executionPlan) {
1102:         final SavepointRestoreSettings savepointRestoreSettings =
1103:                 executionPlan.getSavepointRestoreSettings();
1104:         if (overrideRestoreModeForChangelogStateBackend
1105:                 && savepointRestoreSettings.getRecoveryClaimMode() == RecoveryClaimMode.NO_CLAIM) {
1106:             final Configuration conf = new Configuration();
1107:             SavepointRestoreSettings.toConfiguration(savepointRestoreSettings, conf);
1108:             conf.set(StateRecoveryOptions.RESTORE_MODE, RecoveryClaimMode.LEGACY);
1109:             executionPlan.setSavepointRestoreSettings(
1110:                     SavepointRestoreSettings.fromConfiguration(conf));
1111:         }
1112:     }
