1260:         final Collection<CompletableFuture<Void>> terminationFutures =
1261:                 new ArrayList<>(dispatcherResourceManagerComponents.size());
1262: 
1263:         for (DispatcherResourceManagerComponent dispatcherResourceManagerComponent :
1264:                 dispatcherResourceManagerComponents) {
