1266:         }
1267: 
1268:         final FutureUtils.ConjunctFuture<Void> dispatcherTerminationFuture =
1269:                 FutureUtils.completeAll(terminationFutures);
1270: 
1271:         return FutureUtils.runAfterwards(
1272:                 dispatcherTerminationFuture,
1273:                 () -> {
1274:                     Exception exception = null;
1275: 
1276:                     synchronized (lock) {
1277:                         if (resourceManagerLeaderRetriever != null) {
1278:                             try {
1279:                                 resourceManagerLeaderRetriever.stop();
1280:                             } catch (Exception e) {
1281:                                 exception = ExceptionUtils.firstOrSuppressed(e, exception);
1282:                             }
1283: 
1284:                             resourceManagerLeaderRetriever = null;
1285:                         }
1286: 
1287:                         if (dispatcherLeaderRetriever != null) {
1288:                             try {
1289:                                 dispatcherLeaderRetriever.stop();
1290:                             } catch (Exception e) {
1291:                                 exception = ExceptionUtils.firstOrSuppressed(e, exception);
1292:                             }
1293: 
1294:                             dispatcherLeaderRetriever = null;
1295:                         }
1296: 
1297:                         if (clusterRestEndpointLeaderRetrievalService != null) {
1298:                             try {
1299:                                 clusterRestEndpointLeaderRetrievalService.stop();
1300:                             } catch (Exception e) {
1301:                                 exception = ExceptionUtils.firstOrSuppressed(e, exception);
1302:                             }
1303: 
1304:                             clusterRestEndpointLeaderRetrievalService = null;
1305:                         }
1306:                     }
1307: 
