1314:     private void terminateMiniClusterServices(boolean cleanupHaData) throws Exception {
1315:         // collect the first exception, but continue and add all successive
1316:         // exceptions as suppressed
1317:         Exception exception = null;
1318: 
1319:         synchronized (lock) {
1320:             if (blobCacheService != null) {
1321:                 try {
1322:                     blobCacheService.close();
1323:                 } catch (Exception e) {
1324:                     exception = ExceptionUtils.firstOrSuppressed(e, exception);
1325:                 }
1326:                 blobCacheService = null;
1327:             }
1328: 
1329:             // shut down the blob server
1330:             if (blobServer != null) {
1331:                 try {
1332:                     blobServer.close();
1333:                 } catch (Exception e) {
1334:                     exception = ExceptionUtils.firstOrSuppressed(e, exception);
1335:                 }
1336:                 blobServer = null;
1337:             }
1338: 
1339:             // shut down high-availability services
1340:             if (haServices != null) {
1341:                 haServices.closeWithOptionalClean(cleanupHaData);
1342:                 haServices = null;
1343:             }
1344: 
1345:             try {
1346:                 if (rpcSystem.isOwned()) {
1347:                     rpcSystem.deref().close();
1348:                 }
1349:             } catch (Exception e) {
1350:                 exception = ExceptionUtils.firstOrSuppressed(e, exception);
1351:             }
1352: 
1353:             if (exception != null) {
1354:                 throw exception;
1355:             }
1356:         }
1357:     }
