32: public final class FlinkPipelineTranslationUtil {
33: 
34:     /** Transmogrifies the given {@link Pipeline} to a {@link JobGraph}. */
35:     public static JobGraph getJobGraph(
36:             ClassLoader userClassloader,
37:             Pipeline pipeline,
38:             Configuration optimizerConfiguration,
39:             int defaultParallelism) {
40: 
41:         FlinkPipelineTranslator pipelineTranslator =
42:                 getPipelineTranslator(userClassloader, pipeline);
43: 
44:         JobGraph jobGraph =
45:                 pipelineTranslator.translateToJobGraph(
46:                         pipeline, optimizerConfiguration, defaultParallelism);
47: 
48:         optimizerConfiguration
49:                 .getOptional(PipelineOptions.PARALLELISM_OVERRIDES)
50:                 .ifPresent(
51:                         map ->
52:                                 jobGraph.getJobConfiguration()
53:                                         .set(PipelineOptions.PARALLELISM_OVERRIDES, map));
54: 
55:         return jobGraph;
56:     }
57: 
58:     /**
59:      * Transmogrifies the given {@link Pipeline} under the userClassloader to a {@link JobGraph}.
60:      */
61:     public static JobGraph getJobGraphUnderUserClassLoader(
62:             final ClassLoader userClassloader,
63:             final Pipeline pipeline,
64:             final Configuration configuration,
65:             final int defaultParallelism) {
66:         final ClassLoader contextClassLoader = Thread.currentThread().getContextClassLoader();
67:         try {
68:             Thread.currentThread().setContextClassLoader(userClassloader);
69:             return FlinkPipelineTranslationUtil.getJobGraph(
70:                     userClassloader, pipeline, configuration, defaultParallelism);
71:         } finally {
72:             Thread.currentThread().setContextClassLoader(contextClassLoader);
73:         }
74:     }
