85:             ClassLoader userClassloader, Pipeline pipeline) {
86: 
87:         StreamGraphTranslator streamGraphTranslator = new StreamGraphTranslator(userClassloader);
88: 
89:         if (streamGraphTranslator.canTranslate(pipeline)) {
90:             return streamGraphTranslator;
