63: @Internal
64: public class AbstractSessionClusterExecutor<
65:                 ClusterID, ClientFactory extends ClusterClientFactory<ClusterID>>
66:         implements CacheSupportedPipelineExecutor {
67:     private static final Logger LOG = LoggerFactory.getLogger(AbstractSessionClusterExecutor.class);
68:     private final ExecutorService executorService =
69:             Executors.newFixedThreadPool(
70:                     1, new ExecutorThreadFactory("Flink-SessionClusterExecutor-IO"));
71: 
72:     private final ClientFactory clusterClientFactory;
73:     private final Configuration configuration;
74:     private final List<JobStatusChangedListener> jobStatusChangedListeners;
75: 
76:     public AbstractSessionClusterExecutor(
77:             @Nonnull final ClientFactory clusterClientFactory, Configuration configuration) {
78:         this.clusterClientFactory = checkNotNull(clusterClientFactory);
79:         this.configuration = configuration;
80:         this.jobStatusChangedListeners =
81:                 JobStatusChangedListenerUtils.createJobStatusChangedListeners(
82:                         Thread.currentThread().getContextClassLoader(),
83:                         configuration,
84:                         executorService);
85:     }
