87:     @Override
88:     public CompletableFuture<JobClient> execute(
89:             @Nonnull final Pipeline pipeline,
90:             @Nonnull final Configuration configuration,
91:             @Nonnull final ClassLoader userCodeClassloader)
92:             throws Exception {
93:         final JobGraph jobGraph =
94:                 PipelineExecutorUtils.getExecutionPlan(pipeline, configuration, userCodeClassloader);
95: 
96:         try (final ClusterDescriptor<ClusterID> clusterDescriptor =
97:                 clusterClientFactory.createClusterDescriptor(configuration)) {
98:             final ClusterID clusterID = clusterClientFactory.getClusterId(configuration);
99:             checkState(clusterID != null);
100: 
101:             final ClusterClientProvider<ClusterID> clusterClientProvider =
102:                     clusterDescriptor.retrieve(clusterID);
103:             ClusterClient<ClusterID> clusterClient = clusterClientProvider.getClusterClient();
104:             return clusterClient
105:                     .submitJob(jobGraph)
106:                     .thenApplyAsync(
107:                             FunctionUtils.uncheckedFunction(
108:                                     jobId -> {
109:                                         ClientUtils.waitUntilJobInitializationFinished(
110:                                                 () -> clusterClient.getJobStatus(jobId).get(),
111:                                                 () -> clusterClient.requestJobResult(jobId).get(),
112:                                                 userCodeClassloader);
113:                                         return jobId;
114:                                     }))
115:                     .thenApplyAsync(
116:                             jobID ->
117:                                     (JobClient)
118:                                             new ClusterClientJobClientAdapter<>(
119:                                                     clusterClientProvider,
120:                                                     jobID,
121:                                                     userCodeClassloader))
122:                     .whenCompleteAsync(
123:                             (jobClient, throwable) -> {
124:                                 if (throwable == null) {
125:                                     PipelineExecutorUtils.notifyJobStatusListeners(
126:                                             pipeline, jobGraph, jobStatusChangedListeners);
127:                                 } else {
128:                                     LOG.error(
129:                                             "Failed to submit job graph to remote session cluster.",
130:                                             throwable);
131:                                 }
132:                                 clusterClient.close();
133:                             });
134:         }
135:     }
