144:     private StreamGraph createJobGraph(Configuration conf) {
145:         StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment(conf);
146:         env.fromSequence(Long.MIN_VALUE, Long.MAX_VALUE)
147:                 .keyBy(num -> num % 1000)
148:                 .map(
149:                         new RichMapFunction<Long, Long>() {
150:                             @Override
151:                             public Long map(Long value) throws Exception {
152:                                 getRuntimeContext()
153:                                         .getState(new ValueStateDescriptor<>("state", Long.class))
154:                                         .update(value);
