456:     @Override
457:     public void enableCheckpointing(
458:             CheckpointCoordinatorConfiguration chkConfig,
459:             List<MasterTriggerRestoreHook<?>> masterHooks,
460:             CheckpointIDCounter checkpointIDCounter,
461:             CompletedCheckpointStore checkpointStore,
462:             StateBackend checkpointStateBackend,
463:             CheckpointStorage checkpointStorage,
464:             CheckpointStatsTracker statsTracker,
465:             CheckpointsCleaner checkpointsCleaner,
466:             String changelogStorageName) {
467: 
468:         checkState(state == JobStatus.CREATED, "Job must be in CREATED state");
469:         checkState(checkpointCoordinator == null, "checkpointing already enabled");
470: 
471:         final Collection<OperatorCoordinatorCheckpointContext> operatorCoordinators =
472:                 buildOpCoordinatorCheckpointContexts();
473: 
474:         checkpointStatsTracker = checkNotNull(statsTracker, "CheckpointStatsTracker");
475:         checkpointCoordinatorConfiguration =
476:                 checkNotNull(chkConfig, "CheckpointCoordinatorConfiguration");
477: 
478:         CheckpointFailureManager failureManager =
479:                 new CheckpointFailureManager(
480:                         chkConfig.getTolerableCheckpointFailureNumber(),
481:                         new CheckpointFailureManager.FailJobCallback() {
482:                             @Override
483:                             public void failJob(Throwable cause) {
484:                                 getJobMasterMainThreadExecutor().execute(() -> failGlobal(cause));
485:                             }
486: 
487:                             @Override
488:                             public void failJobDueToTaskFailure(
489:                                     Throwable cause, ExecutionAttemptID failingTask) {
490:                                 getJobMasterMainThreadExecutor()
491:                                         .execute(
492:                                                 () ->
493:                                                         failGlobalIfExecutionIsStillRunning(
494:                                                                 cause, failingTask));
495:                             }
496:                         });
497: 
498:         checkState(checkpointCoordinatorTimer == null);
499: 
500:         checkpointCoordinatorTimer =
501:                 MdcUtils.scopeToJob(
502:                         getJobID(),
503:                         Executors.newSingleThreadScheduledExecutor(
504:                                 new DispatcherThreadFactory(
505:                                         Thread.currentThread().getThreadGroup(),
506:                                         "Checkpoint Timer")));
507: 
508:         // create the coordinator that triggers and commits checkpoints and holds the state
509:         checkpointCoordinator =
510:                 new CheckpointCoordinator(
511:                         jobInformation.getJobId(),
512:                         chkConfig,
513:                         operatorCoordinators,
514:                         checkpointIDCounter,
515:                         checkpointStore,
516:                         checkpointStorage,
517:                         ioExecutor,
518:                         checkpointsCleaner,
519:                         new ScheduledExecutorServiceAdapter(checkpointCoordinatorTimer),
520:                         failureManager,
521:                         createCheckpointPlanCalculator(
522:                                 chkConfig.isEnableCheckpointsAfterTasksFinish()),
523:                         checkpointStatsTracker);
524: 
525:         // register the master hooks on the checkpoint coordinator
526:         for (MasterTriggerRestoreHook<?> hook : masterHooks) {
527:             if (!checkpointCoordinator.addMasterHook(hook)) {
528:                 LOG.warn(
529:                         "Trying to register multiple checkpoint hooks with the name: {}",
530:                         hook.getIdentifier());
531:             }
532:         }
533: 
534:         if (checkpointCoordinator.isPeriodicCheckpointingConfigured()) {
535:             // the periodic checkpoint scheduler is activated and deactivated as a result of
536:             // job status and topology changes (running & all edges non-blocking -> on, all
537:             // other states -> off)
538:             boolean allTasksOutputNonBlocking =
539:                     tasks.values().stream()
540:                             .noneMatch(vertex -> vertex.getJobVertex().isAnyOutputBlocking());
541:             registerJobStatusListener(
542:                     checkpointCoordinator.createActivatorDeactivator(allTasksOutputNonBlocking));
543:         }
544: 
545:         this.stateBackendName = checkpointStateBackend.getName();
546:         this.stateChangelogEnabled =
547:                 TernaryBoolean.fromBoolean(
548:                         StateBackendLoader.isChangelogStateBackend(checkpointStateBackend));
549: 
550:         this.checkpointStorageName = checkpointStorage.getClass().getSimpleName();
551:         this.changelogStorageName = changelogStorageName;
552:     }
