775:     /**
776:      * Gets a serialized accumulator map.
777:      *
778:      * @return The accumulator map with serialized accumulator values.
779:      */
780:     @Override
781:     public Map<String, SerializedValue<OptionalFailure<Object>>> getAccumulatorsSerialized() {
782:         return aggregateUserAccumulators().entrySet().stream()
783:                 .collect(
784:                         Collectors.toMap(
785:                                 Map.Entry::getKey,
786:                                 entry -> serializeAccumulator(entry.getKey(), entry.getValue())));
