789:     private static SerializedValue<OptionalFailure<Object>> serializeAccumulator(
790:             String name, OptionalFailure<Accumulator<?, ?>> accumulator) {
791:         try {
792:             if (accumulator.isFailure()) {
793:                 return new SerializedValue<>(
794:                         OptionalFailure.ofFailure(accumulator.getFailureCause()));
795:             }
796:             return new SerializedValue<>(
797:                     OptionalFailure.of(accumulator.getUnchecked().getLocalValue()));
798:         } catch (IOException ioe) {
799:             LOG.error("Could not serialize accumulator " + name + '.', ioe);
800:             try {
801:                 return new SerializedValue<>(OptionalFailure.ofFailure(ioe));
802:             } catch (IOException e) {
803:                 throw new RuntimeException(
804:                         "It should never happen that we cannot serialize the accumulator serialization exception.",
805:                         e);
806:             }
807:         }
808:     }
