867:     /** Attach job vertices without initializing them. */
868:     private void attachJobVertices(
869:             List<JobVertex> topologicallySorted, JobManagerJobMetricGroup jobManagerJobMetricGroup)
870:             throws JobException {
871:         for (JobVertex jobVertex : topologicallySorted) {
872: 
873:             if (jobVertex.isInputVertex() && !jobVertex.isStoppable()) {
874:                 this.isStoppable = false;
875:             }
876: 
877:             VertexParallelismInformation parallelismInfo =
878:                     parallelismStore.getParallelismInfo(jobVertex.getID());
879: 
880:             // create the execution job vertex and attach it to the graph
881:             ExecutionJobVertex ejv =
882:                     executionJobVertexFactory.createExecutionJobVertex(
883:                             this,
884:                             jobVertex,
885:                             parallelismInfo,
886:                             coordinatorStore,
887:                             jobManagerJobMetricGroup);
888: 
889:             ExecutionJobVertex previousTask = this.tasks.putIfAbsent(jobVertex.getID(), ejv);
890:             if (previousTask != null) {
891:                 throw new JobException(
892:                         String.format(
893:                                 "Encountered two job vertices with ID %s : previous=[%s] / new=[%s]",
894:                                 jobVertex.getID(), ejv, previousTask));
895:             }
896: 
897:             this.verticesInCreationOrder.add(ejv);
898:             this.numJobVerticesTotal++;
899:         }
900:     }
