902:     private void initializeJobVertices(List<JobVertex> topologicallySorted) throws JobException {
903:         final long createTimestamp = System.currentTimeMillis();
904: 
905:         for (JobVertex jobVertex : topologicallySorted) {
906:             final ExecutionJobVertex ejv = tasks.get(jobVertex.getID());
907:             initializeJobVertex(ejv, createTimestamp);
