911:     @Override
912:     public void initializeJobVertex(
913:             ExecutionJobVertex ejv,
914:             long createTimestamp,
915:             Map<IntermediateDataSetID, JobVertexInputInfo> jobVertexInputInfos)
916:             throws JobException {
917: 
918:         checkNotNull(ejv);
919:         checkNotNull(jobVertexInputInfos);
920: 
921:         jobVertexInputInfos.forEach(
922:                 (resultId, info) ->
923:                         this.vertexInputInfoStore.put(ejv.getJobVertexId(), resultId, info));
924: 
925:         ejv.initialize(
926:                 executionHistorySizeLimit,
927:                 rpcTimeout,
928:                 createTimestamp,
929:                 this.initialAttemptCounts.getAttemptCounts(ejv.getJobVertexId()));
930: 
931:         ejv.connectToPredecessors(this.intermediateResults);
932: 
933:         for (IntermediateResult res : ejv.getProducedDataSets()) {
934:             IntermediateResult previousDataSet =
935:                     this.intermediateResults.putIfAbsent(res.getId(), res);
936:             if (previousDataSet != null) {
937:                 throw new JobException(
938:                         String.format(
939:                                 "Encountered two intermediate data set with ID %s : previous=[%s] / new=[%s]",
940:                                 res.getId(), res, previousDataSet));
941:             }
942:         }
943: 
944:         registerExecutionVerticesAndResultPartitionsFor(ejv);
945: 
946:         // enrich network memory.
947:         SlotSharingGroup slotSharingGroup = ejv.getSlotSharingGroup();
948:         if (areJobVerticesAllInitialized(slotSharingGroup)) {
949:             SsgNetworkMemoryCalculationUtils.enrichNetworkMemory(
950:                     slotSharingGroup, this::getJobVertex, shuffleMaster);
951:         }
952:     }
953: 
954:     private boolean areJobVerticesAllInitialized(final SlotSharingGroup group) {
955:         for (JobVertexID jobVertexId : group.getJobVertexIds()) {
956:             final ExecutionJobVertex jobVertex = getJobVertex(jobVertexId);
957:             checkNotNull(jobVertex, "Unknown job vertex %s", jobVertexId);
958:             if (!jobVertex.isInitialized()) {
959:                 return false;
960:             }
961:         }
962:         return true;
963:     }
