973:     @Override
974:     public void cancel() {
975: 
976:         assertRunningInJobMasterMainThread();
977: 
978:         while (true) {
979:             JobStatus current = state;
980: 
981:             if (current == JobStatus.RUNNING
982:                     || current == JobStatus.CREATED
983:                     || current == JobStatus.RESTARTING) {
984:                 if (transitionState(current, JobStatus.CANCELLING)) {
985:                     resetExecutionGraph(ExecutionJobVertex::cancelWithFuture)
986:                             .whenComplete(
987:                                     (Void value, Throwable throwable) -> {
988:                                         if (throwable != null) {
989:                                             transitionState(
990:                                                     JobStatus.CANCELLING,
991:                                                     JobStatus.FAILED,
992:                                                     new FlinkException(
993:                                                             "Could not cancel job "
994:                                                                     + getJobName()
995:                                                                     + " because not all execution job vertices could be cancelled.",
996:                                                             throwable));
997:                                         } else {
998:                                             // cancellations may currently be overridden by failures
999:                                             // which trigger restarts, so we need to pass a proper
1000:                                             // restart global version here
1001:                                             allVerticesInTerminalState();
1002:                                         }
1003:                                     });
1004: 
1005:                     return;
1006:                 }
1007:             }
1008:             // Executions are being canceled. Go into cancelling and wait for
1009:             // all vertices to be in their final state.
1010:             else if (current == JobStatus.FAILING) {
1011:                 if (transitionState(current, JobStatus.CANCELLING)) {
1012:                     return;
1013:                 }
1014:             } else {
1015:                 // no need to treat other states
1016:                 return;
1017:             }
1018:         }
1019:     }
