1021:     private CompletableFuture<Void> resetExecutionGraph(
1022:             Function<ExecutionJobVertex, CompletableFuture<Void>> perVertexOperationAsync) {
1023:         assertRunningInJobMasterMainThread();
1024: 
1025:         incrementRestarts();
1026: 
1027:         // cancel ongoing scheduling action
1028:         if (schedulingFuture != null) {
1029:             schedulingFuture.cancel(false);
1030:         }
1031: 
1032:         return applyToVertexAsync(perVertexOperationAsync);
1033:     }
1034: 
1035:     private CompletableFuture<Void> applyToVertexAsync(
1036:             Function<ExecutionJobVertex, CompletableFuture<Void>> perVertexOperationAsync) {
1037:         return FutureUtils.waitForAll(
1038:                 verticesInCreationOrder.stream()
1039:                         .map(perVertexOperationAsync)
1040:                         .collect(Collectors.toList()));
1041:     }
