1043:     @Override
1044:     public void suspend(Throwable suspensionCause) {
1045: 
1046:         assertRunningInJobMasterMainThread();
1047: 
1048:         if (state.isTerminalState()) {
1049:             // stay in a terminal state
1050:             return;
1051:         } else if (transitionState(state, JobStatus.SUSPENDED, suspensionCause)) {
1052:             initFailureCause(suspensionCause, System.currentTimeMillis());
1053: 
1054:             final CompletableFuture<Void> jobVerticesTerminationFuture =
1055:                     resetExecutionGraph(ExecutionJobVertex::suspend);
1056: 
1057:             checkState(jobVerticesTerminationFuture.isDone(), "Suspend needs to happen atomically");
1058: 
1059:             jobVerticesTerminationFuture.whenComplete(
1060:                     (Void ignored, Throwable throwable) -> {
1061:                         if (throwable != null) {
1062:                             LOG.debug("Could not properly suspend the execution graph.", throwable);
1063:                         }
1064: 
1065:                         onTerminalState(state);
1066:                         LOG.info("Job {} has been suspended.", getJobID());
1067:                     });
1068:         } else {
1069:             throw new IllegalStateException(
1070:                     String.format(
1071:                             "Could not suspend because transition from %s to %s failed.",
1072:                             state, JobStatus.SUSPENDED));
1073:         }
1074:     }
