1076:     void failGlobalIfExecutionIsStillRunning(Throwable cause, ExecutionAttemptID failingAttempt) {
1077:         final Execution failedExecution = currentExecutions.get(failingAttempt);
1078:         if (failedExecution != null
1079:                 && (failedExecution.getState() == ExecutionState.RUNNING
1080:                         || failedExecution.getState() == ExecutionState.INITIALIZING)) {
1081:             failGlobal(cause);
1082:         } else {
1083:             LOG.debug(
1084:                     "The failing attempt {} belongs to an already not"
1085:                             + " running task thus won't fail the job",
1086:                     failingAttempt);
1087:         }
1088:     }
