237:     public static Set<StateHandleID> getAllStateHandleId(JobID jobID, MiniCluster miniCluster)
238:             throws IOException, FlinkJobNotFoundException, ExecutionException,
239:                     InterruptedException {
240:         Optional<String> mostRecentCompletedCheckpointPath =
241:                 getLatestCompletedCheckpointPath(jobID, miniCluster);
242:         if (!mostRecentCompletedCheckpointPath.isPresent()) {
243:             return Collections.emptySet();
244:         }
245: 
246:         CheckpointMetadata checkpointMetadata;
247:         try {
248:             checkpointMetadata = loadCheckpointMetadata(mostRecentCompletedCheckpointPath.get());
249:         } catch (IOException ioException) {
250:             if (ExceptionUtils.findThrowable(ioException, FileNotFoundException.class)
251:                     .isPresent()) {
252:                 // return empty result when the metadata file do not exist due to subsumed
253:                 // checkpoint.
254:                 return Collections.emptySet();
255:             }
256:             throw ioException;
257:         }
258: 
259:         Set<StateHandleID> materializationIds =
260:                 checkpointMetadata.getOperatorStates().stream()
261:                         .flatMap(operatorState -> operatorState.getStates().stream())
262:                         .flatMap(
263:                                 operatorSubtaskState ->
264:                                         operatorSubtaskState.getManagedKeyedState().stream())
265:                         .flatMap(
266:                                 keyedStateHandle ->
267:                                         keyedStateHandle instanceof ChangelogStateBackendHandle
268:                                                 ? ((ChangelogStateBackendHandle) keyedStateHandle)
269:                                                         .getMaterializedStateHandles().stream()
270:                                                 : Stream.of(keyedStateHandle))
271:                         .map(KeyedStateHandle::getStateHandleId)
272:                         .collect(Collectors.toSet());
273:         if (!materializationIds.isEmpty()) {
274:             return materializationIds;
275:         }
276:         return Collections.emptySet();
277:     }
