297:     /** A source consumes data which is generated randomly and supports pre-handling record. */
298:     protected static class ControlledSource extends RichSourceFunction<Integer>
299:             implements CheckpointedFunction, CheckpointListener {
300: 
301:         private static final long serialVersionUID = 1L;
302: 
303:         protected volatile int currentIndex;
304: 
305:         protected final AtomicInteger completedCheckpointNum;
306: 
307:         protected volatile boolean isCanceled;
308: 
309:         private static final List<Integer> sourceList =
310:                 Collections.unmodifiableList(initSourceData(TOTAL_ELEMENTS));
311: 
312:         private transient ListState<Integer> currentIndexState;
313: 
314:         private transient ListState<Integer> completedCheckpointNumState;
315: 
316:         public ControlledSource() {
317:             this.completedCheckpointNum = new AtomicInteger();
318:         }
319: 
320:         public static List<Integer> initSourceData(int totalNum) {
321:             List<Integer> sourceList = new ArrayList<>(totalNum);
322:             for (int i = 0; i < totalNum; i++) {
323:                 sourceList.add(ThreadLocalRandom.current().nextInt(totalNum));
324:             }
325:             return sourceList;
326:         }
327: 
328:         public static Map<Integer, Integer> getExpectedResult() {
329:             return sourceList.stream()
330:                     .collect(
331:                             Collectors.toConcurrentMap(
332:                                     element -> element % 100, element -> 1, Integer::sum));
333:         }
334: 
335:         @Override
336:         public void snapshotState(FunctionSnapshotContext context) throws Exception {
337:             currentIndexState.update(Collections.singletonList(currentIndex));
338:             completedCheckpointNumState.update(
339:                     Collections.singletonList(completedCheckpointNum.get()));
340:         }
341: 
342:         @Override
343:         public void initializeState(FunctionInitializationContext context) throws Exception {
344:             currentIndexState =
345:                     context.getOperatorStateStore()
346:                             .getListState(
347:                                     new ListStateDescriptor<>("currentIndexState", Integer.class));
348:             completedCheckpointNumState =
349:                     context.getOperatorStateStore()
350:                             .getListState(
351:                                     new ListStateDescriptor<>(
352:                                             "completedCheckpointNumState", Integer.class));
353:             if (context.isRestored()) {
354:                 currentIndex = get(currentIndexState.get(), 0);
355:                 completedCheckpointNum.compareAndSet(0, get(completedCheckpointNumState.get(), 0));
356:             }
357:         }
358: 
359:         @Override
360:         public void run(SourceContext<Integer> ctx) throws Exception {
361:             while (!isCanceled && currentIndex < sourceList.size()) {
362:                 beforeElement(ctx);
363:                 synchronized (ctx.getCheckpointLock()) {
364:                     if (!isCanceled && currentIndex < sourceList.size()) {
365:                         int currentElement = sourceList.get(currentIndex++);
366:                         ctx.collect(currentElement % 100);
367:                     }
368:                 }
369:             }
370:         }
371: 
372:         // it runs without holding the checkpoint lock
373:         protected void beforeElement(SourceContext<Integer> ctx) throws Exception {
374:             // do nothing by default
375:         }
376: 
377:         protected void waitWhile(SerializableBooleanSupplierWithException supplier)
378:                 throws Exception {
379:             while (supplier.getAsBoolean()) {
380:                 Thread.sleep(10);
381:             }
382:         }
383: 
384:         protected void throwArtificialFailure() throws Exception {
385:             throw new ArtificialFailure();
386:         }
387: 
388:         @Override
389:         public void cancel() {
390:             isCanceled = true;
391:         }
392: 
393:         @Override
394:         public void notifyCheckpointComplete(long checkpointId) throws Exception {
395:             completedCheckpointNum.getAndIncrement();
396:         }
397:     }
