435:         @Override
436:         public void processElement(
437:                 Integer value, Context ctx, Collector<Tuple2<Integer, Integer>> out)
438:                 throws Exception {
439:             Integer count = countState.value();
440:             Integer currentCount = count == null ? 1 : count + 1;
441:             countState.update(currentCount);
442:             out.collect(Tuple2.of(value, currentCount));
443:         }
444:     }
