255:     @SafeVarargs
256:     protected final void executeAndSnapshot(
257:             StreamExecutionEnvironment env,
258:             String snapshotPath,
259:             SnapshotType snapshotType,
260:             Tuple2<String, Integer>... expectedAccumulators)
261:             throws Exception {
262: 
263:         final Deadline deadLine = Deadline.fromNow(Duration.ofMinutes(5));
264: 
265:         ClusterClient<?> client = miniClusterResource.getClusterClient();
266: 
267:         // Submit the job
268:         StreamGraph jobGraph = env.getStreamGraph().getJobGraph();
269: 
270:         JobID jobID = client.submitJob(jobGraph).get();
271: 
272:         LOG.info("Submitted job {} and waiting...", jobID);
273: 
274:         boolean done = false;
275:         while (deadLine.hasTimeLeft()) {
276:             Thread.sleep(100);
277:             Map<String, Object> accumulators = client.getAccumulators(jobID).get();
278: 
279:             boolean allDone = true;
280:             for (Tuple2<String, Integer> acc : expectedAccumulators) {
281:                 Object accumOpt = accumulators.get(acc.f0);
282:                 if (accumOpt == null) {
283:                     allDone = false;
284:                     break;
285:                 }
286: 
287:                 Integer numFinished = (Integer) accumOpt;
288:                 if (!numFinished.equals(acc.f1)) {
289:                     allDone = false;
290:                     break;
291:                 }
292:             }
293:             if (allDone) {
294:                 done = true;
295:                 break;
296:             }
297:         }
298: 
299:         if (!done) {
300:             fail("Did not see the expected accumulator results within time limit.");
301:         }
302: 
303:         LOG.info("Triggering snapshot.");
304: 
305:         CompletableFuture<String> snapshotPathFuture;
306:         switch (snapshotType) {
307:             case SAVEPOINT_CANONICAL:
308:                 snapshotPathFuture =
309:                         client.triggerSavepoint(jobID, null, SavepointFormatType.CANONICAL);
310:                 break;
311:             case SAVEPOINT_NATIVE:
312:                 snapshotPathFuture =
313:                         client.triggerSavepoint(jobID, null, SavepointFormatType.NATIVE);
314:                 break;
315:             case CHECKPOINT:
316:                 snapshotPathFuture = miniClusterResource.getMiniCluster().triggerCheckpoint(jobID);
317:                 break;
318:             default:
319:                 throw new UnsupportedOperationException("Snapshot type not supported/implemented.");
320:         }
321: 
322:         String jobmanagerSnapshotPath =
323:                 snapshotPathFuture.get(deadLine.timeLeft().toMillis(), TimeUnit.MILLISECONDS);
324: 
325:         File jobManagerSnapshot = new File(new URI(jobmanagerSnapshotPath).getPath());
326:         // savepoints were changed to be directories in Flink 1.3
327:         if (jobManagerSnapshot.isDirectory()) {
328:             FileUtils.moveDirectory(jobManagerSnapshot, new File(snapshotPath));
329:         } else {
330:             FileUtils.moveFile(jobManagerSnapshot, new File(snapshotPath));
331:         }
332:     }
