168:     private static class Source implements SourceFunction<Integer>, CheckpointedFunction {
169: 
170:         private volatile boolean running = true;
171:         private int emittedCount;
172:         private ListState<Integer> state;
173: 
174:         @Override
175:         public void run(SourceContext<Integer> ctx) throws Exception {
176:             while (running) {
177:                 synchronized (ctx.getCheckpointLock()) {
178:                     if (emittedCount == 0) {
179:                         ctx.collect(0);
180:                         emittedCount = 1;
181:                     } else if (emittedCount == 1) {
182:                         ctx.collect(emittedCount);
183:                     } else {
184:                         ctx.collect(emittedCount++);
185:                     }
186:                 }
187:                 Thread.sleep(1);
188:             }
189:         }
190: 
191:         @Override
192:         public void cancel() {
193:             this.running = false;
194:         }
195: 
196:         @Override
197:         public void snapshotState(FunctionSnapshotContext context) throws Exception {
198:             state.add(emittedCount);
199:         }
200: 
201:         @Override
202:         public void initializeState(FunctionInitializationContext context) throws Exception {
203:             state =
204:                     context.getOperatorStateStore()
205:                             .getListState(
206:                                     new ListStateDescriptor<>(
207:                                             "emittedCount", IntSerializer.INSTANCE));
208:             if (context.isRestored()) {
209:                 this.emittedCount = 2;
210:             }
211:         }
212:     }
