214:     private static class TimersProcessFunction
215:             extends KeyedProcessFunction<Integer, Integer, Integer> {
216: 
217:         @Override
218:         public void processElement(Integer value, Context ctx, Collector<Integer> out)
219:                 throws Exception {
220:             if (value == 0) {
221:                 ctx.timerService().registerEventTimeTimer(2L);
222:             }
223:         }
224: 
225:         @Override
226:         public void onTimer(long timestamp, OnTimerContext ctx, Collector<Integer> out)
227:                 throws Exception {
228:             out.collect(1);
229:             resultLatch.trigger();
230:         }
