148:         @Override
149:         public void run(SourceContext<Integer> ctx) throws Exception {
150:             if (isFailoverScenario && getRuntimeContext().getTaskInfo().getAttemptNumber() == 0) {
151:                 // In the first execution, we first send a part of record...
152:                 sendRecordsUntil((int) (numberOfRecords * FAILOVER_RATIO * 0.5), ctx);
