158: 
159:                 // Then we write the second part of data...
160:                 sendRecordsUntil((int) (numberOfRecords * FAILOVER_RATIO), ctx);
161: 
162:                 // And then trigger the failover.
163:                 if (getRuntimeContext().getTaskInfo().getIndexOfThisSubtask() == 0) {
164:                     throw new RuntimeException("Designated Exception");
165:                 } else {
166:                     while (true) {
