185:                     ctx.collect(nextValue++);
186:                 }
187:             }
188:         }
189: 
190:         @Override
191:         public void snapshotState(FunctionSnapshotContext context) throws Exception {
192:             nextValueState.update(Collections.singletonList(nextValue));
