52:     /** Helper class to signal between multiple processes that a job should stop. */
53:     public static class StopJobSignal implements Serializable {
54: 
55:         private final String stopJobMarkerFile;
56: 
57:         public static StopJobSignal usingMarkerFile(final Path stopJobMarkerFile) {
58:             return new StopJobSignal(stopJobMarkerFile.toString());
