64: 
65:         /** Signals that the job should stop. */
66:         public void signal() {
67:             try {
68:                 checkState(
69:                         Files.exists(Paths.get(stopJobMarkerFile)),
70:                         "Marker file is deleted before signal.");
71:                 Files.delete(Paths.get(stopJobMarkerFile));
72:             } catch (final IOException e) {
73:                 throw new RuntimeException(e);
74:             }
75:         }
76: 
