79:     public static class SpeedTestProducer extends AbstractInvokable {
80: 
81:         public SpeedTestProducer(Environment environment) {
82:             super(environment);
83:         }
84: 
85:         @Override
86:         public void invoke() throws Exception {
87:             RecordWriter<SpeedTestRecord> writer =
88:                     new RecordWriterBuilder<SpeedTestRecord>().build(getEnvironment().getWriter(0));
89: 
90:             try {
91:                 // Determine the amount of data to send per subtask
92:                 int dataVolumeGb =
93:                         getTaskConfiguration()
94:                                 .get(
