96:                                                 NetworkStackThroughputITCase
97:                                                         .DATA_VOLUME_GB_CONFIG_KEY),
98:                                         1);
99: 
100:                 long dataMbPerSubtask = (dataVolumeGb * 10) / getCurrentNumberOfSubtasks();
101:                 long numRecordsToEmit =
102:                         (dataMbPerSubtask * 1024 * 1024) / SpeedTestRecord.RECORD_SIZE;
103: 
104:                 LOG.info(
105:                         String.format(
106:                                 "%d/%d: Producing %d records (each record: %d bytes, total: %.2f GB)",
107:                                 getIndexInSubtaskGroup() + 1,
108:                                 getCurrentNumberOfSubtasks(),
109:                                 numRecordsToEmit,
110:                                 SpeedTestRecord.RECORD_SIZE,
111:                                 dataMbPerSubtask / 1024.0));
112: 
113:                 boolean isSlow =
114:                         getTaskConfiguration()
115:                                 .get(getBooleanConfigOption(IS_SLOW_SENDER_CONFIG_KEY), false);
116: 
117:                 int numRecords = 0;
118:                 SpeedTestRecord record = new SpeedTestRecord();
119:                 for (long i = 0; i < numRecordsToEmit; i++) {
120:                     if (isSlow && (numRecords++ % IS_SLOW_EVERY_NUM_RECORDS) == 0) {
121:                         Thread.sleep(IS_SLOW_SLEEP_MS);
