248:         for (Object[] p : configParams) {
249:             final int dataVolumeGb = (Integer) p[0];
250:             final boolean useForwarder = (Boolean) p[1];
251:             final boolean isSlowSender = (Boolean) p[2];
252:             final boolean isSlowReceiver = (Boolean) p[3];
253:             final int parallelism = (Integer) p[4];
254:             final int numSlotsPerTaskManager = (Integer) p[5];
255: 
256:             if (parallelism % numSlotsPerTaskManager != 0) {
257:                 throw new RuntimeException(
258:                         "The test case defines a parallelism that is not a multiple of the slots per task manager.");
259:             }
260: 
261:             final int numTaskManagers = parallelism / numSlotsPerTaskManager;
262: 
263:             final MiniClusterWithClientResource cluster =
264:                     new MiniClusterWithClientResource(
265:                             new MiniClusterResourceConfiguration.Builder()
266:                                     .setNumberTaskManagers(numTaskManagers)
267:                                     .setNumberSlotsPerTaskManager(numSlotsPerTaskManager)
268:                                     .build());
