275:                                 dataVolumeGb,
276:                                 useForwarder,
277:                                 isSlowSender,
278:                                 isSlowReceiver,
279:                                 parallelism,
280:                                 numSlotsPerTaskManager));
281:                 testProgram(
282:                         cluster,
283:                         dataVolumeGb,
284:                         useForwarder,
285:                         isSlowSender,
286:                         isSlowReceiver,
287:                         parallelism);
288:             } finally {
289:                 cluster.after();
290:             }
291:         }
292:     }
