294:     private void testProgram(
295:             final MiniClusterWithClientResource cluster,
296:             final int dataVolumeGb,
297:             final boolean useForwarder,
298:             final boolean isSlowSender,
299:             final boolean isSlowReceiver,
300:             final int parallelism)
301:             throws Exception {
302:         final ClusterClient<?> client = cluster.getClusterClient();
303:         final StreamGraph jobGraph =
304:                 createJobGraph(
305:                         dataVolumeGb, useForwarder, isSlowSender, isSlowReceiver, parallelism);
306:         final JobResult jobResult =
307:                 client.submitJob(jobGraph).thenCompose(client::requestJobResult).get();
308: 
309:         Assert.assertFalse(jobResult.getSerializedThrowable().isPresent());
310: 
311:         final long dataVolumeMbit = dataVolumeGb * 8192;
312:         final long runtimeSecs =
313:                 TimeUnit.SECONDS.convert(jobResult.getNetRuntime(), TimeUnit.MILLISECONDS);
314:         final int mbitPerSecond = (int) (((double) dataVolumeMbit) / runtimeSecs);
315: 
316:         LOG.info(
317:                 String.format(
318:                         "Test finished with throughput of %d MBit/s (runtime [secs]: %d, "
319:                                 + "data volume [gb/mbits]: %d/%d)",
320:                         mbitPerSecond, runtimeSecs, dataVolumeGb, dataVolumeMbit));
321:     }
322: 
323:     private StreamGraph createJobGraph(
324:             int dataVolumeGb,
325:             boolean useForwarder,
326:             boolean isSlowSender,
327:             boolean isSlowReceiver,
328:             int numSubtasks) {
329:         SlotSharingGroup sharingGroup = new SlotSharingGroup();
330: 
331:         final List<JobVertex> jobVertices = new ArrayList<>();
332: 
333:         JobVertex producer = new JobVertex("Speed Test Producer");
334:         producer.setSlotSharingGroup(sharingGroup);
335: 
336:         producer.setInvokableClass(SpeedTestProducer.class);
337:         producer.setParallelism(numSubtasks);
338:         producer.getConfiguration()
339:                 .set(getIntConfigOption(DATA_VOLUME_GB_CONFIG_KEY), dataVolumeGb);
340:         producer.getConfiguration()
341:                 .set(getBooleanConfigOption(IS_SLOW_SENDER_CONFIG_KEY), isSlowSender);
342: 
343:         jobVertices.add(producer);
344: 
345:         JobVertex forwarder = null;
346:         if (useForwarder) {
347:             forwarder = new JobVertex("Speed Test Forwarder");
348:             forwarder.setSlotSharingGroup(sharingGroup);
349: 
350:             forwarder.setInvokableClass(SpeedTestForwarder.class);
351:             forwarder.setParallelism(numSubtasks);
352:             jobVertices.add(forwarder);
353:         }
354: 
355:         JobVertex consumer = new JobVertex("Speed Test Consumer");
356:         consumer.setSlotSharingGroup(sharingGroup);
357: 
358:         consumer.setInvokableClass(SpeedTestConsumer.class);
359:         consumer.setParallelism(numSubtasks);
360:         consumer.getConfiguration()
361:                 .set(getBooleanConfigOption(IS_SLOW_RECEIVER_CONFIG_KEY), isSlowReceiver);
362: 
363:         jobVertices.add(consumer);
364: 
365:         if (useForwarder) {
366:             forwarder.connectNewDataSetAsInput(
367:                     producer, DistributionPattern.ALL_TO_ALL, ResultPartitionType.PIPELINED);
368:             consumer.connectNewDataSetAsInput(
369:                     forwarder, DistributionPattern.ALL_TO_ALL, ResultPartitionType.PIPELINED);
370:         } else {
371:             consumer.connectNewDataSetAsInput(
372:                     producer, DistributionPattern.ALL_TO_ALL, ResultPartitionType.PIPELINED);
373:         }
374: 
375:         return JobGraphTestUtils.streamingJobGraph(jobVertices.toArray(new JobVertex[0]));
376:     }
377: 
378:     public static void main(String[] args) throws Exception {
379:         new NetworkStackThroughputITCase().testThroughput();
380: 
381:         System.out.println("Done.");
382:     }
