450: 
451:     public List<JobVertex> getVerticesSortedTopologicallyFromSources()
452:             throws InvalidProgramException {
453:         // early out on empty lists
454:         if (this.taskVertices.isEmpty()) {
455:             return Collections.emptyList();
456:         }
457: 
458:         List<JobVertex> sorted = new ArrayList<JobVertex>(this.taskVertices.size());
459:         Set<JobVertex> remaining = new LinkedHashSet<JobVertex>(this.taskVertices.values());
460: 
461:         // start by finding the vertices with no input edges
462:         // and the ones with disconnected inputs (that refer to some standalone data set)
463:         {
464:             Iterator<JobVertex> iter = remaining.iterator();
465:             while (iter.hasNext()) {
466:                 JobVertex vertex = iter.next();
467: 
468:                 if (vertex.hasNoConnectedInputs()) {
469:                     sorted.add(vertex);
470:                     iter.remove();
471:                 }
472:             }
473:         }
474: 
475:         int startNodePos = 0;
476: 
477:         // traverse from the nodes that were added until we found all elements
478:         while (!remaining.isEmpty()) {
479: 
480:             // first check if we have more candidates to start traversing from. if not, then the
481:             // graph is cyclic, which is not permitted
482:             if (startNodePos >= sorted.size()) {
483:                 throw new InvalidProgramException("The job graph is cyclic.");
484:             }
485: 
486:             JobVertex current = sorted.get(startNodePos++);
487:             addNodesThatHaveNoNewPredecessors(current, sorted, remaining);
488:         }
489: 
490:         return sorted;
491:     }
492: 
493:     private void addNodesThatHaveNoNewPredecessors(
494:             JobVertex start, List<JobVertex> target, Set<JobVertex> remaining) {
495: 
496:         // forward traverse over all produced data sets and all their consumers
497:         for (IntermediateDataSet dataSet : start.getProducedDataSets()) {
498:             for (JobEdge edge : dataSet.getConsumers()) {
499: 
500:                 // a vertex can be added, if it has no predecessors that are still in the
501:                 // 'remaining' set
502:                 JobVertex v = edge.getTarget();
503:                 if (!remaining.contains(v)) {
504:                     continue;
505:                 }
506: 
507:                 boolean hasNewPredecessors = false;
508: 
509:                 for (JobEdge e : v.getInputs()) {
510:                     // skip the edge through which we came
511:                     if (e == edge) {
512:                         continue;
513:                     }
514: 
515:                     IntermediateDataSet source = e.getSource();
516:                     if (remaining.contains(source.getProducer())) {
517:                         hasNewPredecessors = true;
518:                         break;
519:                     }
520:                 }
521: 
522:                 if (!hasNewPredecessors) {
523:                     target.add(v);
524:                     remaining.remove(v);
525:                     addNodesThatHaveNoNewPredecessors(v, target, remaining);
526:                 }
527:             }
528:         }
529:     }
