338:     /** A {@link Comparator} to compare {@link StreamRecord} while sorting them. */
339:     private class StreamRecordComparator implements Comparator<Object> {
340:         @Override
341:         public int compare(Object o1, Object o2) {
342:             if (o1 instanceof Watermark || o2 instanceof Watermark) {
343:                 return 0;
344:             } else {
345:                 StreamRecord<Integer> sr0 = (StreamRecord<Integer>) o1;
346:                 StreamRecord<Integer> sr1 = (StreamRecord<Integer>) o2;
347: 
348:                 if (sr0.getTimestamp() != sr1.getTimestamp()) {
349:                     return (int) (sr0.getTimestamp() - sr1.getTimestamp());
350:                 }
351: 
352:                 int comparison = sr0.getValue().compareTo(sr1.getValue());
353:                 if (comparison != 0) {
354:                     return comparison;
355:                 } else {
356:                     return sr0.getValue() - sr1.getValue();
357:                 }
358:             }
359:         }
360:     }
