534:     private JobVertex createChainedVertex(
535:             AsyncFunction<Integer, Integer> firstFunction,
536:             AsyncFunction<Integer, Integer> secondFunction) {
537: 
538:         StreamExecutionEnvironment chainEnv = StreamExecutionEnvironment.getExecutionEnvironment();
539: 
540:         // set parallelism to 2 to avoid chaining with source in case when available processors is
541:         // 1.
542:         chainEnv.setParallelism(2);
543: 
544:         // the input is only used to construct a chained operator, and they will not be used in the
545:         // real tests.
546:         DataStream<Integer> input = chainEnv.fromData(1, 2, 3);
547: 
548:         input =
549:                 AsyncDataStream.orderedWait(
550:                         input, firstFunction, TIMEOUT, TimeUnit.MILLISECONDS, 6);
551: 
552:         // the map function is designed to chain after async function. we place an Integer object in
553:         // it and
554:         // it is initialized in the open() method.
555:         // it is used to verify that operators in the operator chain should be opened from the tail
556:         // to the head,
557:         // so the result from AsyncWaitOperator can pass down successfully and correctly.
558:         // if not, the test can not be passed.
559:         input =
560:                 input.map(
561:                         new RichMapFunction<Integer, Integer>() {
562:                             private static final long serialVersionUID = 1L;
563: 
564:                             private Integer initialValue = null;
565: 
566:                             @Override
567:                             public void open(OpenContext openContext) throws Exception {
568:                                 initialValue = 1;
569:                             }
570: 
571:                             @Override
572:                             public Integer map(Integer value) throws Exception {
573:                                 return initialValue + value;
574:                             }
575:                         });
576: 
577:         input =
578:                 AsyncDataStream.unorderedWait(
579:                         input, secondFunction, TIMEOUT, TimeUnit.MILLISECONDS, 3);
580: 
581:         input.map(
582:                         new MapFunction<Integer, Integer>() {
583:                             private static final long serialVersionUID = 5162085254238405527L;
584: 
585:                             @Override
586:                             public Integer map(Integer value) throws Exception {
587:                                 return value;
588:                             }
589:                         })
590:                 .startNewChain()
591:                 .sinkTo(new DiscardingSink<>());
592: 
593:         // be build our own OperatorChain
594:         final StreamGraph jobGraph = chainEnv.getStreamGraph().getJobGraph();
595: 
596:         assertThat(jobGraph.getVerticesSortedTopologicallyFromSources()).hasSize(3);
597: 
598:         return jobGraph.getVerticesSortedTopologicallyFromSources().get(1);
599:     }
