1044:     /**
1045:      * Tests that the AsyncWaitOperator can restart if checkpointed queue was full.
1046:      *
1047:      * <p>See FLINK-7949
1048:      */
1049:     @Test
1050:     @Timeout(value = 10000, unit = TimeUnit.MILLISECONDS)
1051:     void testRestartWithFullQueue() throws Exception {
1052:         final int capacity = 10;
1053: 
1054:         // 1. create the snapshot which contains capacity + 1 elements
1055:         final CompletableFuture<Void> trigger = new CompletableFuture<>();
1056: 
1057:         final OneInputStreamOperatorTestHarness<Integer, Integer> snapshotHarness =
1058:                 createTestHarness(
1059:                         new ControllableAsyncFunction<>(
1060:                                 trigger), // the NoOpAsyncFunction is like a blocking function
1061:                         1000L,
1062:                         capacity,
1063:                         AsyncDataStream.OutputMode.ORDERED);
1064: 
1065:         snapshotHarness.open();
1066: 
1067:         final OperatorSubtaskState snapshot;
1068: 
1069:         final ArrayList<Integer> expectedOutput = new ArrayList<>(capacity);
1070: 
1071:         try {
1072:             synchronized (snapshotHarness.getCheckpointLock()) {
1073:                 for (int i = 0; i < capacity; i++) {
1074:                     snapshotHarness.processElement(i, 0L);
1075:                     expectedOutput.add(i);
1076:                 }
1077:             }
1078: 
1079:             synchronized (snapshotHarness.getCheckpointLock()) {
1080:                 // execute the snapshot within the checkpoint lock, because then it is guaranteed
1081:                 // that the lastElementWriter has written the exceeding element
1082:                 snapshot = snapshotHarness.snapshot(0L, 0L);
1083:             }
1084: 
1085:             // trigger the computation to make the close call finish
1086:             trigger.complete(null);
1087:         } finally {
1088:             synchronized (snapshotHarness.getCheckpointLock()) {
1089:                 snapshotHarness.close();
1090:             }
1091:         }
1092: 
1093:         // 2. restore the snapshot and check that we complete
1094:         final OneInputStreamOperatorTestHarness<Integer, Integer> recoverHarness =
1095:                 createTestHarness(
1096:                         new ControllableAsyncFunction<>(CompletableFuture.completedFuture(null)),
1097:                         1000L,
1098:                         capacity,
1099:                         AsyncDataStream.OutputMode.ORDERED);
1100: 
1101:         recoverHarness.initializeState(snapshot);
1102: 
1103:         synchronized (recoverHarness.getCheckpointLock()) {
1104:             recoverHarness.open();
1105:         }
1106: 
1107:         synchronized (recoverHarness.getCheckpointLock()) {
1108:             recoverHarness.endInput();
1109:             recoverHarness.close();
1110:         }
1111: 
1112:         final ConcurrentLinkedQueue<Object> output = recoverHarness.getOutput();
1113: 
1114:         final List<Integer> outputElements =
1115:                 output.stream()
1116:                         .map(r -> ((StreamRecord<Integer>) r).getValue())
1117:                         .collect(Collectors.toList());
1118: 
1119:         assertThat(outputElements).isEqualTo(expectedOutput);
1120:     }
