214:     public static class Sender extends AbstractInvokable {
215: 
216:         public Sender(Environment environment) {
217:             super(environment);
218:         }
219: 
220:         @Override
221:         public void invoke() throws Exception {
222:             int index = getIndexInSubtaskGroup();
223:             final RecordWriter<IntValue> writer =
224:                     new RecordWriterBuilder<IntValue>().build(getEnvironment().getWriter(0));
225: 
226:             try {
227:                 for (int i = index; i < index + 100; ++i) {
228:                     writer.emit(new IntValue(i));
229:                     LOG.debug("Sender({}) emit {}", index, i);
230:                 }
231:                 writer.flushAll();
232:             } finally {
233:                 writer.close();
234:             }
235:         }
236:     }
