250:             int index = getIndexInSubtaskGroup();
251:             final RecordReader<IntValue> reader =
252:                     new RecordReader<>(
253:                             getEnvironment().getInputGate(0),
254:                             IntValue.class,
255:                             getEnvironment().getTaskManagerInfo().getTmpDirectories());
256:             for (int i = index; i < index + 100; ++i) {
257:                 final int value = reader.next().getValue();
258:                 LOG.debug("Receiver({}) received {}", index, value);
259:                 Assertions.assertThat(value).isEqualTo(i);
260:             }
261: 
262:             Assertions.assertThat(reader.next()).isNull();
263:         }
264:     }
