48: /** A test base that includes utilities for taking a savepoint. */
49: public abstract class SavepointTestBase extends AbstractTestBaseJUnit4 {
50: 
51:     public String takeSavepoint(StreamExecutionEnvironment executionEnvironment) {
52:         StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
53:         env.getConfig().disableClosureCleaner();
54: 
55:         StreamGraph jobGraph = executionEnvironment.getStreamGraph().getJobGraph();
56: 
57:         JobID jobId = jobGraph.getJobID();
58: 
59:         ClusterClient<?> client = MINI_CLUSTER_RESOURCE.getClusterClient();
60: 
61:         try {
62:             JobID jobID = client.submitJob(jobGraph).get();
63: 
64:             waitForAllRunningOrSomeTerminal(jobID, MINI_CLUSTER_RESOURCE);
65: 
66:             return triggerSavepoint(client, jobID).get(5, TimeUnit.MINUTES);
67:         } catch (Exception e) {
68:             throw new RuntimeException("Failed to take savepoint", e);
69:         } finally {
70:             client.cancel(jobId);
71:         }
72:     }
73: 
74:     public static void waitForAllRunningOrSomeTerminal(
75:             JobID jobID, MiniClusterWithClientResource miniClusterResource) throws Exception {
76:         while (true) {
77:             JobDetailsInfo jobInfo =
78:                     miniClusterResource.getRestClusterClient().getJobDetails(jobID).get();
79:             Set<ExecutionState> vertexStates =
80:                     jobInfo.getJobVertexInfos().stream()
81:                             .map(JobDetailsInfo.JobVertexDetailsInfo::getExecutionState)
82:                             .collect(Collectors.toSet());
83:             if (vertexStates.equals(EnumSet.of(RUNNING))
84:                     || vertexStates.stream().anyMatch(ExecutionState::isTerminal)) {
85:                 return;
86:             } else {
87:                 Thread.sleep(500);
88:             }
89:         }
90:     }
