96:     public <T> SourceFunction<T> createSource(Collection<T> data) {
97:         T first = data.iterator().next();
98:         if (first == null) {
99:             throw new IllegalArgumentException("Collection must not contain null elements");
100:         }
101: 
102:         TypeInformation<T> typeInfo = TypeExtractor.getForObject(first);
103:         try {
104:             SourceFunction<T> inner =
105:                     new FromElementsFunction<>(
106:                             typeInfo.createSerializer(new SerializerConfigImpl()), data);
107:             return new WaitingSource<>(inner, typeInfo);
108:         } catch (IOException e) {
109:             throw new RuntimeException(e);
110:         }
111:     }
