38: /** Common utils for computing forward groups. */
39: public class ForwardGroupComputeUtil {
40: 
41:     public static Map<JobVertexID, ForwardGroup> computeForwardGroupsAndCheckParallelism(
42:             final Iterable<JobVertex> topologicallySortedVertices) {
43:         final Map<JobVertexID, ForwardGroup> forwardGroupsByJobVertexId =
44:                 computeForwardGroups(
45:                         topologicallySortedVertices, ForwardGroupComputeUtil::getForwardProducers);
46:         // the vertex's parallelism in parallelism-decided forward group should have been set at
47:         // compilation phase
48:         topologicallySortedVertices.forEach(
49:                 jobVertex -> {
50:                     ForwardGroup forwardGroup = forwardGroupsByJobVertexId.get(jobVertex.getID());
51:                     if (forwardGroup != null && forwardGroup.isParallelismDecided()) {
52:                         checkState(jobVertex.getParallelism() == forwardGroup.getParallelism());
53:                     }
54:                 });
55:         return forwardGroupsByJobVertexId;
56:     }
57: 
58:     public static Map<JobVertexID, ForwardGroup> computeForwardGroups(
59:             final Iterable<JobVertex> topologicallySortedVertices,
60:             final Function<JobVertex, Set<JobVertex>> forwardProducersRetriever) {
61: 
62:         final Map<JobVertex, Set<JobVertex>> vertexToGroup = new IdentityHashMap<>();
63: 
64:         // iterate all the vertices which are topologically sorted
65:         for (JobVertex vertex : topologicallySortedVertices) {
66:             Set<JobVertex> currentGroup = new HashSet<>();
67:             currentGroup.add(vertex);
68:             vertexToGroup.put(vertex, currentGroup);
69: 
70:             for (JobVertex producerVertex : forwardProducersRetriever.apply(vertex)) {
71:                 final Set<JobVertex> producerGroup = vertexToGroup.get(producerVertex);
72: 
73:                 if (producerGroup == null) {
74:                     throw new IllegalStateException(
75:                             "Producer task "
76:                                     + producerVertex.getID()
77:                                     + " forward group is null"
78:                                     + " while calculating forward group for the consumer task "
79:                                     + vertex.getID()
80:                                     + ". This should be a forward group building bug.");
81:                 }
82: 
83:                 if (currentGroup != producerGroup) {
84:                     currentGroup =
85:                             VertexGroupComputeUtil.mergeVertexGroups(
86:                                     currentGroup, producerGroup, vertexToGroup);
87:                 }
88:             }
89:         }
90: 
91:         final Map<JobVertexID, ForwardGroup> ret = new HashMap<>();
92:         for (Set<JobVertex> vertexGroup :
93:                 VertexGroupComputeUtil.uniqueVertexGroups(vertexToGroup)) {
94:             if (vertexGroup.size() > 1) {
95:                 ForwardGroup forwardGroup = new ForwardGroup(vertexGroup);
96:                 for (JobVertexID jobVertexId : forwardGroup.getJobVertexIds()) {
97:                     ret.put(jobVertexId, forwardGroup);
98:                 }
99:             }
100:         }
101:         return ret;
102:     }
103: 
104:     static Set<JobVertex> getForwardProducers(final JobVertex jobVertex) {
105:         return jobVertex.getInputs().stream()
106:                 .filter(JobEdge::isForward)
107:                 .map(JobEdge::getSource)
108:                 .map(IntermediateDataSet::getProducer)
109:                 .collect(Collectors.toSet());
110:     }
111: }
