216:     //  finished, and their produced partitions should also be restored. And middle vertex is
217:     // redeployed.
218:     @TestTemplate
219:     void testRecoverFromJMFailover() throws Exception {
220:         AdaptiveBatchScheduler scheduler = createScheduler(deserializeJobGraph(serializedJobGraph));
221: 
222:         runInMainThread(scheduler::startScheduling);
223: 
224:         runInMainThread(
225:                 () -> {
226:                     // transition all sources to finished.
227:                     transitionExecutionsState(scheduler, ExecutionState.FINISHED, SOURCE_ID);
228:                 });
229:         runInMainThread(
230:                 () -> {
231:                     // transition all middle tasks to RUNNING state
232:                     transitionExecutionsState(scheduler, ExecutionState.INITIALIZING, MIDDLE_ID);
233:                     transitionExecutionsState(scheduler, ExecutionState.RUNNING, MIDDLE_ID);
234:                 });
235:         List<ExecutionAttemptID> sourceExecutions =
236:                 getCurrentAttemptIds(scheduler.getExecutionJobVertex(SOURCE_ID));
237:         List<ExecutionAttemptID> middleExecutions =
238:                 getCurrentAttemptIds(scheduler.getExecutionJobVertex(MIDDLE_ID));
239: 
240:         Map<IntermediateResultPartitionID, Integer> subpartitionNums = new HashMap<>();
241:         for (ExecutionVertex vertex :
242:                 getExecutionVertices(SOURCE_ID, scheduler.getExecutionGraph())) {
243: 
244:             IntermediateResultPartition partition =
245:                     vertex.getProducedPartitions().values().iterator().next();
246:             subpartitionNums.put(partition.getPartitionId(), partition.getNumberOfSubpartitions());
247:         }
248: 
249:         waitUntilWriteExecutionVertexFinishedEventPersisted(5);
250:         runInMainThread(() -> jobEventStore.stop(false));
251: 
252:         // register all produced partitions
253:         registerPartitions(scheduler);
254: 
255:         // start a new scheduler and try to recover.
256:         AdaptiveBatchScheduler newScheduler =
257:                 createScheduler(deserializeJobGraph(serializedJobGraph));
258:         startSchedulingAndWaitRecoverFinish(newScheduler);
259: 
260:         // check source vertices state were recovered.
261:         for (ExecutionVertex vertex :
262:                 getExecutionVertices(SOURCE_ID, newScheduler.getExecutionGraph())) {
263:             // check state.
264:             assertThat(sourceExecutions)
265:                     .contains(vertex.getCurrentExecutionAttempt().getAttemptId());
266:             assertThat(vertex.getExecutionState()).isEqualTo(ExecutionState.FINISHED);
267: 
268:             // check partition tracker was rebuild.
269:             JobMasterPartitionTracker partitionTracker =
270:                     ((InternalExecutionGraphAccessor) newScheduler.getExecutionGraph())
271:                             .getPartitionTracker();
272:             List<ResultPartitionID> resultPartitionIds =
273:                     vertex.getProducedPartitions().keySet().stream()
274:                             .map(
275:                                     ((DefaultExecutionGraph) newScheduler.getExecutionGraph())
276:                                             ::createResultPartitionId)
277:                             .collect(Collectors.toList());
278:             for (ResultPartitionID partitionID : resultPartitionIds) {
279:                 assertThat(partitionTracker.isPartitionTracked(partitionID)).isTrue();
280:             }
281: 
282:             // check partitions are recovered
283:             IntermediateResultPartition partition =
284:                     vertex.getProducedPartitions().values().iterator().next();
285:             assertThat(partition.getNumberOfSubpartitions())
286:                     .isEqualTo(subpartitionNums.get(partition.getPartitionId()));
287:         }
288: 
289:         // check middle vertices state were not recovered.
290:         for (ExecutionVertex vertex :
291:                 getExecutionVertices(MIDDLE_ID, newScheduler.getExecutionGraph())) {
292:             assertThat(middleExecutions)
293:                     .doesNotContain(vertex.getCurrentExecutionAttempt().getAttemptId());
294:             waitUntilExecutionVertexState(vertex, ExecutionState.DEPLOYING, 15000L);
295:         }
296:     }
