972:     private StreamGraph createDefaultJobGraph() throws IOException {
973:         List<JobVertex> jobVertices = new ArrayList<>();
974: 
975:         final JobVertex source = new JobVertex("source", SOURCE_ID);
976:         source.setInvokableClass(NoOpInvokable.class);
977:         source.addOperatorCoordinator(new SerializedValue<>(provider));
978:         source.setParallelism(SOURCE_PARALLELISM);
979:         jobVertices.add(source);
980: 
981:         final JobVertex middle = new JobVertex("middle", MIDDLE_ID);
982:         middle.setInvokableClass(NoOpInvokable.class);
983:         middle.setParallelism(MIDDLE_PARALLELISM);
984:         jobVertices.add(middle);
985: 
986:         final JobVertex sink = new JobVertex("sink", SINK_ID);
987:         sink.setInvokableClass(NoOpInvokable.class);
988:         jobVertices.add(sink);
989: 
990:         middle.connectNewDataSetAsInput(
991:                 source, DistributionPattern.POINTWISE, ResultPartitionType.BLOCKING);
992:         sink.connectNewDataSetAsInput(
993:                 middle, DistributionPattern.ALL_TO_ALL, ResultPartitionType.BLOCKING);
994: 
995:         return new StreamGraph(JOB_ID, "TestJob", jobVertices.toArray(new JobVertex[0]));
996:     }
