406:         @Override
407:         public void handleOperatorEvent(OperatorEvent evt) {
408:             if (evt instanceof IntegerEvent) {
409:                 accumulator.add(((IntegerEvent) evt).value);
410:             } else if (evt instanceof EndEvent) {
411:                 try {
412:                     state.update(accumulator.getLocalValue());
413:                 } catch (Exception e) {
414:                     throw new RuntimeException(e);
415:                 }
416:                 ManuallyClosedSourceFunction.shouldCloseSource = true;
