209:     /**
210:      * Tests that a job with purely keyed state can be restarted from a checkpoint with a different
211:      * parallelism.
212:      */
213:     public void testCheckpointRescalingKeyedState(boolean scaleOut) throws Exception {
214:         final int numberKeys = 42;
215:         final int numberElements = 1000;
216:         final int parallelism = scaleOut ? totalSlots / 2 : totalSlots;
217:         final int parallelism2 = scaleOut ? totalSlots : totalSlots / 2;
218:         final int maxParallelism = 13;
219: 
220:         Duration timeout = Duration.ofMinutes(3);
221:         Deadline deadline = Deadline.now().plus(timeout);
222: 
223:         ClusterClient<?> client = cluster.getClusterClient();
224: 
225:         try {
226: 
227:             StreamGraph jobGraph =
228:                     createJobGraphWithKeyedState(
229:                             cluster.getMiniCluster().getConfiguration().clone(),
230:                             parallelism,
231:                             maxParallelism,
232:                             numberKeys,
233:                             numberElements);
234: 
235:             final JobID jobID = jobGraph.getJobID();
236: 
237:             client.submitJob(jobGraph).get();
238: 
239:             SubtaskIndexSource.SOURCE_LATCH.trigger();
240: 
241:             // wait til the sources have emitted numberElements for each key and completed a
242:             // checkpoint
243:             assertTrue(
244:                     SubtaskIndexFlatMapper.workCompletedLatch.await(
245:                             deadline.timeLeft().toMillis(), TimeUnit.MILLISECONDS));
246: 
247:             // verify the current state
248: 
249:             Set<Tuple2<Integer, Integer>> actualResult = CollectionSink.getElementsSet();
250: 
251:             Set<Tuple2<Integer, Integer>> expectedResult = new HashSet<>();
252: 
253:             for (int key = 0; key < numberKeys; key++) {
254:                 int keyGroupIndex = KeyGroupRangeAssignment.assignToKeyGroup(key, maxParallelism);
255: 
256:                 expectedResult.add(
257:                         Tuple2.of(
258:                                 KeyGroupRangeAssignment.computeOperatorIndexForKeyGroup(
259:                                         maxParallelism, parallelism, keyGroupIndex),
260:                                 numberElements * key));
261:             }
262: 
263:             assertEquals(expectedResult, actualResult);
264: 
265:             // clear the CollectionSink set for the restarted job
266:             CollectionSink.clearElementsSet();
267: 
268:             waitForAllTaskRunning(cluster.getMiniCluster(), jobGraph.getJobID(), false);
269: 
270:             // We need to wait for a checkpoint to be completed that was triggered after all the
271:             // data was processed. That ensures the entire data being flushed out of the Operator's
272:             // network buffers to avoid reprocessing test data twice after the restore (see
273:             // FLINK-34200).
274:             waitForNewCheckpoint(jobID, cluster.getMiniCluster());
275: 
276:             SubtaskIndexSource.SOURCE_LATCH.reset();
277: 
278:             JobResourceRequirements.Builder builder = JobResourceRequirements.newBuilder();
279:             for (JobVertex vertex : jobGraph.getVertices()) {
280:                 builder.setParallelismForJobVertex(vertex.getID(), parallelism2, parallelism2);
281:             }
282: 
283:             restClusterClient.updateJobResourceRequirements(jobID, builder.build()).join();
284: 
285:             waitForRunningTasks(restClusterClient, jobID, 2 * parallelism2);
286:             waitForAvailableSlots(restClusterClient, totalSlots - parallelism2);
287: 
288:             SubtaskIndexSource.SOURCE_LATCH.trigger();
289: 
290:             client.requestJobResult(jobID).get();
291: 
292:             Set<Tuple2<Integer, Integer>> actualResult2 = CollectionSink.getElementsSet();
293: 
294:             Set<Tuple2<Integer, Integer>> expectedResult2 = new HashSet<>();
295: 
296:             for (int key = 0; key < numberKeys; key++) {
297:                 int keyGroupIndex = KeyGroupRangeAssignment.assignToKeyGroup(key, maxParallelism);
298:                 expectedResult2.add(
299:                         Tuple2.of(
300:                                 KeyGroupRangeAssignment.computeOperatorIndexForKeyGroup(
301:                                         maxParallelism, parallelism2, keyGroupIndex),
302:                                 key * 2 * numberElements));
303:             }
304: 
305:             assertEquals(expectedResult2, actualResult2);
306: 
307:         } finally {
308:             // clear the CollectionSink set for the restarted job
309:             CollectionSink.clearElementsSet();
310:         }
311:     }
