493:     /** Tests rescaling of partitioned operator state. */
494:     public void testCheckpointRescalingPartitionedOperatorState(
495:             boolean scaleOut, OperatorCheckpointMethod checkpointMethod) throws Exception {
496:         final int parallelism = scaleOut ? totalSlots : totalSlots / 2;
497:         final int parallelism2 = scaleOut ? totalSlots / 2 : totalSlots;
498:         final int maxParallelism = 13;
499: 
500:         ClusterClient<?> client = cluster.getClusterClient();
501: 
502:         int counterSize = Math.max(parallelism, parallelism2);
503: 
504:         if (checkpointMethod == OperatorCheckpointMethod.CHECKPOINTED_FUNCTION
505:                 || checkpointMethod == OperatorCheckpointMethod.CHECKPOINTED_FUNCTION_BROADCAST) {
506:             PartitionedStateSource.checkCorrectSnapshot = new int[counterSize];
507:             PartitionedStateSource.checkCorrectRestore = new int[counterSize];
508:             PartitionedStateSource.checkCorrectSnapshots.clear();
509:         } else {
510:             throw new UnsupportedOperationException("Unsupported method:" + checkpointMethod);
511:         }
512: 
513:         StreamGraph jobGraph =
514:                 createJobGraphWithOperatorState(parallelism, maxParallelism, checkpointMethod);
515:         // make sure the job does not finish before we take the checkpoint
516:         StateSourceBase.canFinishLatch = new CountDownLatch(1);
517: 
518:         final JobID jobID = jobGraph.getJobID();
519: 
520:         client.submitJob(jobGraph).get();
521: 
522:         // wait until the operator is started
523:         waitForAllTaskRunning(cluster.getMiniCluster(), jobGraph.getJobID(), false);
524:         // wait until the operator handles some data
525:         StateSourceBase.workStartedLatch.await();
526: 
527:         waitForNewCheckpoint(jobID, cluster.getMiniCluster());
528: 
529:         JobResourceRequirements.Builder builder = JobResourceRequirements.newBuilder();
530:         for (JobVertex vertex : jobGraph.getVertices()) {
531:             builder.setParallelismForJobVertex(vertex.getID(), parallelism2, parallelism2);
532:         }
533: 
534:         restClusterClient.updateJobResourceRequirements(jobID, builder.build()).join();
535: 
536:         waitForRunningTasks(restClusterClient, jobID, 2 * parallelism2);
537:         waitForAvailableSlots(restClusterClient, totalSlots - parallelism2);
538: 
539:         StateSourceBase.canFinishLatch.countDown();
540: 
541:         client.requestJobResult(jobID).get();
542: 
543:         int sumExp = 0;
544:         int sumAct = 0;
545: 
546:         if (checkpointMethod == OperatorCheckpointMethod.CHECKPOINTED_FUNCTION) {
547:             for (int c : PartitionedStateSource.checkCorrectSnapshot) {
548:                 sumExp += c;
549:             }
550: 
551:             for (int c : PartitionedStateSource.checkCorrectRestore) {
552:                 sumAct += c;
553:             }
554:         } else {
555:             for (int c : PartitionedStateSource.checkCorrectSnapshot) {
556:                 sumExp += c;
557:             }
558: 
559:             for (int c : PartitionedStateSource.checkCorrectRestore) {
560:                 sumAct += c;
561:             }
562: 
563:             sumExp *= parallelism2;
564:         }
565: 
566:         assertEquals(sumExp, sumAct);
567:     }
