571:     private static void configureCheckpointing(CheckpointConfig config) {
572:         config.setCheckpointInterval(100);
573:         config.setCheckpointingConsistencyMode(CheckpointingMode.EXACTLY_ONCE);
574:         config.enableUnalignedCheckpoints(true);
