577:     private static StreamGraph createJobGraphWithOperatorState(
578:             int parallelism, int maxParallelism, OperatorCheckpointMethod checkpointMethod) {
579: 
580:         StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
581:         configureCheckpointing(env.getCheckpointConfig());
582:         env.setParallelism(parallelism);
583:         env.getConfig().setMaxParallelism(maxParallelism);
584:         RestartStrategyUtils.configureNoRestartStrategy(env);
585: 
586:         StateSourceBase.workStartedLatch = new CountDownLatch(parallelism);
587: 
588:         SourceFunction<Integer> src;
589: 
590:         switch (checkpointMethod) {
591:             case CHECKPOINTED_FUNCTION:
592:                 src = new PartitionedStateSource(false);
593:                 break;
594:             case CHECKPOINTED_FUNCTION_BROADCAST:
595:                 src = new PartitionedStateSource(true);
596:                 break;
597:             case NON_PARTITIONED:
598:                 src = new NonPartitionedStateSource();
599:                 break;
600:             default:
601:                 throw new IllegalArgumentException(checkpointMethod.name());
602:         }
603: 
604:         DataStream<Integer> input = env.addSource(src);
605: 
606:         input.sinkTo(new DiscardingSink<>());
607: 
608:         return env.getStreamGraph().getJobGraph();
609:     }
