611:     public static StreamGraph createJobGraphWithKeyedState(
612:             Configuration configuration,
613:             int parallelism,
614:             int maxParallelism,
615:             int numberKeys,
616:             int numberElements) {
617:         StreamExecutionEnvironment env =
618:                 StreamExecutionEnvironment.getExecutionEnvironment(configuration);
619:         env.setParallelism(parallelism);
620:         if (0 < maxParallelism) {
621:             env.getConfig().setMaxParallelism(maxParallelism);
622:         }
623: 
624:         configureCheckpointing(env.getCheckpointConfig());
625:         RestartStrategyUtils.configureNoRestartStrategy(env);
626:         env.getConfig().setUseSnapshotCompression(true);
627: 
628:         DataStream<Integer> input =
629:                 env.addSource(new SubtaskIndexSource(numberKeys, numberElements, parallelism))
630:                         .keyBy(
631:                                 new KeySelector<Integer, Integer>() {
632:                                     private static final long serialVersionUID =
633:                                             -7952298871120320940L;
634: 
635:                                     @Override
636:                                     public Integer getKey(Integer value) {
637:                                         return value;
638:                                     }
639:                                 });
640: 
641:         SubtaskIndexFlatMapper.workCompletedLatch = new CountDownLatch(numberKeys);
642: 
643:         DataStream<Tuple2<Integer, Integer>> result =
644:                 input.flatMap(new SubtaskIndexFlatMapper(numberElements));
645: 
646:         result.addSink(new CollectionSink<>());
647: 
648:         return env.getStreamGraph().getJobGraph();
649:     }
