652:             int parallelism,
653:             int maxParallelism,
654:             int fixedParallelism,
655:             int numberKeys,
656:             int numberElements,
657:             int numberElementsAfterRestart) {
658: 
659:         StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
660:         env.setParallelism(parallelism);
