669:                                         numberElements,
670:                                         numberElementsAfterRestart,
671:                                         parallelism))
672:                         .setParallelism(fixedParallelism)
673:                         .setMaxParallelism(fixedParallelism)
674:                         .keyBy(
675:                                 new KeySelector<Integer, Integer>() {
676:                                     private static final long serialVersionUID =
677:                                             -7952298871120320940L;
678: 
679:                                     @Override
680:                                     public Integer getKey(Integer value) {
