695:     private static class SubtaskIndexSource extends RichParallelSourceFunction<Integer> {
696: 
697:         private static final long serialVersionUID = -400066323594122516L;
698: 
699:         private final int numberKeys;
700: 
701:         private final int originalParallelism;
702:         protected int numberElements;
703: 
704:         protected int counter = 0;
705: 
706:         private boolean running = true;
707: 
708:         private static final OneShotLatch SOURCE_LATCH = new OneShotLatch();
709: 
710:         SubtaskIndexSource(int numberKeys, int numberElements, int originalParallelism) {
711:             this.numberKeys = numberKeys;
712:             this.numberElements = numberElements;
713:             this.originalParallelism = originalParallelism;
714:         }
715: 
716:         @Override
717:         public void run(SourceContext<Integer> ctx) throws Exception {
718:             RuntimeContext runtimeContext = getRuntimeContext();
719:             final int subtaskIndex = runtimeContext.getTaskInfo().getIndexOfThisSubtask();
720: 
721:             boolean isRestartedOrRescaled =
722:                     runtimeContext.getTaskInfo().getNumberOfParallelSubtasks()
723:                                     != originalParallelism
724:                             || runtimeContext.getTaskInfo().getAttemptNumber() > 0;
725:             while (running) {
726:                 SOURCE_LATCH.await();
727:                 if (counter < numberElements) {
728:                     synchronized (ctx.getCheckpointLock()) {
729:                         for (int value = subtaskIndex;
730:                                 value < numberKeys;
731:                                 value +=
732:                                         runtimeContext
733:                                                 .getTaskInfo()
734:                                                 .getNumberOfParallelSubtasks()) {
735:                             ctx.collect(value);
736:                         }
737: 
738:                         counter++;
739:                     }
740:                 } else {
741:                     if (isRestartedOrRescaled) {
742:                         running = false;
743:                     } else {
744:                         Thread.sleep(100);
745:                     }
746:                 }
747:             }
748:         }
749: 
750:         @Override
751:         public void cancel() {
752:             running = false;
753:         }
754:     }
755: 
756:     private static class SubtaskIndexNonPartitionedStateSource extends SubtaskIndexSource
757:             implements ListCheckpointed<Integer> {
758: 
759:         private static final long serialVersionUID = 8388073059042040203L;
760:         private final int numElementsAfterRestart;
761: 
762:         SubtaskIndexNonPartitionedStateSource(
763:                 int numberKeys,
