913:     private static class PartitionedStateSource extends StateSourceBase
914:             implements CheckpointedFunction {
915: 
916:         private static final long serialVersionUID = -359715965103593462L;
917:         private static final int NUM_PARTITIONS = 7;
918: 
919:         private transient ListState<Integer> counterPartitions;
920:         private final boolean broadcast;
921: 
922:         private static final ConcurrentHashMap<Long, int[]> checkCorrectSnapshots =
923:                 new ConcurrentHashMap<>();
924:         private static int[] checkCorrectSnapshot;
925:         private static int[] checkCorrectRestore;
926: 
927:         public PartitionedStateSource(boolean broadcast) {
928:             this.broadcast = broadcast;
929:         }
930: 
931:         @Override
932:         public void snapshotState(FunctionSnapshotContext context) throws Exception {
933: 
934:             if (getRuntimeContext().getTaskInfo().getAttemptNumber() == 0) {
935:                 int[] snapshot =
936:                         checkCorrectSnapshots.computeIfAbsent(
937:                                 context.getCheckpointId(),
938:                                 (x) -> new int[checkCorrectRestore.length]);
939:                 snapshot[getRuntimeContext().getTaskInfo().getIndexOfThisSubtask()] = counter;
940:             }
941: 
942:             counterPartitions.clear();
943: 
944:             int div = counter / NUM_PARTITIONS;
945:             int mod = counter % NUM_PARTITIONS;
946: 
947:             for (int i = 0; i < NUM_PARTITIONS; ++i) {
948:                 int partitionValue = div;
949:                 if (mod > 0) {
950:                     --mod;
951:                     ++partitionValue;
952:                 }
953:                 counterPartitions.add(partitionValue);
954:             }
955:         }
956: 
957:         @Override
958:         public void initializeState(FunctionInitializationContext context) throws Exception {
959:             if (broadcast) {
960:                 this.counterPartitions =
961:                         context.getOperatorStateStore()
962:                                 .getUnionListState(
963:                                         new ListStateDescriptor<>(
964:                                                 "counter_partitions", IntSerializer.INSTANCE));
965:             } else {
966:                 this.counterPartitions =
967:                         context.getOperatorStateStore()
968:                                 .getListState(
969:                                         new ListStateDescriptor<>(
970:                                                 "counter_partitions", IntSerializer.INSTANCE));
971:             }
972: 
973:             if (context.isRestored()) {
974:                 for (int v : counterPartitions.get()) {
975:                     counter += v;
976:                 }
977:                 checkCorrectRestore[getRuntimeContext().getTaskInfo().getIndexOfThisSubtask()] =
978:                         counter;
979:                 context.getRestoredCheckpointId()
980:                         .ifPresent((id) -> checkCorrectSnapshot = checkCorrectSnapshots.get(id));
981:             }
982:         }
983:     }
