23: import org.apache.flink.runtime.scheduler.adaptive.allocator.VertexParallelism;
24: 
25: import java.util.Collection;
26: import java.util.Collections;
27: 
28: /**
29:  * A plan that describes how to execute {@link StreamGraph JobGraph}.
30:  *
31:  * <ol>
32:  *   <li>{@link #vertexParallelism} is necessary to create {@link
33:  *       org.apache.flink.runtime.executiongraph.ExecutionGraph ExecutionGraph}
34:  *   <li>{@link #slotAssignments} are used to schedule it onto the cluster
35:  * </ol>
36:  *
37:  * {@link AdaptiveScheduler} passes this structure from {@link WaitingForResources} to {@link
38:  * CreatingExecutionGraph} stages.
39:  */
40: @Internal
41: public class JobSchedulingPlan {
42:     private final VertexParallelism vertexParallelism;
43:     private final Collection<SlotAssignment> slotAssignments;
44: 
45:     public JobSchedulingPlan(
46:             VertexParallelism vertexParallelism, Collection<SlotAssignment> slotAssignments) {
47:         this.vertexParallelism = vertexParallelism;
48:         this.slotAssignments = slotAssignments;
49:     }
50: 
51:     public VertexParallelism getVertexParallelism() {
52:         return vertexParallelism;
53:     }
54: 
55:     public Collection<SlotAssignment> getSlotAssignments() {
56:         return slotAssignments;
57:     }
58: 
59:     /**
60:      * Create an empty {@link JobSchedulingPlan} with no information about vertices or allocations.
61:      */
62:     public static JobSchedulingPlan empty() {
63:         return new JobSchedulingPlan(VertexParallelism.empty(), Collections.emptyList());
64:     }
65: 
66:     /** Assignment of a slot to some target (e.g. a slot sharing group). */
67:     public static class SlotAssignment {
68:         private final SlotInfo slotInfo;
69:         /**
70:          * Interpreted by {@link
71:          * org.apache.flink.runtime.scheduler.adaptive.allocator.SlotAllocator#tryReserveResources(JobSchedulingPlan)}.
72:          * This can be a slot sharing group, a task, or something else.
73:          */
74:         private final Object target;
75: 
76:         public SlotAssignment(SlotInfo slotInfo, Object target) {
77:             this.slotInfo = slotInfo;
78:             this.target = target;
79:         }
80: 
81:         public SlotInfo getSlotInfo() {
82:             return slotInfo;
83:         }
84: 
85:         public Object getTarget() {
86:             return target;
87:         }
88: 
89:         public <T> T getTargetAs(Class<T> clazz) {
90:             return (T) getTarget();
91:         }
92: 
93:         @Override
94:         public String toString() {
95:             return String.format(
96:                     "SlotAssignment: %s, target: %s", slotInfo.getAllocationId(), target);
97:         }
98:     }
99: 
100:     @Override
101:     public String toString() {
102:         return String.format(
103:                 "JobSchedulingPlan: parallelism: %s, assignments: %s",
104:                 vertexParallelism, slotAssignments);
105:     }
106: }
