286:         validateNoInteractions(gateway);
287: 
288:         scheduler.cancel();
289:         assertThat(eg.getState()).isEqualTo(JobStatus.SUSPENDED);
290:         validateNoInteractions(gateway);
291: 
292:         scheduler.closeAsync();
293:         assertThat(eg.getState()).isEqualTo(JobStatus.SUSPENDED);
294:         validateNoInteractions(gateway);
295: 
296:         for (ExecutionVertex ev : eg.getAllExecutionVertices()) {
297:             assertThat(ev.getCurrentExecutionAttempt().getAttemptNumber()).isZero();
