26: /**
27:  * Partitioner that distributes the data equally by cycling through the output channels. This
28:  * distributes only to a subset of downstream nodes because {@link
29:  * org.apache.flink.streaming.api.graph.StreamingJobGraphGenerator} instantiates a {@link
30:  * DistributionPattern#POINTWISE} distribution pattern when encountering {@code RescalePartitioner}.
31:  *
32:  * <p>The subset of downstream operations to which the upstream operation sends elements depends on
33:  * the degree of parallelism of both the upstream and downstream operation. For example, if the
34:  * upstream operation has parallelism 2 and the downstream operation has parallelism 4, then one
35:  * upstream operation would distribute elements to two downstream operations while the other
36:  * upstream operation would distribute to the other two downstream operations. If, on the other
37:  * hand, the downstream operation has parallelism 2 while the upstream operation has parallelism 4
38:  * then two upstream operations will distribute to one downstream operation while the other two
39:  * upstream operations will distribute to the other downstream operations.
40:  *
41:  * <p>In cases where the different parallelisms are not multiples of each other one or several
42:  * downstream operations will have a differing number of inputs from upstream operations.
43:  *
44:  * @param <T> Type of the elements in the Stream being rescaled
45:  */
46: @Internal
47: public class RescalePartitioner<T> extends StreamPartitioner<T> {
48:     private static final long serialVersionUID = 1L;
49: 
50:     private int nextChannelToSendTo = -1;
51: 
52:     @Override
53:     public int selectChannel(SerializationDelegate<StreamRecord<T>> record) {
54:         if (++nextChannelToSendTo >= numberOfChannels) {
55:             nextChannelToSendTo = 0;
56:         }
57:         return nextChannelToSendTo;
58:     }
59: 
60:     @Override
61:     public SubtaskStateMapper getDownstreamSubtaskStateMapper() {
62:         return SubtaskStateMapper.UNSUPPORTED;
63:     }
64: 
