116:     private static class BatchExecutionOnceFailingMap extends RichMapFunction<Integer, Integer> {
117: 
118:         private final int maxNumber;
119: 
120:         private final boolean triggerFailover;
121: 
122:         public BatchExecutionOnceFailingMap(int maxNumber, boolean triggerFailover) {
123:             this.maxNumber = maxNumber;
124:             this.triggerFailover = triggerFailover;
125:         }
126: 
127:         @Override
128:         public Integer map(Integer value) {
129:             if (triggerFailover
130:                     && getRuntimeContext().getTaskInfo().getIndexOfThisSubtask() == 0
131:                     && getRuntimeContext().getTaskInfo().getAttemptNumber() == 0
132:                     && value >= FAILOVER_RATIO * maxNumber) {
133:                 throw new RuntimeException("Designated Failure");
134:             }
135: 
136:             return value;
137:         }
138:     }
