175:             this.failExecution = failExecution;
176:             this.deletePartitionFile = deletePartitionFile;
177:             this.isWatermarkReceived = false;
178:         }
179: 
180:         @Override
181:         public void open(OpenContext openContext) throws Exception {
182:             NUM_RECEIVED_RECORDS[getRuntimeContext().getTaskInfo().getIndexOfThisSubtask()] = 0;
183:             if (getRuntimeContext().getTaskInfo().getAttemptNumber() > 0
184:                     || getRuntimeContext().getTaskInfo().getIndexOfThisSubtask() != 0) {
185:                 return;
186:             }
187: 
188:             if (deletePartitionFile) {
189:                 synchronized (BatchShuffleITCaseBase.class) {
190:                     deleteFiles(tmpDir.toFile());
191:                 }
192:             }
193: 
194:             if (failExecution) {
