89:                         .collect(Collectors.toMap(File::getName, Path::fromLocalFile));
90: 
91:         if (uploadedFiles.size() != nameToFile.size()) {
92:             throw new RestHandlerException(
93:                     String.format(
94:                             "The number of uploaded files was %s than the expected count. Expected: %s Actual %s",
95:                             uploadedFiles.size() < nameToFile.size() ? "lower" : "higher",
96:                             nameToFile.size(),
