100: 
101:         final JobSubmitRequestBody requestBody = request.getRequestBody();
102: 
103:         if (requestBody.executionPlanFileName == null) {
104:             throw new RestHandlerException(
105:                     String.format(
106:                             "The %s field must not be omitted or be null.",
107:                             JobSubmitRequestBody.FIELD_NAME_JOB_GRAPH),
