70: /**
71:  * Utility class to encapsulate the logic of building an {@link DefaultExecutionGraph} from a {@link
72:  * StreamGraph}.
73:  */
74: public class DefaultExecutionGraphBuilder {
75: 
76:     public static DefaultExecutionGraph buildGraph(
77:             StreamGraph jobGraph,
78:             Configuration jobManagerConfig,
79:             ScheduledExecutorService futureExecutor,
80:             Executor ioExecutor,
81:             ClassLoader classLoader,
82:             CompletedCheckpointStore completedCheckpointStore,
83:             CheckpointsCleaner checkpointsCleaner,
84:             CheckpointIDCounter checkpointIdCounter,
85:             Duration rpcTimeout,
86:             BlobWriter blobWriter,
87:             Logger log,
88:             ShuffleMaster<?> shuffleMaster,
89:             JobMasterPartitionTracker partitionTracker,
90:             TaskDeploymentDescriptorFactory.PartitionLocationConstraint partitionLocationConstraint,
91:             ExecutionDeploymentListener executionDeploymentListener,
92:             ExecutionStateUpdateListener executionStateUpdateListener,
93:             long initializationTimestamp,
94:             VertexAttemptNumberStore vertexAttemptNumberStore,
95:             VertexParallelismStore vertexParallelismStore,
96:             CheckpointStatsTracker checkpointStatsTracker,
97:             boolean isDynamicGraph,
98:             ExecutionJobVertex.Factory executionJobVertexFactory,
99:             MarkPartitionFinishedStrategy markPartitionFinishedStrategy,
100:             boolean nonFinishedHybridPartitionShouldBeUnknown,
101:             JobManagerJobMetricGroup jobManagerJobMetricGroup)
102:             throws JobExecutionException, JobException {
103: 
104:         checkNotNull(jobGraph, "job graph cannot be null");
105: 
106:         final String jobName = jobGraph.getName();
107:         final JobID jobId = jobGraph.getJobID();
108:         final JobType jobType = jobGraph.getJobType();
109: 
110:         final JobInformation jobInformation =
111:                 new JobInformation(
112:                         jobId,
113:                         jobType,
114:                         jobName,
115:                         jobGraph.getSerializedExecutionConfig(),
116:                         jobGraph.getJobConfiguration(),
117:                         jobGraph.getUserJarBlobKeys(),
118:                         jobGraph.getClasspaths());
119: 
120:         final int executionHistorySizeLimit =
121:                 jobManagerConfig.get(JobManagerOptions.MAX_ATTEMPTS_HISTORY_SIZE);
122: 
123:         final PartitionGroupReleaseStrategy.Factory partitionGroupReleaseStrategyFactory =
124:                 PartitionGroupReleaseStrategyFactoryLoader.loadPartitionGroupReleaseStrategyFactory(
125:                         jobManagerConfig);
126: 
127:         final int offloadShuffleDescriptorsThreshold =
128:                 jobManagerConfig.get(
129:                         TaskDeploymentDescriptorFactory.OFFLOAD_SHUFFLE_DESCRIPTORS_THRESHOLD);
130: 
131:         final TaskDeploymentDescriptorFactory taskDeploymentDescriptorFactory;
132:         try {
133:             taskDeploymentDescriptorFactory =
134:                     new TaskDeploymentDescriptorFactory(
135:                             BlobWriter.serializeAndTryOffload(jobInformation, jobId, blobWriter),
136:                             jobId,
137:                             partitionLocationConstraint,
138:                             blobWriter,
139:                             nonFinishedHybridPartitionShouldBeUnknown,
140:                             offloadShuffleDescriptorsThreshold);
141:         } catch (IOException e) {
142:             throw new JobException("Could not create the TaskDeploymentDescriptorFactory.", e);
143:         }
144: 
145:         final List<JobStatusChangedListener> jobStatusChangedListeners =
146:                 JobStatusChangedListenerUtils.createJobStatusChangedListeners(
147:                         classLoader, jobManagerConfig, ioExecutor);
148: 
149:         // create a new execution graph, if none exists so far
150:         final DefaultExecutionGraph executionGraph =
151:                 new DefaultExecutionGraph(
152:                         jobGraph.getJobType(),
153:                         jobInformation,
154:                         futureExecutor,
155:                         ioExecutor,
156:                         rpcTimeout,
157:                         executionHistorySizeLimit,
158:                         classLoader,
159:                         blobWriter,
160:                         partitionGroupReleaseStrategyFactory,
161:                         shuffleMaster,
162:                         partitionTracker,
163:                         executionDeploymentListener,
164:                         executionStateUpdateListener,
165:                         initializationTimestamp,
166:                         vertexAttemptNumberStore,
167:                         vertexParallelismStore,
168:                         isDynamicGraph,
169:                         executionJobVertexFactory,
170:                         jobGraph.getJobStatusHooks(),
171:                         markPartitionFinishedStrategy,
172:                         taskDeploymentDescriptorFactory,
173:                         jobStatusChangedListeners);
174: 
175:         // set the basic properties
176: 
177:         try {
178:             executionGraph.setJsonPlan(JsonPlanGenerator.generatePlan(jobGraph));
179:         } catch (Throwable t) {
180:             log.warn("Cannot create JSON plan for job", t);
181:             // give the graph an empty plan
182:             executionGraph.setJsonPlan("{}");
183:         }
184: 
185:         // initialize the vertices that have a master initialization hook
186:         // file output formats create directories here, input formats create splits
187: 
188:         final long initMasterStart = System.nanoTime();
189:         log.info("Running initialization on master for job {} ({}).", jobName, jobId);
190: 
191:         for (JobVertex vertex : jobGraph.getVertices()) {
192:             String executableClass = vertex.getInvokableClassName();
193:             if (executableClass == null || executableClass.isEmpty()) {
194:                 throw new JobSubmissionException(
195:                         jobId,
196:                         "The vertex "
197:                                 + vertex.getID()
198:                                 + " ("
199:                                 + vertex.getName()
200:                                 + ") has no invokable class.");
201:             }
202: 
203:             try {
204:                 vertex.initializeOnMaster(
205:                         new SimpleInitializeOnMasterContext(
206:                                 classLoader,
207:                                 vertexParallelismStore
208:                                         .getParallelismInfo(vertex.getID())
209:                                         .getParallelism()));
210:             } catch (Throwable t) {
211:                 throw new JobExecutionException(
212:                         jobId,
213:                         "Cannot initialize task '" + vertex.getName() + "': " + t.getMessage(),
214:                         t);
215:             }
216:         }
217: 
218:         log.info(
219:                 "Successfully ran initialization on master in {} ms.",
220:                 (System.nanoTime() - initMasterStart) / 1_000_000);
221: 
222:         // topologically sort the job vertices and attach the graph to the existing one
223:         List<JobVertex> sortedTopology = jobGraph.getVerticesSortedTopologicallyFromSources();
224:         if (log.isDebugEnabled()) {
225:             log.debug(
226:                     "Adding {} vertices from job graph {} ({}).",
227:                     sortedTopology.size(),
228:                     jobName,
229:                     jobId);
230:         }
231:         executionGraph.attachJobGraph(sortedTopology, jobManagerJobMetricGroup);
232: 
233:         if (log.isDebugEnabled()) {
234:             log.debug(
235:                     "Successfully created execution graph from job graph {} ({}).", jobName, jobId);
236:         }
237: 
238:         // configure the state checkpointing
239:         if (isDynamicGraph) {
240:             // dynamic graph does not support checkpointing so we skip it
241:             log.warn("Skip setting up checkpointing for a job with dynamic graph.");
242:         } else if (isCheckpointingEnabled(jobGraph)) {
243:             JobCheckpointingSettings snapshotSettings = jobGraph.getCheckpointingSettings();
244: 
245:             // load the state backend from the application settings
246:             final StateBackend applicationConfiguredBackend;
247:             final SerializedValue<StateBackend> serializedAppConfigured =
248:                     snapshotSettings.getDefaultStateBackend();
249: 
250:             if (serializedAppConfigured == null) {
251:                 applicationConfiguredBackend = null;
252:             } else {
253:                 try {
254:                     applicationConfiguredBackend =
255:                             serializedAppConfigured.deserializeValue(classLoader);
256:                 } catch (IOException | ClassNotFoundException e) {
257:                     throw new JobExecutionException(
258:                             jobId, "Could not deserialize application-defined state backend.", e);
259:                 }
260:             }
261: 
262:             final StateBackend rootBackend;
263:             try {
264:                 rootBackend =
265:                         StateBackendLoader.fromApplicationOrConfigOrDefault(
266:                                 applicationConfiguredBackend,
267:                                 jobGraph.getJobConfiguration(),
268:                                 jobManagerConfig,
269:                                 classLoader,
270:                                 log);
271:             } catch (IllegalConfigurationException | IOException | DynamicCodeLoadingException e) {
272:                 throw new JobExecutionException(
273:                         jobId, "Could not instantiate configured state backend", e);
274:             }
275: 
276:             // load the checkpoint storage from the application settings
277:             final CheckpointStorage applicationConfiguredStorage;
278:             final SerializedValue<CheckpointStorage> serializedAppConfiguredStorage =
279:                     snapshotSettings.getDefaultCheckpointStorage();
280: 
281:             if (serializedAppConfiguredStorage == null) {
282:                 applicationConfiguredStorage = null;
283:             } else {
284:                 try {
285:                     applicationConfiguredStorage =
286:                             serializedAppConfiguredStorage.deserializeValue(classLoader);
287:                 } catch (IOException | ClassNotFoundException e) {
288:                     throw new JobExecutionException(
289:                             jobId,
290:                             "Could not deserialize application-defined checkpoint storage.",
291:                             e);
292:                 }
293:             }
294: 
295:             final CheckpointStorage rootStorage;
296:             try {
297:                 rootStorage =
298:                         CheckpointStorageLoader.load(
299:                                 applicationConfiguredStorage,
300:                                 rootBackend,
301:                                 jobGraph.getJobConfiguration(),
302:                                 jobManagerConfig,
303:                                 classLoader,
304:                                 log);
305:             } catch (IllegalConfigurationException | DynamicCodeLoadingException e) {
306:                 throw new JobExecutionException(
307:                         jobId, "Could not instantiate configured checkpoint storage", e);
308:             }
309: 
310:             // instantiate the user-defined checkpoint hooks
311: 
312:             final SerializedValue<MasterTriggerRestoreHook.Factory[]> serializedHooks =
313:                     snapshotSettings.getMasterHooks();
314:             final List<MasterTriggerRestoreHook<?>> hooks;
315: 
316:             if (serializedHooks == null) {
317:                 hooks = Collections.emptyList();
318:             } else {
319:                 final MasterTriggerRestoreHook.Factory[] hookFactories;
320:                 try {
321:                     hookFactories = serializedHooks.deserializeValue(classLoader);
322:                 } catch (IOException | ClassNotFoundException e) {
323:                     throw new JobExecutionException(
324:                             jobId, "Could not instantiate user-defined checkpoint hooks", e);
325:                 }
326: 
327:                 final Thread thread = Thread.currentThread();
328:                 final ClassLoader originalClassLoader = thread.getContextClassLoader();
329:                 thread.setContextClassLoader(classLoader);
330: 
331:                 try {
332:                     hooks = new ArrayList<>(hookFactories.length);
333:                     for (MasterTriggerRestoreHook.Factory factory : hookFactories) {
334:                         hooks.add(MasterHooks.wrapHook(factory.create(), classLoader));
335:                     }
336:                 } finally {
337:                     thread.setContextClassLoader(originalClassLoader);
338:                 }
339:             }
340: 
341:             final CheckpointCoordinatorConfiguration chkConfig =
342:                     snapshotSettings.getCheckpointCoordinatorConfiguration();
343: 
344:             executionGraph.enableCheckpointing(
345:                     chkConfig,
346:                     hooks,
347:                     checkpointIdCounter,
348:                     completedCheckpointStore,
349:                     rootBackend,
350:                     rootStorage,
351:                     checkpointStatsTracker,
352:                     checkpointsCleaner,
353:                     jobManagerConfig.get(STATE_CHANGE_LOG_STORAGE));
354:         }
355: 
356:         return executionGraph;
357:     }
358: 
359:     public static boolean isCheckpointingEnabled(StreamGraph jobGraph) {
360:         return jobGraph.getCheckpointingSettings() != null;
361:     }
362: 
363:     // ------------------------------------------------------------------------
364: 
365:     /** This class is not supposed to be instantiated. */
366:     private DefaultExecutionGraphBuilder() {}
367: }
