463:         final StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
464:         StateBackendUtils.configureRocksDBStateBackend(env, true);
465:         env.getCheckpointConfig()
466:                 .setExternalizedCheckpointRetention(
467:                         ExternalizedCheckpointRetention.RETAIN_ON_CANCELLATION);
468:         CheckpointStorageUtils.configureFileSystemCheckpointStorage(
469:                 env, folder.newFolder().toURI());
470:         env.setParallelism(parallelism);
471: 
472:         final SharedReference<CountDownLatch> counter =
473:                 sharedObjects.add(new CountDownLatch(10_000));
474:         env.fromSequence(1, Long.MAX_VALUE)
475:                 .keyBy(i -> i % parallelism)
476:                 .process(
477:                         new KeyedProcessFunction<Long, Long, Long>() {
478:                             private ListState<Long> last;
479: 
480:                             @Override
481:                             public void open(OpenContext openContext) {
482:                                 // we use list state here to create sst files of a significant size
483:                                 // if sst files do not reach certain thresholds they are not stored
484:                                 // in files, but as a byte stream in checkpoints metadata
485:                                 last =
486:                                         getRuntimeContext()
487:                                                 .getListState(
488:                                                         new ListStateDescriptor<>(
489:                                                                 "last",
490:                                                                 BasicTypeInfo.LONG_TYPE_INFO));
491:                             }
492: 
493:                             @Override
494:                             public void processElement(
495:                                     Long value,
496:                                     KeyedProcessFunction<Long, Long, Long>.Context ctx,
497:                                     Collector<Long> out)
498:                                     throws Exception {
499:                                 last.add(value);
500:                                 out.collect(value);
501:                             }
502:                         })
503:                 .addSink(
504:                         new SinkFunction<Long>() {
505:                             @Override
506:                             public void invoke(Long value) {
507:                                 counter.consumeSync(CountDownLatch::countDown);
508:                             }
509:                         })
510:                 .setParallelism(1);
511: 
512:         final StreamGraph jobGraph = env.getStreamGraph().getJobGraph();
513: 
514:         MiniClusterWithClientResource cluster =
515:                 new MiniClusterWithClientResource(
516:                         new MiniClusterResourceConfiguration.Builder()
517:                                 .setNumberTaskManagers(numTaskManagers)
518:                                 .setNumberSlotsPerTaskManager(numSlotsPerTaskManager)
519:                                 .build());
520:         cluster.before();
521:         try {
522:             final JobID jobID1 = new JobID();
523:             jobGraph.setJobID(jobID1);
524:             cluster.getClusterClient().submitJob(jobGraph).get();
525:             CommonTestUtils.waitForAllTaskRunning(cluster.getMiniCluster(), jobID1, false);
526:             // wait for some records to be processed before taking the checkpoint
527:             counter.get().await();
528:             final String firstCheckpoint = cluster.getMiniCluster().triggerCheckpoint(jobID1).get();
529: 
530:             cluster.getClusterClient().cancel(jobID1).get();
531:             jobGraph.setSavepointRestoreSettings(
532:                     SavepointRestoreSettings.forPath(
533:                             firstCheckpoint, false, RecoveryClaimMode.NO_CLAIM));
534:             final JobID jobID2 = new JobID();
535:             jobGraph.setJobID(jobID2);
536:             cluster.getClusterClient().submitJob(jobGraph).get();
537:             CommonTestUtils.waitForAllTaskRunning(cluster.getMiniCluster(), jobID2, false);
538:             String secondCheckpoint = cluster.getMiniCluster().triggerCheckpoint(jobID2).get();
539:             cluster.getClusterClient().cancel(jobID2).get();
540: 
541:             // delete the checkpoint we restored from
542:             FileUtils.deleteDirectory(Paths.get(new URI(firstCheckpoint)).getParent().toFile());
543: 
544:             // we should be able to restore from the second checkpoint even though it has been built
545:             // on top of the first checkpoint
546:             jobGraph.setSavepointRestoreSettings(
547:                     SavepointRestoreSettings.forPath(
548:                             secondCheckpoint, false, RecoveryClaimMode.NO_CLAIM));
549:             final JobID jobID3 = new JobID();
550:             jobGraph.setJobID(jobID3);
551:             cluster.getClusterClient().submitJob(jobGraph).get();
552:             CommonTestUtils.waitForAllTaskRunning(cluster.getMiniCluster(), jobID3, false);
553:         } finally {
554:             cluster.after();
555:         }
556:     }
