678:     @FunctionalInterface
679:     interface PostCancelChecker {
680:         void check(MiniClusterWithClientResource cluster) throws Exception;
681:     }
682: 
683:     private void restoreJobAndVerifyState(
684:             MiniClusterResourceFactory clusterFactory,
685:             int parallelism,
686:             SavepointRestoreSettings savepointRestoreSettings,
687:             PostCancelChecker postCancelChecks)
688:             throws Exception {
689:         final StreamGraph jobGraph = createJobGraph(parallelism, 0, 1000);
690:         jobGraph.setSavepointRestoreSettings(savepointRestoreSettings);
691:         final JobID jobId = jobGraph.getJobID();
692:         StatefulCounter.resetForTest(parallelism);
693: 
694:         MiniClusterWithClientResource cluster = clusterFactory.get();
695:         cluster.before();
696:         ClusterClient<?> client = cluster.getClusterClient();
697: 
698:         try {
699:             client.submitJob(jobGraph).get();
700: 
701:             // Await state is restored
702:             StatefulCounter.getRestoreLatch().await();
703: 
704:             // Await some progress after restore
705:             StatefulCounter.getProgressLatch().await();
706: 
707:             client.cancel(jobId).get();
708: 
709:             FutureUtils.retrySuccessfulWithDelay(
710:                     () -> client.getJobStatus(jobId),
711:                     Duration.ofMillis(50),
712:                     Deadline.now().plus(Duration.ofSeconds(30)),
713:                     status -> status == JobStatus.CANCELED,
714:                     new ScheduledExecutorServiceAdapter(EXECUTOR_RESOURCE.getExecutor()));
715: 
716:             postCancelChecks.check(cluster);
717:         } finally {
718:             cluster.after();
719:             StatefulCounter.resetForTest(parallelism);
720:         }
721:     }
