844:     static class BoundedPassThroughOperator<T> extends AbstractStreamOperator<T>
845:             implements OneInputStreamOperator<T, T>, BoundedOneInput {
846:         static volatile CountDownLatch progressLatch;
847:         static volatile CountDownLatch snapshotAllowedLatch;
848:         static volatile CountDownLatch snapshotStartedLatch;
849:         static volatile boolean inputEnded;
850: 
851:         private transient boolean processed;
852: 
853:         BoundedPassThroughOperator() {}
854: 
855:         private static void allowSnapshots() {
856:             snapshotAllowedLatch.countDown();
857:         }
858: 
859:         public static void awaitSnapshotStarted() throws InterruptedException {
860:             snapshotStartedLatch.await();
861:         }
862: 
863:         @Override
864:         public void endInput() throws Exception {
865:             inputEnded = true;
866:         }
867: 
868:         @Override
869:         public void processElement(StreamRecord<T> element) throws Exception {
870:             output.collect(element);
871:             if (!processed) {
872:                 processed = true;
873:                 progressLatch.countDown();
874:             }
875:         }
876: 
877:         @Override
878:         public void snapshotState(StateSnapshotContext context) throws Exception {
879:             snapshotStartedLatch.countDown();
880:             snapshotAllowedLatch.await();
881:             super.snapshotState(context);
882:         }
883: 
884:         // --------------------------------------------------------------------
885: 
886:         static CountDownLatch getProgressLatch() {
887:             return progressLatch;
888:         }
889: 
890:         static void resetForTest(int parallelism, boolean allowSnapshots) {
891:             progressLatch = new CountDownLatch(parallelism);
892:             snapshotAllowedLatch = new CountDownLatch(allowSnapshots ? 0 : 1);
893:             snapshotStartedLatch = new CountDownLatch(parallelism);
894:             inputEnded = false;
895:         }
896:     }
