1096:     /**
1097:      * FLINK-21030
1098:      *
1099:      * <p>Tests the handling of a failure that happened while stopping an embarrassingly parallel
1100:      * job with a Savepoint. The test expects that the stopping action fails and all executions are
1101:      * in state {@code RUNNING} afterwards.
1102:      *
1103:      * @param failingSource the failing {@link SourceFunction} used in one of the two pipelines.
1104:      * @param expectedMaximumNumberOfRestarts the maximum number of restarts allowed by the restart
1105:      *     strategy.
1106:      * @param exceptionAssertion asserts the client-call exception to verify that the right error
1107:      *     was handled.
1108:      * @see SavepointITCase#failingPipelineLatch The latch used to trigger the successful start of
1109:      *     the later on failing pipeline.
1110:      * @see SavepointITCase#succeedingPipelineLatch The latch that triggers the successful start of
1111:      *     the succeeding pipeline.
1112:      * @throws Exception if an error occurred while running the test.
1113:      */
1114:     private static void testStopWithFailingSourceInOnePipeline(
1115:             InfiniteTestSource failingSource,
1116:             File savepointDir,
1117:             int expectedMaximumNumberOfRestarts,
1118:             BiFunction<JobID, ExecutionException, Boolean> exceptionAssertion,
1119:             boolean shouldRestart)
1120:             throws Exception {
1121:         MiniClusterWithClientResource cluster =
1122:                 new MiniClusterWithClientResource(
1123:                         new MiniClusterResourceConfiguration.Builder().build());
1124: 
1125:         failingPipelineLatch = new OneShotLatch();
1126:         succeedingPipelineLatch = new OneShotLatch();
1127: 
1128:         StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
1129:         env.setParallelism(1);
1130:         RestartStrategyUtils.configureFixedDelayRestartStrategy(
1131:                 env, expectedMaximumNumberOfRestarts, 0L);
1132:         env.addSource(failingSource)
1133:                 .name("Failing Source")
1134:                 .map(
1135:                         value -> {
1136:                             failingPipelineLatch.trigger();
1137:                             return value;
1138:                         })
1139:                 .sinkTo(new DiscardingSink<>());
1140:         env.addSource(new InfiniteTestSource())
1141:                 .name("Succeeding Source")
1142:                 .map(
1143:                         value -> {
1144:                             succeedingPipelineLatch.trigger();
1145:                             return value;
1146:                         })
1147:                 .sinkTo(new DiscardingSink<>());
1148: 
1149:         final StreamGraph jobGraph = env.getStreamGraph().getJobGraph();
1150: 
1151:         cluster.before();
1152:         try {
1153:             ClusterClient<?> client = cluster.getClusterClient();
1154:             JobID jobID = client.submitJob(jobGraph).get();
1155: 
1156:             // we need to wait for both pipelines to be in state RUNNING because that's the only
1157:             // state which allows creating a savepoint
1158:             failingPipelineLatch.await();
1159:             succeedingPipelineLatch.await();
1160:             waitForAllTaskRunning(cluster.getMiniCluster(), jobID, false);
1161: 
1162:             try {
1163:                 client.stopWithSavepoint(
1164:                                 jobGraph.getJobID(),
1165:                                 false,
1166:                                 savepointDir.getAbsolutePath(),
1167:                                 SavepointFormatType.CANONICAL)
1168:                         .get();
1169:                 fail("The future should fail exceptionally.");
1170:             } catch (ExecutionException e) {
1171:                 assertThrowable(e, ex -> exceptionAssertion.apply(jobGraph.getJobID(), e));
1172:             }
1173: 
1174:             if (shouldRestart) {
1175:                 waitUntilAllTasksAreRunning(cluster.getRestClusterClient(), jobGraph.getJobID());
1176:             }
1177:         } finally {
1178:             cluster.after();
1179:         }
1180:     }
