1182:     public static void waitUntilAllTasksAreRunning(
1183:             RestClusterClient<?> restClusterClient, JobID jobId) throws Exception {
1184:         // access the REST endpoint of the cluster to determine the state of each
1185:         // ExecutionVertex
1186: 
1187:         final JobDetailsHeaders detailsHeaders = JobDetailsHeaders.getInstance();
1188:         final JobMessageParameters params = detailsHeaders.getUnresolvedMessageParameters();
1189:         params.jobPathParameter.resolve(jobId);
1190: 
1191:         CommonTestUtils.waitUntilCondition(
1192:                 () ->
1193:                         restClusterClient
1194:                                 .sendRequest(detailsHeaders, params, EmptyRequestBody.getInstance())
1195:                                 .thenApply(
1196:                                         detailsInfo ->
1197:                                                 allVerticesRunning(
1198:                                                         detailsInfo.getJobVerticesPerState()))
1199:                                 .get());
1200:     }
1201: 
1202:     private static boolean allVerticesRunning(Map<ExecutionState, Integer> states) {
1203:         return states.entrySet().stream()
1204:                 .allMatch(
1205:                         entry -> {
1206:                             if (entry.getKey() == ExecutionState.RUNNING) {
1207:                                 return entry.getValue() > 0;
1208:                             } else {
1209:                                 return entry.getValue() == 0; // no vertices in non-running state.
1210:                             }
1211:                         });
1212:     }
