1365:     private static class InfiniteTestSource implements ParallelSourceFunction<Integer> {
1366: 
1367:         private static final long serialVersionUID = 1L;
1368:         private volatile boolean running = true;
1369:         private volatile boolean suspended = false;
1370:         private static final Collection<InfiniteTestSource> createdSources =
1371:                 new CopyOnWriteArrayList<>();
1372:         private transient volatile CompletableFuture<Void> completeFuture;
1373: 
1374:         @Override
1375:         public void run(SourceContext<Integer> ctx) throws Exception {
1376:             completeFuture = new CompletableFuture<>();
1377:             createdSources.add(this);
1378:             try {
1379:                 while (running) {
1380:                     if (!suspended) {
1381:                         synchronized (ctx.getCheckpointLock()) {
1382:                             ctx.collect(1);
1383:                         }
1384:                     }
1385:                     Thread.sleep(1);
1386:                 }
1387:                 completeFuture.complete(null);
1388:             } catch (Exception e) {
1389:                 completeFuture.completeExceptionally(e);
1390:                 throw e;
1391:             }
1392:         }
1393: 
1394:         @Override
1395:         public void cancel() {
1396:             running = false;
1397:         }
1398: 
1399:         public void suspend() {
1400:             suspended = true;
1401:         }
1402: 
1403:         public static void resetForTest() {
1404:             createdSources.clear();
1405:         }
1406: 
1407:         public CompletableFuture<Void> getCompleteFuture() {
1408:             return completeFuture;
1409:         }
1410: 
1411:         public static void cancelAllAndAwait() throws ExecutionException, InterruptedException {
1412:             createdSources.forEach(InfiniteTestSource::cancel);
1413:             allOf(
1414:                             createdSources.stream()
1415:                                     .map(InfiniteTestSource::getCompleteFuture)
1416:                                     .toArray(CompletableFuture[]::new))
1417:                     .get();
1418:         }
1419: 
1420:         public static void suspendAll() {
1421:             createdSources.forEach(InfiniteTestSource::suspend);
1422:         }
1423:     }
