152:             IntermediateDataSetID resultId = consumedIntermediateResult.getId();
153:             ResultPartitionType partitionType = consumedIntermediateResult.getResultType();
154:             IndexRange subpartitionRange =
155:                     executionVertex
156:                             .getExecutionVertexInputInfo(resultId)
157:                             .getSubpartitionIndexRange();
158: 
159:             inputGates.add(
160:                     new InputGateDeploymentDescriptor(
161:                             resultId,
162:                             partitionType,
163:                             subpartitionRange,
164:                             consumedPartitionGroup.size(),
165:                             getConsumedPartitionShuffleDescriptors(
166:                                     consumedIntermediateResult,
167:                                     consumedPartitionGroup,
