171:         final Map<IntermediateDataSetID, ShuffleDescriptorAndIndex[]>
172:                 consumedClusterPartitionShuffleDescriptors;
173:         try {
174:             consumedClusterPartitionShuffleDescriptors =
175:                     getClusterPartitionShuffleDescriptors(executionVertex);
176:         } catch (Throwable e) {
