179:                     executionVertex
180:                             .getJobVertex()
181:                             .getJobVertex()
182:                             .getIntermediateDataSetIdsToConsume());
183:         }
184: 
185:         for (Map.Entry<IntermediateDataSetID, ShuffleDescriptorAndIndex[]> entry :
186:                 consumedClusterPartitionShuffleDescriptors.entrySet()) {
187:             // For FLIP-205, the JobGraph generating side ensure that the cluster partition is
188:             // produced with only one subpartition. Therefore, we always consume the partition with
