210:                     intermediateResult.cacheShuffleDescriptors(
211:                             consumedPartitionGroup,
212:                             // compute all shuffle descriptors if it is not cached before.
213:                             computeConsumedPartitionShuffleDescriptors(
214:                                     consumedPartitionGroup, internalExecutionGraphAccessor));
215:         }
216:         cachedShuffleDescriptors.serializeShuffleDescriptors(shuffleDescriptorSerializer);
217: 
218:         return cachedShuffleDescriptors.getAllSerializedShuffleDescriptorGroups();
219:     }
