221:     private ShuffleDescriptorAndIndex[] computeConsumedPartitionShuffleDescriptors(
222:             ConsumedPartitionGroup consumedPartitionGroup,
223:             InternalExecutionGraphAccessor internalExecutionGraphAccessor) {
224: 
225:         ShuffleDescriptorAndIndex[] shuffleDescriptors =
226:                 new ShuffleDescriptorAndIndex[consumedPartitionGroup.size()];
227:         // Each edge is connected to a different result partition
228:         int i = 0;
229:         for (IntermediateResultPartitionID partitionId : consumedPartitionGroup) {
230:             shuffleDescriptors[i] =
231:                     new ShuffleDescriptorAndIndex(
232:                             getConsumedPartitionShuffleDescriptor(
233:                                     internalExecutionGraphAccessor.getResultPartitionOrThrow(
234:                                             partitionId),
235:                                     partitionDeploymentConstraint,
236:                                     nonFinishedHybridPartitionShouldBeUnknown),
237:                             i);
238:             i++;
239:         }
240:         return shuffleDescriptors;
241:     }
