243:     private static Map<IntermediateDataSetID, ShuffleDescriptorAndIndex[]>
244:             getClusterPartitionShuffleDescriptors(ExecutionVertex executionVertex) {
245:         final InternalExecutionGraphAccessor internalExecutionGraphAccessor =
246:                 executionVertex.getExecutionGraphAccessor();
247:         final List<IntermediateDataSetID> consumedClusterDataSetIds =
248:                 executionVertex.getJobVertex().getJobVertex().getIntermediateDataSetIdsToConsume();
249:         Map<IntermediateDataSetID, ShuffleDescriptorAndIndex[]> clusterPartitionShuffleDescriptors =
250:                 new HashMap<>();
251: 
252:         for (IntermediateDataSetID consumedClusterDataSetId : consumedClusterDataSetIds) {
253:             List<? extends ShuffleDescriptor> shuffleDescriptors =
254:                     internalExecutionGraphAccessor.getClusterPartitionShuffleDescriptors(
255:                             consumedClusterDataSetId);
256: 
257:             // For FLIP-205, the job graph generating side makes sure that the producer and consumer
258:             // of the cluster partition have the same parallelism and each consumer Task consumes
259:             // one output partition of the producer.
260:             checkState(
261:                     executionVertex.getTotalNumberOfParallelSubtasks() == shuffleDescriptors.size(),
262:                     "The parallelism (%s) of the cache consuming job vertex is "
263:                             + "different from the number of shuffle descriptors (%s) of the intermediate data set",
264:                     executionVertex.getTotalNumberOfParallelSubtasks(),
265:                     shuffleDescriptors.size());
266: 
267:             clusterPartitionShuffleDescriptors.put(
268:                     consumedClusterDataSetId,
269:                     new ShuffleDescriptorAndIndex[] {
270:                         new ShuffleDescriptorAndIndex(
271:                                 shuffleDescriptors.get(executionVertex.getParallelSubtaskIndex()),
272:                                 // For FLIP-205, the JobGraph generating side ensure that the
273:                                 // cluster partition is produced with only one subpartition.
274:                                 // Therefore, this index is always 0.
275:                                 0)
276:                     });
277:         }
278:         return clusterPartitionShuffleDescriptors;
279:     }
