297:     public static ShuffleDescriptor getConsumedPartitionShuffleDescriptor(
298:             IntermediateResultPartition consumedPartition,
299:             PartitionLocationConstraint partitionDeploymentConstraint,
300:             boolean nonFinishedHybridPartitionShouldBeUnknown) {
301:         Execution producer = consumedPartition.getProducer().getPartitionProducer();
302: 
303:         ExecutionState producerState = producer.getState();
304:         Optional<ResultPartitionDeploymentDescriptor> consumedPartitionDescriptor =
305:                 producer.getResultPartitionDeploymentDescriptor(consumedPartition.getPartitionId());
306: 
307:         ResultPartitionID consumedPartitionId =
308:                 new ResultPartitionID(consumedPartition.getPartitionId(), producer.getAttemptId());
309: 
310:         return getConsumedPartitionShuffleDescriptor(
311:                 consumedPartitionId,
312:                 consumedPartition.getResultType(),
313:                 consumedPartition.hasDataAllProduced(),
314:                 producerState,
315:                 partitionDeploymentConstraint,
316:                 consumedPartitionDescriptor.orElse(null),
317:                 nonFinishedHybridPartitionShouldBeUnknown);
318:     }
319: 
320:     @VisibleForTesting
321:     static ShuffleDescriptor getConsumedPartitionShuffleDescriptor(
322:             ResultPartitionID consumedPartitionId,
323:             ResultPartitionType resultPartitionType,
324:             boolean hasAllDataProduced,
325:             ExecutionState producerState,
326:             PartitionLocationConstraint partitionDeploymentConstraint,
327:             @Nullable ResultPartitionDeploymentDescriptor consumedPartitionDescriptor,
328:             boolean nonFinishedHybridPartitionShouldBeUnknown) {
329:         // The producing task needs to be RUNNING or already FINISHED
330:         if ((resultPartitionType.canBePipelinedConsumed() || hasAllDataProduced)
331:                 && consumedPartitionDescriptor != null
332:                 && isProducerAvailable(producerState)) {
333:             if (resultPartitionType.isHybridResultPartition()
334:                     && nonFinishedHybridPartitionShouldBeUnknown) {
335:                 // if producer is not finished, shuffle descriptor should be unknown.
336:                 if (producerState != ExecutionState.FINISHED) {
337:                     checkState(
338:                             partitionDeploymentConstraint
339:                                     == PartitionLocationConstraint.CAN_BE_UNKNOWN,
340:                             "partition location constraint should allow unknown shuffle descriptor when nonFinishedHybridPartitionShouldBeUnknown is true.");
341:                     return new UnknownShuffleDescriptor(consumedPartitionId);
342:                 }
343:             }
344:             // partition is already registered
345:             return consumedPartitionDescriptor.getShuffleDescriptor();
346:         } else if (partitionDeploymentConstraint == PartitionLocationConstraint.CAN_BE_UNKNOWN) {
347:             // The producing task might not have registered the partition yet
348:             //
349:             // Currently, UnknownShuffleDescriptor will be created only if there is an intra-region
350:             // blocking edge in the graph. This means that when its consumer restarts, the
351:             // producer of the UnknownShuffleDescriptors will also restart. Therefore, it's safe to
352:             // cache UnknownShuffleDescriptors and there's no need to update the cache when the
353:             // corresponding partition becomes consumable.
354:             return new UnknownShuffleDescriptor(consumedPartitionId);
355:         } else {
356:             // throw respective exceptions
357:             throw handleConsumedPartitionShuffleDescriptorErrors(
358:                     consumedPartitionId, resultPartitionType, hasAllDataProduced, producerState);
359:         }
360:     }
361: 
362:     private static RuntimeException handleConsumedPartitionShuffleDescriptorErrors(
363:             ResultPartitionID consumedPartitionId,
364:             ResultPartitionType resultPartitionType,
365:             boolean hasAllDataProduced,
366:             ExecutionState producerState) {
367:         String msg;
368:         if (isProducerFailedOrCanceled(producerState)) {
369:             msg =
370:                     "Trying to consume an input partition whose producer has been canceled or failed. "
371:                             + "The producer is in state "
372:                             + producerState
373:                             + ".";
374:         } else {
375:             msg =
376:                     String.format(
377:                             "Trying to consume an input partition whose producer "
378:                                     + "is not ready (result type: %s, hasAllDataProduced: %s, producer state: %s, partition id: %s).",
379:                             resultPartitionType,
380:                             hasAllDataProduced,
381:                             producerState,
382:                             consumedPartitionId);
383:         }
384:         return new IllegalStateException(msg);
385:     }
386: 
387:     private static boolean isProducerAvailable(ExecutionState producerState) {
388:         return producerState == ExecutionState.RUNNING
389:                 || producerState == ExecutionState.INITIALIZING
390:                 || producerState == ExecutionState.FINISHED
391:                 || producerState == ExecutionState.SCHEDULED
392:                 || producerState == ExecutionState.DEPLOYING;
393:     }
394: 
395:     private static boolean isProducerFailedOrCanceled(ExecutionState producerState) {
396:         return producerState == ExecutionState.CANCELING
397:                 || producerState == ExecutionState.CANCELED
398:                 || producerState == ExecutionState.FAILED;
399:     }
