401:     /**
402:      * Defines whether the partition's location must be known at deployment time or can be unknown
403:      * and, therefore, updated later.
404:      */
405:     public enum PartitionLocationConstraint {
406:         MUST_BE_KNOWN,
407:         CAN_BE_UNKNOWN;
408: 
409:         public static PartitionLocationConstraint fromJobType(JobType jobType) {
410:             switch (jobType) {
411:                 case BATCH:
412:                     return CAN_BE_UNKNOWN;
413:                 case STREAMING:
414:                     return MUST_BE_KNOWN;
415:                 default:
416:                     throw new IllegalArgumentException(
417:                             String.format(
418:                                     "Unknown JobType %s. Cannot derive partition location constraint for it.",
419:                                     jobType));
420:             }
421:         }
422:     }
