424:     /**
425:      * This class represents the shuffle descriptor with it index in {@link ConsumedPartitionGroup}.
426:      */
427:     public static class ShuffleDescriptorAndIndex implements Serializable {
428:         private static final long serialVersionUID = 1L;
429: 
430:         private final ShuffleDescriptor shuffleDescriptor;
431: 
432:         private final int index;
433: 
434:         public ShuffleDescriptorAndIndex(ShuffleDescriptor shuffleDescriptor, int index) {
435:             this.shuffleDescriptor = shuffleDescriptor;
436:             this.index = index;
437:         }
438: 
439:         public ShuffleDescriptor getShuffleDescriptor() {
440:             return shuffleDescriptor;
441:         }
442: 
443:         public int getIndex() {
444:             return index;
445:         }
446:     }
