448:     /** A set of shuffle descriptors that will be serialized together. */
449:     public static class ShuffleDescriptorGroup implements Serializable {
450:         private static final long serialVersionUID = 1L;
451: 
452:         private final ShuffleDescriptorAndIndex[] shuffleDescriptors;
453: 
454:         public ShuffleDescriptorGroup(ShuffleDescriptorAndIndex[] shuffleDescriptors) {
455:             this.shuffleDescriptors = checkNotNull(shuffleDescriptors);
456:         }
457: 
458:         public ShuffleDescriptorAndIndex[] getShuffleDescriptors() {
459:             return shuffleDescriptors;
460:         }
461:     }
462: 
463:     /** Serialize shuffle descriptors. */
464:     interface ShuffleDescriptorSerializer {
465:         /**
466:          * Serialize and try offload shuffle descriptors.
467:          *
468:          * @param shuffleDescriptorGroup to serialize
469:          * @param numConsumer consumers number of these shuffle descriptors, it means how many times
470:          *     serialized shuffle descriptor should be sent
471:          * @return offloaded or non-offloaded serialized shuffle descriptors
472:          */
473:         MaybeOffloaded<ShuffleDescriptorGroup> serializeAndTryOffloadShuffleDescriptor(
474:                 ShuffleDescriptorGroup shuffleDescriptorGroup, int numConsumer) throws IOException;
475:     }
476: 
477:     private static class DefaultShuffleDescriptorSerializer implements ShuffleDescriptorSerializer {
478:         private final JobID jobID;
479:         private final BlobWriter blobWriter;
480:         private final int offloadShuffleDescriptorsThreshold;
481: 
482:         public DefaultShuffleDescriptorSerializer(
483:                 JobID jobID, BlobWriter blobWriter, int offloadShuffleDescriptorsThreshold) {
484:             this.jobID = checkNotNull(jobID);
485:             this.blobWriter = checkNotNull(blobWriter);
486:             this.offloadShuffleDescriptorsThreshold = offloadShuffleDescriptorsThreshold;
487:         }
488: 
489:         @Override
490:         public MaybeOffloaded<ShuffleDescriptorGroup> serializeAndTryOffloadShuffleDescriptor(
491:                 ShuffleDescriptorGroup shuffleDescriptorGroup, int numConsumer) throws IOException {
492: 
493:             final CompressedSerializedValue<ShuffleDescriptorGroup> compressedSerializedValue =
494:                     CompressedSerializedValue.fromObject(shuffleDescriptorGroup);
495: 
496:             final Either<SerializedValue<ShuffleDescriptorGroup>, PermanentBlobKey>
497:                     serializedValueOrBlobKey =
498:                             shouldOffload(
499:                                             shuffleDescriptorGroup.getShuffleDescriptors(),
500:                                             numConsumer)
501:                                     ? BlobWriter.offloadWithException(
502:                                             compressedSerializedValue, jobID, blobWriter)
503:                                     : Either.Left(compressedSerializedValue);
504: 
505:             if (serializedValueOrBlobKey.isLeft()) {
506:                 return new TaskDeploymentDescriptor.NonOffloaded<>(serializedValueOrBlobKey.left());
507:             } else {
508:                 return new TaskDeploymentDescriptor.Offloaded<>(serializedValueOrBlobKey.right());
509:             }
510:         }
511: 
512:         /**
513:          * Determine whether shuffle descriptors should be offloaded to blob server.
514:          *
515:          * @param shuffleDescriptorsToSerialize shuffle descriptors to serialize
516:          * @param numConsumers how many consumers this serialized shuffle descriptor should be sent
517:          * @return whether shuffle descriptors should be offloaded to blob server
518:          */
519:         private boolean shouldOffload(
520:                 ShuffleDescriptorAndIndex[] shuffleDescriptorsToSerialize, int numConsumers) {
521:             return shuffleDescriptorsToSerialize.length * numConsumers
522:                     >= offloadShuffleDescriptorsThreshold;
523:         }
524:     }
525: }
