44: 
45:     private DefaultLogicalTopology(final List<JobVertex> jobVertices) {
46:         checkNotNull(jobVertices);
47: 
48:         this.verticesSorted = new ArrayList<>(jobVertices.size());
49:         this.idToVertexMap = new HashMap<>();
50:         this.idToResultMap = new HashMap<>();
51: 
52:         buildVerticesAndResults(jobVertices);
53:     }
