67:     private void buildVerticesAndResults(final Iterable<JobVertex> topologicallySortedJobVertices) {
68:         final Function<JobVertexID, DefaultLogicalVertex> vertexRetriever = this::getVertex;
69:         final Function<IntermediateDataSetID, DefaultLogicalResult> resultRetriever =
70:                 this::getResult;
71: 
72:         for (JobVertex jobVertex : topologicallySortedJobVertices) {
73:             final DefaultLogicalVertex logicalVertex =
74:                     new DefaultLogicalVertex(jobVertex, resultRetriever);
75:             this.verticesSorted.add(logicalVertex);
76:             this.idToVertexMap.put(logicalVertex.getId(), logicalVertex);
77: 
78:             for (IntermediateDataSet intermediateDataSet : jobVertex.getProducedDataSets()) {
79:                 final DefaultLogicalResult logicalResult =
80:                         new DefaultLogicalResult(intermediateDataSet, vertexRetriever);
81:                 idToResultMap.put(logicalResult.getId(), logicalResult);
82:             }
83:         }
84:     }
