92:         return Optional.ofNullable(idToVertexMap.get(vertexId))
93:                 .orElseThrow(
94:                         () -> new IllegalArgumentException("can not find vertex: " + vertexId));
95:     }
96: 
97:     private DefaultLogicalResult getResult(final IntermediateDataSetID resultId) {
98:         return Optional.ofNullable(idToResultMap.get(resultId))
99:                 .orElseThrow(
100:                         () -> new IllegalArgumentException("can not find result: " + resultId));
101:     }
