33: 
34:     /** Transmogrifies the given {@link Pipeline} to a {@link StreamGraph}. */
35:     public static StreamGraph getJobGraph(
36:             ClassLoader userClassloader,
37:             Pipeline pipeline,
38:             Configuration optimizerConfiguration,
39:             int defaultParallelism) {
40: 
41:         FlinkPipelineTranslator pipelineTranslator =
42:                 getPipelineTranslator(userClassloader, pipeline);
