49:                 jobVertices.stream()
50:                         .filter(
51:                                 jobVertex -> {
52:                                     jobVertexIds.add(jobVertex.getID());
53:                                     return jobVertex.getParallelism() > 0;
54:                                 })
55:                         .map(JobVertex::getParallelism)
56:                         .collect(Collectors.toSet());
57: 
58:         checkState(configuredParallelisms.size() <= 1);
59:         if (configuredParallelisms.size() == 1) {
60:             this.parallelism = configuredParallelisms.iterator().next();
61:         }
62: 
63:         Set<Integer> configuredMaxParallelisms =
64:                 jobVertices.stream()
65:                         .map(JobVertex::getMaxParallelism)
66:                         .filter(val -> val > 0)
67:                         .collect(Collectors.toSet());
68: 
69:         if (!configuredMaxParallelisms.isEmpty()) {
70:             this.maxParallelism = Collections.min(configuredMaxParallelisms);
71:             checkState(
72:                     parallelism == ExecutionConfig.PARALLELISM_DEFAULT
73:                             || maxParallelism >= parallelism,
74:                     "There is a job vertex in the forward group whose maximum parallelism is smaller than the group's parallelism");
75:         }
76:     }
