49:     /**
50:      * Creates the {@link StreamGraph} corresponding to the provided {@link Pipeline}.
51:      *
52:      * @param pipeline the pipeline whose job graph we are computing.
53:      * @param configuration the configuration with the necessary information such as jars and
54:      *     classpaths to be included, the parallelism of the job and potential savepoint settings
55:      *     used to bootstrap its state.
56:      * @param userClassloader the classloader which can load user classes.
57:      * @return the corresponding {@link StreamGraph}.
58:      */
59:     public static StreamGraph getStreamGraph(
60:             @Nonnull final Pipeline pipeline,
61:             @Nonnull final Configuration configuration,
62:             @Nonnull ClassLoader userClassloader)
63:             throws MalformedURLException {
64:         checkNotNull(pipeline);
65:         checkNotNull(configuration);
66: 
67:         final ExecutionConfigAccessor executionConfigAccessor =
68:                 ExecutionConfigAccessor.fromConfiguration(configuration);
69:         final StreamGraph jobGraph =
70:                 FlinkPipelineTranslationUtil.getJobGraph(
71:                         userClassloader,
72:                         pipeline,
73:                         configuration,
74:                         executionConfigAccessor.getParallelism());
75: 
76:         configuration
77:                 .getOptional(PipelineOptionsInternal.PIPELINE_FIXED_JOB_ID)
78:                 .ifPresent(strJobID -> jobGraph.setJobID(JobID.fromHexString(strJobID)));
79: 
80:         if (configuration.get(DeploymentOptions.ATTACHED)
81:                 && configuration.get(DeploymentOptions.SHUTDOWN_IF_ATTACHED)) {
82:             jobGraph.setInitialClientHeartbeatTimeout(
83:                     configuration.get(ClientOptions.CLIENT_HEARTBEAT_TIMEOUT).toMillis());
84:         }
85: 
86:         jobGraph.addJars(executionConfigAccessor.getJars());
87:         jobGraph.setClasspaths(executionConfigAccessor.getClasspaths());
88:         jobGraph.setSavepointRestoreSettings(executionConfigAccessor.getSavepointRestoreSettings());
89: 
90:         return jobGraph;
91:     }
