93:     /**
94:      * Notify the {@link DefaultJobCreatedEvent} to job status changed listeners.
95:      *
96:      * @param pipeline the pipeline that contains lineage graph information.
97:      * @param jobGraph jobGraph that contains job basic info
98:      * @param listeners the list of job status changed listeners
99:      */
100:     public static void notifyJobStatusListeners(
101:             @Nonnull final Pipeline pipeline,
102:             @Nonnull final StreamGraph jobGraph,
103:             List<JobStatusChangedListener> listeners) {
104:         RuntimeExecutionMode executionMode =
105:                 jobGraph.getJobConfiguration().get(ExecutionOptions.RUNTIME_MODE);
106:         listeners.forEach(
107:                 listener -> {
108:                     try {
109:                         listener.onEvent(
110:                                 new DefaultJobCreatedEvent(
111:                                         jobGraph.getJobID(),
112:                                         jobGraph.getName(),
113:                                         ((org.apache.flink.streaming.api.graph.StreamGraph) pipeline).getLineageGraph(),
114:                                         executionMode));
115:                     } catch (Throwable e) {
116:                         LOG.error(
117:                                 "Fail to notify job status changed listener {}",
118:                                 listener.getClass().getName(),
119:                                 e);
120:                     }
121:                 });
122:     }
123: }
