498:     private void tryComputeSourceParallelismThenRunAsync(BiConsumer<Void, Throwable> action) {
499:         // Ensure `initializeVerticesIfPossible` is invoked asynchronously post
500:         // `computeDynamicSourceParallelism`. Any method required to run after
501:         // `initializeVerticesIfPossible` should be enqueued within the same asynchronous action to
502:         // maintain the correct execution order.
