515:     public List<CompletableFuture<Integer>> computeDynamicSourceParallelism() {
516:         final List<CompletableFuture<Integer>> dynamicSourceParallelismFutures = new ArrayList<>();
517:         for (ExecutionJobVertex jobVertex : getExecutionGraph().getVerticesTopologically()) {
518:             List<SourceCoordinator<?, ?>> sourceCoordinators = jobVertex.getSourceCoordinators();
519:             if (sourceCoordinators.isEmpty() || jobVertex.isParallelismDecided()) {
520:                 continue;
521:             }
522:             if (sourceParallelismFuturesByJobVertexId.containsKey(jobVertex.getJobVertexId())) {
523:                 dynamicSourceParallelismFutures.add(
524:                         sourceParallelismFuturesByJobVertexId.get(jobVertex.getJobVertexId()));
525:                 continue;
526:             }
527: 
528:             // We need to wait for the upstream vertex to complete, otherwise, dynamic filtering
529:             // information will be inaccessible during source parallelism inference.
530:             Optional<List<BlockingResultInfo>> consumedResultsInfo =
531:                     tryGetConsumedResultsInfo(jobVertex);
532:             if (consumedResultsInfo.isPresent()) {
533:                 List<CompletableFuture<Integer>> sourceParallelismFutures =
534:                         sourceCoordinators.stream()
535:                                 .map(
536:                                         sourceCoordinator ->
537:                                                 sourceCoordinator.inferSourceParallelismAsync(
538:                                                         vertexParallelismAndInputInfosDecider
539:                                                                 .computeSourceParallelismUpperBound(
540:                                                                         jobVertex.getJobVertexId(),
541:                                                                         jobVertex
542:                                                                                 .getMaxParallelism()),
543:                                                         vertexParallelismAndInputInfosDecider
544:                                                                 .getDataVolumePerTask()))
545:                                 .collect(Collectors.toList());
546:                 CompletableFuture<Integer> dynamicSourceParallelismFuture =
547:                         mergeDynamicParallelismFutures(sourceParallelismFutures);
548:                 sourceParallelismFuturesByJobVertexId.put(
549:                         jobVertex.getJobVertexId(), dynamicSourceParallelismFuture);
550:                 dynamicSourceParallelismFutures.add(dynamicSourceParallelismFuture);
551:             }
552:         }
553: 
554:         return dynamicSourceParallelismFutures;
555:     }
