557:     @VisibleForTesting
558:     static CompletableFuture<Integer> mergeDynamicParallelismFutures(
559:             List<CompletableFuture<Integer>> sourceParallelismFutures) {
560:         return sourceParallelismFutures.stream()
561:                 .reduce(
562:                         CompletableFuture.completedFuture(ExecutionConfig.PARALLELISM_DEFAULT),
563:                         (a, b) -> a.thenCombine(b, Math::max));
564:     }
