566:     @VisibleForTesting
567:     public void initializeVerticesIfPossible() {
568:         final List<ExecutionJobVertex> newlyInitializedJobVertices = new ArrayList<>();
569:         try {
570:             final long createTimestamp = System.currentTimeMillis();
571:             for (ExecutionJobVertex jobVertex : getExecutionGraph().getVerticesTopologically()) {
572:                 if (jobVertex.isInitialized()) {
573:                     continue;
574:                 }
575: 
576:                 if (canInitialize(jobVertex)) {
577:                     // This branch is for: If the parallelism is user-specified(decided), the
578:                     // downstream job vertices can be initialized earlier, so that it can be
579:                     // scheduled together with its upstream in hybrid shuffle mode.
580: 
581:                     // Note that in current implementation, the decider will not load balance
582:                     // (evenly distribute data) for job vertices whose parallelism has already been
583:                     // decided, so we can call the initializeJobVertex method, specifying the
584:                     // user-defined parallelism as its argument.
585:                     // TODO: In the future, if we want to load balance for job vertices whose
586:                     // parallelism has already been decided, we need to refactor the logic here.
587:                     initializeJobVertex(
588:                             jobVertex,
589:                             jobVertex.getParallelism(),
590:                             VertexInputInfoComputationUtils.computeVertexInputInfos(
591:                                     jobVertex,
592:                                     getExecutionGraph().getAllIntermediateResults()::get),
593:                             createTimestamp);
594:                     newlyInitializedJobVertices.add(jobVertex);
595:                 } else {
596:                     Optional<List<BlockingResultInfo>> consumedResultsInfo =
597:                             tryGetConsumedResultsInfo(jobVertex);
598:                     if (consumedResultsInfo.isPresent()) {
599:                         ParallelismAndInputInfos parallelismAndInputInfos =
600:                                 tryDecideParallelismAndInputInfos(
601:                                         jobVertex, consumedResultsInfo.get());
602:                         initializeJobVertex(
603:                                 jobVertex,
604:                                 parallelismAndInputInfos.getParallelism(),
605:                                 parallelismAndInputInfos.getJobVertexInputInfos(),
606:                                 createTimestamp);
607:                         newlyInitializedJobVertices.add(jobVertex);
608:                     }
609:                 }
610:             }
611:         } catch (JobException ex) {
612:             log.error("Unexpected error occurred when initializing ExecutionJobVertex", ex);
613:             this.handleGlobalFailure(new SuppressRestartsException(ex));
614:         }
615: 
616:         if (newlyInitializedJobVertices.size() > 0) {
617:             updateTopology(newlyInitializedJobVertices);
