621:     private ParallelismAndInputInfos tryDecideParallelismAndInputInfos(
622:             final ExecutionJobVertex jobVertex, List<BlockingResultInfo> inputs) {
623:         int vertexInitialParallelism = jobVertex.getParallelism();
624:         ForwardGroup forwardGroup = forwardGroupsByJobVertexId.get(jobVertex.getJobVertexId());
625:         if (!jobVertex.isParallelismDecided() && forwardGroup != null) {
626:             checkState(!forwardGroup.isParallelismDecided());
627:         }
628: 
629:         int vertexMinParallelism = ExecutionConfig.PARALLELISM_DEFAULT;
630:         if (sourceParallelismFuturesByJobVertexId.containsKey(jobVertex.getJobVertexId())) {
631:             int dynamicSourceParallelism = getDynamicSourceParallelism(jobVertex);
632:             // If the JobVertex only acts as a source vertex, dynamicSourceParallelism will serve as
633:             // the vertex's initial parallelism and will remain unchanged. If the JobVertex is also
634:             // a source with upstream inputs, dynamicSourceParallelism will serve as the vertex's
635:             // minimum parallelism, with the final parallelism being the maximum of
636:             // dynamicSourceParallelism and the vertex's dynamic parallelism according to upstream
637:             // inputs.
638:             if (!inputs.isEmpty()) {
639:                 vertexMinParallelism = dynamicSourceParallelism;
640:             } else {
641:                 vertexInitialParallelism = dynamicSourceParallelism;
642:             }
643:         }
644: 
645:         final ParallelismAndInputInfos parallelismAndInputInfos =
646:                 vertexParallelismAndInputInfosDecider.decideParallelismAndInputInfosForVertex(
647:                         jobVertex.getJobVertexId(),
648:                         inputs,
649:                         vertexInitialParallelism,
650:                         vertexMinParallelism,
651:                         jobVertex.getMaxParallelism());
652: 
653:         if (vertexInitialParallelism == ExecutionConfig.PARALLELISM_DEFAULT) {
654:             log.info(
655:                     "Parallelism of JobVertex: {} ({}) is decided to be {}.",
656:                     jobVertex.getName(),
657:                     jobVertex.getJobVertexId(),
658:                     parallelismAndInputInfos.getParallelism());
659:         } else {
660:             checkState(parallelismAndInputInfos.getParallelism() == vertexInitialParallelism);
661:         }
662: 
663:         if (forwardGroup != null && !forwardGroup.isParallelismDecided()) {
664:             forwardGroup.setParallelism(parallelismAndInputInfos.getParallelism());
665: 
666:             // When the parallelism for a forward group is determined, we ensure that the
667:             // parallelism for all job vertices within that group is also set.
668:             // This approach ensures that each forward edge produces single subpartition.
669:             //
670:             // This setting is crucial because the Sink V2 committer relies on the interplay
671:             // between the CommittableSummary and the CommittableWithLineage, which are sent by
672:             // the upstream Sink V2 Writer. The committer expects to receive CommittableSummary
673:             // before CommittableWithLineage.
674:             //
675:             // If the number of subpartitions produced by a forward edge is greater than one,
676:             // the ordering of these elements received by the committer cannot be assured, which
677:             // would break the assumption that CommittableSummary is received before
678:             // CommittableWithLineage.
679:             for (JobVertexID jobVertexId : forwardGroup.getJobVertexIds()) {
680:                 ExecutionJobVertex executionJobVertex = getExecutionJobVertex(jobVertexId);
681:                 if (!executionJobVertex.isParallelismDecided()) {
682:                     log.info(
683:                             "Parallelism of JobVertex: {} ({}) is decided to be {} according to forward group's parallelism.",
684:                             executionJobVertex.getName(),
685:                             executionJobVertex.getJobVertexId(),
686:                             parallelismAndInputInfos.getParallelism());
687:                     changeJobVertexParallelism(
688:                             executionJobVertex, parallelismAndInputInfos.getParallelism());
689:                 } else {
690:                     checkState(
691:                             parallelismAndInputInfos.getParallelism()
692:                                     == executionJobVertex.getParallelism());
693:                 }
694:             }
695:         }
696: 
697:         return parallelismAndInputInfos;
698:     }
