700:     private int getDynamicSourceParallelism(ExecutionJobVertex jobVertex) {
701:         CompletableFuture<Integer> dynamicSourceParallelismFuture =
702:                 sourceParallelismFuturesByJobVertexId.get(jobVertex.getJobVertexId());
703:         int dynamicSourceParallelism = ExecutionConfig.PARALLELISM_DEFAULT;
704:         if (dynamicSourceParallelismFuture != null) {
705:             dynamicSourceParallelism = dynamicSourceParallelismFuture.join();
706:             int vertexMaxParallelism = jobVertex.getMaxParallelism();
707:             if (dynamicSourceParallelism > vertexMaxParallelism) {
708:                 log.info(
709:                         "The dynamic inferred source parallelism {} is larger than the maximum parallelism {}. "
710:                                 + "Use {} as the upper bound parallelism of source job vertex {}.",
711:                         dynamicSourceParallelism,
712:                         vertexMaxParallelism,
713:                         vertexMaxParallelism,
714:                         jobVertex.getJobVertexId());
715:                 dynamicSourceParallelism = vertexMaxParallelism;
716:             } else if (dynamicSourceParallelism > 0) {
717:                 log.info(
718:                         "Parallelism of JobVertex: {} ({}) is decided to be {} according to dynamic source parallelism inference.",
719:                         jobVertex.getName(),
720:                         jobVertex.getJobVertexId(),
721:                         dynamicSourceParallelism);
722:             } else {
723:                 dynamicSourceParallelism = ExecutionConfig.PARALLELISM_DEFAULT;
724:             }
725:         }
726: 
727:         return dynamicSourceParallelism;
728:     }
