730:     private void enrichInputBytesForExecutionVertices(List<ExecutionVertex> executionVertices) {
731:         for (ExecutionVertex ev : executionVertices) {
732:             List<IntermediateResult> intermediateResults = ev.getJobVertex().getInputs();
733:             boolean hasHybridEdge =
734:                     intermediateResults.stream()
735:                             .anyMatch(
736:                                     ir ->
737:                                             ir.getResultType() == HYBRID_FULL
738:                                                     || ir.getResultType() == HYBRID_SELECTIVE);
739:             if (intermediateResults.isEmpty() || hasHybridEdge) {
740:                 continue;
741:             }
742:             long inputBytes = 0;
743:             for (IntermediateResult intermediateResult : intermediateResults) {
744:                 ExecutionVertexInputInfo inputInfo =
745:                         ev.getExecutionVertexInputInfo(intermediateResult.getId());
746:                 IndexRange partitionIndexRange = inputInfo.getPartitionIndexRange();
747:                 IndexRange subpartitionIndexRange = inputInfo.getSubpartitionIndexRange();
748:                 BlockingResultInfo blockingResultInfo =
749:                         checkNotNull(getBlockingResultInfo(intermediateResult.getId()));
750:                 inputBytes +=
751:                         blockingResultInfo.getNumBytesProduced(
752:                                 partitionIndexRange, subpartitionIndexRange);
753:             }
754:             ev.setInputBytes(inputBytes);
755:         }
756:     }
