777:     private Optional<List<BlockingResultInfo>> tryGetConsumedResultsInfo(
778:             final ExecutionJobVertex jobVertex) {
779: 
780:         List<BlockingResultInfo> consumableResultInfo = new ArrayList<>();
781: 
782:         DefaultLogicalVertex logicalVertex = logicalTopology.getVertex(jobVertex.getJobVertexId());
783:         Iterable<DefaultLogicalResult> consumedResults = logicalVertex.getConsumedResults();
784: 
785:         for (DefaultLogicalResult consumedResult : consumedResults) {
786:             final ExecutionJobVertex producerVertex =
787:                     getExecutionJobVertex(consumedResult.getProducer().getId());
788:             if (producerVertex.isFinished()) {
789:                 BlockingResultInfo resultInfo =
790:                         checkNotNull(blockingResultInfos.get(consumedResult.getId()));
791:                 consumableResultInfo.add(resultInfo);
792:             } else {
793:                 // not all inputs consumable, return Optional.empty()
794:                 return Optional.empty();
795:             }
796:         }
797: 
798:         return Optional.of(consumableResultInfo);
799:     }
