873:     private static BlockingResultInfo createFromIntermediateResult(IntermediateResult result) {
874:         checkArgument(result != null);
875:         // Note that for dynamic graph, different partitions in the same result have the same number
876:         // of subpartitions.
877:         if (result.getConsumingDistributionPattern() == DistributionPattern.POINTWISE) {
878:             return new PointwiseBlockingResultInfo(
879:                     result.getId(),
880:                     result.getNumberOfAssignedPartitions(),
881:                     result.getPartitions()[0].getNumberOfSubpartitions());
882:         } else {
883:             return new AllToAllBlockingResultInfo(
884:                     result.getId(),
885:                     result.getNumberOfAssignedPartitions(),
886:                     result.getPartitions()[0].getNumberOfSubpartitions(),
887:                     result.isBroadcast());
888:         }
889:     }
