90:         int nonLocalRecoveredTasks = 0;
91:         for (ArchivedExecutionVertex vertex : graph.getAllExecutionVertices()) {
92:             int currentAttemptNumber = vertex.getCurrentExecutionAttempt().getAttemptNumber();
93:             if (currentAttemptNumber == 0) {
94:                 // the task had never restarted and do not need to recover
95:                 continue;
96:             }
97:             AllocationID priorAllocation =
98:                     vertex.getExecutionHistory()
99:                             .getHistoricalExecution(currentAttemptNumber - 1)
