102:             AllocationID currentAllocation =
103:                     vertex.getCurrentExecutionAttempt().getAssignedAllocationID();
104: 
105:             assertNotNull(priorAllocation);
106:             assertNotNull(currentAllocation);
107:             if (!currentAllocation.equals(priorAllocation)) {
108:                 nonLocalRecoveredTasks++;
109:             }
110:         }
111:         assertThat(nonLocalRecoveredTasks, is(expected));
112:     }
