123:         final MiniClusterConfiguration miniClusterConfiguration =
124:                 new MiniClusterConfiguration.Builder()
125:                         .withRandomPorts()
126:                         .setConfiguration(configuration)
127:                         .setNumTaskManagers(parallelism)
