136:             StreamGraph jobGraph = createJobGraph(parallelism);
137: 
138:             // wait for the submission to succeed
139:             JobID jobId = miniClusterClient.submitJob(jobGraph).get(TIMEOUT, TimeUnit.SECONDS);
140: 
141:             // wait until all tasks running before triggering task failures
142:             waitUntilAllVerticesRunning(jobId, miniCluster);
