39: /** Used for translating data sets into corresponding operators. */
40: @Internal
41: public class OperatorTranslation {
42: 
43:     /** The already translated operations. */
44:     private Map<DataSet<?>, Operator<?>> translated = new HashMap<>();
45: 
46:     public StreamGraph translateToPlan(List<DataSink<?>> sinks, String jobName) {
47:         List<GenericDataSinkBase<?>> planSinks = new ArrayList<>();
48: 
49:         for (DataSink<?> sink : sinks) {
50:             planSinks.add(translate(sink));
51:         }
52: 
53:         StreamGraph p = new StreamGraph(planSinks);
54:         p.setJobName(jobName);
55:         return p;
56:     }
57: 
58:     private <T> GenericDataSinkBase<T> translate(DataSink<T> sink) {
59: 
60:         // translate the input recursively
61:         Operator<T> input = translate(sink.getDataSet());
62: 
63:         // translate the sink itself and connect it to the input
64:         GenericDataSinkBase<T> translatedSink = sink.translateToDataFlow(input);
65: 
66:         translatedSink.setResources(sink.getMinResources(), sink.getPreferredResources());
67: 
68:         return translatedSink;
69:     }
70: 
71:     private <T> Operator<T> translate(DataSet<T> dataSet) {
72:         while (dataSet instanceof NoOpOperator) {
73:             dataSet = ((NoOpOperator<T>) dataSet).getInput();
74:         }
75: 
76:         // check if we have already translated that data set (operation or source)
77:         Operator<?> previous = this.translated.get(dataSet);
78:         if (previous != null) {
79: 
80:             // Union operators may only have a single output.
81:             // We ensure this by not reusing previously created union operators.
82:             // The optimizer will merge subsequent binary unions into one n-ary union.
83:             if (!(dataSet instanceof UnionOperator)) {
84:                 // all other operators are reused.
85:                 @SuppressWarnings("unchecked")
86:                 Operator<T> typedPrevious = (Operator<T>) previous;
87:                 return typedPrevious;
88:             }
89:         }
90: 
91:         Operator<T> dataFlowOp;
92: 
93:         if (dataSet instanceof DataSource) {
94:             DataSource<T> dataSource = (DataSource<T>) dataSet;
95:             dataFlowOp = dataSource.translateToDataFlow();
96:             dataFlowOp.setResources(
97:                     dataSource.getMinResources(), dataSource.getPreferredResources());
98:         } else if (dataSet instanceof SingleInputOperator) {
99:             SingleInputOperator<?, ?, ?> singleInputOperator =
100:                     (SingleInputOperator<?, ?, ?>) dataSet;
101:             dataFlowOp = translateSingleInputOperator(singleInputOperator);
102:             dataFlowOp.setResources(
103:                     singleInputOperator.getMinResources(),
104:                     singleInputOperator.getPreferredResources());
105:         } else if (dataSet instanceof TwoInputOperator) {
106:             TwoInputOperator<?, ?, ?, ?> twoInputOperator = (TwoInputOperator<?, ?, ?, ?>) dataSet;
107:             dataFlowOp = translateTwoInputOperator(twoInputOperator);
108:             dataFlowOp.setResources(
109:                     twoInputOperator.getMinResources(), twoInputOperator.getPreferredResources());
110:         } else if (dataSet instanceof BulkIterationResultSet) {
111:             BulkIterationResultSet<?> bulkIterationResultSet = (BulkIterationResultSet<?>) dataSet;
112:             dataFlowOp = translateBulkIteration(bulkIterationResultSet);
113:             dataFlowOp.setResources(
114:                     bulkIterationResultSet.getIterationHead().getMinResources(),
115:                     bulkIterationResultSet.getIterationHead().getPreferredResources());
116:         } else if (dataSet instanceof DeltaIterationResultSet) {
117:             DeltaIterationResultSet<?, ?> deltaIterationResultSet =
118:                     (DeltaIterationResultSet<?, ?>) dataSet;
119:             dataFlowOp = translateDeltaIteration(deltaIterationResultSet);
120:             dataFlowOp.setResources(
121:                     deltaIterationResultSet.getIterationHead().getMinResources(),
122:                     deltaIterationResultSet.getIterationHead().getPreferredResources());
123:         } else if (dataSet instanceof DeltaIteration.SolutionSetPlaceHolder
124:                 || dataSet instanceof DeltaIteration.WorksetPlaceHolder) {
125:             throw new InvalidProgramException(
126:                     "A data set that is part of a delta iteration was used as a sink or action."
127:                             + " Did you forget to close the iteration?");
128:         } else {
129:             throw new RuntimeException(
130:                     "Error while creating the data flow plan for the program: Unknown operator or data set type: "
131:                             + dataSet);
132:         }
133: 
134:         this.translated.put(dataSet, dataFlowOp);
135: 
136:         // take care of broadcast variables
137:         translateBcVariables(dataSet, dataFlowOp);
138: 
139:         return dataFlowOp;
140:     }
