142:     private <I, O> org.apache.flink.api.common.operators.Operator<O> translateSingleInputOperator(
143:             SingleInputOperator<?, ?, ?> op) {
144: 
145:         @SuppressWarnings("unchecked")
146:         SingleInputOperator<I, O, ?> typedOp = (SingleInputOperator<I, O, ?>) op;
147: 
148:         @SuppressWarnings("unchecked")
149:         DataSet<I> typedInput = (DataSet<I>) op.getInput();
150: 
151:         Operator<I> input = translate(typedInput);
152: 
153:         org.apache.flink.api.common.operators.Operator<O> dataFlowOp =
154:                 typedOp.translateToDataFlow(input);
155: 
156:         if (op instanceof UdfOperator<?>) {
157:             @SuppressWarnings("unchecked")
158:             SingleInputUdfOperator<I, O, ?> udfOp = (SingleInputUdfOperator<I, O, ?>) op;
159: 
160:             // set configuration parameters
161:             Configuration opParams = udfOp.getParameters();
162:             if (opParams != null) {
163:                 dataFlowOp.getParameters().addAll(opParams);
164:             }
165: 
166:             if (dataFlowOp instanceof org.apache.flink.api.common.operators.SingleInputOperator) {
167:                 org.apache.flink.api.common.operators.SingleInputOperator<?, O, ?> unaryOp =
168:                         (org.apache.flink.api.common.operators.SingleInputOperator<?, O, ?>)
169:                                 dataFlowOp;
170:                 // set the semantic properties
171:                 unaryOp.setSemanticProperties(udfOp.getSemanticProperties());
172:             }
173:         }
174: 
175:         return dataFlowOp;
176:     }
