178:     private <I1, I2, O> org.apache.flink.api.common.operators.Operator<O> translateTwoInputOperator(
179:             TwoInputOperator<?, ?, ?, ?> op) {
180: 
181:         @SuppressWarnings("unchecked")
182:         TwoInputOperator<I1, I2, O, ?> typedOp = (TwoInputOperator<I1, I2, O, ?>) op;
183: 
184:         @SuppressWarnings("unchecked")
185:         DataSet<I1> typedInput1 = (DataSet<I1>) op.getInput1();
186:         @SuppressWarnings("unchecked")
187:         DataSet<I2> typedInput2 = (DataSet<I2>) op.getInput2();
188: 
189:         Operator<I1> input1 = translate(typedInput1);
190:         Operator<I2> input2 = translate(typedInput2);
191: 
192:         org.apache.flink.api.common.operators.Operator<O> dataFlowOp =
193:                 typedOp.translateToDataFlow(input1, input2);
194: 
195:         if (op instanceof UdfOperator<?>) {
196:             @SuppressWarnings("unchecked")
197:             TwoInputUdfOperator<I1, I2, O, ?> udfOp = (TwoInputUdfOperator<I1, I2, O, ?>) op;
198: 
199:             // set configuration parameters
200:             Configuration opParams = udfOp.getParameters();
201:             if (opParams != null) {
202:                 dataFlowOp.getParameters().addAll(opParams);
203:             }
204: 
205:             if (dataFlowOp instanceof org.apache.flink.api.common.operators.DualInputOperator) {
206:                 org.apache.flink.api.common.operators.DualInputOperator<?, ?, O, ?> binaryOp =
207:                         (org.apache.flink.api.common.operators.DualInputOperator<?, ?, O, ?>)
208:                                 dataFlowOp;
209:                 // set the semantic properties
210:                 binaryOp.setSemanticProperties(udfOp.getSemanticProperties());
211:             }
212:         }
213: 
214:         return dataFlowOp;
215:     }
