217:     private <T> BulkIterationBase<T> translateBulkIteration(
218:             BulkIterationResultSet<?> untypedIterationEnd) {
219:         @SuppressWarnings("unchecked")
220:         BulkIterationResultSet<T> iterationEnd = (BulkIterationResultSet<T>) untypedIterationEnd;
221:         IterativeDataSet<T> iterationHead = iterationEnd.getIterationHead();
222:         BulkIterationBase<T> iterationOperator =
223:                 new BulkIterationBase<>(
224:                         new UnaryOperatorInformation<>(
225:                                 iterationEnd.getType(), iterationEnd.getType()),
226:                         "Bulk Iteration");
227: 
228:         if (iterationHead.getParallelism() > 0) {
229:             iterationOperator.setParallelism(iterationHead.getParallelism());
230:         }
231: 
232:         translated.put(iterationHead, iterationOperator.getPartialSolution());
233: 
234:         Operator<T> translatedBody = translate(iterationEnd.getNextPartialSolution());
235:         iterationOperator.setNextPartialSolution(translatedBody);
236:         iterationOperator.setMaximumNumberOfIterations(iterationHead.getMaxIterations());
237:         iterationOperator.setInput(translate(iterationHead.getInput()));
238: 
239:         iterationOperator.getAggregators().addAll(iterationHead.getAggregators());
240: 
241:         if (iterationEnd.getTerminationCriterion() != null) {
242:             iterationOperator.setTerminationCriterion(
243:                     translate(iterationEnd.getTerminationCriterion()));
244:         }
245: 
246:         return iterationOperator;
247:     }
