249:     private <D, W> DeltaIterationBase<D, W> translateDeltaIteration(
250:             DeltaIterationResultSet<?, ?> untypedIterationEnd) {
251:         @SuppressWarnings("unchecked")
252:         DeltaIterationResultSet<D, W> iterationEnd =
253:                 (DeltaIterationResultSet<D, W>) untypedIterationEnd;
254:         DeltaIteration<D, W> iterationHead = iterationEnd.getIterationHead();
255: 
256:         String name =
257:                 iterationHead.getName() == null
258:                         ? "Unnamed Delta Iteration"
259:                         : iterationHead.getName();
260: 
261:         DeltaIterationBase<D, W> iterationOperator =
262:                 new DeltaIterationBase<>(
263:                         new BinaryOperatorInformation<>(
264:                                 iterationEnd.getType(),
265:                                 iterationEnd.getWorksetType(),
266:                                 iterationEnd.getType()),
267:                         iterationEnd.getKeyPositions(),
268:                         name);
269: 
270:         iterationOperator.setMaximumNumberOfIterations(iterationEnd.getMaxIterations());
271: 
272:         if (iterationHead.getParallelism() > 0) {
273:             iterationOperator.setParallelism(iterationHead.getParallelism());
274:         }
275: 
276:         DeltaIteration.SolutionSetPlaceHolder<D> solutionSetPlaceHolder =
277:                 iterationHead.getSolutionSet();
278:         DeltaIteration.WorksetPlaceHolder<W> worksetPlaceHolder = iterationHead.getWorkset();
279: 
280:         translated.put(solutionSetPlaceHolder, iterationOperator.getSolutionSet());
281:         translated.put(worksetPlaceHolder, iterationOperator.getWorkset());
