172:         this.defaultMaxFan = AlgorithmOptions.SPILLING_MAX_FAN.defaultValue();
173:         this.defaultSortSpillingThreshold = AlgorithmOptions.SORT_SPILLING_THRESHOLD.defaultValue();
174:         this.useLargeRecordHandler = USE_LARGE_RECORDS_HANDLER.defaultValue();
