183:     /**
184:      * Translates a {@link org.apache.flink.optimizer.plan.OptimizedPlan} into a {@link
185:      * org.apache.flink.runtime.jobgraph.JobGraph}.
186:      *
187:      * @param program Optimized plan that is translated into a JobGraph.
188:      * @return JobGraph generated from the plan.
189:      */
190:     public JobGraph compileJobGraph(OptimizedPlan program) {
191:         return compileJobGraph(program, null);
192:     }
193: 
194:     public JobGraph compileJobGraph(OptimizedPlan program, JobID jobId) {
195:         if (program == null) {
196:             throw new NullPointerException(
197:                     "Program is null, did you called " + "ExecutionEnvironment.execute()");
198:         }
199: 
200:         if (jobId == null) {
201:             jobId = JobID.generate();
202:         }
203: 
204:         this.vertices = new HashMap<PlanNode, JobVertex>();
205:         this.chainedTasks = new HashMap<PlanNode, TaskInChain>();
206:         this.chainedTasksInSequence = new ArrayList<TaskInChain>();
207:         this.auxVertices = new ArrayList<JobVertex>();
208:         this.iterations = new HashMap<IterationPlanNode, IterationDescriptor>();
209:         this.iterationStack = new ArrayList<IterationPlanNode>();
210: 
211:         this.sharingGroup = new SlotSharingGroup();
212: 
213:         ExecutionConfig executionConfig = program.getOriginalPlan().getExecutionConfig();
214:         Configuration jobConfiguration = program.getOriginalPlan().getJobConfiguration();
215: 
216:         // this starts the traversal that generates the job graph
217:         program.accept(this);
218: 
219:         // sanity check that we are not somehow in an iteration at the end
220:         if (this.currentIteration != null) {
221:             throw new CompilerException(
222:                     "The graph translation ended prematurely, leaving an unclosed iteration.");
223:         }
224: 
225:         // finalize the iterations
226:         for (IterationDescriptor iteration : this.iterations.values()) {
227:             if (iteration.getIterationNode() instanceof BulkIterationPlanNode) {
228:                 finalizeBulkIteration(iteration);
229:             } else if (iteration.getIterationNode() instanceof WorksetIterationPlanNode) {
230:                 finalizeWorksetIteration(iteration);
231:             } else {
232:                 throw new CompilerException();
233:             }
234:         }
235: 
236:         // now that the traversal is done, we have the chained tasks write their configs into their
237:         // parents' configurations
238:         for (TaskInChain tic : this.chainedTasksInSequence) {
239:             TaskConfig t = new TaskConfig(tic.getContainingVertex().getConfiguration());
240:             t.addChainedTask(tic.getChainedTask(), tic.getTaskConfig(), tic.getTaskName());
241:         }
242: 
243:         // ----- attach the additional info to the job vertices, for display in the runtime monitor
244: 
245:         attachOperatorNamesAndDescriptions();
246: 
247:         // ----------- finalize the job graph -----------
248: 
249:         for (JobVertex vertex : this.auxVertices) {
250:             vertex.setSlotSharingGroup(sharingGroup);
251:         }
252: 
253:         final Map<String, DistributedCache.DistributedCacheEntry> userArtifacts =
254:                 JobGraphUtils.prepareUserArtifactEntries(
255:                         program.getOriginalPlan().getCachedFiles().stream()
256:                                 .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue)),
257:                         jobId);
258: 
259:         // create the job graph object
260:         final JobGraph graph;
261:         try {
262:             graph =
263:                     JobGraphBuilder.newBatchJobGraphBuilder()
264:                             .setJobId(jobId)
265:                             .setJobName(program.getJobName())
266:                             .setExecutionConfig(executionConfig)
267:                             .setJobConfiguration(jobConfiguration)
268:                             .addJobVertices(vertices.values())
269:                             .addJobVertices(auxVertices)
270:                             .addUserArtifacts(userArtifacts)
271:                             .build();
272: 
273:             if (executionConfig.getSchedulerType().isPresent()
274:                     && executionConfig.getSchedulerType().get()
275:                             == JobManagerOptions.SchedulerType.AdaptiveBatch) {
276:                 graph.setDynamic(true);
277:             }
278: 
279:         } catch (IOException e) {
280:             throw new CompilerException(
281:                     "Could not serialize the ExecutionConfig."
282:                             + "This indicates that non-serializable types (like custom serializers) were registered");
283:         }
284: 
285:         // release all references again
286:         this.vertices = null;
287:         this.chainedTasks = null;
288:         this.chainedTasksInSequence = null;
289:         this.auxVertices = null;
290:         this.iterations = null;
291:         this.iterationStack = null;
292: 
293:         // return job graph
294:         return graph;
295:     }
296: 
297:     /**
298:      * This methods implements the pre-visiting during a depth-first traversal. It create the job
299:      * vertex and sets local strategy.
300:      *
301:      * @param node The node that is currently processed.
302:      * @return True, if the visitor should descend to the node's children, false if not.
303:      * @see org.apache.flink.util.Visitor#preVisit(org.apache.flink.util.Visitable)
304:      */
305:     @Override
306:     public boolean preVisit(PlanNode node) {
307:         // check if we have visited this node before. in non-tree graphs, this happens
308:         if (this.vertices.containsKey(node)
309:                 || this.chainedTasks.containsKey(node)
310:                 || this.iterations.containsKey(node)) {
311:             // return false to prevent further descend
312:             return false;
313:         }
314: 
315:         // the vertex to be created for the current node
316:         final JobVertex vertex;
317:         try {
318:             if (node instanceof SinkPlanNode) {
319:                 vertex = createDataSinkVertex((SinkPlanNode) node);
320:             } else if (node instanceof SourcePlanNode) {
321:                 vertex = createDataSourceVertex((SourcePlanNode) node);
322:             } else if (node instanceof BulkIterationPlanNode) {
323:                 BulkIterationPlanNode iterationNode = (BulkIterationPlanNode) node;
324:                 // for the bulk iteration, we skip creating anything for now. we create the graph
325:                 // for the step function in the post visit.
326: 
327:                 // check that the root of the step function has the same parallelism as the
328:                 // iteration.
329:                 // because the tail must have the same parallelism as the head, we can only merge
330:                 // the last
331:                 // operator with the tail, if they have the same parallelism. not merging is
332:                 // currently not
333:                 // implemented
334:                 PlanNode root = iterationNode.getRootOfStepFunction();
335:                 if (root.getParallelism() != node.getParallelism()) {
336:                     throw new CompilerException(
337:                             "Error: The final operator of the step "
338:                                     + "function has a different parallelism than the iteration operator itself.");
339:                 }
340: 
341:                 IterationDescriptor descr =
342:                         new IterationDescriptor(iterationNode, this.iterationIdEnumerator++);
343:                 this.iterations.put(iterationNode, descr);
344:                 vertex = null;
345:             } else if (node instanceof WorksetIterationPlanNode) {
346:                 WorksetIterationPlanNode iterationNode = (WorksetIterationPlanNode) node;
347: 
348:                 // we have the same constraints as for the bulk iteration
349:                 PlanNode nextWorkSet = iterationNode.getNextWorkSetPlanNode();
350:                 PlanNode solutionSetDelta = iterationNode.getSolutionSetDeltaPlanNode();
351: 
352:                 if (nextWorkSet.getParallelism() != node.getParallelism()) {
353:                     throw new CompilerException(
354:                             "It is currently not supported that the final operator of the step "
355:                                     + "function has a different parallelism than the iteration operator itself.");
356:                 }
357:                 if (solutionSetDelta.getParallelism() != node.getParallelism()) {
358:                     throw new CompilerException(
359:                             "It is currently not supported that the final operator of the step "
360:                                     + "function has a different parallelism than the iteration operator itself.");
361:                 }
362: 
363:                 IterationDescriptor descr =
364:                         new IterationDescriptor(iterationNode, this.iterationIdEnumerator++);
365:                 this.iterations.put(iterationNode, descr);
366:                 vertex = null;
367:             } else if (node instanceof SingleInputPlanNode) {
368:                 vertex = createSingleInputVertex((SingleInputPlanNode) node);
369:             } else if (node instanceof DualInputPlanNode) {
370:                 vertex = createDualInputVertex((DualInputPlanNode) node);
371:             } else if (node instanceof NAryUnionPlanNode) {
372:                 // skip the union for now
373:                 vertex = null;
374:             } else if (node instanceof BulkPartialSolutionPlanNode) {
375:                 // create a head node (or not, if it is merged into its successor)
376:                 vertex = createBulkIterationHead((BulkPartialSolutionPlanNode) node);
377:             } else if (node instanceof SolutionSetPlanNode) {
378:                 // this represents an access into the solution set index.
379:                 // we do not create a vertex for the solution set here (we create the head at the
380:                 // workset place holder)
381: 
382:                 // we adjust the joins / cogroups that go into the solution set here
383:                 for (Channel c : node.getOutgoingChannels()) {
384:                     DualInputPlanNode target = (DualInputPlanNode) c.getTarget();
385:                     JobVertex accessingVertex = this.vertices.get(target);
386:                     TaskConfig conf = new TaskConfig(accessingVertex.getConfiguration());
387:                     int inputNum = c == target.getInput1() ? 0 : c == target.getInput2() ? 1 : -1;
388: 
389:                     // sanity checks
390:                     if (inputNum == -1) {
391:                         throw new CompilerException();
392:                     }
393: 
394:                     // adjust the driver
395:                     if (conf.getDriver().equals(JoinDriver.class)) {
396:                         conf.setDriver(
397:                                 inputNum == 0
398:                                         ? JoinWithSolutionSetFirstDriver.class
399:                                         : JoinWithSolutionSetSecondDriver.class);
400:                     } else if (conf.getDriver().equals(CoGroupDriver.class)) {
401:                         conf.setDriver(
402:                                 inputNum == 0
403:                                         ? CoGroupWithSolutionSetFirstDriver.class
404:                                         : CoGroupWithSolutionSetSecondDriver.class);
405:                     } else {
406:                         throw new CompilerException(
407:                                 "Found join with solution set using incompatible operator (only Join/CoGroup are valid).");
408:                     }
409:                 }
410: 
411:                 // make sure we do not visit this node again. for that, we add a 'already seen'
412:                 // entry into one of the sets
413:                 this.chainedTasks.put(node, ALREADY_VISITED_PLACEHOLDER);
414: 
415:                 vertex = null;
416:             } else if (node instanceof WorksetPlanNode) {
417:                 // create the iteration head here
418:                 vertex = createWorksetIterationHead((WorksetPlanNode) node);
419:             } else {
420:                 throw new CompilerException("Unrecognized node type: " + node.getClass().getName());
421:             }
422:         } catch (Exception e) {
423:             throw new CompilerException(
424:                     "Error translating node '" + node + "': " + e.getMessage(), e);
425:         }
426: 
427:         // check if a vertex was created, or if it was chained or skipped
428:         if (vertex != null) {
429:             // set parallelism
430:             int pd = node.getParallelism();
431:             vertex.setParallelism(pd);
432:             vertex.setMaxParallelism(pd);
433: 
434:             vertex.setSlotSharingGroup(sharingGroup);
435: 
436:             // check whether this vertex is part of an iteration step function
437:             if (this.currentIteration != null) {
438:                 // check that the task has the same parallelism as the iteration as such
439:                 PlanNode iterationNode = (PlanNode) this.currentIteration;
440:                 if (iterationNode.getParallelism() < pd) {
441:                     throw new CompilerException(
442:                             "Error: All functions that are part of an iteration must have the same, or a lower, parallelism than the iteration operator.");
443:                 }
444: 
445:                 // store the id of the iterations the step functions participate in
446:                 IterationDescriptor descr = this.iterations.get(this.currentIteration);
447:                 new TaskConfig(vertex.getConfiguration()).setIterationId(descr.getId());
448:             }
449: 
450:             // store in the map
451:             this.vertices.put(node, vertex);
452:         }
453: 
454:         // returning true causes deeper descend
455:         return true;
456:     }
457: 
458:     /**
459:      * This method implements the post-visit during the depth-first traversal. When the post visit
460:      * happens, all of the descendants have been processed, so this method connects all of the
461:      * current node's predecessors to the current node.
462:      *
463:      * @param node The node currently processed during the post-visit.
464:      * @see org.apache.flink.util.Visitor#postVisit(org.apache.flink.util.Visitable) t
465:      */
466:     @Override
467:     public void postVisit(PlanNode node) {
468:         try {
469:             // --------- check special cases for which we handle post visit differently ----------
470: 
471:             // skip data source node (they have no inputs)
472:             // also, do nothing for union nodes, we connect them later when gathering the inputs for
473:             // a task
474:             // solution sets have no input. the initial solution set input is connected when the
475:             // iteration node is in its postVisit
476:             if (node instanceof SourcePlanNode
477:                     || node instanceof NAryUnionPlanNode
478:                     || node instanceof SolutionSetPlanNode) {
479:                 return;
480:             }
481: 
482:             // if this is a blocking shuffle vertex, we add one IntermediateDataSetID to its
483:             // predecessor and return
484:             if (checkAndConfigurePersistentIntermediateResult(node)) {
485:                 return;
486:             }
487: 
488:             // check if we have an iteration. in that case, translate the step function now
489:             if (node instanceof IterationPlanNode) {
490:                 // prevent nested iterations
491:                 if (node.isOnDynamicPath()) {
492:                     throw new CompilerException(
493:                             "Nested Iterations are not possible at the moment!");
494:                 }
495: 
496:                 // if we recursively go into an iteration (because the constant path of one
497:                 // iteration contains
498:                 // another one), we push the current one onto the stack
499:                 if (this.currentIteration != null) {
500:                     this.iterationStack.add(this.currentIteration);
501:                 }
502: 
503:                 this.currentIteration = (IterationPlanNode) node;
504:                 this.currentIteration.acceptForStepFunction(this);
505: 
506:                 // pop the current iteration from the stack
507:                 if (this.iterationStack.isEmpty()) {
508:                     this.currentIteration = null;
509:                 } else {
510:                     this.currentIteration =
511:                             this.iterationStack.remove(this.iterationStack.size() - 1);
512:                 }
513: 
514:                 // inputs for initial bulk partial solution or initial workset are already connected
515:                 // to the iteration head in the head's post visit.
516:                 // connect the initial solution set now.
517:                 if (node instanceof WorksetIterationPlanNode) {
518:                     // connect the initial solution set
519:                     WorksetIterationPlanNode wsNode = (WorksetIterationPlanNode) node;
520:                     JobVertex headVertex = this.iterations.get(wsNode).getHeadTask();
521:                     TaskConfig headConfig = new TaskConfig(headVertex.getConfiguration());
522:                     int inputIndex = headConfig.getDriverStrategy().getNumInputs();
523:                     headConfig.setIterationHeadSolutionSetInputIndex(inputIndex);
524:                     translateChannel(
525:                             wsNode.getInitialSolutionSetInput(),
526:                             inputIndex,
527:                             headVertex,
528:                             headConfig,
529:                             false);
530:                 }
531: 
532:                 return;
533:             }
534: 
535:             final JobVertex targetVertex = this.vertices.get(node);
536: 
537:             // --------- Main Path: Translation of channels ----------
538:             //
539:             // There are two paths of translation: One for chained tasks (or merged tasks in
540:             // general),
541:             // which do not have their own task vertex. The other for tasks that have their own
542:             // vertex,
543:             // or are the primary task in a vertex (to which the others are chained).
544: 
545:             // check whether this node has its own task, or is merged with another one
546:             if (targetVertex == null) {
547:                 // node's task is merged with another task. it is either chained, of a merged head
548:                 // vertex
549:                 // from an iteration
550:                 final TaskInChain chainedTask;
551:                 if ((chainedTask = this.chainedTasks.get(node)) != null) {
552:                     // Chained Task. Sanity check first...
553:                     final Iterator<Channel> inConns = node.getInputs().iterator();
554:                     if (!inConns.hasNext()) {
555:                         throw new CompilerException("Bug: Found chained task with no input.");
556:                     }
557:                     final Channel inConn = inConns.next();
558: 
559:                     if (inConns.hasNext()) {
560:                         throw new CompilerException(
561:                                 "Bug: Found a chained task with more than one input!");
562:                     }
563:                     if (inConn.getLocalStrategy() != null
564:                             && inConn.getLocalStrategy() != LocalStrategy.NONE) {
565:                         throw new CompilerException(
566:                                 "Bug: Found a chained task with an input local strategy.");
567:                     }
568:                     if (inConn.getShipStrategy() != null
569:                             && inConn.getShipStrategy() != ShipStrategyType.FORWARD) {
570:                         throw new CompilerException(
571:                                 "Bug: Found a chained task with an input ship strategy other than FORWARD.");
572:                     }
573: 
574:                     JobVertex container = chainedTask.getContainingVertex();
575: 
576:                     if (container == null) {
577:                         final PlanNode sourceNode = inConn.getSource();
578:                         container = this.vertices.get(sourceNode);
579:                         if (container == null) {
580:                             // predecessor is itself chained
581:                             container = this.chainedTasks.get(sourceNode).getContainingVertex();
582:                             if (container == null) {
583:                                 throw new IllegalStateException(
584:                                         "Bug: Chained task predecessor has not been assigned its containing vertex.");
585:                             }
586:                         } else {
587:                             // predecessor is a proper task job vertex and this is the first chained
588:                             // task. add a forward connection entry.
589:                             new TaskConfig(container.getConfiguration())
590:                                     .addOutputShipStrategy(ShipStrategyType.FORWARD);
591:                         }
592:                         chainedTask.setContainingVertex(container);
593:                     }
594: 
595:                     // add info about the input serializer type
596:                     chainedTask.getTaskConfig().setInputSerializer(inConn.getSerializer(), 0);
597: 
598:                     // update name of container task
599:                     String containerTaskName = container.getName();
600:                     if (containerTaskName.startsWith("CHAIN ")) {
601:                         container.setName(containerTaskName + " -> " + chainedTask.getTaskName());
602:                     } else {
603:                         container.setName(
604:                                 "CHAIN " + containerTaskName + " -> " + chainedTask.getTaskName());
605:                     }
606: 
607:                     // update resource of container task
608:                     container.setResources(
609:                             container.getMinResources().merge(node.getMinResources()),
610:                             container.getPreferredResources().merge(node.getPreferredResources()));
611: 
612:                     this.chainedTasksInSequence.add(chainedTask);
613:                     return;
614:                 } else if (node instanceof BulkPartialSolutionPlanNode
615:                         || node instanceof WorksetPlanNode) {
616:                     // merged iteration head task. the task that the head is merged with will take
617:                     // care of it
618:                     return;
619:                 } else {
620:                     throw new CompilerException("Bug: Unrecognized merged task vertex.");
621:                 }
622:             }
623: 
624:             // -------- Here, we translate non-chained tasks -------------
625: 
626:             if (this.currentIteration != null) {
627:                 JobVertex head = this.iterations.get(this.currentIteration).getHeadTask();
628:                 // Exclude static code paths from the co-location constraint, because otherwise
629:                 // their execution determines the deployment slots of the co-location group
630:                 if (node.isOnDynamicPath()) {
631:                     targetVertex.setStrictlyCoLocatedWith(head);
632:                 }
633:             }
634: 
635:             // create the config that will contain all the description of the inputs
636:             final TaskConfig targetVertexConfig = new TaskConfig(targetVertex.getConfiguration());
637: 
638:             // get the inputs. if this node is the head of an iteration, we obtain the inputs from
639:             // the
640:             // enclosing iteration node, because the inputs are the initial inputs to the iteration.
641:             final Iterator<Channel> inConns;
642:             if (node instanceof BulkPartialSolutionPlanNode) {
643:                 inConns =
644:                         ((BulkPartialSolutionPlanNode) node)
645:                                 .getContainingIterationNode()
646:                                 .getInputs()
647:                                 .iterator();
648:                 // because the partial solution has its own vertex, is has only one (logical) input.
649:                 // note this in the task configuration
650:                 targetVertexConfig.setIterationHeadPartialSolutionOrWorksetInputIndex(0);
651:             } else if (node instanceof WorksetPlanNode) {
652:                 WorksetPlanNode wspn = (WorksetPlanNode) node;
653:                 // input that is the initial workset
654:                 inConns =
655:                         Collections.singleton(wspn.getContainingIterationNode().getInput2())
656:                                 .iterator();
657: 
658:                 // because we have a stand-alone (non-merged) workset iteration head, the initial
659:                 // workset will
660:                 // be input 0 and the solution set will be input 1
661:                 targetVertexConfig.setIterationHeadPartialSolutionOrWorksetInputIndex(0);
662:                 targetVertexConfig.setIterationHeadSolutionSetInputIndex(1);
663:             } else {
664:                 inConns = node.getInputs().iterator();
665:             }
666:             if (!inConns.hasNext()) {
667:                 throw new CompilerException("Bug: Found a non-source task with no input.");
668:             }
669: 
670:             int inputIndex = 0;
671:             while (inConns.hasNext()) {
672:                 Channel input = inConns.next();
673:                 inputIndex +=
674:                         translateChannel(
675:                                 input, inputIndex, targetVertex, targetVertexConfig, false);
676:             }
677:             // broadcast variables
678:             int broadcastInputIndex = 0;
679:             for (NamedChannel broadcastInput : node.getBroadcastInputs()) {
680:                 int broadcastInputIndexDelta =
681:                         translateChannel(
682:                                 broadcastInput,
683:                                 broadcastInputIndex,
684:                                 targetVertex,
685:                                 targetVertexConfig,
686:                                 true);
687:                 targetVertexConfig.setBroadcastInputName(
688:                         broadcastInput.getName(), broadcastInputIndex);
689:                 targetVertexConfig.setBroadcastInputSerializer(
690:                         broadcastInput.getSerializer(), broadcastInputIndex);
691:                 broadcastInputIndex += broadcastInputIndexDelta;
692:             }
693:         } catch (Exception e) {
694:             throw new CompilerException(
695:                     "An error occurred while translating the optimized plan to a JobGraph: "
696:                             + e.getMessage(),
697:                     e);
698:         }
699:     }
700: 
701:     private int translateChannel(
702:             Channel input,
703:             int inputIndex,
704:             JobVertex targetVertex,
705:             TaskConfig targetVertexConfig,
706:             boolean isBroadcast)
707:             throws Exception {
708:         final PlanNode inputPlanNode = input.getSource();
709:         final Iterator<Channel> allInChannels;
710: 
711:         if (inputPlanNode instanceof NAryUnionPlanNode) {
712:             allInChannels = ((NAryUnionPlanNode) inputPlanNode).getListOfInputs().iterator();
713: 
714:             // If the union node has a batch data exchange, we have to adopt the exchange mode of
715:             // the inputs of the union as well, because the optimizer has a separate union
716:             // node, which does not exist in the JobGraph. Otherwise, this can result in
717:             // deadlocks when closing a branching flow at runtime.
718:             for (Channel in : inputPlanNode.getInputs()) {
719:                 if (input.getDataExchangeMode().equals(DataExchangeMode.BATCH)) {
720:                     in.setDataExchangeMode(DataExchangeMode.BATCH);
721:                 }
722:                 if (isBroadcast) {
723:                     in.setShipStrategy(ShipStrategyType.BROADCAST, in.getDataExchangeMode());
724:                 }
725:             }
726: 
727:             // The outgoing connection of an NAryUnion must be a forward connection.
728:             if (input.getShipStrategy() != ShipStrategyType.FORWARD && !isBroadcast) {
729:                 throw new CompilerException(
730:                         "Optimized plan contains Union with non-forward outgoing ship strategy.");
731:             }
732: 
733:         } else if (inputPlanNode instanceof BulkPartialSolutionPlanNode) {
734:             if (this.vertices.get(inputPlanNode) == null) {
735:                 // merged iteration head
736:                 final BulkPartialSolutionPlanNode pspn =
737:                         (BulkPartialSolutionPlanNode) inputPlanNode;
738:                 final BulkIterationPlanNode iterationNode = pspn.getContainingIterationNode();
739: 
740:                 // check if the iteration's input is a union
741:                 if (iterationNode.getInput().getSource() instanceof NAryUnionPlanNode) {
742:                     allInChannels = (iterationNode.getInput().getSource()).getInputs().iterator();
743:                 } else {
744:                     allInChannels = Collections.singletonList(iterationNode.getInput()).iterator();
745:                 }
746: 
747:                 // also, set the index of the gate with the partial solution
748:                 targetVertexConfig.setIterationHeadPartialSolutionOrWorksetInputIndex(inputIndex);
749:             } else {
750:                 // standalone iteration head
751:                 allInChannels = Collections.singletonList(input).iterator();
752:             }
753:         } else if (inputPlanNode instanceof WorksetPlanNode) {
754:             if (this.vertices.get(inputPlanNode) == null) {
755:                 // merged iteration head
756:                 final WorksetPlanNode wspn = (WorksetPlanNode) inputPlanNode;
757:                 final WorksetIterationPlanNode iterationNode = wspn.getContainingIterationNode();
758: 
759:                 // check if the iteration's input is a union
760:                 if (iterationNode.getInput2().getSource() instanceof NAryUnionPlanNode) {
761:                     allInChannels = (iterationNode.getInput2().getSource()).getInputs().iterator();
762:                 } else {
763:                     allInChannels = Collections.singletonList(iterationNode.getInput2()).iterator();
764:                 }
765: 
766:                 // also, set the index of the gate with the partial solution
767:                 targetVertexConfig.setIterationHeadPartialSolutionOrWorksetInputIndex(inputIndex);
768:             } else {
769:                 // standalone iteration head
770:                 allInChannels = Collections.singletonList(input).iterator();
771:             }
772:         } else if (inputPlanNode instanceof SolutionSetPlanNode) {
773:             // for now, skip connections with the solution set node, as this is a local index access
774:             // (later to be parameterized here)
775:             // rather than a vertex connection
776:             return 0;
777:         } else {
778:             allInChannels = Collections.singletonList(input).iterator();
779:         }
780: 
781:         // check that the type serializer is consistent
782:         TypeSerializerFactory<?> typeSerFact = null;
783: 
784:         // accounting for channels on the dynamic path
785:         int numChannelsTotal = 0;
786:         int numChannelsDynamicPath = 0;
787:         int numDynamicSenderTasksTotal = 0;
788: 
789:         // expand the channel to all the union channels, in case there is a union operator at its
790:         // source
791:         while (allInChannels.hasNext()) {
792:             final Channel inConn = allInChannels.next();
793: 
794:             // sanity check the common serializer
795:             if (typeSerFact == null) {
796:                 typeSerFact = inConn.getSerializer();
797:             } else if (!typeSerFact.equals(inConn.getSerializer())) {
798:                 throw new CompilerException("Conflicting types in union operator.");
799:             }
800: 
801:             final PlanNode sourceNode = inConn.getSource();
802:             JobVertex sourceVertex = this.vertices.get(sourceNode);
803:             TaskConfig sourceVertexConfig;
804: 
805:             if (sourceVertex == null) {
806:                 // this predecessor is chained to another task or an iteration
807:                 final TaskInChain chainedTask;
808:                 final IterationDescriptor iteration;
809:                 if ((chainedTask = this.chainedTasks.get(sourceNode)) != null) {
810:                     // push chained task
811:                     if (chainedTask.getContainingVertex() == null) {
812:                         throw new IllegalStateException(
813:                                 "Bug: Chained task has not been assigned its containing vertex when connecting.");
814:                     }
815:                     sourceVertex = chainedTask.getContainingVertex();
816:                     sourceVertexConfig = chainedTask.getTaskConfig();
817:                 } else if ((iteration = this.iterations.get(sourceNode)) != null) {
818:                     // predecessor is an iteration
819:                     sourceVertex = iteration.getHeadTask();
820:                     sourceVertexConfig = iteration.getHeadFinalResultConfig();
821:                 } else {
822:                     throw new CompilerException(
823:                             "Bug: Could not resolve source node for a channel.");
824:                 }
825:             } else {
826:                 // predecessor is its own vertex
827:                 sourceVertexConfig = new TaskConfig(sourceVertex.getConfiguration());
828:             }
829:             DistributionPattern pattern =
830:                     connectJobVertices(
831:                             inConn,
832:                             inputIndex,
833:                             sourceVertex,
834:                             sourceVertexConfig,
835:                             targetVertex,
836:                             targetVertexConfig,
837:                             isBroadcast);
838: 
839:             // accounting on channels and senders
840:             numChannelsTotal++;
841:             if (inConn.isOnDynamicPath()) {
842:                 numChannelsDynamicPath++;
843:                 numDynamicSenderTasksTotal +=
844:                         getNumberOfSendersPerReceiver(
845:                                 pattern,
846:                                 sourceVertex.getParallelism(),
847:                                 targetVertex.getParallelism());
848:             }
849:         }
850: 
851:         // for the iterations, check that the number of dynamic channels is the same as the number
852:         // of channels for this logical input. this condition is violated at the moment, if there
853:         // is a union between nodes on the static and nodes on the dynamic path
854:         if (numChannelsDynamicPath > 0 && numChannelsTotal != numChannelsDynamicPath) {
855:             throw new CompilerException(
856:                     "Error: It is currently not supported to union between dynamic and static path in an iteration.");
857:         }
858:         if (numDynamicSenderTasksTotal > 0) {
859:             if (isBroadcast) {
860:                 targetVertexConfig.setBroadcastGateIterativeWithNumberOfEventsUntilInterrupt(
861:                         inputIndex, numDynamicSenderTasksTotal);
862:             } else {
863:                 targetVertexConfig.setGateIterativeWithNumberOfEventsUntilInterrupt(
864:                         inputIndex, numDynamicSenderTasksTotal);
865:             }
866:         }
867: 
868:         // the local strategy is added only once. in non-union case that is the actual edge,
869:         // in the union case, it is the edge between union and the target node
870:         addLocalInfoFromChannelToConfig(input, targetVertexConfig, inputIndex, isBroadcast);
871:         return 1;
872:     }
873: 
874:     private int getNumberOfSendersPerReceiver(
875:             DistributionPattern pattern, int numSenders, int numReceivers) {
876:         if (pattern == DistributionPattern.ALL_TO_ALL) {
877:             return numSenders;
878:         } else if (pattern == DistributionPattern.POINTWISE) {
879:             if (numSenders != numReceivers) {
880:                 if (numReceivers == 1) {
881:                     return numSenders;
882:                 } else if (numSenders == 1) {
883:                     return 1;
884:                 } else {
885:                     throw new CompilerException(
886:                             "Error: A changing parallelism is currently "
887:                                     + "not supported between tasks within an iteration.");
888:                 }
889:             } else {
890:                 return 1;
891:             }
892:         } else {
893:             throw new CompilerException("Unknown distribution pattern for channels: " + pattern);
894:         }
895:     }
