901:     private JobVertex createSingleInputVertex(SingleInputPlanNode node) throws CompilerException {
902:         final String taskName = node.getNodeName();
903:         final DriverStrategy ds = node.getDriverStrategy();
904: 
905:         // check, whether chaining is possible
906:         boolean chaining;
907:         {
908:             Channel inConn = node.getInput();
909:             PlanNode pred = inConn.getSource();
910:             chaining =
911:                     ds.getPushChainDriverClass() != null
912:                             && !(pred instanceof NAryUnionPlanNode)
913:                             && // first op after union is stand-alone, because union is merged
914:                             !(pred instanceof BulkPartialSolutionPlanNode)
915:                             && // partial solution merges anyways
916:                             !(pred instanceof WorksetPlanNode)
917:                             && // workset merges anyways
918:                             !(pred instanceof IterationPlanNode)
919:                             && // cannot chain with iteration heads currently
920:                             inConn.getShipStrategy() == ShipStrategyType.FORWARD
921:                             && inConn.getLocalStrategy() == LocalStrategy.NONE
922:                             && pred.getOutgoingChannels().size() == 1
923:                             && node.getParallelism() == pred.getParallelism()
924:                             && node.getBroadcastInputs().isEmpty();
925: 
926:             // cannot chain the nodes that produce the next workset or the next solution set, if
927:             // they are not the
928:             // in a tail
929:             if (this.currentIteration instanceof WorksetIterationPlanNode
930:                     && node.getOutgoingChannels().size() > 0) {
931:                 WorksetIterationPlanNode wspn = (WorksetIterationPlanNode) this.currentIteration;
932:                 if (wspn.getSolutionSetDeltaPlanNode() == pred
933:                         || wspn.getNextWorkSetPlanNode() == pred) {
934:                     chaining = false;
935:                 }
936:             }
937:             // cannot chain the nodes that produce the next workset in a bulk iteration if a
938:             // termination criterion follows
939:             if (this.currentIteration instanceof BulkIterationPlanNode) {
940:                 BulkIterationPlanNode wspn = (BulkIterationPlanNode) this.currentIteration;
941:                 if (node == wspn.getRootOfTerminationCriterion()
942:                         && wspn.getRootOfStepFunction() == pred) {
943:                     chaining = false;
944:                 } else if (node.getOutgoingChannels().size() > 0
945:                         && (wspn.getRootOfStepFunction() == pred
946:                                 || wspn.getRootOfTerminationCriterion() == pred)) {
947:                     chaining = false;
948:                 }
949:             }
950:         }
951: 
952:         final JobVertex vertex;
953:         final TaskConfig config;
954: 
955:         if (chaining) {
956:             vertex = null;
957:             config = new TaskConfig(new Configuration());
958:             this.chainedTasks.put(
959:                     node, new TaskInChain(node, ds.getPushChainDriverClass(), config, taskName));
960:         } else {
961:             // create task vertex
962:             vertex = new JobVertex(taskName);
963:             vertex.setResources(node.getMinResources(), node.getPreferredResources());
964:             vertex.setInvokableClass(
965:                     (this.currentIteration != null && node.isOnDynamicPath())
966:                             ? IterationIntermediateTask.class
967:                             : BatchTask.class);
968: 
969:             config = new TaskConfig(vertex.getConfiguration());
970:             config.setDriver(ds.getDriverClass());
971:         }
972: 
973:         // set user code
974:         config.setStubWrapper(node.getProgramOperator().getUserCodeWrapper());
975:         config.setStubParameters(node.getProgramOperator().getParameters());
976: 
977:         // set the driver strategy
978:         config.setDriverStrategy(ds);
979:         for (int i = 0; i < ds.getNumRequiredComparators(); i++) {
980:             config.setDriverComparator(node.getComparator(i), i);
981:         }
982:         // assign memory, file-handles, etc.
983:         assignDriverResources(node, config);
984:         return vertex;
985:     }
