1069:     private JobVertex createBulkIterationHead(BulkPartialSolutionPlanNode pspn) {
1070:         // get the bulk iteration that corresponds to this partial solution node
1071:         final BulkIterationPlanNode iteration = pspn.getContainingIterationNode();
1072: 
1073:         // check whether we need an individual vertex for the partial solution, or whether we
1074:         // attach ourselves to the vertex of the parent node. We can combine the head with a node of
1075:         // the step function, if
1076:         // 1) There is one parent that the partial solution connects to via a forward pattern and no
1077:         //    local strategy
1078:         // 2) parallelism and the number of subtasks per instance does not change
1079:         // 3) That successor is not a union
1080:         // 4) That successor is not itself the last node of the step function
1081:         // 5) There is no local strategy on the edge for the initial partial solution, as
1082:         //    this translates to a local strategy that would only be executed in the first iteration
1083: 
1084:         final boolean merge;
1085:         if (mergeIterationAuxTasks && pspn.getOutgoingChannels().size() == 1) {
1086:             final Channel c = pspn.getOutgoingChannels().get(0);
1087:             final PlanNode successor = c.getTarget();
1088:             merge =
1089:                     c.getShipStrategy() == ShipStrategyType.FORWARD
1090:                             && c.getLocalStrategy() == LocalStrategy.NONE
1091:                             && c.getTempMode() == TempMode.NONE
1092:                             && successor.getParallelism() == pspn.getParallelism()
1093:                             && !(successor instanceof NAryUnionPlanNode)
1094:                             && successor != iteration.getRootOfStepFunction()
1095:                             && iteration.getInput().getLocalStrategy() == LocalStrategy.NONE;
1096:         } else {
1097:             merge = false;
1098:         }
1099: 
1100:         // create or adopt the head vertex
1101:         final JobVertex toReturn;
1102:         final JobVertex headVertex;
1103:         final TaskConfig headConfig;
1104:         if (merge) {
1105:             final PlanNode successor = pspn.getOutgoingChannels().get(0).getTarget();
1106:             headVertex = this.vertices.get(successor);
1107: 
1108:             if (headVertex == null) {
1109:                 throw new CompilerException(
1110:                         "Bug: Trying to merge solution set with its successor, but successor has not been created.");
1111:             }
1112: 
1113:             // reset the vertex type to iteration head
1114:             headVertex.setInvokableClass(IterationHeadTask.class);
1115:             headConfig = new TaskConfig(headVertex.getConfiguration());
1116:             toReturn = null;
1117:         } else {
1118:             // instantiate the head vertex and give it a no-op driver as the driver strategy.
1119:             // everything else happens in the post visit, after the input (the initial partial
1120:             // solution)
1121:             // is connected.
1122:             headVertex = new JobVertex("PartialSolution (" + iteration.getNodeName() + ")");
1123:             headVertex.setResources(iteration.getMinResources(), iteration.getPreferredResources());
1124:             headVertex.setInvokableClass(IterationHeadTask.class);
1125:             headConfig = new TaskConfig(headVertex.getConfiguration());
1126:             headConfig.setDriver(NoOpDriver.class);
1127:             toReturn = headVertex;
1128:         }
1129: 
1130:         // create the iteration descriptor and the iteration to it
1131:         IterationDescriptor descr = this.iterations.get(iteration);
1132:         if (descr == null) {
1133:             throw new CompilerException(
1134:                     "Bug: Iteration descriptor was not created at when translating the iteration node.");
1135:         }
1136:         descr.setHeadTask(headVertex, headConfig);
1137: 
1138:         return toReturn;
1139:     }
