1141:     private JobVertex createWorksetIterationHead(WorksetPlanNode wspn) {
1142:         // get the bulk iteration that corresponds to this partial solution node
1143:         final WorksetIterationPlanNode iteration = wspn.getContainingIterationNode();
1144: 
1145:         // check whether we need an individual vertex for the partial solution, or whether we
1146:         // attach ourselves to the vertex of the parent node. We can combine the head with a node of
1147:         // the step function, if
1148:         // 1) There is one parent that the partial solution connects to via a forward pattern and no
1149:         //    local strategy
1150:         // 2) parallelism and the number of subtasks per instance does not change
1151:         // 3) That successor is not a union
1152:         // 4) That successor is not itself the last node of the step function
1153:         // 5) There is no local strategy on the edge for the initial workset, as
1154:         //    this translates to a local strategy that would only be executed in the first superstep
1155: 
1156:         final boolean merge;
1157:         if (mergeIterationAuxTasks && wspn.getOutgoingChannels().size() == 1) {
1158:             final Channel c = wspn.getOutgoingChannels().get(0);
1159:             final PlanNode successor = c.getTarget();
1160:             merge =
1161:                     c.getShipStrategy() == ShipStrategyType.FORWARD
1162:                             && c.getLocalStrategy() == LocalStrategy.NONE
1163:                             && c.getTempMode() == TempMode.NONE
1164:                             && successor.getParallelism() == wspn.getParallelism()
1165:                             && !(successor instanceof NAryUnionPlanNode)
1166:                             && successor != iteration.getNextWorkSetPlanNode()
1167:                             && iteration.getInitialWorksetInput().getLocalStrategy()
1168:                                     == LocalStrategy.NONE;
1169:         } else {
1170:             merge = false;
1171:         }
1172: 
1173:         // create or adopt the head vertex
1174:         final JobVertex toReturn;
1175:         final JobVertex headVertex;
1176:         final TaskConfig headConfig;
1177:         if (merge) {
1178:             final PlanNode successor = wspn.getOutgoingChannels().get(0).getTarget();
1179:             headVertex = this.vertices.get(successor);
1180: 
1181:             if (headVertex == null) {
1182:                 throw new CompilerException(
1183:                         "Bug: Trying to merge solution set with its sucessor, but successor has not been created.");
1184:             }
1185: 
1186:             // reset the vertex type to iteration head
1187:             headVertex.setInvokableClass(IterationHeadTask.class);
1188:             headConfig = new TaskConfig(headVertex.getConfiguration());
1189:             toReturn = null;
1190:         } else {
1191:             // instantiate the head vertex and give it a no-op driver as the driver strategy.
1192:             // everything else happens in the post visit, after the input (the initial partial
1193:             // solution)
1194:             // is connected.
1195:             headVertex = new JobVertex("IterationHead(" + iteration.getNodeName() + ")");
1196:             headVertex.setResources(iteration.getMinResources(), iteration.getPreferredResources());
1197:             headVertex.setInvokableClass(IterationHeadTask.class);
1198:             headConfig = new TaskConfig(headVertex.getConfiguration());
1199:             headConfig.setDriver(NoOpDriver.class);
1200:             toReturn = headVertex;
1201:         }
1202: 
1203:         headConfig.setSolutionSetUnmanaged(
1204:                 iteration.getIterationNode().getIterationContract().isSolutionSetUnManaged());
1205: 
1206:         // create the iteration descriptor and the iteration to it
1207:         IterationDescriptor descr = this.iterations.get(iteration);
1208:         if (descr == null) {
1209:             throw new CompilerException(
1210:                     "Bug: Iteration descriptor was not created at when translating the iteration node.");
1211:         }
1212:         descr.setHeadTask(headVertex, headConfig);
1213: 
1214:         return toReturn;
1215:     }
