1235:     private boolean checkAndConfigurePersistentIntermediateResult(PlanNode node) {
1236:         if (!(node instanceof SinkPlanNode)) {
1237:             return false;
1238:         }
1239: 
1240:         final Object userCodeObject =
1241:                 node.getProgramOperator().getUserCodeWrapper().getUserCodeObject();
1242:         if (!(userCodeObject instanceof BlockingShuffleOutputFormat)) {
1243:             return false;
1244:         }
1245: 
1246:         final Iterator<Channel> inputIterator = node.getInputs().iterator();
1247:         checkState(inputIterator.hasNext(), "SinkPlanNode must have a input.");
1248: 
1249:         final PlanNode predecessorNode = inputIterator.next().getSource();
1250:         final JobVertex predecessorVertex =
1251:                 (vertices.containsKey(predecessorNode))
1252:                         ? vertices.get(predecessorNode)
1253:                         : chainedTasks.get(predecessorNode).getContainingVertex();
1254: 
1255:         checkState(
1256:                 predecessorVertex != null,
1257:                 "Bug: Chained task has not been assigned its containing vertex when connecting.");
1258: 
1259:         predecessorVertex.getOrCreateResultDataSet(
1260:                 // use specified intermediateDataSetID
1261:                 new IntermediateDataSetID(
1262:                         ((BlockingShuffleOutputFormat) userCodeObject).getIntermediateDataSetId()),
1263:                 ResultPartitionType.BLOCKING_PERSISTENT);
1264: 
1265:         // remove this node so the OutputFormatVertex will not shown in the final JobGraph.
1266:         vertices.remove(node);
1267:         return true;
1268:     }
