1270:     // ------------------------------------------------------------------------
1271:     // Connecting Vertices
1272:     // ------------------------------------------------------------------------
1273: 
1274:     /**
1275:      * NOTE: The channel for global and local strategies are different if we connect a union. The
1276:      * global strategy channel is then the channel into the union node, the local strategy channel
1277:      * the one from the union to the actual target operator.
1278:      *
1279:      * @throws CompilerException
1280:      */
1281:     private DistributionPattern connectJobVertices(
1282:             Channel channel,
1283:             int inputNumber,
1284:             final JobVertex sourceVertex,
1285:             final TaskConfig sourceConfig,
1286:             final JobVertex targetVertex,
1287:             final TaskConfig targetConfig,
1288:             boolean isBroadcast)
1289:             throws CompilerException {
1290:         // ------------ connect the vertices to the job graph --------------
1291:         final DistributionPattern distributionPattern;
1292: 
1293:         switch (channel.getShipStrategy()) {
1294:             case FORWARD:
1295:                 distributionPattern = DistributionPattern.POINTWISE;
1296:                 break;
1297:             case PARTITION_RANDOM:
1298:             case BROADCAST:
1299:             case PARTITION_HASH:
1300:             case PARTITION_CUSTOM:
1301:             case PARTITION_RANGE:
1302:             case PARTITION_FORCED_REBALANCE:
1303:                 distributionPattern = DistributionPattern.ALL_TO_ALL;
1304:                 break;
1305:             default:
1306:                 throw new RuntimeException(
1307:                         "Unknown runtime ship strategy: " + channel.getShipStrategy());
1308:         }
1309: 
1310:         final ResultPartitionType resultType;
1311: 
1312:         switch (channel.getDataExchangeMode()) {
1313:             case PIPELINED:
1314:                 resultType = ResultPartitionType.PIPELINED;
1315:                 break;
1316: 
1317:             case BATCH:
1318:                 // BLOCKING results are currently not supported in closed loop iterations
1319:                 //
1320:                 // See https://issues.apache.org/jira/browse/FLINK-1713 for details
1321:                 resultType =
1322:                         channel.getSource().isOnDynamicPath()
1323:                                 ? ResultPartitionType.PIPELINED
1324:                                 : ResultPartitionType.BLOCKING;
1325:                 break;
1326: 
1327:             case PIPELINE_WITH_BATCH_FALLBACK:
1328:                 throw new UnsupportedOperationException(
1329:                         "Data exchange mode "
1330:                                 + channel.getDataExchangeMode()
1331:                                 + " currently not supported.");
1332: 
1333:             default:
1334:                 throw new UnsupportedOperationException("Unknown data exchange mode.");
1335:         }
1336: 
1337:         JobEdge edge =
1338:                 targetVertex.connectNewDataSetAsInput(
1339:                         sourceVertex, distributionPattern, resultType, isBroadcast);
1340: 
1341:         // -------------- configure the source task's ship strategy strategies in task config
1342:         // --------------
1343:         final int outputIndex = sourceConfig.getNumOutputs();
1344:         sourceConfig.addOutputShipStrategy(channel.getShipStrategy());
1345:         if (outputIndex == 0) {
1346:             sourceConfig.setOutputSerializer(channel.getSerializer());
1347:         }
1348:         if (channel.getShipStrategyComparator() != null) {
1349:             sourceConfig.setOutputComparator(channel.getShipStrategyComparator(), outputIndex);
1350:         }
1351: 
1352:         if (channel.getShipStrategy() == ShipStrategyType.PARTITION_RANGE) {
1353: 
1354:             final DataDistribution dataDistribution = channel.getDataDistribution();
1355:             if (dataDistribution != null) {
1356:                 sourceConfig.setOutputDataDistribution(dataDistribution, outputIndex);
1357:             } else {
1358:                 throw new RuntimeException("Range partitioning requires data distribution.");
1359:             }
1360:         }
1361: 
1362:         if (channel.getShipStrategy() == ShipStrategyType.PARTITION_CUSTOM) {
1363:             if (channel.getPartitioner() != null) {
1364:                 sourceConfig.setOutputPartitioner(channel.getPartitioner(), outputIndex);
1365:             } else {
1366:                 throw new CompilerException(
1367:                         "The ship strategy was set to custom partitioning, but no partitioner was set.");
1368:             }
1369:         }
1370: 
1371:         // ---------------- configure the receiver -------------------
1372:         if (isBroadcast) {
1373:             targetConfig.addBroadcastInputToGroup(inputNumber);
1374:         } else {
1375:             targetConfig.addInputToGroup(inputNumber);
1376:         }
1377: 
1378:         // ---------------- attach the additional infos to the job edge -------------------
1379: 
1380:         String shipStrategy = JsonMapper.getShipStrategyString(channel.getShipStrategy());
1381:         if (channel.getShipStrategyKeys() != null && channel.getShipStrategyKeys().size() > 0) {
1382:             shipStrategy +=
1383:                     " on "
1384:                             + (channel.getShipStrategySortOrder() == null
1385:                                     ? channel.getShipStrategyKeys().toString()
1386:                                     : Utils.createOrdering(
1387:                                                     channel.getShipStrategyKeys(),
1388:                                                     channel.getShipStrategySortOrder())
1389:                                             .toString());
1390:         }
1391: 
1392:         String localStrategy;
1393:         if (channel.getLocalStrategy() == null
1394:                 || channel.getLocalStrategy() == LocalStrategy.NONE) {
1395:             localStrategy = null;
1396:         } else {
1397:             localStrategy = JsonMapper.getLocalStrategyString(channel.getLocalStrategy());
1398:             if (localStrategy != null
1399:                     && channel.getLocalStrategyKeys() != null
1400:                     && channel.getLocalStrategyKeys().size() > 0) {
1401:                 localStrategy +=
1402:                         " on "
1403:                                 + (channel.getLocalStrategySortOrder() == null
1404:                                         ? channel.getLocalStrategyKeys().toString()
1405:                                         : Utils.createOrdering(
1406:                                                         channel.getLocalStrategyKeys(),
1407:                                                         channel.getLocalStrategySortOrder())
1408:                                                 .toString());
1409:             }
1410:         }
1411: 
1412:         String caching =
1413:                 channel.getTempMode() == TempMode.NONE ? null : channel.getTempMode().toString();
1414: 
1415:         edge.setShipStrategyName(shipStrategy);
1416:         edge.setForward(channel.getShipStrategy() == ShipStrategyType.FORWARD);
1417:         edge.setPreProcessingOperationName(localStrategy);
1418:         edge.setOperatorLevelCachingDescription(caching);
1419: 
1420:         return distributionPattern;
1421:     }
