1423:     private void addLocalInfoFromChannelToConfig(
1424:             Channel channel, TaskConfig config, int inputNum, boolean isBroadcastChannel) {
1425:         // serializer
1426:         if (isBroadcastChannel) {
1427:             config.setBroadcastInputSerializer(channel.getSerializer(), inputNum);
1428: 
1429:             if (channel.getLocalStrategy() != LocalStrategy.NONE
1430:                     || (channel.getTempMode() != null && channel.getTempMode() != TempMode.NONE)) {
1431:                 throw new CompilerException(
1432:                         "Found local strategy or temp mode on a broadcast variable channel.");
1433:             } else {
1434:                 return;
1435:             }
1436:         } else {
1437:             config.setInputSerializer(channel.getSerializer(), inputNum);
1438:         }
1439: 
1440:         // local strategy
1441:         if (channel.getLocalStrategy() != LocalStrategy.NONE) {
1442:             config.setInputLocalStrategy(inputNum, channel.getLocalStrategy());
1443:             if (channel.getLocalStrategyComparator() != null) {
1444:                 config.setInputComparator(channel.getLocalStrategyComparator(), inputNum);
1445:             }
1446:         }
1447: 
1448:         assignLocalStrategyResources(channel, config, inputNum);
1449: 
1450:         // materialization / caching
1451:         if (channel.getTempMode() != null) {
1452:             final TempMode tm = channel.getTempMode();
1453: 
1454:             boolean needsMemory = false;
1455:             // Don't add a pipeline breaker if the data exchange is already blocking, EXCEPT the
1456:             // channel is within an iteration.
1457:             if (tm.breaksPipeline()
1458:                     && (channel.isOnDynamicPath()
1459:                             || channel.getDataExchangeMode() != DataExchangeMode.BATCH)) {
1460:                 config.setInputAsynchronouslyMaterialized(inputNum, true);
1461:                 needsMemory = true;
1462:             }
1463:             if (tm.isCached()) {
1464:                 config.setInputCached(inputNum, true);
1465:                 needsMemory = true;
1466:             }
1467: 
1468:             if (needsMemory) {
1469:                 // sanity check
1470:                 if (tm == TempMode.NONE || channel.getRelativeTempMemory() <= 0) {
1471:                     throw new CompilerException(
1472:                             "Bug in compiler: Inconsistent description of input materialization.");
1473:                 }
1474:                 config.setRelativeInputMaterializationMemory(
1475:                         inputNum, channel.getRelativeTempMemory());
1476:             }
1477:         }
1478:     }
