1480:     private void finalizeBulkIteration(IterationDescriptor descr) {
1481: 
1482:         final BulkIterationPlanNode bulkNode = (BulkIterationPlanNode) descr.getIterationNode();
1483:         final JobVertex headVertex = descr.getHeadTask();
1484:         final TaskConfig headConfig = new TaskConfig(headVertex.getConfiguration());
1485:         final TaskConfig headFinalOutputConfig = descr.getHeadFinalResultConfig();
1486: 
1487:         // ------------ finalize the head config with the final outputs and the sync gate
1488:         // ------------
1489:         final int numStepFunctionOuts = headConfig.getNumOutputs();
1490:         final int numFinalOuts = headFinalOutputConfig.getNumOutputs();
1491: 
1492:         if (numStepFunctionOuts == 0) {
1493:             throw new CompilerException("The iteration has no operation inside the step function.");
1494:         }
1495: 
1496:         headConfig.setIterationHeadFinalOutputConfig(headFinalOutputConfig);
1497:         headConfig.setIterationHeadIndexOfSyncOutput(numStepFunctionOuts + numFinalOuts);
1498:         final double relativeMemForBackChannel = bulkNode.getRelativeMemoryPerSubTask();
1499:         if (relativeMemForBackChannel <= 0) {
1500:             throw new CompilerException(
1501:                     "Bug: No memory has been assigned to the iteration back channel.");
1502:         }
1503:         headConfig.setRelativeBackChannelMemory(relativeMemForBackChannel);
1504: 
1505:         // --------------------------- create the sync task ---------------------------
1506:         final JobVertex sync = new JobVertex("Sync (" + bulkNode.getNodeName() + ")");
1507:         sync.setResources(bulkNode.getMinResources(), bulkNode.getPreferredResources());
1508:         sync.setInvokableClass(IterationSynchronizationSinkTask.class);
1509:         sync.setParallelism(1);
1510:         sync.setMaxParallelism(1);
1511:         this.auxVertices.add(sync);
1512: 
1513:         final TaskConfig syncConfig = new TaskConfig(sync.getConfiguration());
1514:         syncConfig.setGateIterativeWithNumberOfEventsUntilInterrupt(0, headVertex.getParallelism());
1515: 
1516:         // set the number of iteration / convergence criterion for the sync
1517:         final int maxNumIterations =
1518:                 bulkNode.getIterationNode().getIterationContract().getMaximumNumberOfIterations();
1519:         if (maxNumIterations < 1) {
1520:             throw new CompilerException(
1521:                     "Cannot create bulk iteration with unspecified maximum number of iterations.");
1522:         }
1523:         syncConfig.setNumberOfIterations(maxNumIterations);
1524: 
1525:         // connect the sync task
1526:         sync.connectNewDataSetAsInput(
1527:                 headVertex, DistributionPattern.POINTWISE, ResultPartitionType.PIPELINED);
1528: 
1529:         // ----------------------------- create the iteration tail ------------------------------
1530: 
1531:         final PlanNode rootOfTerminationCriterion = bulkNode.getRootOfTerminationCriterion();
1532:         final PlanNode rootOfStepFunction = bulkNode.getRootOfStepFunction();
1533:         final TaskConfig tailConfig;
1534: 
1535:         JobVertex rootOfStepFunctionVertex = this.vertices.get(rootOfStepFunction);
1536:         if (rootOfStepFunctionVertex == null) {
1537:             // last op is chained
1538:             final TaskInChain taskInChain = this.chainedTasks.get(rootOfStepFunction);
1539:             if (taskInChain == null) {
1540:                 throw new CompilerException(
1541:                         "Bug: Tail of step function not found as vertex or chained task.");
1542:             }
1543:             rootOfStepFunctionVertex = taskInChain.getContainingVertex();
1544: 
1545:             // the fake channel is statically typed to pact record. no data is sent over this
1546:             // channel anyways.
1547:             tailConfig = taskInChain.getTaskConfig();
1548:         } else {
1549:             tailConfig = new TaskConfig(rootOfStepFunctionVertex.getConfiguration());
1550:         }
1551: 
1552:         tailConfig.setIsWorksetUpdate();
1553: 
1554:         // No following termination criterion
1555:         if (rootOfStepFunction.getOutgoingChannels().isEmpty()) {
1556: 
1557:             rootOfStepFunctionVertex.setInvokableClass(IterationTailTask.class);
1558: 
1559:             tailConfig.setOutputSerializer(bulkNode.getSerializerForIterationChannel());
1560:         }
1561: 
1562:         // create the fake output task for termination criterion, if needed
1563:         final TaskConfig tailConfigOfTerminationCriterion;
1564:         // If we have a termination criterion and it is not an intermediate node
1565:         if (rootOfTerminationCriterion != null
1566:                 && rootOfTerminationCriterion.getOutgoingChannels().isEmpty()) {
1567:             JobVertex rootOfTerminationCriterionVertex =
1568:                     this.vertices.get(rootOfTerminationCriterion);
1569: 
1570:             if (rootOfTerminationCriterionVertex == null) {
1571:                 // last op is chained
1572:                 final TaskInChain taskInChain = this.chainedTasks.get(rootOfTerminationCriterion);
1573:                 if (taskInChain == null) {
1574:                     throw new CompilerException(
1575:                             "Bug: Tail of termination criterion not found as vertex or chained task.");
1576:                 }
1577:                 rootOfTerminationCriterionVertex = taskInChain.getContainingVertex();
1578: 
1579:                 // the fake channel is statically typed to pact record. no data is sent over this
1580:                 // channel anyways.
1581:                 tailConfigOfTerminationCriterion = taskInChain.getTaskConfig();
1582:             } else {
1583:                 tailConfigOfTerminationCriterion =
1584:                         new TaskConfig(rootOfTerminationCriterionVertex.getConfiguration());
1585:             }
1586: 
1587:             rootOfTerminationCriterionVertex.setInvokableClass(IterationTailTask.class);
1588:             // Hack
1589:             tailConfigOfTerminationCriterion.setIsSolutionSetUpdate();
1590:             tailConfigOfTerminationCriterion.setOutputSerializer(
1591:                     bulkNode.getSerializerForIterationChannel());
1592: 
1593:             // tell the head that it needs to wait for the solution set updates
1594:             headConfig.setWaitForSolutionSetUpdate();
1595:         }
1596: 
1597:         // ------------------- register the aggregators -------------------
1598:         AggregatorRegistry aggs =
1599:                 bulkNode.getIterationNode().getIterationContract().getAggregators();
1600:         Collection<AggregatorWithName<?>> allAggregators = aggs.getAllRegisteredAggregators();
1601: 
1602:         headConfig.addIterationAggregators(allAggregators);
1603:         syncConfig.addIterationAggregators(allAggregators);
1604: 
1605:         String convAggName = aggs.getConvergenceCriterionAggregatorName();
1606:         ConvergenceCriterion<?> convCriterion = aggs.getConvergenceCriterion();
1607: 
1608:         if (convCriterion != null || convAggName != null) {
1609:             if (convCriterion == null) {
1610:                 throw new CompilerException(
1611:                         "Error: Convergence criterion aggregator set, but criterion is null.");
1612:             }
1613:             if (convAggName == null) {
1614:                 throw new CompilerException(
1615:                         "Error: Aggregator convergence criterion set, but aggregator is null.");
1616:             }
1617: 
1618:             syncConfig.setConvergenceCriterion(convAggName, convCriterion);
1619:         }
1620:     }
