1622:     private void finalizeWorksetIteration(IterationDescriptor descr) {
1623:         final WorksetIterationPlanNode iterNode =
1624:                 (WorksetIterationPlanNode) descr.getIterationNode();
1625:         final JobVertex headVertex = descr.getHeadTask();
1626:         final TaskConfig headConfig = new TaskConfig(headVertex.getConfiguration());
1627:         final TaskConfig headFinalOutputConfig = descr.getHeadFinalResultConfig();
1628: 
1629:         // ------------ finalize the head config with the final outputs and the sync gate
1630:         // ------------
1631:         {
1632:             final int numStepFunctionOuts = headConfig.getNumOutputs();
1633:             final int numFinalOuts = headFinalOutputConfig.getNumOutputs();
1634: 
1635:             if (numStepFunctionOuts == 0) {
1636:                 throw new CompilerException(
1637:                         "The workset iteration has no operation on the workset inside the step function.");
1638:             }
1639: 
1640:             headConfig.setIterationHeadFinalOutputConfig(headFinalOutputConfig);
1641:             headConfig.setIterationHeadIndexOfSyncOutput(numStepFunctionOuts + numFinalOuts);
1642:             final double relativeMemory = iterNode.getRelativeMemoryPerSubTask();
1643:             if (relativeMemory <= 0) {
1644:                 throw new CompilerException(
1645:                         "Bug: No memory has been assigned to the workset iteration.");
1646:             }
1647: 
1648:             headConfig.setIsWorksetIteration();
1649:             headConfig.setRelativeBackChannelMemory(relativeMemory / 2);
1650:             headConfig.setRelativeSolutionSetMemory(relativeMemory / 2);
1651: 
1652:             // set the solution set serializer and comparator
1653:             headConfig.setSolutionSetSerializer(iterNode.getSolutionSetSerializer());
1654:             headConfig.setSolutionSetComparator(iterNode.getSolutionSetComparator());
1655:         }
1656: 
1657:         // --------------------------- create the sync task ---------------------------
1658:         final TaskConfig syncConfig;
1659:         {
1660:             final JobVertex sync = new JobVertex("Sync (" + iterNode.getNodeName() + ")");
1661:             sync.setResources(iterNode.getMinResources(), iterNode.getPreferredResources());
1662:             sync.setInvokableClass(IterationSynchronizationSinkTask.class);
1663:             sync.setParallelism(1);
1664:             sync.setMaxParallelism(1);
1665:             this.auxVertices.add(sync);
1666: 
1667:             syncConfig = new TaskConfig(sync.getConfiguration());
1668:             syncConfig.setGateIterativeWithNumberOfEventsUntilInterrupt(
1669:                     0, headVertex.getParallelism());
1670: 
1671:             // set the number of iteration / convergence criterion for the sync
1672:             final int maxNumIterations =
1673:                     iterNode.getIterationNode()
1674:                             .getIterationContract()
1675:                             .getMaximumNumberOfIterations();
1676:             if (maxNumIterations < 1) {
1677:                 throw new CompilerException(
1678:                         "Cannot create workset iteration with unspecified maximum number of iterations.");
1679:             }
1680:             syncConfig.setNumberOfIterations(maxNumIterations);
1681: 
1682:             // connect the sync task
1683:             sync.connectNewDataSetAsInput(
1684:                     headVertex, DistributionPattern.POINTWISE, ResultPartitionType.PIPELINED);
1685:         }
1686: 
1687:         // ----------------------------- create the iteration tails -----------------------------
1688:         // ----------------------- for next workset and solution set delta-----------------------
1689: 
1690:         {
1691:             // we have three possible cases:
1692:             // 1) Two tails, one for workset update, one for solution set update
1693:             // 2) One tail for workset update, solution set update happens in an intermediate task
1694:             // 3) One tail for solution set update, workset update happens in an intermediate task
1695: 
1696:             final PlanNode nextWorksetNode = iterNode.getNextWorkSetPlanNode();
1697:             final PlanNode solutionDeltaNode = iterNode.getSolutionSetDeltaPlanNode();
1698: 
1699:             final boolean hasWorksetTail = nextWorksetNode.getOutgoingChannels().isEmpty();
1700:             final boolean hasSolutionSetTail =
1701:                     (!iterNode.isImmediateSolutionSetUpdate()) || (!hasWorksetTail);
1702: 
1703:             {
1704:                 // get the vertex for the workset update
1705:                 final TaskConfig worksetTailConfig;
1706:                 JobVertex nextWorksetVertex = this.vertices.get(nextWorksetNode);
1707:                 if (nextWorksetVertex == null) {
1708:                     // nextWorksetVertex is chained
1709:                     TaskInChain taskInChain = this.chainedTasks.get(nextWorksetNode);
1710:                     if (taskInChain == null) {
1711:                         throw new CompilerException(
1712:                                 "Bug: Next workset node not found as vertex or chained task.");
1713:                     }
1714:                     nextWorksetVertex = taskInChain.getContainingVertex();
1715:                     worksetTailConfig = taskInChain.getTaskConfig();
1716:                 } else {
1717:                     worksetTailConfig = new TaskConfig(nextWorksetVertex.getConfiguration());
1718:                 }
1719: 
1720:                 // mark the node to perform workset updates
1721:                 worksetTailConfig.setIsWorksetIteration();
1722:                 worksetTailConfig.setIsWorksetUpdate();
1723: 
1724:                 if (hasWorksetTail) {
1725:                     nextWorksetVertex.setInvokableClass(IterationTailTask.class);
1726: 
1727:                     worksetTailConfig.setOutputSerializer(iterNode.getWorksetSerializer());
1728:                 }
1729:             }
1730:             {
1731:                 final TaskConfig solutionDeltaConfig;
1732:                 JobVertex solutionDeltaVertex = this.vertices.get(solutionDeltaNode);
1733:                 if (solutionDeltaVertex == null) {
1734:                     // last op is chained
1735:                     TaskInChain taskInChain = this.chainedTasks.get(solutionDeltaNode);
1736:                     if (taskInChain == null) {
1737:                         throw new CompilerException(
1738:                                 "Bug: Solution Set Delta not found as vertex or chained task.");
1739:                     }
1740:                     solutionDeltaVertex = taskInChain.getContainingVertex();
1741:                     solutionDeltaConfig = taskInChain.getTaskConfig();
1742:                 } else {
1743:                     solutionDeltaConfig = new TaskConfig(solutionDeltaVertex.getConfiguration());
1744:                 }
1745: 
1746:                 solutionDeltaConfig.setIsWorksetIteration();
1747:                 solutionDeltaConfig.setIsSolutionSetUpdate();
1748: 
1749:                 if (hasSolutionSetTail) {
1750:                     solutionDeltaVertex.setInvokableClass(IterationTailTask.class);
1751: 
1752:                     solutionDeltaConfig.setOutputSerializer(iterNode.getSolutionSetSerializer());
1753: 
1754:                     // tell the head that it needs to wait for the solution set updates
1755:                     headConfig.setWaitForSolutionSetUpdate();
1756:                 } else {
1757:                     // no tail, intermediate update. must be immediate update
1758:                     if (!iterNode.isImmediateSolutionSetUpdate()) {
1759:                         throw new CompilerException(
1760:                                 "A solution set update without dedicated tail is not set to perform immediate updates.");
1761:                     }
1762:                     solutionDeltaConfig.setIsSolutionSetUpdateWithoutReprobe();
1763:                 }
1764:             }
1765:         }
1766: 
1767:         // ------------------- register the aggregators -------------------
1768:         AggregatorRegistry aggs =
1769:                 iterNode.getIterationNode().getIterationContract().getAggregators();
1770:         Collection<AggregatorWithName<?>> allAggregators = aggs.getAllRegisteredAggregators();
1771: 
1772:         for (AggregatorWithName<?> agg : allAggregators) {
1773:             if (agg.getName().equals(WorksetEmptyConvergenceCriterion.AGGREGATOR_NAME)) {
1774:                 throw new CompilerException(
1775:                         "User defined aggregator used the same name as built-in workset "
1776:                                 + "termination check aggregator: "
1777:                                 + WorksetEmptyConvergenceCriterion.AGGREGATOR_NAME);
1778:             }
1779:         }
1780: 
1781:         headConfig.addIterationAggregators(allAggregators);
1782:         syncConfig.addIterationAggregators(allAggregators);
1783: 
1784:         String convAggName = aggs.getConvergenceCriterionAggregatorName();
1785:         ConvergenceCriterion<?> convCriterion = aggs.getConvergenceCriterion();
1786: 
1787:         if (convCriterion != null || convAggName != null) {
1788:             if (convCriterion == null) {
1789:                 throw new CompilerException(
1790:                         "Error: Convergence criterion aggregator set, but criterion is null.");
1791:             }
1792:             if (convAggName == null) {
1793:                 throw new CompilerException(
1794:                         "Error: Aggregator convergence criterion set, but aggregator is null.");
1795:             }
1796: 
1797:             syncConfig.setConvergenceCriterion(convAggName, convCriterion);
1798:         }
1799: 
1800:         headConfig.addIterationAggregator(
1801:                 WorksetEmptyConvergenceCriterion.AGGREGATOR_NAME, new LongSumAggregator());
1802:         syncConfig.addIterationAggregator(
1803:                 WorksetEmptyConvergenceCriterion.AGGREGATOR_NAME, new LongSumAggregator());
1804:         syncConfig.setImplicitConvergenceCriterion(
1805:                 WorksetEmptyConvergenceCriterion.AGGREGATOR_NAME,
1806:                 new WorksetEmptyConvergenceCriterion());
1807:     }
