1825:     private void attachOperatorNamesAndDescriptions() {
1826:         JsonFactory jsonFactory = new JsonFactory();
1827: 
1828:         // we go back to front
1829: 
1830:         // start with the in chains
1831:         for (int i = chainedTasksInSequence.size() - 1; i >= 0; i--) {
1832:             TaskInChain next = chainedTasksInSequence.get(i);
1833:             PlanNode planNode = next.getPlanNode();
1834: 
1835:             JobVertex vertex = next.getContainingVertex();
1836: 
1837:             // operator
1838:             String opName = planNode.getOptimizerNode().getOperatorName();
1839:             if (vertex.getOperatorName() == null) {
1840:                 vertex.setOperatorName(opName);
1841:             } else {
1842:                 vertex.setOperatorName(opName + " -> " + vertex.getOperatorName());
1843:             }
1844: 
1845:             // operator description
1846:             String opDescription =
1847:                     JsonMapper.getOperatorStrategyString(planNode.getDriverStrategy());
1848:             if (vertex.getOperatorDescription() == null) {
1849:                 vertex.setOperatorDescription(opDescription);
1850:             } else {
1851:                 vertex.setOperatorDescription(
1852:                         opDescription + "\n -> " + vertex.getOperatorDescription());
1853:             }
1854: 
1855:             // pretty name
1856:             String prettyName = StringUtils.showControlCharacters(planNode.getNodeName());
1857:             if (vertex.getOperatorPrettyName() == null) {
1858:                 vertex.setOperatorPrettyName(prettyName);
1859:             } else {
1860:                 vertex.setOperatorPrettyName(
1861:                         prettyName + "\n -> " + vertex.getOperatorPrettyName());
1862:             }
1863: 
1864:             // optimizer output properties
1865:             if (vertex.getResultOptimizerProperties() == null) {
1866:                 // since we go backwards, this must be the last in its chain
1867:                 String outputProps = JsonMapper.getOptimizerPropertiesJson(jsonFactory, planNode);
1868:                 vertex.setResultOptimizerProperties(outputProps);
1869:             }
1870:         }
1871: 
1872:         // finish back-to-front traversal by going over the head vertices
1873:         for (Map.Entry<PlanNode, JobVertex> entry : vertices.entrySet()) {
1874:             PlanNode node = entry.getKey();
1875:             JobVertex vertex = entry.getValue();
1876: 
1877:             // get the predecessors
1878: 
1879:             String input1name = null;
1880:             String input2name = null;
1881:             int num = 0;
1882:             for (Channel c : node.getInputs()) {
1883:                 if (num == 0) {
1884:                     input1name = c.getSource().getNodeName();
1885:                 } else if (num == 1) {
1886:                     input2name = c.getSource().getNodeName();
1887:                 }
1888:                 num++;
1889:             }
1890: 
1891:             // operator
1892:             String opName = node.getOptimizerNode().getOperatorName();
1893:             if (vertex.getOperatorName() == null) {
1894:                 vertex.setOperatorName(opName);
1895:             } else {
1896:                 vertex.setOperatorName(opName + " -> " + vertex.getOperatorName());
1897:             }
1898: 
1899:             // operator description
1900:             String opStrategy =
