146:     public static StreamGraph kmeans(String[] args) throws Exception {
147:         ExecutionEnvironment env = ExecutionEnvironment.getExecutionEnvironment();
148: 
149:         DataSet<Point> points =
150:                 env.readCsvFile(args[0])
151:                         .fieldDelimiter(" ")
152:                         .includeFields(true, true)
153:                         .types(Double.class, Double.class)
154:                         .name(DATAPOINTS)
155:                         .map(
156:                                 new MapFunction<Tuple2<Double, Double>, Point>() {
157:                                     @Override
158:                                     public Point map(Tuple2<Double, Double> value)
159:                                             throws Exception {
160:                                         return new Point(value.f0, value.f1);
161:                                     }
162:                                 });
163: 
164:         DataSet<Centroid> centroids =
165:                 env.readCsvFile(args[1])
166:                         .fieldDelimiter(" ")
167:                         .includeFields(true, true, true)
168:                         .types(Integer.class, Double.class, Double.class)
169:                         .name(CENTERS)
170:                         .map(
171:                                 new MapFunction<Tuple3<Integer, Double, Double>, Centroid>() {
172:                                     @Override
173:                                     public Centroid map(Tuple3<Integer, Double, Double> value)
174:                                             throws Exception {
175:                                         return new Centroid(value.f0, value.f1, value.f2);
176:                                     }
177:                                 });
178: 
179:         DataSet<Tuple3<Integer, Point, Integer>> newCentroids =
180:                 points.map(new SelectNearestCenter())
181:                         .name(MAPPER_NAME)
182:                         .withBroadcastSet(centroids, "centroids");
183: 
184:         DataSet<Tuple3<Integer, Point, Integer>> recomputeClusterCenter =
185:                 newCentroids
186:                         .groupBy(0)
187:                         .reduceGroup(new RecomputeClusterCenter())
188:                         .name(REDUCER_NAME);
189: 
190:         recomputeClusterCenter.project(0, 1).writeAsCsv(args[2], "\n", " ").name(SINK);
191: 
192:         return env.createProgramPlan("KMeans Example");
193:     }
194: 
195:     /** Two-dimensional point. */
196:     public static class Point extends Tuple2<Double, Double> {
197:         public Point(double x, double y) {
198:             this.f0 = x;
199:             this.f1 = y;
200:         }
201: 
202:         public Point add(Point other) {
203:             f0 += other.f0;
204:             f1 += other.f1;
205:             return this;
206:         }
207: 
208:         public Point div(long val) {
209:             f0 /= val;
210:             f1 /= val;
211:             return this;
212:         }
213: 
214:         public double euclideanDistance(Point other) {
215:             return Math.sqrt((f0 - other.f0) * (f0 - other.f0) + (f1 - other.f1) * (f1 - other.f1));
216:         }
217: 
218:         public double euclideanDistance(Centroid other) {
219:             return Math.sqrt(
220:                     (f0 - other.f1.f0) * (f0 - other.f1.f0)
221:                             + (f1 - other.f1.f1) * (f1 - other.f1.f1));
222:         }
223:     }
224: 
225:     /** Center of a cluster. */
226:     public static class Centroid extends Tuple2<Integer, Point> {
227: 
228:         public Centroid(int id, double x, double y) {
229:             this.f0 = id;
230:             this.f1 = new Point(x, y);
231:         }
232: 
233:         public Centroid(int id, Point p) {
234:             this.f0 = id;
235:             this.f1 = p;
236:         }
237:     }
238: 
239:     /** Determines the closest cluster center for a data point. */
240:     private static final class SelectNearestCenter
241:             extends RichMapFunction<Point, Tuple3<Integer, Point, Integer>> {
242:         private Collection<Centroid> centroids;
243: 
244:         @Override
245:         public void open(OpenContext openContext) throws Exception {
246:             this.centroids = getRuntimeContext().getBroadcastVariable("centroids");
247:         }
248: 
249:         @Override
250:         public Tuple3<Integer, Point, Integer> map(Point p) throws Exception {
251:             double minDistance = Double.MAX_VALUE;
252:             int closestCentroidId = -1;
253:             for (Centroid centroid : centroids) {
254:                 double distance = p.euclideanDistance(centroid);
255:                 if (distance < minDistance) {
256:                     minDistance = distance;
257:                     closestCentroidId = centroid.f0;
258:                 }
259:             }
260:             return new Tuple3<>(closestCentroidId, p, 1);
261:         }
262:     }
263: 
264:     private static final class RecomputeClusterCenter
265:             implements GroupReduceFunction<
266:                             Tuple3<Integer, Point, Integer>, Tuple3<Integer, Point, Integer>>,
267:                     GroupCombineFunction<
268:                             Tuple3<Integer, Point, Integer>, Tuple3<Integer, Point, Integer>> {
269: 
270:         @Override
271:         public void reduce(
272:                 Iterable<Tuple3<Integer, Point, Integer>> values,
273:                 Collector<Tuple3<Integer, Point, Integer>> out)
274:                 throws Exception {
275:             int id = -1;
276:             double x = 0;
277:             double y = 0;
278:             int count = 0;
279:             for (Tuple3<Integer, Point, Integer> value : values) {
280:                 id = value.f0;
281:                 x += value.f1.f0;
282:                 y += value.f1.f1;
283:                 count += value.f2;
284:             }
285:             out.collect(new Tuple3<>(id, new Point(x, y), count));
286:         }
287: 
288:         @Override
289:         public void combine(
290:                 Iterable<Tuple3<Integer, Point, Integer>> values,
291:                 Collector<Tuple3<Integer, Point, Integer>> out)
292:                 throws Exception {
293:             reduce(values, out);
294:         }
295:     }
296: }
