146:     private static void submitJobAndVerifyResults(JobGraph jobGraph) throws Exception {
147:         Deadline deadline = Deadline.now().plus(Duration.ofSeconds(30));
148: 
149:         final ClusterClient<?> client = MINI_CLUSTER_RESOURCE.getClusterClient();
150: 
151:         final CheckedThread submissionThread =
152:                 new CheckedThread() {
153:                     @Override
154:                     public void go() throws Exception {
155:                         submitJobAndWaitForResult(client, jobGraph, getClass().getClassLoader());
156:                     }
157:                 };
158: 
159:         submissionThread.start();
160: 
161:         try {
162:             NotifyingMapper.notifyLatch.await();
163: 
164:             // verify using the ClusterClient
165:             verifyResults(jobGraph, deadline, client);
166:             // verify using the MiniClusterJobClient
167:             verifyResults(jobGraph, deadline, null);
168: 
169:             NotifyingMapper.shutdownLatch.trigger();
170:         } finally {
171:             NotifyingMapper.shutdownLatch.trigger();
172: 
173:             // wait for the job to have terminated
174:             submissionThread.sync();
175:         }
176:     }
