178:     private static void verifyResults(JobGraph jobGraph, Deadline deadline, ClusterClient<?> client)
179:             throws InterruptedException, java.util.concurrent.ExecutionException,
180:                     java.util.concurrent.TimeoutException {
181:         FutureUtils.retrySuccessfulWithDelay(
182:                         () -> {
183:                             try {
184:                                 if (client != null) {
185:                                     return CompletableFuture.completedFuture(
186:                                             client.getAccumulators(jobGraph.getJobID()).get());
187:                                 } else {
188:                                     final MiniClusterJobClient miniClusterJobClient =
189:                                             new MiniClusterJobClient(
190:                                                     jobGraph.getJobID(),
191:                                                     MINI_CLUSTER_RESOURCE.getMiniCluster(),
192:                                                     ClassLoader.getSystemClassLoader(),
193:                                                     MiniClusterJobClient.JobFinalizationBehavior
194:                                                             .NOTHING);
195:                                     return CompletableFuture.completedFuture(
196:                                             miniClusterJobClient.getAccumulators().get());
197:                                 }
198:                             } catch (Exception e) {
199:                                 return FutureUtils.completedExceptionally(e);
200:                             }
201:                         },
202:                         Duration.ofMillis(20),
203:                         deadline,
204:                         accumulators ->
205:                                 accumulators.size() == 1
206:                                         && accumulators.containsKey(ACCUMULATOR_NAME)
207:                                         && (int) accumulators.get(ACCUMULATOR_NAME)
208:                                                 == NUM_ITERATIONS,
209:                         new ScheduledExecutorServiceAdapter(EXECUTOR_RESOURCE.getExecutor()))
210:                 .get(deadline.timeLeft().toMillis(), TimeUnit.MILLISECONDS);
211:     }
