213:     /** UDF that notifies when it changes the accumulator values. */
214:     private static class NotifyingMapper extends RichFlatMapFunction<Integer, Integer> {
215:         private static final long serialVersionUID = 1L;
216: 
217:         private static final OneShotLatch notifyLatch = new OneShotLatch();
218:         private static final OneShotLatch shutdownLatch = new OneShotLatch();
219: 
220:         private final IntCounter counter = new IntCounter();
221: 
222:         @Override
223:         public void open(OpenContext openContext) throws Exception {
224:             getRuntimeContext().addAccumulator(ACCUMULATOR_NAME, counter);
225:         }
226: 
227:         @Override
228:         public void flatMap(Integer value, Collector<Integer> out) throws Exception {
229:             counter.add(1);
230:             out.collect(value);
231:             LOG.debug("Emitting value {}.", value);
232:             if (counter.getLocalValuePrimitive() == 5) {
233:                 notifyLatch.trigger();
234:             }
235:         }
236: 
237:         @Override
238:         public void close() throws Exception {
239:             shutdownLatch.await();
240:         }
241: 
242:         private static void reset() throws InterruptedException {
243:             notifyLatch.reset();
244:             shutdownLatch.reset();
245:         }
246:     }
