222:     public boolean matchesOrderedPartitioning(Ordering o) {
223:         if (this.partitioning == PartitioningProperty.RANGE_PARTITIONED) {
224:             if (this.ordering.getNumberOfFields() > o.getNumberOfFields()) {
225:                 return false;
