233:                 // if this one request no order, everything is good
234:                 final Order oo = o.getOrder(i);
235:                 final Order to = this.ordering.getOrder(i);
236:                 if (oo != Order.NONE) {
237:                     if (oo == Order.ANY) {
238:                         // if any order is requested, any not NONE order is good
239:                         if (to == Order.NONE) {
240:                             return false;
241:                         }
242:                     } else if (oo != to) {
243:                         // the orders must be equal
244:                         return false;
245:                     }
246:                 }
247:             }
248:             return true;
249:         } else {
250:             return false;
251:         }
