278:     public GlobalProperties filterBySemanticProperties(SemanticProperties props, int input) {
279: 
280:         if (props == null) {
281:             throw new NullPointerException("SemanticProperties may not be null.");
282:         }
283: 
284:         GlobalProperties gp = new GlobalProperties();
285: 
286:         // filter partitioning
287:         switch (this.partitioning) {
288:             case RANGE_PARTITIONED:
289:                 // check if ordering is preserved
290:                 Ordering newOrdering = new Ordering();
291:                 for (int i = 0; i < this.ordering.getInvolvedIndexes().size(); i++) {
292:                     int sourceField = this.ordering.getInvolvedIndexes().get(i);
293:                     FieldSet targetField = props.getForwardingTargetFields(input, sourceField);
294: 
295:                     if (targetField == null || targetField.size() == 0) {
296:                         // partitioning is destroyed
297:                         newOrdering = null;
298:                         break;
299:                     } else {
300:                         // use any field of target fields for now. We should use something like
301:                         // field equivalence sets in the future.
302:                         if (targetField.size() > 1) {
303:                             LOG.warn(
304:                                     "Found that a field is forwarded to more than one target field in "
305:                                             + "semantic forwarded field information. Will only use the field with the lowest index.");
306:                         }
307:                         newOrdering.appendOrdering(
308:                                 targetField.toArray()[0],
309:                                 this.ordering.getType(i),
310:                                 this.ordering.getOrder(i));
311:                     }
312:                 }
313:                 if (newOrdering != null) {
314:                     gp.partitioning = PartitioningProperty.RANGE_PARTITIONED;
315:                     gp.ordering = newOrdering;
316:                     gp.partitioningFields = newOrdering.getInvolvedIndexes();
317:                     gp.distribution = this.distribution;
318:                 }
319:                 break;
320:             case HASH_PARTITIONED:
321:             case ANY_PARTITIONING:
322:             case CUSTOM_PARTITIONING:
323:                 FieldList newPartitioningFields = new FieldList();
324:                 for (int sourceField : this.partitioningFields) {
325:                     FieldSet targetField = props.getForwardingTargetFields(input, sourceField);
326: 
327:                     if (targetField == null || targetField.size() == 0) {
328:                         newPartitioningFields = null;
329:                         break;
330:                     } else {
331:                         // use any field of target fields for now.  We should use something like
332:                         // field equivalence sets in the future.
333:                         if (targetField.size() > 1) {
334:                             LOG.warn(
335:                                     "Found that a field is forwarded to more than one target field in "
336:                                             + "semantic forwarded field information. Will only use the field with the lowest index.");
337:                         }
338:                         newPartitioningFields =
339:                                 newPartitioningFields.addField(targetField.toArray()[0]);
340:                     }
341:                 }
342:                 if (newPartitioningFields != null) {
343:                     gp.partitioning = this.partitioning;
344:                     gp.partitioningFields = newPartitioningFields;
345:                     gp.customPartitioner = this.customPartitioner;
346:                 }
347:                 break;
348:             case FORCED_REBALANCED:
349:             case FULL_REPLICATION:
350:             case RANDOM_PARTITIONED:
351:                 gp.partitioning = this.partitioning;
352:                 break;
353:             default:
354:                 throw new RuntimeException("Unknown partitioning type.");
355:         }
356: 
357:         // filter unique field combinations
358:         if (this.uniqueFieldCombinations != null) {
359:             Set<FieldSet> newUniqueFieldCombinations = new HashSet<FieldSet>();
360:             for (FieldSet fieldCombo : this.uniqueFieldCombinations) {
361:                 FieldSet newFieldCombo = new FieldSet();
362:                 for (Integer sourceField : fieldCombo) {
363:                     FieldSet targetField = props.getForwardingTargetFields(input, sourceField);
364: 
365:                     if (targetField == null || targetField.size() == 0) {
366:                         newFieldCombo = null;
367:                         break;
368:                     } else {
369:                         // use any field of target fields for now.  We should use something like
370:                         // field equivalence sets in the future.
371:                         if (targetField.size() > 1) {
372:                             LOG.warn(
373:                                     "Found that a field is forwarded to more than one target field in "
374:                                             + "semantic forwarded field information. Will only use the field with the lowest index.");
375:                         }
376:                         newFieldCombo = newFieldCombo.addField(targetField.toArray()[0]);
377:                     }
378:                 }
379:                 if (newFieldCombo != null) {
380:                     newUniqueFieldCombinations.add(newFieldCombo);
381:                 }
382:             }
383:             if (!newUniqueFieldCombinations.isEmpty()) {
384:                 gp.uniqueFieldCombinations = newUniqueFieldCombinations;
385:             }
386:         }
387: 
388:         return gp;
389:     }
