391:     public void parameterizeChannel(
392:             Channel channel,
393:             boolean globalDopChange,
394:             ExecutionMode exchangeMode,
395:             boolean breakPipeline) {
396: 
397:         ShipStrategyType shipType;
398:         FieldList partitionKeys;
399:         boolean[] sortDirection;
400:         Partitioner<?> partitioner;
401: 
402:         switch (this.partitioning) {
403:             case RANDOM_PARTITIONED:
404:                 shipType =
405:                         globalDopChange
406:                                 ? ShipStrategyType.PARTITION_RANDOM
407:                                 : ShipStrategyType.FORWARD;
408:                 partitionKeys = null;
409:                 sortDirection = null;
410:                 partitioner = null;
411:                 break;
412: 
413:             case FULL_REPLICATION:
414:                 shipType = ShipStrategyType.BROADCAST;
415:                 partitionKeys = null;
416:                 sortDirection = null;
417:                 partitioner = null;
418:                 break;
419: 
420:             case ANY_PARTITIONING:
421:             case HASH_PARTITIONED:
422:                 shipType = ShipStrategyType.PARTITION_HASH;
423:                 partitionKeys = Utils.createOrderedFromSet(this.partitioningFields);
424:                 sortDirection = null;
425:                 partitioner = null;
426:                 break;
427: 
428:             case RANGE_PARTITIONED:
429:                 shipType = ShipStrategyType.PARTITION_RANGE;
430:                 partitionKeys = this.ordering.getInvolvedIndexes();
431:                 sortDirection = this.ordering.getFieldSortDirections();
432:                 partitioner = null;
433:                 break;
434: 
435:             case FORCED_REBALANCED:
436:                 shipType = ShipStrategyType.PARTITION_RANDOM;
437:                 partitionKeys = null;
438:                 sortDirection = null;
439:                 partitioner = null;
440:                 break;
441: 
442:             case CUSTOM_PARTITIONING:
443:                 shipType = ShipStrategyType.PARTITION_CUSTOM;
444:                 partitionKeys = this.partitioningFields;
445:                 sortDirection = null;
446:                 partitioner = this.customPartitioner;
447:                 break;
448: 
449:             default:
450:                 throw new CompilerException("Unsupported partitioning strategy");
451:         }
452: 
453:         channel.setDataDistribution(this.distribution);
454:         DataExchangeMode exMode = DataExchangeMode.select(exchangeMode, shipType, breakPipeline);
455:         channel.setShipStrategy(shipType, partitionKeys, sortDirection, partitioner, exMode);
456:     }
