531:     /**
532:      * Adds a new virtual node that is used to connect a downstream vertex to only the outputs with
533:      * the selected side-output {@link OutputTag}.
534:      *
535:      * @param originalId ID of the node that should be connected to.
536:      * @param virtualId ID of the virtual node.
537:      * @param outputTag The selected side-output {@code OutputTag}.
538:      */
539:     public void addVirtualSideOutputNode(
540:             Integer originalId, Integer virtualId, OutputTag outputTag) {
541: 
542:         if (virtualSideOutputNodes.containsKey(virtualId)) {
543:             throw new IllegalStateException("Already has virtual output node with id " + virtualId);
544:         }
545: 
546:         // verify that we don't already have a virtual node for the given originalId/outputTag
547:         // combination with a different TypeInformation. This would indicate that someone is trying
548:         // to read a side output from an operation with a different type for the same side output
549:         // id.
550: 
551:         for (Tuple2<Integer, OutputTag> tag : virtualSideOutputNodes.values()) {
552:             if (!tag.f0.equals(originalId)) {
553:                 // different source operator
554:                 continue;
555:             }
556: 
557:             if (tag.f1.getId().equals(outputTag.getId())
558:                     && !tag.f1.getTypeInfo().equals(outputTag.getTypeInfo())) {
559:                 throw new IllegalArgumentException(
560:                         "Trying to add a side output for the same "
561:                                 + "side-output id with a different type. This is not allowed. Side-output ID: "
562:                                 + tag.f1.getId());
563:             }
564:         }
565: 
566:         virtualSideOutputNodes.put(virtualId, new Tuple2<>(originalId, outputTag));
567:     }
