574:      * to the original node, but with the partitioning given here.
575:      *
576:      * @param originalId ID of the node that should be connected to.
577:      * @param virtualId ID of the virtual node.
578:      * @param partitioner The partitioner
579:      */
580:     public void addVirtualPartitionNode(
581:             Integer originalId,
582:             Integer virtualId,
583:             StreamPartitioner<?> partitioner,
584:             StreamExchangeMode exchangeMode) {
585: 
586:         if (virtualPartitionNodes.containsKey(virtualId)) {
587:             throw new IllegalStateException(
