275:     @PublicEvolving
276:     public StreamExecutionEnvironment(
277:             final PipelineExecutorServiceLoader executorServiceLoader,
278:             final org.apache.flink.configuration.Configuration configuration,
279:             final ClassLoader userClassloader) {
280:         this.executorServiceLoader = checkNotNull(executorServiceLoader);
281:         this.configuration = new org.apache.flink.configuration.Configuration(checkNotNull(configuration));
282:         this.config = new ExecutionConfig(this.configuration);
283:         this.checkpointCfg = new CheckpointConfig(this.configuration);
284:         this.userClassloader =
285:                 userClassloader == null ? getClass().getClassLoader() : userClassloader;
286: 
287:         // the configuration of a job or an operator can be specified at the following places:
288:         //     i) at the operator level via e.g. parallelism by using the
289:         // SingleOutputStreamOperator.setParallelism().
290:         //     ii) programmatically by using e.g. the env.setRestartStrategy() method
291:         //     iii) in the configuration passed here
292:         //
293:         // if specified in multiple places, the priority order is the above.
294:         //
295:         // Given this, it is safe to overwrite the execution config default values here because all
296:         // other ways assume
297:         // that the env is already instantiated so they will overwrite the value passed here.
298:         this.configure(this.configuration, this.userClassloader);
299:     }
