425:     /**
426:      * Sets the maximum time frequency (milliseconds) for the flushing of the output buffers. By
427:      * default the output buffers flush frequently to provide low latency and to aid smooth
428:      * developer experience. Setting the parameter can result in three logical modes:
429:      *
430:      * <ul>
431:      *   <li>A positive integer triggers flushing periodically by that integer
432:      *   <li>0 triggers flushing after every record thus minimizing latency
433:      *   <li>-1 triggers flushing only when the output buffer is full thus maximizing throughput
434:      * </ul>
435:      *
436:      * @param timeoutMillis The maximum time between two output flushes.
437:      */
438:     public StreamExecutionEnvironment setBufferTimeout(long timeoutMillis) {
439:         if (timeoutMillis < ExecutionOptions.DISABLED_NETWORK_BUFFER_TIMEOUT) {
440:             throw new IllegalArgumentException("Timeout of buffer must be non-negative or -1");
441:         }
442: 
443:         if (timeoutMillis == ExecutionOptions.DISABLED_NETWORK_BUFFER_TIMEOUT) {
444:             this.configuration.set(ExecutionOptions.BUFFER_TIMEOUT_ENABLED, false);
445:         } else {
446:             this.configuration.set(
447:                     ExecutionOptions.BUFFER_TIMEOUT, Duration.ofMillis(timeoutMillis));
448:         }
449:         return this;
450:     }
451: 
452:     /**
453:      * Gets the maximum time frequency (milliseconds) for the flushing of the output buffers. For
454:      * clarification on the extremal values see {@link #setBufferTimeout(long)}.
455:      *
456:      * @return The timeout of the buffer.
457:      */
458:     public long getBufferTimeout() {
459:         return this.configuration.get(ExecutionOptions.BUFFER_TIMEOUT_ENABLED)
460:                 ? this.configuration.get(ExecutionOptions.BUFFER_TIMEOUT).toMillis()
461:                 : ExecutionOptions.DISABLED_NETWORK_BUFFER_TIMEOUT;
462:     }
