2265:     /**
2266:      * Triggers the program execution. The environment will execute all parts of the program that
2267:      * have resulted in a "sink" operation. Sink operations are for example printing results or
2268:      * forwarding them to a message queue.
2269:      *
2270:      * @param streamGraph the stream graph representing the transformations
2271:      * @return The result of the job execution, containing elapsed time and accumulators.
2272:      * @throws Exception which occurs during job execution.
2273:      */
2274:     @Internal
2275:     public JobExecutionResult execute(StreamGraph streamGraph) throws Exception {
2276:         final JobClient jobClient = executeAsync(streamGraph);
2277: 
2278:         try {
2279:             final JobExecutionResult jobExecutionResult;
2280: 
2281:             if (configuration.get(DeploymentOptions.ATTACHED)) {
2282:                 jobExecutionResult = jobClient.getJobExecutionResult().get();
2283:             } else {
2284:                 jobExecutionResult = new DetachedJobExecutionResult(jobClient.getJobID());
2285:             }
2286: 
2287:             jobListeners.forEach(
2288:                     jobListener -> jobListener.onJobExecuted(jobExecutionResult, null));
2289: 
2290:             return jobExecutionResult;
2291:         } catch (Throwable t) {
2292:             // get() on the JobExecutionResult Future will throw an ExecutionException. This
2293:             // behaviour was largely not there in Flink versions before the PipelineExecutor
2294:             // refactoring so we should strip that exception.
2295:             Throwable strippedException = ExceptionUtils.stripExecutionException(t);
2296: 
2297:             jobListeners.forEach(
2298:                     jobListener -> {
2299:                         jobListener.onJobExecuted(null, strippedException);
2300:                     });
2301:             ExceptionUtils.rethrowException(strippedException);
2302: 
2303:             // never reached, only make javac happy
2304:             return null;
2305:         }
2306:     }
