2493:         // We copy the transformation so that newly added transformations cannot intervene with the
2494:         // stream graph generation.
2495:         return new StreamGraphGenerator(
2496:                         new ArrayList<>(transformations), config, checkpointCfg, configuration)
2497:                 .setStateBackend(defaultStateBackend)
2498:                 .setTimeCharacteristic(getStreamTimeCharacteristic())
