306:     private static DataStream<OperatorState> getFinalOperatorStates(
307:             StreamExecutionEnvironment executionEnvironment,
308:             List<OperatorState> existingOperators,
309:             @Nullable DataStream<OperatorState> newOperatorStates,
310:             String path) {
311:         if (existingOperators.isEmpty()) {
312:             return newOperatorStates;
313:         }
314: 
315:         DataStream<OperatorState> existingOperatorStates =
316:                 executionEnvironment.fromData(existingOperators).name("existingOperatorStates");
317: 
318:         existingOperatorStates
319:                 .flatMap(new StatePathExtractor())
320:                 .setParallelism(1)
321:                 .addSink(new OutputFormatSinkFunction<>(new FileCopyFunction(path)));
322: 
323:         return newOperatorStates != null
324:                 ? newOperatorStates.union(existingOperatorStates)
325:                 : existingOperatorStates;
326:     }
