330:             org.apache.flink.configuration.Configuration config,
331:             Path savepointWritePath) {
332:         return newOperatorStates.stream()
333:                 .map(
334:                         newOperatorState ->
335:                                 newOperatorState
336:                                         .getBootstrapTransformation()
337:                                         .writeOperatorState(
338:                                                 newOperatorState.getOperatorIdentifier(),
339:                                                 stateBackend,
340:                                                 config,
341:                                                 metadata.getMaxParallelism(),
342:                                                 savepointWritePath))
343:                 .reduce(DataStream::union);
