346:     private static class CheckpointMetadataCheckpointMetadataMapFunction
347:             extends RichMapFunction<CheckpointMetadata, CheckpointMetadata> {
348:         private static final long serialVersionUID = 1L;
349: 
350:         private final Map<OperatorIdentifier, OperatorIdentifier> uidTransformationMap;
351: 
352:         public CheckpointMetadataCheckpointMetadataMapFunction(
353:                 Map<OperatorIdentifier, OperatorIdentifier> uidTransformationMap) {
354:             this.uidTransformationMap = new HashMap<>(uidTransformationMap);
355:         }
356: 
357:         @Override
358:         public CheckpointMetadata map(CheckpointMetadata value) throws Exception {
359:             final List<OperatorState> mapped =
360:                     value.getOperatorStates().stream()
361:                             .map(
362:                                     operatorState -> {
363:                                         OperatorIdentifier operatorIdentifier;
364:                                         if (operatorState.getOperatorUid().isPresent()) {
365:                                             operatorIdentifier =
366:                                                     OperatorIdentifier.forUid(
367:                                                             operatorState.getOperatorUid().get());
368:                                         } else {
369:                                             operatorIdentifier =
370:                                                     OperatorIdentifier.forUidHash(
371:                                                             operatorState
372:                                                                     .getOperatorID()
373:                                                                     .toHexString());
374:                                         }
375: 
376:                                         final OperatorIdentifier transformedIdentifier =
377:                                                 uidTransformationMap.remove(operatorIdentifier);
378:                                         if (transformedIdentifier != null) {
379:                                             return operatorState.copyWithNewIDs(
380:                                                     transformedIdentifier.getUid().orElse(null),
381:                                                     transformedIdentifier.getOperatorId());
382:                                         }
383:                                         return operatorState;
384:                                     })
385:                             .collect(Collectors.toList());
386:             return new CheckpointMetadata(value.getCheckpointId(), mapped, value.getMasterStates());
387:         }
388: 
389:         @Override
390:         public void close() throws Exception {
391:             if (!uidTransformationMap.isEmpty()) {
392:                 throw new FlinkRuntimeException(
393:                         "Some identifier changes were never applied!"
394:                                 + uidTransformationMap.entrySet().stream()
395:                                         .map(Map.Entry::toString)
396:                                         .collect(Collectors.joining("\n\t", "\n\t", "")));
397:             }
398:         }
