54: import static org.apache.flink.runtime.state.KeyGroupRangeAssignment.UPPER_BOUND_MAX_PARALLELISM;
55: 
56: /**
57:  * A {@code SavepointWriter} can create new savepoints from bounded data streams. This can allow for
58:  * boostrapping state for new applications or modifying the savepoints of existing jobs.
59:  */
60: @PublicEvolving
61: public class SavepointWriter {
62: 
63:     @Nullable private final StreamExecutionEnvironment executionEnvironment;
64: 
65:     private final Map<OperatorIdentifier, OperatorIdentifier> uidTransformationMap =
66:             new HashMap<>();
67: 
68:     /**
69:      * Loads an existing savepoint. Useful if you want to modify or extend the state of an existing
70:      * application. The savepoint will be written using the state backend defined via the clusters
71:      * configuration.
72:      *
73:      * @param path The path to an existing savepoint on disk.
74:      * @return A {@link SavepointWriter}.
75:      * @see #fromExistingSavepoint(StreamExecutionEnvironment, String, Configuration)
76:      * @see #withConfiguration(ConfigOption, Object)
77:      */
78:     public static SavepointWriter fromExistingSavepoint(
79:             StreamExecutionEnvironment executionEnvironment, String path) throws IOException {
80:         return new SavepointWriter(readSavepointMetadata(path), null, executionEnvironment);
81:     }
82: 
83:     /**
84:      * Loads an existing savepoint. Useful if you want to modify or extend the state of an existing
85:      * application.
86:      *
87:      * @param path The path to an existing savepoint on disk.
88:      * @param config The state backend of the savepoint.
89:      * @return A {@link SavepointWriter}.
90:      */
91:     public static SavepointWriter fromExistingSavepoint(
92:             StreamExecutionEnvironment executionEnvironment, String path, Configuration config)
93:             throws IOException {
94:         return new SavepointWriter(readSavepointMetadata(path), config, executionEnvironment);
95:     }
96: 
97:     private static SavepointMetadataV2 readSavepointMetadata(String path) throws IOException {
98:         CheckpointMetadata metadata = SavepointLoader.loadSavepointMetadata(path);
99: 
100:         int maxParallelism =
101:                 metadata.getOperatorStates().stream()
102:                         .map(OperatorState::getMaxParallelism)
103:                         .max(Comparator.naturalOrder())
104:                         .orElseThrow(
105:                                 () ->
106:                                         new RuntimeException(
107:                                                 "Savepoint must contain at least one operator state."));
108: 
109:         return new SavepointMetadataV2(
110:                 maxParallelism, metadata.getMasterStates(), metadata.getOperatorStates());
111:     }
112: 
113:     /**
114:      * Creates a new savepoint. The savepoint will be written using the state backend defined via
115:      * the clusters configuration.
116:      *
117:      * @param maxParallelism The max parallelism of the savepoint.
118:      * @return A {@link SavepointWriter}.
119:      * @see #newSavepoint(StreamExecutionEnvironment, Configuration, int)
120:      * @see #withConfiguration(ConfigOption, Object)
121:      */
122:     public static SavepointWriter newSavepoint(
123:             StreamExecutionEnvironment executionEnvironment, int maxParallelism) {
124:         return new SavepointWriter(
125:                 createSavepointMetadata(maxParallelism), null, executionEnvironment);
126:     }
127: 
128:     /**
129:      * Creates a new savepoint.
130:      *
131:      * @param stateBackend The state backend of the savepoint used for keyed state.
132:      * @param maxParallelism The max parallelism of the savepoint.
133:      * @return A {@link SavepointWriter}.
134:      * @see #newSavepoint(StreamExecutionEnvironment, int)
135:      */
136:     public static SavepointWriter newSavepoint(
137:             StreamExecutionEnvironment executionEnvironment,
138:             Configuration stateBackend,
139:             int maxParallelism) {
140:         return new SavepointWriter(
141:                 createSavepointMetadata(maxParallelism), stateBackend, executionEnvironment);
142:     }
143: 
144:     private static SavepointMetadataV2 createSavepointMetadata(int maxParallelism) {
145:         Preconditions.checkArgument(
146:                 maxParallelism > 0 && maxParallelism <= UPPER_BOUND_MAX_PARALLELISM,
147:                 "Maximum parallelism must be between 1 and "
148:                         + UPPER_BOUND_MAX_PARALLELISM
149:                         + ". Found: "
150:                         + maxParallelism);
151: 
152:         return new SavepointMetadataV2(
153:                 maxParallelism, Collections.emptyList(), Collections.emptyList());
154:     }
155: 
156:     /**
157:      * The savepoint metadata, which maintains the current set of existing / newly added operator
158:      * states.
159:      */
160:     protected final SavepointMetadataV2 metadata;
161: 
162:     /** The state backend to use when writing this savepoint. */
163:     @Nullable protected final Configuration stateBackend;
164: 
165:     private final org.apache.flink.configuration.Configuration configuration;
166: 
167:     private SavepointWriter(
168:             SavepointMetadataV2 metadata,
169:             @Nullable Configuration stateBackend,
170:             @Nullable StreamExecutionEnvironment executionEnvironment) {
171:         Preconditions.checkNotNull(metadata, "The savepoint metadata must not be null");
172:         this.metadata = metadata;
173:         this.stateBackend = stateBackend;
174:         this.configuration = new org.apache.flink.configuration.Configuration();
175:         this.executionEnvironment = executionEnvironment;
176:     }
177: 
178:     /**
179:      * Drop an existing operator from the savepoint.
180:      *
181:      * @param identifier The identifier of the operator.
182:      * @return A modified savepoint.
183:      */
184:     public SavepointWriter removeOperator(OperatorIdentifier identifier) {
185:         metadata.removeOperator(identifier);
186:         return this;
187:     }
188: 
189:     /**
190:      * Adds a new operator to the savepoint.
191:      *
192:      * @param identifier The identifier of the operator.
193:      * @param transformation The operator to be included.
194:      * @return The modified savepoint.
195:      */
196:     public <T> SavepointWriter withOperator(
197:             OperatorIdentifier identifier, StateBootstrapTransformation<T> transformation) {
198:         metadata.addOperator(identifier, transformation);
199:         return this;
200:     }
201: 
202:     /**
203:      * Sets a configuration that will be applied to the stream operators used to bootstrap a new
204:      * savepoint.
205:      *
206:      * @param option metadata information
207:      * @param value value to be stored
208:      * @param <T> type of the value to be stored
209:      * @return The modified savepoint.
210:      */
211:     public <T> SavepointWriter withConfiguration(ConfigOption<T> option, T value) {
212:         configuration.set(option, value);
213:         return this;
214:     }
215: 
216:     /**
217:      * Changes the identifier of an operator.
218:      *
219:      * <p>This method is comparatively cheap since it only modifies savepoint metadata without
220:      * reading the entire savepoint data.
221:      *
222:      * <p>Use-cases include, but are not limited to:
223:      *
224:      * <ul>
225:      *   <li>assigning a UID to an operator that did not have a UID assigned before
226:      *   <li>changing the UID of an operator
227:      *   <li>swapping the states of 2 operators
228:      * </ul>
229:      *
230:      * <p>Identifier changes are applied after all other operations; in the following example the
231:      * savepoint will only contain UID_2.
232:      *
233:      * <pre>
234:      *     SavepointWriter savepoint = ...
235:      *     savepoint.withOperator(UID_1, ...)
236:      *     savepoint.changeOperatorIdentifier(UID_1, UID_2)
237:      *     savepoint.write(...)
238:      * </pre>
239:      *
240:      * <p>You cannot define a chain of changes; in the following example the savepoint will only
241:      * contain UID_2.
242:      *
243:      * <pre>
244:      *     SavepointWriter savepoint = ...
245:      *     savepoint.withOperator(UID_1, ...)
246:      *     savepoint.changeOperatorIdentifier(UID_1, UID_2)
247:      *     savepoint.changeOperatorIdentifier(UID_2, UID_3)
248:      *     savepoint.write(...)
249:      * </pre>
250:      *
251:      * @param from operator whose identifier should be changed
252:      * @param to desired identifier
253:      * @return The modified savepoint.
254:      */
255:     public SavepointWriter changeOperatorIdentifier(
256:             OperatorIdentifier from, OperatorIdentifier to) {
257:         this.uidTransformationMap.put(from, to);
258:         return this;
259:     }
260: 
261:     /**
262:      * Write out a new or updated savepoint.
263:      *
264:      * @param path The path to where the savepoint should be written.
265:      */
266:     public final void write(String path) {
267:         final Path savepointPath = new Path(path);
268: 
269:         List<StateBootstrapTransformationWithID<?>> newOperatorTransformations =
270:                 metadata.getNewOperators();
271:         Optional<DataStream<OperatorState>> newOperatorStates =
272:                 writeOperatorStates(newOperatorTransformations, configuration, savepointPath);
273: 
274:         if (executionEnvironment == null && !newOperatorStates.isPresent()) {
275:             throw new IllegalStateException(
276:                     "Savepoint must contain at least one operator if no execution environment was provided.");
277:         }
278: 
279:         List<OperatorState> existingOperators = metadata.getExistingOperators();
280: 
281:         if (!newOperatorStates.isPresent() && existingOperators.isEmpty()) {
282:             throw new IllegalStateException(
283:                     "Savepoint must contain at least one operator to be created.");
284:         }
285: 
286:         getFinalOperatorStates(
287:                         executionEnvironment != null
288:                                 ? executionEnvironment
289:                                 : newOperatorStates.get().getExecutionEnvironment(),
290:                         existingOperators,
291:                         newOperatorStates.orElse(null),
292:                         path)
293:                 .transform(
294:                         "reduce(OperatorState)",
295:                         TypeInformation.of(CheckpointMetadata.class),
296:                         new GroupReduceOperator<>(
297:                                 new MergeOperatorStates(metadata.getMasterStates())))
298:                 .forceNonParallel()
299:                 .map(new CheckpointMetadataCheckpointMetadataMapFunction(this.uidTransformationMap))
300:                 .setParallelism(1)
301:                 .addSink(new OutputFormatSinkFunction<>(new SavepointOutputFormat(savepointPath)))
302:                 .setParallelism(1)
303:                 .name(path);
304:     }
305: 
306:     private static DataStream<OperatorState> getFinalOperatorStates(
307:             StreamExecutionEnvironment executionEnvironment,
308:             List<OperatorState> existingOperators,
309:             @Nullable DataStream<OperatorState> newOperatorStates,
310:             String path) {
311:         if (existingOperators.isEmpty()) {
312:             return newOperatorStates;
313:         }
314: 
315:         DataStream<OperatorState> existingOperatorStates =
316:                 executionEnvironment.fromData(existingOperators).name("existingOperatorStates");
317: 
318:         existingOperatorStates
319:                 .flatMap(new StatePathExtractor())
320:                 .setParallelism(1)
321:                 .addSink(new OutputFormatSinkFunction<>(new FileCopyFunction(path)));
322: 
323:         return newOperatorStates != null
324:                 ? newOperatorStates.union(existingOperatorStates)
325:                 : existingOperatorStates;
326:     }
327: 
328:     private Optional<DataStream<OperatorState>> writeOperatorStates(
329:             List<StateBootstrapTransformationWithID<?>> newOperatorStates,
330:             org.apache.flink.configuration.Configuration config,
331:             Path savepointWritePath) {
332:         return newOperatorStates.stream()
333:                 .map(
334:                         newOperatorState ->
335:                                 newOperatorState
336:                                         .getBootstrapTransformation()
337:                                         .writeOperatorState(
338:                                                 newOperatorState.getOperatorIdentifier(),
339:                                                 stateBackend,
340:                                                 config,
341:                                                 metadata.getMaxParallelism(),
342:                                                 savepointWritePath))
343:                 .reduce(DataStream::union);
344:     }
345: 
346:     private static class CheckpointMetadataCheckpointMetadataMapFunction
347:             extends RichMapFunction<CheckpointMetadata, CheckpointMetadata> {
348:         private static final long serialVersionUID = 1L;
349: 
350:         private final Map<OperatorIdentifier, OperatorIdentifier> uidTransformationMap;
351: 
352:         public CheckpointMetadataCheckpointMetadataMapFunction(
353:                 Map<OperatorIdentifier, OperatorIdentifier> uidTransformationMap) {
354:             this.uidTransformationMap = new HashMap<>(uidTransformationMap);
355:         }
356: 
357:         @Override
358:         public CheckpointMetadata map(CheckpointMetadata value) throws Exception {
359:             final List<OperatorState> mapped =
360:                     value.getOperatorStates().stream()
361:                             .map(
362:                                     operatorState -> {
363:                                         OperatorIdentifier operatorIdentifier;
364:                                         if (operatorState.getOperatorUid().isPresent()) {
365:                                             operatorIdentifier =
366:                                                     OperatorIdentifier.forUid(
367:                                                             operatorState.getOperatorUid().get());
368:                                         } else {
369:                                             operatorIdentifier =
370:                                                     OperatorIdentifier.forUidHash(
371:                                                             operatorState
372:                                                                     .getOperatorID()
373:                                                                     .toHexString());
374:                                         }
375: 
376:                                         final OperatorIdentifier transformedIdentifier =
377:                                                 uidTransformationMap.remove(operatorIdentifier);
378:                                         if (transformedIdentifier != null) {
379:                                             return operatorState.copyWithNewIDs(
380:                                                     transformedIdentifier.getUid().orElse(null),
381:                                                     transformedIdentifier.getOperatorId());
382:                                         }
383:                                         return operatorState;
384:                                     })
385:                             .collect(Collectors.toList());
386:             return new CheckpointMetadata(value.getCheckpointId(), mapped, value.getMasterStates());
387:         }
388: 
389:         @Override
390:         public void close() throws Exception {
391:             if (!uidTransformationMap.isEmpty()) {
392:                 throw new FlinkRuntimeException(
393:                         "Some identifier changes were never applied!"
394:                                 + uidTransformationMap.entrySet().stream()
395:                                         .map(Map.Entry::toString)
396:                                         .collect(Collectors.joining("\n\t", "\n\t", "")));
397:             }
398:         }
399:     }
400: }
