401:             final List<OperatorState> mapped =
402:                     value.getOperatorStates().stream()
403:                             .map(
404:                                     operatorState -> {
405:                                         OperatorIdentifier operatorIdentifier =
406:                                                 OperatorIdentifier.forUidHash(
407:                                                         operatorState
