161:     // To make the parallelization of the StreamConfig serialization easier, we use this map
162:     // to collect all the need-to-be-serialized objects. These objects will be serialized all at
163:     // once then.
164:     private final transient Map<String, Object> toBeSerializedConfigObjects = new HashMap<>();
165:     private final transient Map<Integer, CompletableFuture<StreamConfig>> chainedTaskFutures =
166:             new HashMap<>();
167:     private final transient CompletableFuture<StreamConfig> serializationFuture =
168:             new CompletableFuture<>();
