189:     /** Trigger the object config serialization and return the completable future. */
190:     public CompletableFuture<StreamConfig> triggerSerializationAndReturnFuture(
191:             Executor ioExecutor) {
192:         FutureUtils.combineAll(chainedTaskFutures.values())
193:                 .thenAcceptAsync(
194:                         chainedConfigs -> {
195:                             try {
196:                                 // Serialize all the objects to config.
197:                                 serializeAllConfigs();
198:                                 InstantiationUtil.writeObjectToConfig(
199:                                         chainedConfigs.stream()
200:                                                 .collect(
201:                                                         Collectors.toMap(
202:                                                                 StreamConfig::getVertexID,
203:                                                                 Function.identity())),
204:                                         this.config,
205:                                         CHAINED_TASK_CONFIG);
206:                                 serializationFuture.complete(this);
207:                             } catch (Throwable throwable) {
208:                                 serializationFuture.completeExceptionally(throwable);
209:                             }
210:                         },
211:                         ioExecutor);
212:         return serializationFuture;
213:     }
