215:     /**
216:      * Serialize all object configs synchronously. Only used for operators which need to reconstruct
217:      * the StreamConfig internally or test.
218:      */
219:     public void serializeAllConfigs() {
220:         toBeSerializedConfigObjects.forEach(
221:                 (key, object) -> {
222:                     try {
223:                         InstantiationUtil.writeObjectToConfig(object, this.config, key);
224:                     } catch (IOException e) {
225:                         throw new StreamTaskException(
226:                                 String.format("Could not serialize object for key %s.", key), e);
227:                     }
228:                 });
229:     }
