412:     public <T extends StreamOperatorFactory<?>> T getStreamOperatorFactory(ClassLoader cl) {
413:         try {
414:             checkState(
415:                     !removedKeys.contains(SERIALIZED_UDF),
416:                     String.format("%s has been removed.", SERIALIZED_UDF));
417:             return InstantiationUtil.readObjectFromConfig(this.config, SERIALIZED_UDF, cl);
418:         } catch (ClassNotFoundException e) {
419:             String classLoaderInfo = ClassLoaderUtil.getUserCodeClassLoaderInfo(cl);
420:             boolean loadableDoubleCheck = ClassLoaderUtil.validateClassLoadable(e, cl);
421: 
422:             String exceptionMessage =
423:                     "Cannot load user class: "
424:                             + e.getMessage()
425:                             + "\nClassLoader info: "
426:                             + classLoaderInfo
427:                             + (loadableDoubleCheck
428:                                     ? "\nClass was actually found in classloader - deserialization issue."
429:                                     : "\nClass not resolvable through given classloader.");
430: 
431:             throw new StreamTaskException(exceptionMessage, e);
432:         } catch (Exception e) {
433:             throw new StreamTaskException("Cannot instantiate user function.", e);
434:         }
435:     }
