618:     /**
619:      * A utility function that computes an "aggregated" state for the vertex.
620:      *
621:      * <p>This state is not used anywhere in the coordination, but can be used for display in
622:      * dashboards to as a summary for how the particular parallel operation represented by this
623:      * ExecutionJobVertex is currently behaving.
624:      *
625:      * <p>For example, if at least one parallel task is failed, the aggregate state is failed. If
626:      * not, and at least one parallel task is cancelling (or cancelled), the aggregate state is
627:      * cancelling (or cancelled). If all tasks are finished, the aggregate state is finished, and so
628:      * on.
629:      *
630:      * @param verticesPerState The number of vertices in each state (indexed by the ordinal of the
631:      *     ExecutionState values).
632:      * @param parallelism The parallelism of the ExecutionJobVertex
633:      * @return The aggregate state of this ExecutionJobVertex.
634:      */
635:     public static ExecutionState getAggregateJobVertexState(
636:             int[] verticesPerState, int parallelism) {
637:         if (verticesPerState == null || verticesPerState.length != ExecutionState.values().length) {
638:             throw new IllegalArgumentException(
639:                     "Must provide an array as large as there are execution states.");
640:         }
641: 
642:         if (verticesPerState[ExecutionState.FAILED.ordinal()] > 0) {
643:             return ExecutionState.FAILED;
644:         }
645:         if (verticesPerState[ExecutionState.CANCELING.ordinal()] > 0) {
646:             return ExecutionState.CANCELING;
647:         } else if (verticesPerState[ExecutionState.CANCELED.ordinal()] > 0) {
648:             return ExecutionState.CANCELED;
649:         } else if (verticesPerState[ExecutionState.INITIALIZING.ordinal()] > 0) {
650:             return ExecutionState.INITIALIZING;
651:         } else if (verticesPerState[ExecutionState.RUNNING.ordinal()] > 0) {
652:             return ExecutionState.RUNNING;
653:         } else if (verticesPerState[ExecutionState.FINISHED.ordinal()] > 0) {
654:             return verticesPerState[ExecutionState.FINISHED.ordinal()] == parallelism
655:                     ? ExecutionState.FINISHED
656:                     : ExecutionState.RUNNING;
657:         } else {
658:             // all else collapses under created
659:             return ExecutionState.CREATED;
660:         }
661:     }
