189:     @Override
190:     public void registerSharedStates(SharedStateRegistry stateRegistry, long checkpointID) {
191:         for (OperatorSubtaskState operatorSubtaskState : subtaskStatesByOperatorIdentifier.values()) {
192:             if (operatorSubtaskState != null) {
193:                 operatorSubtaskState.registerSharedStates(stateRegistry, checkpointID);
194:             }
195:         }
196:     }
197: 
198:     @Override
199:     public boolean equals(Object o) {
200:         if (this == o) {
201:             return true;
202:         }
203:         if (o == null || getClass() != o.getClass()) {
204:             return false;
205:         }
206: 
207:         TaskStateSnapshot that = (TaskStateSnapshot) o;
208: 
209:         return subtaskStatesByOperatorIdentifier.equals(that.subtaskStatesByOperatorIdentifier)
210:                 && isTaskDeployedAsFinished == that.isTaskDeployedAsFinished
211:                 && isTaskFinished == that.isTaskFinished;
212:     }
213: 
214:     @Override
215:     public int hashCode() {
216:         return Objects.hash(subtaskStatesByOperatorIdentifier, isTaskDeployedAsFinished, isTaskFinished);
217:     }
218: 
219:     @Override
220:     public String toString() {
221:         return "TaskOperatorSubtaskStates{"
222:                 + "subtaskStatesByOperatorID="
223:                 + subtaskStatesByOperatorIdentifier
224:                 + ", isTaskDeployedAsFinished="
225:                 + isTaskDeployedAsFinished
226:                 + ", isTaskFinished="
227:                 + isTaskFinished
228:                 + '}';
229:     }
230: 
231:     /** Returns the only valid mapping as ensured by {@link StateAssignmentOperation}. */
232:     private InflightDataRescalingDescriptor getMapping(
233:             Function<OperatorSubtaskState, InflightDataRescalingDescriptor> mappingExtractor) {
234:         return Iterators.getOnlyElement(
235:                 subtaskStatesByOperatorIdentifier.values().stream()
236:                         .map(mappingExtractor)
237:                         .filter(mapping -> !mapping.equals(NO_RESCALE))
238:                         .iterator(),
239:                 NO_RESCALE);
240:     }
