455:     /**
456:      * Tells this vertex to strictly co locate its subtasks with the subtasks of the given vertex.
457:      * Strict co-location implies that the n'th subtask of this vertex will run on the same parallel
458:      * computing instance (TaskManager) as the n'th subtask of the given vertex.
459:      *
460:      * <p>NOTE: Co-location is only possible between vertices in a slot sharing group.
461:      *
462:      * <p>NOTE: This vertex must (transitively) depend on the vertex to be co-located with. That
463:      * means that the respective vertex must be a (transitive) input of this vertex.
464:      *
465:      * @param strictlyCoLocatedWith The vertex whose subtasks to co-locate this vertex's subtasks
466:      *     with.
467:      * @throws IllegalArgumentException Thrown, if this vertex and the vertex to co-locate with are
468:      *     not in a common slot sharing group.
469:      * @see #setSlotSharingGroup(SlotSharingGroup)
470:      */
471:     public void setStrictlyCoLocatedWith(JobVertex strictlyCoLocatedWith) {
472:         if (this.slotSharingGroup == null
473:                 || this.slotSharingGroup != strictlyCoLocatedWith.slotSharingGroup) {
474:             throw new IllegalArgumentException(
475:                     "Strict co-location requires that both vertices are in the same slot sharing group.");
476:         }
477: 
478:         CoLocationGroupImpl thisGroup = this.coLocationGroup;
479:         CoLocationGroupImpl otherGroup = strictlyCoLocatedWith.coLocationGroup;
480: 
481:         if (otherGroup == null) {
482:             if (thisGroup == null) {
483:                 CoLocationGroupImpl group = new CoLocationGroupImpl(this, strictlyCoLocatedWith);
484:                 this.coLocationGroup = group;
485:                 strictlyCoLocatedWith.coLocationGroup = group;
486:             } else {
487:                 thisGroup.addVertex(strictlyCoLocatedWith);
488:                 strictlyCoLocatedWith.coLocationGroup = thisGroup;
489:             }
490:         } else {
491:             if (thisGroup == null) {
492:                 otherGroup.addVertex(this);
493:                 this.coLocationGroup = otherGroup;
494:             } else {
495:                 // both had yet distinct groups, we need to merge them
496:                 thisGroup.mergeInto(otherGroup);
497:             }
498:         }
499:     }
