472:         if (this.slotSharingGroup == null
473:                 || this.slotSharingGroup != strictlyCoLocatedWith.slotSharingGroup) {
474:             throw new IllegalArgumentException(
475:                     "Strict co-location requires that both vertices are in the same slot sharing group.");
476:         }
