488:                 strictlyCoLocatedWith.coLocationGroup = thisGroup;
489:             }
490:         } else {
491:             if (thisGroup == null) {
492:                 otherGroup.addVertex(this);
493:                 this.coLocationGroup = otherGroup;
494:             } else {
495:                 // both had yet distinct groups, we need to merge them
496:                 thisGroup.mergeInto(otherGroup);
