217:     /**
218:      * Creates a new {@code EmbeddedRocksDBStateBackend} for storing local state.
219:      *
220:      * @param enableIncrementalCheckpointing True if incremental checkpointing is enabled.
221:      */
222:     public EmbeddedRocksDBStateBackend(TernaryBoolean enableIncrementalCheckpointing) {
223:         this.enableIncrementalCheckpointing = enableIncrementalCheckpointing;
224:         this.numberOfTransferThreads = UNDEFINED_NUMBER_OF_TRANSFER_THREADS;
225:         this.nativeMetricOptions = new RocksDBNativeMetricOptions();
226:         this.memoryConfiguration = new RocksDBMemoryConfiguration();
227:         this.writeBatchSize = UNDEFINED_WRITE_BATCH_SIZE;
228:         this.overlapFractionThreshold = UNDEFINED_OVERLAP_FRACTION_THRESHOLD;
229:         this.rocksDBMemoryFactory = RocksDBMemoryFactory.DEFAULT;
230:         this.priorityQueueConfig = new RocksDBPriorityQueueConfig();
231:         this.useIngestDbRestoreMode = TernaryBoolean.UNDEFINED;
232:         this.incrementalRestoreAsyncCompactAfterRescale = TernaryBoolean.UNDEFINED;
233:         this.rescalingUseDeleteFilesInRange = TernaryBoolean.UNDEFINED;
234:         this.manualCompactionConfig = null;
235:     }
