551:     private RocksDBOptionsFactory configureOptionsFactory(
552:             @Nullable RocksDBOptionsFactory originalOptionsFactory,
553:             @Nullable String factoryClassName,
554:             ReadableConfig config,
555:             ClassLoader classLoader)
556:             throws DynamicCodeLoadingException {
557: 
558:         RocksDBOptionsFactory optionsFactory = null;
559: 
560:         if (originalOptionsFactory != null) {
561:             if (originalOptionsFactory instanceof ConfigurableRocksDBOptionsFactory) {
562:                 originalOptionsFactory =
563:                         ((ConfigurableRocksDBOptionsFactory) originalOptionsFactory)
564:                                 .configure(config);
565:             }
566:             LOG.info("Using application-defined options factory: {}.", originalOptionsFactory);
567: 
568:             optionsFactory = originalOptionsFactory;
569:         } else if (factoryClassName != null) {
570:             // Do nothing if user does not define any factory class.
571:             if (factoryClassName.equalsIgnoreCase(
572:                     DefaultConfigurableOptionsFactory.class.getName())) {
573:                 // From FLINK-24046, we deprecate the DefaultConfigurableOptionsFactory.
574:                 LOG.warn(
575:                         "{} is deprecated. Please remove this value from the configuration."
576:                                 + "It is safe to do so since the configurable options will be loaded "
577:                                 + "in other place. For more information, please refer to FLINK-24046.",
578:                         DefaultConfigurableOptionsFactory.class.getName());
579:             } else {
580:                 try {
581:                     Class<? extends RocksDBOptionsFactory> clazz =
582:                             Class.forName(factoryClassName, false, classLoader)
583:                                     .asSubclass(RocksDBOptionsFactory.class);
584: 
585:                     optionsFactory = clazz.newInstance();
586:                     if (optionsFactory instanceof ConfigurableRocksDBOptionsFactory) {
587:                         optionsFactory =
588:                                 ((ConfigurableRocksDBOptionsFactory) optionsFactory)
589:                                         .configure(config);
590:                     }
591:                     LOG.info("Using configured options factory: {}.", optionsFactory);
592: 
593:                 } catch (ClassNotFoundException e) {
594:                     throw new DynamicCodeLoadingException(
595:                             "Cannot find configured options factory class: " + factoryClassName, e);
596:                 } catch (ClassCastException | InstantiationException | IllegalAccessException e) {
597:                     throw new DynamicCodeLoadingException(
598:                             "The class configured under '"
599:                                     + RocksDBOptions.OPTIONS_FACTORY.key()
600:                                     + "' is not a valid options factory ("
601:                                     + factoryClassName
602:                                     + ')',
603:                             e);
604:                 }
605:             }
606:         }
607: 
608:         if (optionsFactory instanceof DefaultConfigurableOptionsFactory) {
609:             LOG.warn(
610:                     "{} is extending from {}, which is deprecated and will be removed in the "
611:                             + "future. It is highly recommended to directly implement the "
612:                             + "ConfigurableRocksDBOptionsFactory without extending the {}. "
613:                             + "For more information, please refer to FLINK-24046.",
614:                     optionsFactory,
615:                     DefaultConfigurableOptionsFactory.class.getName(),
616:                     DefaultConfigurableOptionsFactory.class.getName());
617:         }
618: 
619:         return optionsFactory;
620:     }
