889:     private ReadableConfig mergeConfigurableOptions(ReadableConfig base, ReadableConfig onTop) {
890:         if (base == null) {
891:             base = new Configuration();
892:         }
893:         Configuration configuration = new Configuration();
894:         Map<String, String> baseMap = base.toMap();
895:         Map<String, String> onTopMap = onTop.toMap();
896:         for (ConfigOption<?> option : RocksDBConfigurableOptions.CANDIDATE_CONFIGS) {
897:             Optional<?> baseValue = base.getOptional(option);
898:             Optional<?> topValue = onTop.getOptional(option);
899: 
900:             if (topValue.isPresent() || baseValue.isPresent()) {
901:                 Object validValue = topValue.isPresent() ? topValue.get() : baseValue.get();
902:                 RocksDBConfigurableOptions.checkArgumentValid(option, validValue);
903:                 String valueString =
904:                         topValue.isPresent()
905:                                 ? onTopMap.get(option.key())
906:                                 : baseMap.get(option.key());
907:                 configuration.setString(option.key(), valueString);
908:             }
909:         }
910:         return configuration;
911:     }
