956:     @VisibleForTesting
957:     static void ensureRocksDBIsLoaded(
958:             String tempDirectory, Supplier<NativeLibraryLoader> nativeLibraryLoaderSupplier)
959:             throws IOException {
960:         synchronized (EmbeddedRocksDBStateBackend.class) {
961:             if (!rocksDbInitialized) {
962: 
963:                 final File tempDirParent = new File(tempDirectory).getAbsoluteFile();
964:                 LOG.info(
965:                         "Attempting to load RocksDB native library and store it under '{}'",
966:                         tempDirParent);
967: 
968:                 Throwable lastException = null;
969:                 for (int attempt = 1; attempt <= ROCKSDB_LIB_LOADING_ATTEMPTS; attempt++) {
970:                     File rocksLibFolder = null;
971:                     try {
972:                         // when multiple instances of this class and RocksDB exist in different
973:                         // class loaders, then we can see the following exception:
974:                         // "java.lang.UnsatisfiedLinkError: Native Library
975:                         // /path/to/temp/dir/librocksdbjni-linux64.so
976:                         // already loaded in another class loader"
977: 
978:                         // to avoid that, we need to add a random element to the library file path
979:                         // (I know, seems like an unnecessary hack, since the JVM obviously can
980:                         // handle multiple
981:                         //  instances of the same JNI library being loaded in different class
982:                         // loaders, but
983:                         //  apparently not when coming from the same file path, so there we go)
984: 
985:                         rocksLibFolder = new File(tempDirParent, "rocksdb-lib-" + new AbstractID());
986: 
987:                         // make sure the temp path exists
988:                         LOG.debug(
989:                                 "Attempting to create RocksDB native library folder {}",
990:                                 rocksLibFolder);
991:                         // noinspection ResultOfMethodCallIgnored
992:                         rocksLibFolder.mkdirs();
993: 
994:                         // explicitly load the JNI dependency if it has not been loaded before
995:                         nativeLibraryLoaderSupplier
996:                                 .get()
997:                                 .loadLibrary(rocksLibFolder.getAbsolutePath());
998: 
999:                         // this initialization here should validate that the loading succeeded
1000:                         RocksDB.loadLibrary();
1001: 
1002:                         // seems to have worked
1003:                         LOG.info("Successfully loaded RocksDB native library");
1004:                         rocksDbInitialized = true;
1005:                         return;
1006:                     } catch (Throwable t) {
1007:                         lastException = t;
1008:                         LOG.debug("RocksDB JNI library loading attempt {} failed", attempt, t);
1009: 
1010:                         // try to force RocksDB to attempt reloading the library
1011:                         try {
1012:                             resetRocksDBLoadedFlag();
1013:                         } catch (Throwable tt) {
1014:                             LOG.debug(
1015:                                     "Failed to reset 'initialized' flag in RocksDB native code loader",
1016:                                     tt);
1017:                         }
1018: 
1019:                         FileUtils.deleteDirectoryQuietly(rocksLibFolder);
1020:                     }
1021:                 }
1022: 
1023:                 throw new IOException("Could not load the native RocksDB library", lastException);
1024:             }
1025:         }
1026:     }
1027: 
1028:     @VisibleForTesting
1029:     static void resetRocksDBLoadedFlag() throws Exception {
1030:         final Field initField =
1031:                 org.rocksdb.NativeLibraryLoader.class.getDeclaredField("initialized");
1032:         initField.setAccessible(true);
1033:         initField.setBoolean(null, false);
1034:     }
