1255:     /**
1256:      * In this weird construct, we are:
1257:      *
1258:      * <ul>
1259:      *   <li>1. We start a thread, which will...
1260:      *   <li>2. ... sleep for X ms, and enqueue another mail, that will...
1261:      *   <li>3. ... sleep for Y ms, and make the output available again
1262:      * </ul>
1263:      *
1264:      * <p>2nd step is to check that back pressure or idle counter is at least X. In the last 3rd
1265:      * step, we test whether this counter was paused for the duration of processing mails.
1266:      */
1267:     private static class WaitingThread extends Thread {
1268:         private final MailboxExecutor executor;
1269:         private final RunnableWithException resumeTask;
1270:         private final long sleepTimeInsideMail;
1271:         private final long sleepTimeOutsideMail;
1272:         private final TimerGauge sleepOutsideMailTimer;
1273: 
1274:         @Nullable private Exception asyncException;
1275: 
1276:         public WaitingThread(
1277:                 MailboxExecutor executor,
1278:                 RunnableWithException resumeTask,
1279:                 long sleepTimeInsideMail,
1280:                 long sleepTimeOutsideMail,
1281:                 TimerGauge sleepOutsideMailTimer) {
1282:             this.executor = executor;
1283:             this.resumeTask = resumeTask;
1284:             this.sleepTimeInsideMail = sleepTimeInsideMail;
1285:             this.sleepTimeOutsideMail = sleepTimeOutsideMail;
1286:             this.sleepOutsideMailTimer = sleepOutsideMailTimer;
1287:         }
1288: 
1289:         @Override
1290:         public void run() {
1291:             try {
1292:                 // Make sure that the Task thread actually starts measuring the backpressure before
1293:                 // we start the measured sleep. The WaitingThread is started from within the mailbox
1294:                 // so we should first wait until mailbox loop starts idling before we enter the
1295:                 // measured sleep
1296:                 while (!sleepOutsideMailTimer.isMeasuring()) {
1297:                     Thread.sleep(1);
