1680:                                 0); // disable the threshold to achieve exact buffer sizes
1681: 
1682:         final long throughputGate1 = 1024L;
1683:         final long throughputGate2 = 60 * 1024L;
1684:         final int inputChannelsGate1 = 1;
1685:         final int inputChannelsGate2 = 4;
