1958:     private static class RunningTask<T extends StreamTask<?, ?>> {
1959:         final T streamTask;
1960:         final CompletableFuture<Void> invocationFuture;
1961: 
1962:         RunningTask(T streamTask, CompletableFuture<Void> invocationFuture) {
1963:             this.streamTask = streamTask;
1964:             this.invocationFuture = invocationFuture;
1965:         }
1966: 
1967:         void waitForTaskCompletion(boolean cancelled) throws Exception {
1968:             try {
1969:                 invocationFuture.get();
1970:             } catch (Exception e) {
1971:                 if (cancelled) {
1972:                     assertThat(e).hasCauseInstanceOf(CancelTaskException.class);
1973:                 } else {
1974:                     throw e;
1975:                 }
1976:             }
1977:             assertThat(streamTask.isCanceled()).isEqualTo(cancelled);
1978:         }
1979:     }
1980: 
1981:     private static <T extends StreamTask<?, ?>> RunningTask<T> runTask(
1982:             SupplierWithException<T, Exception> taskFactory) throws Exception {
1983:         CompletableFuture<T> taskCreationFuture = new CompletableFuture<>();
1984:         CompletableFuture<Void> invocationFuture =
1985:                 CompletableFuture.runAsync(
1986:                         () -> {
1987:                             T task;
1988:                             try {
1989:                                 task = taskFactory.get();
1990:                                 taskCreationFuture.complete(task);
1991:                             } catch (Exception e) {
1992:                                 taskCreationFuture.completeExceptionally(e);
1993:                                 return;
1994:                             }
1995:                             try {
1996:                                 task.invoke();
1997:                             } catch (RuntimeException e) {
1998:                                 throw e;
1999:                             } catch (Exception e) {
2000:                                 throw new RuntimeException(e);
2001:                             }
2002:                         },
2003:                         Executors.newSingleThreadExecutor());
2004: 
2005:         // Wait until task is created.
2006:         return new RunningTask<>(taskCreationFuture.get(), invocationFuture);
2007:     }
