30: /** Maintains the configured parallelisms for vertices, which should be defined by a scheduler. */
31: public class DefaultVertexParallelismStore implements MutableVertexParallelismStore {
32: 
33:     private static final Function<Integer, Optional<String>> RESCALE_MAX_REJECT =
34:             maxParallelism -> Optional.of("Cannot change the max parallelism.");
35: 
36:     /**
37:      * Create a new {@link VertexParallelismStore} that reflects given {@link
38:      * JobResourceRequirements}.
39:      *
40:      * @param oldVertexParallelismStore old vertex parallelism store that serves as a base for the
41:      *     new one
42:      * @param jobResourceRequirements to apply over the old vertex parallelism store
43:      * @return new vertex parallelism store iff it was updated
44:      */
45:     public static Optional<VertexParallelismStore> applyJobResourceRequirements(
46:             VertexParallelismStore oldVertexParallelismStore,
47:             JobResourceRequirements jobResourceRequirements) {
48:         final DefaultVertexParallelismStore newVertexParallelismStore =
49:                 new DefaultVertexParallelismStore();
50:         boolean changed = false;
51:         for (final JobVertexID jobVertexId : jobResourceRequirements.getJobVertices()) {
52:             final VertexParallelismInformation oldVertexParallelismInfo =
53:                     oldVertexParallelismStore.getParallelismInfo(jobVertexId);
54:             final JobVertexResourceRequirements.Parallelism parallelismSettings =
55:                     jobResourceRequirements.getParallelism(jobVertexId);
56:             final int minParallelism = parallelismSettings.getLowerBound();
57:             final int parallelism = parallelismSettings.getUpperBound();
58:             newVertexParallelismStore.setParallelismInfo(
59:                     jobVertexId,
60:                     new DefaultVertexParallelismInfo(
61:                             minParallelism,
62:                             parallelism,
63:                             oldVertexParallelismInfo.getMaxParallelism(),
64:                             RESCALE_MAX_REJECT));
65:             changed |=
66:                     oldVertexParallelismInfo.getMinParallelism() != minParallelism
67:                             || oldVertexParallelismInfo.getParallelism() != parallelism;
68:         }
69:         return changed ? Optional.of(newVertexParallelismStore) : Optional.empty();
70:     }
