205:     private static void closeInExecutorService(
206:             @Nullable AdaptiveScheduler scheduler, ComponentMainThreadExecutor executor) {
207:         if (scheduler != null) {
208:             final CompletableFuture<Void> closeFuture = new CompletableFuture<>();
209:             executor.execute(
210:                     () -> {
211:                         try {
212:                             // no matter what state the scheduler is in; we have to go to Finished
213:                             // state to please the Preconditions of the close call
214:                             if (scheduler.getState().getClass() != Finished.class) {
215:                                 scheduler.goToFinished(
216:                                         scheduler.getArchivedExecutionGraph(
217:                                                 JobStatus.CANCELED, null));
218:                             }
219:                             FutureUtils.forward(scheduler.closeAsync(), closeFuture);
220:                         } catch (Throwable t) {
221:                             closeFuture.completeExceptionally(t);
222:                         }
223:                     });
224:             assertThatFuture(closeFuture).eventuallySucceeds();
225:         }
226:     }
