538:         final ManuallyTriggeredComponentMainThreadExecutor mainThreadExecutor =
539:                 new ManuallyTriggeredComponentMainThreadExecutor(Thread.currentThread());
540:         final Duration resourceTimeout = Duration.ofMinutes(1234);
541:         final Configuration configuration = new Configuration();
