555:         // check whether some task was scheduled with the expected timeout
556:         // this is technically not really safe, but the chosen timeout value
557:         // is odd enough that it realistically won't cause issues.
558:         // With this approach we don't have to make assumption as to how many
559:         // tasks are being scheduled.
560:         final boolean b =
561:                 mainThreadExecutor.getActiveNonPeriodicScheduledTask().stream()
562:                         .anyMatch(
563:                                 scheduledTask ->
564:                                         scheduledTask.getDelay(TimeUnit.MINUTES)
565:                                                 == resourceTimeout.toMinutes());
566:         assertThat(b).isTrue();
567:     }
