585:                 new DefaultDeclarativeSlotPool(
586:                         jobGraph.getJobID(),
587:                         new DefaultAllocatedSlotPool(),
588:                         ignored -> {},
589:                         Duration.ofMinutes(10),
590:                         Duration.ofMinutes(10),
591:                         Duration.ZERO,
592:                         mainThreadExecutor);
593: 
594:         final Configuration configuration = createConfigurationWithNoTimeouts();
595:         configuration.set(JobManagerOptions.MIN_PARALLELISM_INCREASE, 1);
596: 
597:         scheduler =
598:                 new AdaptiveSchedulerBuilder(
599:                                 jobGraph,
600:                                 singleThreadMainThreadExecutor,
601:                                 EXECUTOR_RESOURCE.getExecutor())
602:                         .setJobMasterConfiguration(configuration)
603:                         .setJobManagerJobMetricGroup(
604:                                 JobManagerMetricGroup.createJobManagerMetricGroup(
605:                                                 metricRegistry, "localhost")
606:                                         .addJob(new JobID(), "jobName"))
607:                         .setDeclarativeSlotPool(declarativeSlotPool)
608:                         .build();
609: 
610:         final Gauge<Long> numRestartsMetric = numRestartsMetricFuture.get();
611: 
612:         final SubmissionBufferingTaskManagerGateway taskManagerGateway =
613:                 new SubmissionBufferingTaskManagerGateway(1 + PARALLELISM);
614: 
615:         taskManagerGateway.setCancelConsumer(createCancelConsumer(scheduler));
616: 
617:         startTestInstanceInMainThread();
618:         runInMainThread(
619:                 () ->
620:                         declarativeSlotPool.offerSlots(
621:                                 createSlotOffersForResourceRequirements(
622:                                         ResourceCounter.withResource(ResourceProfile.UNKNOWN, 1)),
623:                                 new LocalTaskManagerLocation(),
624:                                 taskManagerGateway,
625:                                 System.currentTimeMillis()));
626: 
627:         // wait for the first task submission
628:         taskManagerGateway.waitForSubmissions(1);
629: 
630:         assertThat(numRestartsMetric.getValue()).isEqualTo(0L);
631: 
632:         // offer more slots, which will cause a restart in order to scale up
633:         runInMainThread(
634:                 () ->
635:                         offerSlots(
636:                                 declarativeSlotPool,
637:                                 createSlotOffersForResourceRequirements(
638:                                         ResourceCounter.withResource(
639:                                                 ResourceProfile.UNKNOWN, PARALLELISM)),
640:                                 taskManagerGateway));
641: 
642:         // wait for the second task submissions
643:         taskManagerGateway.waitForSubmissions(PARALLELISM);
644: 
645:         assertThat(numRestartsMetric.getValue()).isEqualTo(1L);
646:     }
