1037:     @Test
1038:     void testConsistentMaxParallelism() throws Exception {
1039:         final int parallelism = 240;
1040:         final int expectedMaxParallelism =
1041:                 KeyGroupRangeAssignment.computeDefaultMaxParallelism(parallelism);
1042:         final JobVertex vertex = createNoOpVertex(parallelism);
1043:         final JobGraph jobGraph = streamingJobGraph(vertex);
1044: 
1045:         final DefaultDeclarativeSlotPool declarativeSlotPool =
1046:                 createDeclarativeSlotPool(jobGraph.getJobID());
1047: 
1048:         scheduler =
1049:                 new AdaptiveSchedulerBuilder(
1050:                                 jobGraph,
1051:                                 singleThreadMainThreadExecutor,
1052:                                 EXECUTOR_RESOURCE.getExecutor())
1053:                         .setDeclarativeSlotPool(declarativeSlotPool)
1054:                         .setJobMasterConfiguration(createConfigurationWithNoTimeouts())
1055:                         .build();
1056: 
1057:         final SubmissionBufferingTaskManagerGateway taskManagerGateway =
1058:                 new SubmissionBufferingTaskManagerGateway(1 + parallelism);
1059:         taskManagerGateway.setCancelConsumer(createCancelConsumer(scheduler));
1060: 
1061:         // offer just enough resources to run at the lowest possible parallelism
1062:         singleThreadMainThreadExecutor.execute(
1063:                 () -> {
1064:                     scheduler.startScheduling();
1065:                     offerSlots(
1066:                             declarativeSlotPool,
1067:                             createSlotOffersForResourceRequirements(
1068:                                     ResourceCounter.withResource(ResourceProfile.UNKNOWN, 1)),
1069:                             taskManagerGateway);
1070:                 });
1071: 
1072:         // Wait for task to be submitted
1073:         taskManagerGateway.waitForSubmissions(1);
1074: 
1075:         ArchivedExecutionGraph executionGraph =
1076:                 getArchivedExecutionGraphForRunningJob(scheduler).get();
1077:         ArchivedExecutionJobVertex archivedVertex = executionGraph.getJobVertex(vertex.getID());
1078: 
1079:         // ensure that the parallelism was submitted based on what is available
1080:         assertThat(archivedVertex.getParallelism()).isOne();
1081:         // and that the max parallelism was submitted based on what was configured
1082:         assertThat(archivedVertex.getMaxParallelism()).isEqualTo(expectedMaxParallelism);
1083: 
1084:         // offer the resources to run at full parallelism
1085:         singleThreadMainThreadExecutor.execute(
1086:                 () -> {
1087:                     offerSlots(
1088:                             declarativeSlotPool,
1089:                             createSlotOffersForResourceRequirements(
1090:                                     ResourceCounter.withResource(
1091:                                             ResourceProfile.UNKNOWN, parallelism)),
1092:                             taskManagerGateway);
1093:                 });
1094: 
1095:         // wait for the job to be re-submitted
1096:         taskManagerGateway.waitForSubmissions(parallelism);
1097: 
1098:         ArchivedExecutionGraph resubmittedExecutionGraph =
1099:                 getArchivedExecutionGraphForRunningJob(scheduler).get();
1100:         ArchivedExecutionJobVertex resubmittedArchivedVertex =
1101:                 resubmittedExecutionGraph.getJobVertex(vertex.getID());
1102: 
1103:         // ensure that the parallelism was submitted based on what is available
1104:         assertThat(resubmittedArchivedVertex.getParallelism()).isEqualTo(parallelism);
1105:         // and that the max parallelism was submitted based on what was configured
1106:         assertThat(resubmittedArchivedVertex.getMaxParallelism()).isEqualTo(expectedMaxParallelism);
1107:     }
