1326:                 createSubmissionBufferingTaskManagerGateway(PARALLELISM, scheduler);
1327: 
1328:         startJobWithSlotsMatchingParallelism(
1329:                 scheduler, declarativeSlotPool, taskManagerGateway, availableSlots);
1330: 
1331:         // unlock job by decreasing the parallelism
1332:         JobResourceRequirements newJobResourceRequirements =
1333:                 createRequirementsWithLowerAndUpperParallelism(availableSlots, PARALLELISM);
1334:         singleThreadMainThreadExecutor.execute(
1335:                 () -> scheduler.updateJobResourceRequirements(newJobResourceRequirements));
1336: 
1337:         awaitJobReachingParallelism(taskManagerGateway, scheduler, availableSlots);
1338:     }
