1348:     private AdaptiveSchedulerBuilder prepareSchedulerWithNoTimeouts(
1349:             JobGraph jobGraph, DeclarativeSlotPool declarativeSlotPool) {
1350:         return new AdaptiveSchedulerBuilder(
1351:                         jobGraph, singleThreadMainThreadExecutor, EXECUTOR_RESOURCE.getExecutor())
1352:                 .setDeclarativeSlotPool(declarativeSlotPool)
1353:                 .setJobMasterConfiguration(createConfigurationWithNoTimeouts());
1354:     }
1355: 
1356:     private AdaptiveScheduler createSchedulerWithNoTimeouts(
1357:             JobGraph jobGraph, DeclarativeSlotPool declarativeSlotPool) throws Exception {
1358:         return prepareSchedulerWithNoTimeouts(jobGraph, declarativeSlotPool).build();
1359:     }
