1361:     private SubmissionBufferingTaskManagerGateway createSubmissionBufferingTaskManagerGateway(
1362:             int parallelism, SchedulerNG scheduler) {
1363:         SubmissionBufferingTaskManagerGateway taskManagerGateway =
1364:                 new SubmissionBufferingTaskManagerGateway(parallelism);
1365:         taskManagerGateway.setCancelConsumer(
1366:                 executionAttemptID ->
1367:                         singleThreadMainThreadExecutor.execute(
1368:                                 () ->
1369:                                         scheduler.updateTaskExecutionState(
1370:                                                 new TaskExecutionState(
1371:                                                         executionAttemptID,
1372:                                                         ExecutionState.CANCELED))));
1373:         return taskManagerGateway;
1374:     }
1375: 
1376:     private void startJobWithSlotsMatchingParallelism(
1377:             SchedulerNG scheduler,
1378:             DeclarativeSlotPool declarativeSlotPool,
1379:             TaskManagerGateway taskManagerGateway,
1380:             int parallelism) {
1381:         singleThreadMainThreadExecutor.execute(
1382:                 () -> {
1383:                     scheduler.startScheduling();
1384:                     offerSlots(
1385:                             declarativeSlotPool,
1386:                             createSlotOffersForResourceRequirements(
1387:                                     ResourceCounter.withResource(
1388:                                             ResourceProfile.UNKNOWN, parallelism)),
1389:                             taskManagerGateway);
1390:                 });
1391:     }
1392: 
1393:     private void awaitJobReachingParallelism(
1394:             SubmissionBufferingTaskManagerGateway taskManagerGateway,
1395:             SchedulerNG scheduler,
1396:             int parallelism)
1397:             throws Exception {
1398:         // Wait for all tasks to be submitted
1399:         taskManagerGateway.waitForSubmissions(parallelism);
1400: 
1401:         final ArchivedExecutionGraph executionGraph =
1402:                 CompletableFuture.supplyAsync(
1403:                                 () -> scheduler.requestJob().getArchivedExecutionGraph(),
1404:                                 singleThreadMainThreadExecutor)
1405:                         .get();
1406: 
1407:         assertThat(executionGraph.getJobVertex(JOB_VERTEX.getID()).getParallelism())
1408:                 .isEqualTo(parallelism);
1409:     }
1410: 
1411:     private static JobResourceRequirements createRequirementsWithUpperParallelism(int parallelism) {
1412:         return createRequirementsWithLowerAndUpperParallelism(1, parallelism);
1413:     }
1414: 
1415:     private static JobResourceRequirements createRequirementsWithEqualLowerAndUpperParallelism(
1416:             int parallelism) {
1417:         return createRequirementsWithLowerAndUpperParallelism(parallelism, parallelism);
1418:     }
1419: 
1420:     private static JobResourceRequirements createRequirementsWithLowerAndUpperParallelism(
1421:             int lowerParallelism, int upperParallelism) {
1422:         return new JobResourceRequirements(
1423:                 Collections.singletonMap(
1424:                         JOB_VERTEX.getID(),
1425:                         new JobVertexResourceRequirements(
1426:                                 new JobVertexResourceRequirements.Parallelism(
1427:                                         lowerParallelism, upperParallelism))));
1428:     }
