1073:     @Override
1074:     public boolean hasDesiredResources() {
1075:         final Collection<? extends SlotInfo> freeSlots =
1076:                 declarativeSlotPool.getFreeSlotTracker().getFreeSlotsInformation();
1077:         return hasDesiredResources(desiredResources, freeSlots);
