558:     private static void assertPreconditions(JobGraph jobGraph) throws RuntimeException {
559:         Preconditions.checkState(
560:                 jobGraph.getJobType() == JobType.STREAMING,
561:                 "The adaptive scheduler only supports streaming jobs.");
562: 
563:         for (JobVertex vertex : jobGraph.getVertices()) {
564:             Preconditions.checkState(
565:                     vertex.getParallelism() > 0,
566:                     "The adaptive scheduler expects the parallelism being set for each JobVertex (violated JobVertex: %s).",
567:                     vertex.getID());
568:             for (JobEdge jobEdge : vertex.getInputs()) {
569:                 Preconditions.checkState(
570:                         jobEdge.getSource()
571:                                 .getResultType()
572:                                 .isPipelinedOrPipelinedBoundedResultPartition(),
573:                         "The adaptive scheduler supports pipelined data exchanges (violated by %s -> %s).",
574:                         jobEdge.getSource().getProducer(),
575:                         jobEdge.getTarget().getID());
576:             }
577:         }
578:     }
