1107:     private JobSchedulingPlan determineParallelism(
1108:             SlotAllocator slotAllocator, @Nullable ExecutionGraph previousExecutionGraph)
1109:             throws NoResourceAvailableException {
1110: 
1111:         return slotAllocator
