2020:     @Test
2021:     void testIdleSlotsAreReleasedAfterDownScalingTriggeredByLoweredResourceRequirements()
2022:             throws Exception {
2023:         final JobGraph jobGraph = createJobGraph();
2024:         final Duration slotIdleTimeout = Duration.ofMillis(10);
2025: 
2026:         final Configuration configuration = createConfigurationWithNoTimeouts();
2027:         configuration.set(JobManagerOptions.SLOT_IDLE_TIMEOUT, slotIdleTimeout);
2028: 
2029:         final DeclarativeSlotPool declarativeSlotPool =
2030:                 createDeclarativeSlotPool(jobGraph.getJobID(), slotIdleTimeout);
2031:         scheduler =
2032:                 new AdaptiveSchedulerBuilder(
2033:                                 jobGraph,
2034:                                 singleThreadMainThreadExecutor,
2035:                                 EXECUTOR_RESOURCE.getExecutor())
2036:                         .setDeclarativeSlotPool(declarativeSlotPool)
2037:                         .setJobMasterConfiguration(configuration)
2038:                         .build();
2039: 
2040:         final int numInitialSlots = 4;
2041:         final int numSlotsAfterDownscaling = 2;
2042: 
2043:         final SubmissionBufferingTaskManagerGateway taskManagerGateway =
2044:                 new SubmissionBufferingTaskManagerGateway(numInitialSlots);
2045: 
2046:         taskManagerGateway.setCancelConsumer(createCancelConsumer(scheduler));
2047: 
2048:         singleThreadMainThreadExecutor.execute(
2049:                 () -> {
2050:                     scheduler.startScheduling();
2051:                     offerSlots(
2052:                             declarativeSlotPool,
2053:                             createSlotOffersForResourceRequirements(
2054:                                     ResourceCounter.withResource(
2055:                                             ResourceProfile.UNKNOWN, numInitialSlots)),
2056:                             taskManagerGateway);
2057:                 });
2058: 
2059:         // wait for all tasks to be submitted
2060:         taskManagerGateway.waitForSubmissions(numInitialSlots);
2061: 
2062:         // lower the resource requirements
2063:         singleThreadMainThreadExecutor.execute(
2064:                 () ->
2065:                         scheduler.updateJobResourceRequirements(
2066:                                 JobResourceRequirements.newBuilder()
2067:                                         .setParallelismForJobVertex(
2068:                                                 JOB_VERTEX.getID(), 1, numSlotsAfterDownscaling)
2069:                                         .build()));
2070: 
2071:         // job should be resubmitted with lower parallelism
2072:         taskManagerGateway.waitForSubmissions(numSlotsAfterDownscaling);
2073: 
2074:         // and excessive slots should be freed
2075:         taskManagerGateway.waitForFreedSlots(numInitialSlots - numSlotsAfterDownscaling);
2076: 
2077:         final CompletableFuture<JobStatus> jobStatusFuture = new CompletableFuture<>();
2078:         singleThreadMainThreadExecutor.execute(
2079:                 () -> jobStatusFuture.complete(scheduler.getState().getJobStatus()));
2080:         assertThatFuture(jobStatusFuture).eventuallySucceeds().isEqualTo(JobStatus.RUNNING);
2081: 
2082:         // make sure we haven't freed up any more slots
2083:         assertThat(taskManagerGateway.freedSlots).isEmpty();
2084:     }
