2202:     private void testCheckpointStatsEventBeingExecutedInTheMainThread(
2203:             Consumer<CheckpointStatsListener> eventCallback,
2204:             int eventRepetitions,
2205:             int triggerOnFailedCheckpointCount)
2206:             throws Exception {
2207: 
2208:         final CompletableFuture<CheckpointStatsListener> statsListenerInstantiatedFuture =
2209:                 new CompletableFuture<>();
2210:         final BlockingQueue<Integer> eventQueue = new ArrayBlockingQueue<>(1);
2211: 
2212:         scheduler =
2213:                 createSchedulerThatReachesExecutingState(
2214:                         PARALLELISM,
2215:                         triggerOnFailedCheckpointCount,
2216:                         eventQueue,
2217:                         statsListenerInstantiatedFuture);
2218: 
2219:         // start scheduling to reach Executing state
2220:         singleThreadMainThreadExecutor.execute(scheduler::startScheduling);
2221: 
2222:         final CheckpointStatsListener statsListener = statsListenerInstantiatedFuture.get();
2223:         assertThat(statsListener)
2224:                 .as("The CheckpointStatsListener should have been instantiated.")
2225:                 .isNotNull();
2226: 
2227:         // the first trigger happens in the Executing initialization - let's wait for that event
2228:         // to pass
2229:         assertThat(eventQueue.take())
2230:                 .as(
2231:                         "The first event should have been appeared during Executing state initialization and should be ignored.")
2232:                 .isEqualTo(0);
2233: 
2234:         // counting the failed checkpoints only starts on a change event
2235:         scheduler.updateJobResourceRequirements(
2236:                 JobResourceRequirements.newBuilder()
2237:                         .setParallelismForJobVertex(JOB_VERTEX.getID(), 1, PARALLELISM - 1)
2238:                         .build());
2239: 
2240:         for (int i = 0; i < eventRepetitions; i++) {
2241:             assertThatNoException()
2242:                     .as(
2243:                             "Triggering the event from outside the main thread should not have caused an error.")
2244:                     .isThrownBy(() -> eventCallback.accept(statsListener));
2245:         }
2246: 
2247:         assertThat(eventQueue.take()).as("Only one event should have been observed.").isEqualTo(1);
2248:     }
