2389:     /**
2390:      * A {@link SimpleAckingTaskManagerGateway} that buffers all the task submissions into a
2391:      * blocking queue, allowing one to wait for an arbitrary number of submissions.
2392:      */
2393:     public static class SubmissionBufferingTaskManagerGateway
2394:             extends SimpleAckingTaskManagerGateway {
2395:         final BlockingQueue<TaskDeploymentDescriptor> submittedTasks;
2396:         final BlockingQueue<AllocationID> freedSlots;
2397: 
2398:         public SubmissionBufferingTaskManagerGateway(int capacity) {
2399:             submittedTasks = new ArrayBlockingQueue<>(capacity);
2400:             freedSlots = new ArrayBlockingQueue<>(capacity);
2401:             initializeFunctions();
2402:         }
2403: 
2404:         @Override
2405:         public void setSubmitConsumer(Consumer<TaskDeploymentDescriptor> submitConsumer) {
2406:             super.setSubmitConsumer(
2407:                     taskDeploymentDescriptor -> {
2408:                         Preconditions.checkState(submittedTasks.offer(taskDeploymentDescriptor));
2409:                         submitConsumer.accept(taskDeploymentDescriptor);
2410:                     });
2411:         }
2412: 
2413:         @Override
2414:         public void setFreeSlotFunction(
2415:                 BiFunction<AllocationID, Throwable, CompletableFuture<Acknowledge>>
2416:                         freeSlotFunction) {
2417:             super.setFreeSlotFunction(
2418:                     (allocationID, throwable) -> {
2419:                         Preconditions.checkState(freedSlots.offer(allocationID));
2420:                         return freeSlotFunction.apply(allocationID, throwable);
2421:                     });
2422:         }
2423: 
2424:         /**
2425:          * Block until an arbitrary number of submissions have been received.
2426:          *
2427:          * @param numSubmissions The number of submissions to wait for
2428:          * @return the list of the waited-for submissions
2429:          * @throws InterruptedException if a timeout is exceeded waiting for a submission
2430:          */
2431:         public List<TaskDeploymentDescriptor> waitForSubmissions(int numSubmissions)
2432:                 throws InterruptedException {
2433:             List<TaskDeploymentDescriptor> descriptors = new ArrayList<>();
2434:             for (int i = 0; i < numSubmissions; i++) {
2435:                 descriptors.add(submittedTasks.take());
2436:             }
2437:             return descriptors;
2438:         }
2439: 
2440:         public List<AllocationID> waitForFreedSlots(int numFreedSlots) throws InterruptedException {
2441:             final List<AllocationID> allocationIds = new ArrayList<>();
2442:             for (int i = 0; i < numFreedSlots; i++) {
2443:                 allocationIds.add(freedSlots.take());
2444:             }
2445:             return allocationIds;
2446:         }
2447: 
2448:         private void initializeFunctions() {
2449:             setSubmitConsumer(ignored -> {});
2450:             setFreeSlotFunction(
2451:                     (allocationId, throwable) ->
2452:                             CompletableFuture.completedFuture(Acknowledge.get()));
2453:         }
2454:     }
