557:             Executing executing =
558:                     new ExecutingStateBuilder()
559:                             .setExecutionGraph(finishingMockExecutionGraph)
560:                             .build(ctx);
561: 
562:             // ideally we'd delay the async call to #onGloballyTerminalState instead, but the
563:             // context does not support that
564:             ctx.setExpectFinished(eg -> {});
565: 
566:             finishingMockExecutionGraph.completeTerminationFuture(JobStatus.FINISHED);
567: 
568:             // this is just a sanity check for the test
569:             assertThat(executing.getExecutionGraph().getState()).isEqualTo(JobStatus.FINISHED);
570: 
571:             assertThat(executing.getJobStatus()).isEqualTo(JobStatus.RUNNING);
572:             assertThat(executing.getJob().getState()).isEqualTo(JobStatus.RUNNING);
573:             assertThat(executing.getJob().getStatusTimestamp(JobStatus.FINISHED)).isZero();
574:         }
575:     }
