254:     @Test
255:     public void testOnCompletedCheckpointResetsFailedCheckpointCount() throws Exception {
256:         final AtomicInteger rescaleTriggeredCount = new AtomicInteger();
257:         final StateTransitionManager.Factory rescaleManagerFactory =
258:                 new TestingStateTransitionManager.Factory(() -> {}, rescaleTriggeredCount::incrementAndGet);
259:         final int rescaleOnFailedCheckpointsCount = 3;
260:         try (MockExecutingContext ctx = new MockExecutingContext()) {
261:             final Executing testInstance =
262:                     new ExecutingStateBuilder()
263:                             .setStateTransitionManagerFactory(rescaleManagerFactory)
264:                             .setRescaleOnFailedCheckpointCount(rescaleOnFailedCheckpointsCount)
265:                             .build(ctx);
266: 
267:             // trigger an initial failed checkpoint event to show that the counting only starts with
268:             // the subsequent change event
269:             testInstance.onFailedCheckpoint();
270: 
271:             // trigger change
272:             testInstance.onNewResourcesAvailable();
273: 
274:             IntStream.range(0, rescaleOnFailedCheckpointsCount - 1)
275:                     .forEach(ignored -> testInstance.onFailedCheckpoint());
276: 
277:             assertThat(rescaleTriggeredCount)
278:                     .as("No rescaling should have been trigger, yet.")
279:                     .hasValue(0);
280: 
281:             testInstance.onCompletedCheckpoint();
282: 
283:             // trigger change
284:             testInstance.onNewResourceRequirements();
285: 
286:             assertThat(rescaleTriggeredCount)
287:                     .as("The completed checkpoint should have triggered a rescale.")
288:                     .hasValue(1);
289: 
290:             IntStream.range(0, rescaleOnFailedCheckpointsCount - 1)
291:                     .forEach(ignored -> testInstance.onFailedCheckpoint());
292: 
293:             assertThat(rescaleTriggeredCount)
294:                     .as(
295:                             "No additional rescaling should have been trigger by any subsequent failed checkpoint, yet.")
296:                     .hasValue(1);
297: 
298:             testInstance.onFailedCheckpoint();
299: 
300:             assertThat(rescaleTriggeredCount)
301:                     .as("The previous failed checkpoint should have triggered the rescale.")
302:                     .hasValue(2);
303:         }
304:     }
