531:         tmpJobStatusListeners.add(jobStatusStore);
532: 
533:         final MetricOptions.JobStatusMetricsSettings jobStatusMetricsSettings =
534:                 MetricOptions.JobStatusMetricsSettings.fromConfiguration(configuration);
535: 
536:         deploymentTimeMetrics =
537:                 new DeploymentStateTimeMetrics(jobGraph.getJobType(), jobStatusMetricsSettings);
538: 
539:         SchedulerBase.registerJobMetrics(
540:                 jobManagerJobMetricGroup,
541:                 jobStatusStore,
542:                 () -> (long) numRestarts,
543:                 deploymentTimeMetrics,
544:                 tmpJobStatusListeners::add,
545:                 initializationTimestamp,
546:                 jobStatusMetricsSettings);
547: 
548:         jobStatusListeners = Collections.unmodifiableCollection(tmpJobStatusListeners);
549:         this.failureEnrichers = failureEnrichers;
550:         this.exceptionHistory =
551:                 new BoundedFIFOQueue<>(configuration.get(WebOptions.MAX_EXCEPTION_HISTORY_SIZE));
552:         this.jobManagerJobMetricGroup = jobManagerJobMetricGroup;
553: 
554:         this.jobFailureMetricReporter = new JobFailureMetricReporter(jobManagerJobMetricGroup);
555:         this.reportEventsAsSpans = configuration.get(TraceOptions.REPORT_EVENTS_AS_SPANS);
556:     }
