1393:     private void awaitJobReachingParallelism(
1394:             SubmissionBufferingTaskManagerGateway taskManagerGateway,
1395:             SchedulerNG scheduler,
1396:             int parallelism)
1397:             throws Exception {
1398:         // Wait for all tasks to be submitted
1399:         taskManagerGateway.waitForSubmissions(parallelism);
1400: 
1401:         final ArchivedExecutionGraph executionGraph =
1402:                 CompletableFuture.supplyAsync(
1403:                                 () -> scheduler.requestJob().getArchivedExecutionGraph(),
1404:                                 singleThreadMainThreadExecutor)
1405:                         .get();
1406: 
1407:         assertThat(executionGraph.getJobVertex(JOB_VERTEX.getID()).getParallelism())
1408:                 .isEqualTo(parallelism);
1409:     }
