1420:     private static JobResourceRequirements createRequirementsWithLowerAndUpperParallelism(
1421:             int lowerParallelism, int upperParallelism) {
1422:         return new JobResourceRequirements(
1423:                 Collections.singletonMap(
1424:                         JOB_VERTEX.getID(),
1425:                         new JobVertexResourceRequirements(
1426:                                 new JobVertexResourceRequirements.Parallelism(
1427:                                         lowerParallelism, upperParallelism))));
1428:     }
